--
-- Name: audit_prevent_delete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.audit_prevent_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    -- service_role bypasses audit immutability for admin recovery.
    IF current_setting('role', true) = 'service_role' THEN
        RETURN OLD;
    END IF;
    RAISE EXCEPTION 'Audit table "%" is immutable: DELETE rejected for role "%".',
        TG_TABLE_NAME, current_setting('role', true);
END;
$$;


ALTER FUNCTION public.audit_prevent_delete() OWNER TO postgres;

--
-- Name: FUNCTION audit_prevent_delete(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.audit_prevent_delete() IS 'KAD-SEC: Generic BEFORE DELETE trigger — raises EXCEPTION for all non-service_role sessions. Attach to any audit table that must be append-only.';


