--
-- Name: can_access_program(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_access_program(p_user_id uuid, p_program_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    -- Return false if the programs table doesn't exist yet (migration 010 not applied)
    IF NOT EXISTS (
        SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'program_participants'
    ) THEN
        RETURN false;
    END IF;

    RETURN EXISTS (
        SELECT 1
        FROM public.organization_memberships om
        JOIN public.program_participants pp ON pp.organization_id = om.organization_id
        WHERE om.user_id = p_user_id
          AND om.status = 'active'
          AND pp.program_id = p_program_id
          AND pp.status = 'active'
    );
END;
$$;


ALTER FUNCTION public.can_access_program(p_user_id uuid, p_program_id uuid) OWNER TO postgres;

