--
-- Name: check_visibility(uuid, public.visibility_scope); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_visibility(p_organization_id uuid, p_visibility_scope public.visibility_scope) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT
        CASE p_visibility_scope
            WHEN 'public' THEN true
            WHEN 'organization' THEN public.is_org_member(p_organization_id)
            WHEN 'program' THEN false  -- requires program_id context, handled per-policy
            WHEN 'network' THEN
                EXISTS (
                    SELECT 1
                    FROM public.organization_memberships om
                    WHERE om.user_id = auth.uid()
                      AND om.status = 'active'
                )
            ELSE false
        END;
$$;


