-- Name: continuity_verification_history_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.continuity_verification_history_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.verification_status IS DISTINCT FROM NEW.verification_status THEN
        NEW.verification_history = COALESCE(OLD.verification_history, '[]'::jsonb) || jsonb_build_object(
            'from', OLD.verification_status,
            'to',   NEW.verification_status,
            'by',   NEW.reviewer_id,
            'at',   NOW(),
            'note', NEW.reviewer_notes
        );
    END IF;
    RETURN NEW;
END;
$$;


