--
-- Name: discovery_search(text, public.supply_item_type[], text[], text, text, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.discovery_search(p_search_text text DEFAULT NULL::text, p_types public.supply_item_type[] DEFAULT NULL::public.supply_item_type[], p_sample_types text[] DEFAULT NULL::text[], p_disease_icd10 text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_commercial_only boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, organization_id uuid, type public.supply_item_type, title text, description text, disease_icd10 text, disease_label text, sample_types text[], country text, commercial_use_allowed boolean, status text, search_rank real, total_count bigint)
    LANGUAGE sql STABLE
    AS $$
    WITH filtered AS (
        SELECT
            si.id,
            si.organization_id,
            si.type,
            si.title,
            si.description,
            si.disease_icd10,
            si.disease_label,
            si.sample_types,
            si.country,
            si.commercial_use_allowed,
            si.status,
            -- Calculate search rank (0 if no search text)
            CASE
                WHEN p_search_text IS NOT NULL AND p_search_text != ''
                THEN ts_rank(si.search_vector, plainto_tsquery('english', p_search_text))
                ELSE 1.0
            END AS rank
        FROM public.supply_items si
        WHERE si.status = 'active'
          AND (p_search_text IS NULL OR p_search_text = '' OR si.search_vector @@ plainto_tsquery('english', p_search_text))
          AND (p_types IS NULL OR si.type = ANY(p_types))
          AND (p_sample_types IS NULL OR si.sample_types && p_sample_types)
          AND (p_disease_icd10 IS NULL OR si.disease_icd10 = p_disease_icd10)
          AND (p_country IS NULL OR si.country = p_country)
          AND (p_commercial_only IS NULL OR (p_commercial_only = true AND si.commercial_use_allowed = true))
    )
    SELECT
        f.id, f.organization_id, f.type, f.title, f.description,
        f.disease_icd10, f.disease_label, f.sample_types, f.country,
        f.commercial_use_allowed, f.status,
        f.rank AS search_rank,
        COUNT(*) OVER() AS total_count
    FROM filtered f
    ORDER BY f.rank DESC, f.title ASC
    LIMIT p_limit
    OFFSET p_offset;
$$;


ALTER FUNCTION public.discovery_search(p_search_text text, p_types public.supply_item_type[], p_sample_types text[], p_disease_icd10 text, p_country text, p_commercial_only boolean, p_limit integer, p_offset integer) OWNER TO postgres;

