-- Name: FUNCTION discovery_search(p_search_text text, p_types public.supply_item_type[], p_sample_types text[], p_disease_icd10 text, p_country text, p_commercial_only boolean, p_limit integer, p_offset integer); Type: COMMENT; Schema: public; Owner: postgres
