COMMENT ON FUNCTION public.discovery_search(p_search_text text, p_types public.supply_item_type[], p_sample_types text[], p_disease_icd10 text, p_country text, p_commercial_only boolean, p_limit integer, p_offset integer) IS 'Discovery Engine search. Supports full-text search, faceted filtering by type, sample type, disease, and country. Returns ranked results with total count.';


--
-- Name: emit_audit_event(public.audit_action, public.audit_resource_type, uuid, uuid, uuid, uuid, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.emit_audit_event(p_action public.audit_action, p_resource_type public.audit_resource_type, p_resource_id uuid, p_resource_owner_org_id uuid DEFAULT NULL::uuid, p_organization_id uuid DEFAULT NULL::uuid, p_program_id uuid DEFAULT NULL::uuid, p_summary text DEFAULT NULL::text, p_old_values jsonb DEFAULT NULL::jsonb, p_new_values jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_id UUID;
    v_actor_email TEXT;
BEGIN
    BEGIN
        v_actor_email := auth.jwt() ->> 'email';
    EXCEPTION WHEN OTHERS THEN
        v_actor_email := NULL;
    END;

    INSERT INTO public.audit_events (
        actor_id, actor_email, action, resource_type, resource_id,
        resource_owner_org_id, organization_id, program_id, summary,
        old_values, new_values, metadata
    ) VALUES (
        COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000'),
        v_actor_email, p_action, p_resource_type, p_resource_id,
        p_resource_owner_org_id, p_organization_id, p_program_id, p_summary,
        p_old_values, p_new_values, p_metadata
    )
    RETURNING id INTO v_id;

    RETURN v_id;
END;
$$;


ALTER FUNCTION public.emit_audit_event(p_action public.audit_action, p_resource_type public.audit_resource_type, p_resource_id uuid, p_resource_owner_org_id uuid, p_organization_id uuid, p_program_id uuid, p_summary text, p_old_values jsonb, p_new_values jsonb, p_metadata jsonb) OWNER TO postgres;

--
-- Name: ensure_provenance_edge(public.provenance_edge_type, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ensure_provenance_edge(p_edge_type public.provenance_edge_type, p_source_node_id uuid, p_target_node_id uuid, p_properties jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_edge_id UUID;
BEGIN
    INSERT INTO provenance_edges (edge_type, source_node_id, target_node_id, properties)
    VALUES (p_edge_type, p_source_node_id, p_target_node_id, p_properties)
    ON CONFLICT (edge_type, source_node_id, target_node_id) DO NOTHING
    RETURNING id INTO v_edge_id;

    RETURN v_edge_id;
END;
$$;


