--
-- Name: ensure_provenance_node(public.provenance_node_type, character varying, character varying, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ensure_provenance_node(p_node_type public.provenance_node_type, p_external_id character varying, p_label character varying DEFAULT NULL::character varying, p_properties jsonb DEFAULT '{}'::jsonb, p_organization_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_node_id UUID;
BEGIN
    INSERT INTO provenance_nodes (node_type, external_id, label, properties, organization_id)
    VALUES (p_node_type, p_external_id, p_label, p_properties, p_organization_id)
    ON CONFLICT (node_type, external_id) DO NOTHING
    RETURNING id INTO v_node_id;

    -- If the node already existed, return its id
    IF v_node_id IS NULL THEN
        SELECT id INTO v_node_id
        FROM provenance_nodes
        WHERE node_type = p_node_type AND external_id = p_external_id;
    END IF;

    RETURN v_node_id;
END;
$$;


ALTER FUNCTION public.ensure_provenance_node(p_node_type public.provenance_node_type, p_external_id character varying, p_label character varying, p_properties jsonb, p_organization_id uuid) OWNER TO postgres;

