--
-- Name: provenance_node_integrity_status(uuid, public.provenance_node_type); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.provenance_node_integrity_status(p_node_id uuid, p_node_type public.provenance_node_type) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_evidence_count INTEGER;
    v_edge_count     INTEGER;
    v_critical_types provenance_node_type[] := ARRAY[
        'specimen'::provenance_node_type,
        'aliquot'::provenance_node_type,
        'consent'::provenance_node_type,
        'shipment'::provenance_node_type
    ];
BEGIN
    SELECT COUNT(*) INTO v_evidence_count
    FROM provenance_evidence
    WHERE node_id = p_node_id;

    SELECT COUNT(*) INTO v_edge_count
    FROM provenance_edges
    WHERE source_node_id = p_node_id OR target_node_id = p_node_id;

    IF v_evidence_count = 0 AND p_node_type = ANY(v_critical_types) THEN
        RETURN 'missing_evidence';
    END IF;

    IF v_edge_count = 0 THEN
        RETURN 'warning';
    END IF;

    RETURN 'complete';
END;
$$;


ALTER FUNCTION public.provenance_node_integrity_status(p_node_id uuid, p_node_type public.provenance_node_type) OWNER TO postgres;

--
-- Name: provenance_node_integrity_status_batch(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.provenance_node_integrity_status_batch(p_node_ids uuid[]) RETURNS TABLE(node_id uuid, integrity_status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_critical_types provenance_node_type[] := ARRAY[
        'specimen'::provenance_node_type,
        'aliquot'::provenance_node_type,
        'consent'::provenance_node_type,
        'shipment'::provenance_node_type
    ];
BEGIN
    RETURN QUERY
    SELECT
        n.id AS node_id,
        CASE
            WHEN COUNT(ev.id) = 0 AND n.node_type = ANY(v_critical_types) THEN 'missing_evidence'
            WHEN COUNT(e.id) = 0                                           THEN 'warning'
            ELSE                                                                'complete'
        END AS integrity_status
    FROM provenance_nodes n
    LEFT JOIN provenance_evidence ev ON ev.node_id = n.id
    LEFT JOIN provenance_edges    e  ON e.source_node_id = n.id OR e.target_node_id = n.id
    WHERE n.id = ANY(p_node_ids)
    GROUP BY n.id, n.node_type;
END;
$$;


ALTER FUNCTION public.provenance_node_integrity_status_batch(p_node_ids uuid[]) OWNER TO postgres;

