--
-- Name: publish_domain_event(text, jsonb, uuid, uuid, uuid, uuid, uuid, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_domain_event(p_event_type text, p_payload jsonb, p_actor_id uuid, p_organization_id uuid DEFAULT NULL::uuid, p_program_id uuid DEFAULT NULL::uuid, p_correlation_id uuid DEFAULT NULL::uuid, p_causation_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_event_version integer DEFAULT 1, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_existing_id UUID;
    v_event_id UUID;
    v_outbox_id UUID;
BEGIN
    IF p_idempotency_key IS NOT NULL AND length(trim(p_idempotency_key)) > 0 THEN
        SELECT id INTO v_existing_id
        FROM public.domain_event_store
        WHERE idempotency_key = p_idempotency_key;

        IF v_existing_id IS NOT NULL THEN
            RETURN jsonb_build_object(
                'event_id', v_existing_id,
                'duplicate', true,
                'outbox_id', NULL
            );
        END IF;
    END IF;

    INSERT INTO public.domain_event_store (
        event_type, event_version, actor_id, organization_id, program_id,
        correlation_id, causation_id, idempotency_key, payload, metadata
    ) VALUES (
        p_event_type, COALESCE(p_event_version, 1), p_actor_id,
        p_organization_id, p_program_id, p_correlation_id, p_causation_id,
        NULLIF(trim(p_idempotency_key), ''), COALESCE(p_payload, '{}'::jsonb),
        COALESCE(p_metadata, '{}'::jsonb)
    )
    RETURNING id INTO v_event_id;

    INSERT INTO public.domain_event_outbox (event_id, status)
    VALUES (v_event_id, 'pending')
    RETURNING id INTO v_outbox_id;

    RETURN jsonb_build_object(
        'event_id', v_event_id,
        'duplicate', false,
        'outbox_id', v_outbox_id
    );
EXCEPTION
    WHEN unique_violation THEN
        SELECT id INTO v_existing_id
        FROM public.domain_event_store
        WHERE idempotency_key = p_idempotency_key;

        RETURN jsonb_build_object(
            'event_id', v_existing_id,
            'duplicate', true,
            'outbox_id', NULL
        );
END;
$$;


