--
-- Name: replay_domain_events(timestamp with time zone, timestamp with time zone, text[], uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.replay_domain_events(p_from timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_event_types text[] DEFAULT NULL::text[], p_correlation_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500) RETURNS SETOF public.domain_event_store
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT *
    FROM public.domain_event_store
    WHERE occurred_at >= p_from
      AND (p_to IS NULL OR occurred_at <= p_to)
      AND (p_event_types IS NULL OR event_type = ANY(p_event_types))
      AND (p_correlation_id IS NULL OR correlation_id = p_correlation_id)
    ORDER BY occurred_at ASC, recorded_at ASC
    LIMIT GREATEST(p_limit, 1);
$$;


