--
-- Name: suggest_organizations(text[], text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.suggest_organizations(p_required_capabilities text[], p_disease_icd10 text DEFAULT NULL::text, p_target_country text DEFAULT NULL::text, p_limit integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_agg(jsonb_build_object(
        'organization_id', o.id,
        'organization_name', o.name,
        'country', o.country,
        'matched_capabilities', (
            SELECT jsonb_agg(oct.key)
            FROM public.organization_capabilities oc
            JOIN public.organization_capability_types oct ON oct.id = oc.capability_type_id
            WHERE oc.organization_id = o.id AND oct.key = ANY(p_required_capabilities)
        ),
        'score', (
            SELECT COUNT(*)::NUMERIC / array_length(p_required_capabilities, 1)
            FROM public.organization_capabilities oc
            JOIN public.organization_capability_types oct ON oct.id = oc.capability_type_id
            WHERE oc.organization_id = o.id AND oct.key = ANY(p_required_capabilities)
        )
    ) ORDER BY score DESC)
    INTO v_result
    FROM public.organizations o
    WHERE o.is_active = true
      AND (p_target_country IS NULL OR o.country = p_target_country)
      AND EXISTS (
          SELECT 1 FROM public.organization_capabilities oc
          JOIN public.organization_capability_types oct ON oct.id = oc.capability_type_id
          WHERE oc.organization_id = o.id AND oct.key = ANY(p_required_capabilities)
      )
    LIMIT p_limit;

    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


