ALTER TABLE public.capability_claim_links OWNER TO postgres;

--
-- Name: TABLE capability_claim_links; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.capability_claim_links IS 'M2M join linking capability instances to the claims that serve as their evidence dependencies. dependency_type controls how the claim set is aggregated: ALL_REQUIRED, ANY_SUFFICIENT, WEIGHTED, or CONDITIONAL.';


--
-- Name: COLUMN capability_claim_links.is_critical; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.capability_claim_links.is_critical IS 'If true, failure of this dependency immediately degrades the capability instance to DEGRADED state, regardless of other dependencies.';


--
-- Name: capability_dependency_status; Type: TABLE; Schema: public; Owner: postgres
