--
-- Name: TABLE capability_dependency_status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.capability_dependency_status IS 'Resolved status of each individual claim dependency for a capability instance. Recomputed when claim state changes. Provides a fast-path lookup for dependency satisfaction evaluation.';


--
-- Name: capability_instances; Type: TABLE; Schema: public; Owner: postgres
--

