    CONSTRAINT ck_no_self_conflict CHECK ((claim_a <> claim_b)),
    CONSTRAINT claim_conflicts_conflict_type_check CHECK ((conflict_type = ANY (ARRAY['direct_contradiction'::text, 'value_mismatch'::text, 'scope_overlap'::text, 'temporal_conflict'::text, 'jurisdictional'::text])))
);


ALTER TABLE public.claim_conflicts OWNER TO postgres;

