    CONSTRAINT continuity_evidence_links_claim_table_check CHECK ((claim_table = ANY (ARRAY['site_continuity_profiles'::text, 'continuity_experience_ledger'::text, 'continuity_relationships'::text, 'continuity_capabilities'::text, 'continuity_performance_metrics'::text, 'continuity_timeline_events'::text])))
