-- Name: continuity_experience_claims; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.continuity_experience_claims (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    site_continuity_profile_id uuid NOT NULL,
    claim_type text NOT NULL,
    category text NOT NULL,
    title text NOT NULL,
    description text,
    experience_source text DEFAULT 'legacy'::text NOT NULL,
    therapeutic_area text,
    study_phase text,
    biospecimen_type text,
    start_date date,
    end_date date,
    quantity numeric,
    verification_status public.continuity_claim_verification_status DEFAULT 'self_reported'::public.continuity_claim_verification_status NOT NULL,
    confidence_score integer DEFAULT 25 NOT NULL,
    is_public boolean DEFAULT false NOT NULL,
    sponsor_name_policy text DEFAULT 'masked'::text NOT NULL,
    masked_sponsor_label text,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    badge_level public.continuity_badge_level DEFAULT 'self_reported'::public.continuity_badge_level NOT NULL,
