    reviewed_at timestamp with time zone,
    reviewer_notes text,
    verification_history jsonb DEFAULT '[]'::jsonb NOT NULL,
    submitted_for_review_at timestamp with time zone,
    promoted_to_ledger_at timestamp with time zone,
    CONSTRAINT continuity_claim_dates CHECK (((end_date IS NULL) OR (start_date IS NULL) OR (end_date >= start_date))),
    CONSTRAINT continuity_claim_public_requires_safe_sponsor_policy CHECK (((is_public = false) OR (sponsor_name_policy = ANY (ARRAY['masked'::text, 'permissioned'::text, 'public'::text])))),
    CONSTRAINT continuity_experience_claims_confidence_score_check CHECK (((confidence_score >= 0) AND (confidence_score <= 100))),
    CONSTRAINT continuity_experience_claims_experience_source_check CHECK ((experience_source = ANY (ARRAY['legacy'::text, 'native'::text]))),
    CONSTRAINT continuity_experience_claims_masked_sponsor_label_check CHECK (((masked_sponsor_label IS NULL) OR (masked_sponsor_label = ANY (ARRAY['Global pharma sponsor'::text, 'Top 10 CRO'::text, 'IVD company'::text, 'Academic medical center'::text, 'Specialty lab'::text])))),
    CONSTRAINT continuity_experience_claims_sponsor_name_policy_check CHECK ((sponsor_name_policy = ANY (ARRAY['private'::text, 'masked'::text, 'permissioned'::text, 'public'::text])))
);


ALTER TABLE public.continuity_experience_claims OWNER TO postgres;

