    description text,
    status public.exchange_deal_status DEFAULT 'pending_acceptance'::public.exchange_deal_status NOT NULL,
    total_value numeric(12,2),
    milestone_amounts jsonb DEFAULT '{}'::jsonb,
    currency text DEFAULT 'USD'::text,
