    actual_start_date date,
    actual_end_date date,
    sample_count_expected integer,
    sample_count_delivered integer DEFAULT 0,
    delivery_percentage numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN (sample_count_expected > 0) THEN round((((sample_count_delivered)::numeric / (sample_count_expected)::numeric) * (100)::numeric), 2)
    ELSE (0)::numeric
END) STORED,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


