    organization_id uuid NOT NULL,
    operational_score numeric(5,3) DEFAULT 0.500 NOT NULL,
    regulatory_score numeric(5,3) DEFAULT 0.500 NOT NULL,
    financial_score numeric(5,3) DEFAULT 0.500 NOT NULL,
    technical_score numeric(5,3) DEFAULT 0.500 NOT NULL,
    overall_score numeric(5,3) DEFAULT 0.500 NOT NULL,
    last_event_at timestamp with time zone,
    last_decay_at timestamp with time zone DEFAULT now() NOT NULL,
    total_fulfillments integer DEFAULT 0 NOT NULL,
    successful_fulfillments integer DEFAULT 0 NOT NULL,
    incident_count integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT trust_score_range CHECK ((((operational_score >= 0.000) AND (operational_score <= 1.000)) AND ((regulatory_score >= 0.000) AND (regulatory_score <= 1.000)) AND ((financial_score >= 0.000) AND (financial_score <= 1.000)) AND ((technical_score >= 0.000) AND (technical_score <= 1.000)) AND ((overall_score >= 0.000) AND (overall_score <= 1.000))))
);


