--
-- Name: organization_twins; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.organization_twins AS
 SELECT o.id,
    o.name,
    o.country,
    COALESCE(( SELECT jsonb_agg(oct.key) AS jsonb_agg
           FROM (public.organization_capabilities oc
             JOIN public.organization_capability_types oct ON ((oct.id = oc.capability_type_id)))
          WHERE (oc.organization_id = o.id)), '[]'::jsonb) AS capabilities,
    t.operational_score,
    t.regulatory_score,
    t.financial_score,
    t.technical_score,
    t.overall_score,
    t.total_fulfillments,
    t.successful_fulfillments,
    t.incident_count,
    t.last_event_at,
    t.last_decay_at,
    t.updated_at AS trust_updated_at
   FROM (public.organizations o
     LEFT JOIN public.organization_trust t ON ((o.id = t.organization_id)));


ALTER VIEW public.organization_twins OWNER TO postgres;

