-- Name: user_organizations; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.user_organizations AS
 SELECT DISTINCT m.user_id,
    m.organization_id,
    r.key AS role
   FROM ((public.organization_memberships m
     JOIN public.membership_roles mr ON ((mr.membership_id = m.id)))
     JOIN public.organization_roles r ON ((r.id = mr.role_id)))
  WHERE (m.status = 'active'::public.membership_status);


