--
-- Data for Name: schema_migrations; Type: TABLE DATA; Schema: supabase_migrations; Owner: postgres
--

COPY supabase_migrations.schema_migrations (version, statements, name) FROM stdin;
008	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 0A: Core Identity & Organizations\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Domain: Multi-tenant biospecimen infrastructure (BNOS)\n-- Design: ADR-002 — Multi-Tenant Architecture & Organization-Capability Model\n-- Blueprint: docs/architecture/kadarn-platform-blueprint.md\n-- Dependencies: none (foundational migration)\n--\n-- This migration creates the identity and organization layer that all\n-- other modules build upon. Every organization is a legal entity with\n-- capabilities (many-to-many), memberships (users), and roles.\n-- ============================================================================\n\n-- ############################################################################\n-- PART 0: EXTENSION SAFETY\n-- ################################################################------------\n\n-- pgcrypto is needed for password hashing by admin_create_user.\n-- Supabase comes with pgcrypto pre-installed in the extensions schema.\n-- The function references extensions.crypt() which is available via search path.\n\n-- pg_trgm supports fuzzy text search on organization names.\nCREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA extensions","-- ############################################################################\n-- PART 1: ENUMS\n-- ############################################################################\n\n-- Visibility scope for multi-tenant data isolation (Blueprint §4.2)\nDO $$ BEGIN\n    CREATE TYPE visibility_scope AS ENUM (\n        'organization',     -- visible only within the owning org\n        'program',          -- visible to program participants\n        'network',          -- visible to all authenticated users\n        'public'            -- visible to unauthenticated users\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- Membership lifecycle (Blueprint §5.3)\nDO $$ BEGIN\n    CREATE TYPE membership_status AS ENUM (\n        'invited',\n        'active',\n        'suspended',\n        'inactive'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- Identity provider types (Blueprint §4.4 — OIDC-ready abstraction)\nDO $$ BEGIN\n    CREATE TYPE identity_provider_type AS ENUM (\n        'supabase',\n        'azure_ad',\n        'okta',\n        'keycloak',\n        'auth0',\n        'google_workspace',\n        'custom_oidc'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: TABLE — organizations\n-- ############################################################################\n--\n-- A legal entity that participates in the Kadarn network.\n-- No rigid type enum — capabilities define what an org can do.\n-- (Blueprint §5.1, ADR-002)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.organizations (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n\n    -- Identity\n    name                TEXT NOT NULL,\n    legal_name          TEXT,                          -- registered legal name\n    tax_id              TEXT,                          -- EIN / VAT\n    country             CHAR(2) NOT NULL DEFAULT 'US', -- ISO 3166-1 alpha2\n    region              TEXT,                          -- state / province\n\n    -- Contact\n    email               TEXT,\n    phone               TEXT,\n    website             TEXT,\n    address_line1       TEXT,\n    address_line2       TEXT,\n    city                TEXT,\n    postal_code         TEXT,\n\n    -- Profile\n    description         TEXT,\n    logo_url            TEXT,\n    certifications      TEXT[] DEFAULT '{}',\n    metadata            JSONB DEFAULT '{}',\n\n    -- Audit & lifecycle\n    is_active           BOOLEAN NOT NULL DEFAULT true,\n    -- References auth.users.id logically. No physical FK to avoid Supabase auth schema coupling.\n    created_by          UUID NOT NULL,\n    visibility_scope    visibility_scope NOT NULL DEFAULT 'network',\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_organizations_country\n    ON public.organizations(country)","CREATE INDEX IF NOT EXISTS idx_organizations_active\n    ON public.organizations(is_active)","CREATE INDEX IF NOT EXISTS idx_organizations_visibility\n    ON public.organizations(visibility_scope)","CREATE INDEX IF NOT EXISTS idx_organizations_name_trgm\n    ON public.organizations USING GIN (name gin_trgm_ops)","ALTER TABLE public.organizations\n    ADD CONSTRAINT uq_organizations_name_country\n    UNIQUE (name, country)","COMMENT ON TABLE public.organizations IS\n    'Legal entities in Kadarn. Uses capability model (not type enum) per ADR-002.'","-- ############################################################################\n-- PART 3: TABLE — organization_capability_types\n-- ############################################################################\n--\n-- Controlled vocabulary of capabilities. Managed by platform administrators.\n-- (Blueprint §5.2)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.organization_capability_types (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    key                 TEXT NOT NULL UNIQUE,          -- stable identifier, e.g. 'biobank'\n    name                TEXT NOT NULL,                 -- human-readable label\n    description         TEXT,\n    category            TEXT,                          -- grouping: research, clinical, logistics, regulatory, technology\n    is_active           BOOLEAN NOT NULL DEFAULT true,\n    display_order       INTEGER NOT NULL DEFAULT 0,\n    metadata            JSONB DEFAULT '{}',\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","COMMENT ON TABLE public.organization_capability_types IS\n    'Controlled vocabulary of capabilities. Seeded with 12 standard types.'","-- Seed the 12 standard capability types (Blueprint §5.2)\nINSERT INTO public.organization_capability_types (key, name, description, category, display_order) VALUES\n    ('sponsor',              'Sponsor',              'Funds and oversees research programs',                    'research',    1),\n    ('cro',                  'CRO',                  'Contract Research Organization managing study operations','research',    2),\n    ('biobank',              'Biobank',              'Biospecimen repository with collection and storage',      'clinical',    3),\n    ('clinical_site',        'Clinical Site',        'Patient-facing clinical research site',                   'clinical',    4),\n    ('processing_lab',       'Processing Lab',       'Laboratory that processes biospecimens',                  'clinical',    5),\n    ('storage_facility',     'Storage Facility',     'Long-term biospecimen storage facility',                  'clinical',    6),\n    ('logistics_vendor',     'Logistics Vendor',     'Transportation and cold-chain logistics',                 'logistics',   7),\n    ('irb',                  'IRB / Ethics Board',   'Institutional Review Board or ethics committee',          'regulatory',  8),\n    ('regulatory_body',      'Regulatory Body',      'Government or regulatory agency',                         'regulatory',  9),\n    ('diagnostic_lab',       'Diagnostic Lab',       'Clinical diagnostic laboratory',                          'clinical',   10),\n    ('data_processor',       'Data Processor',       'Handles data analysis, curation, or integration',         'technology', 11),\n    ('technology_provider',  'Technology Provider',  'Provides software, platforms, or IT infrastructure',      'technology', 12)\nON CONFLICT (key) DO NOTHING","-- ############################################################################\n-- PART 4: TABLE — organization_capabilities\n-- ############################################################################\n--\n-- Many-to-many: which organizations have which capabilities.\n-- (Blueprint §5.1 — capability model)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.organization_capabilities (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n    capability_type_id  UUID NOT NULL REFERENCES public.organization_capability_types(id) ON DELETE RESTRICT,\n\n    is_primary          BOOLEAN NOT NULL DEFAULT false,\n    accredited_until    DATE,\n    scope_description   TEXT,\n\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (organization_id, capability_type_id)\n)","CREATE INDEX IF NOT EXISTS idx_org_capabilities_org\n    ON public.organization_capabilities(organization_id)","CREATE INDEX IF NOT EXISTS idx_org_capabilities_type\n    ON public.organization_capabilities(capability_type_id)","CREATE INDEX IF NOT EXISTS idx_org_capabilities_primary\n    ON public.organization_capabilities(organization_id, is_primary)\n    WHERE is_primary = true","COMMENT ON TABLE public.organization_capabilities IS\n    'Which capabilities each organization has. Many-to-many per ADR-002.'","-- ############################################################################\n-- PART 5: TABLE — organization_roles\n-- ############################################################################\n--\n-- Role definitions within an organization. (Blueprint §5.3)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.organization_roles (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    key                 TEXT NOT NULL UNIQUE,\n    name                TEXT NOT NULL,\n    description         TEXT,\n    is_system_role      BOOLEAN NOT NULL DEFAULT false,\n    priority            INTEGER NOT NULL DEFAULT 0,    -- higher = more privileged\n\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","COMMENT ON TABLE public.organization_roles IS\n    'Role definitions. System roles: org_admin, org_member, readonly, etc.'","-- Seed system roles (Blueprint §5.3)\nINSERT INTO public.organization_roles (key, name, description, is_system_role, priority) VALUES\n    ('org_admin',      'Organization Admin',  'Full administrative access within the organization',        true, 100),\n    ('org_member',     'Organization Member', 'Standard member with role-based permissions',               true,  50),\n    ('biobank_tech',   'Biobank Technician',  'Manages biospecimen inventory and processing',              true,  60),\n    ('irb_chair',      'IRB Chair',           'Oversees ethics review for the organization',               true,  70),\n    ('data_steward',   'Data Steward',        'Manages data sharing policies and access',                  true,  65),\n    ('readonly',       'Read Only',           'Can view organization data but not modify',                 true,  10)\nON CONFLICT (key) DO NOTHING","-- ############################################################################\n-- PART 6: TABLE — organization_memberships\n-- ############################################################################\n--\n-- Which users belong to which organizations. A user can belong to multiple.\n-- (Blueprint §4.3 — RLS architecture, §5 — Organization-Capability Model)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.organization_memberships (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    user_id             UUID NOT NULL,                   -- FK to auth.users\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    -- References auth.users.id logically. No physical FK to avoid Supabase auth schema coupling.\n    title               TEXT,\n    department          TEXT,\n    status              membership_status NOT NULL DEFAULT 'invited',\n\n    invited_by          UUID,\n    invited_at          TIMESTAMPTZ,\n    joined_at           TIMESTAMPTZ,\n    deactivated_at      TIMESTAMPTZ,\n    deactivated_reason  TEXT,\n\n    metadata            JSONB DEFAULT '{}',\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (user_id, organization_id)\n)","CREATE INDEX IF NOT EXISTS idx_org_memberships_user\n    ON public.organization_memberships(user_id)","CREATE INDEX IF NOT EXISTS idx_org_memberships_org\n    ON public.organization_memberships(organization_id)","CREATE INDEX IF NOT EXISTS idx_org_memberships_status\n    ON public.organization_memberships(status)","COMMENT ON TABLE public.organization_memberships IS\n    'Links users to organizations. A user can belong to multiple organizations.'","-- ############################################################################\n-- PART 7: TABLE — membership_roles\n-- ############################################################################\n--\n-- Junction: each membership can have multiple roles within the org.\n-- (Blueprint §5.3)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.membership_roles (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    membership_id       UUID NOT NULL REFERENCES public.organization_memberships(id) ON DELETE CASCADE,\n    role_id             UUID NOT NULL REFERENCES public.organization_roles(id) ON DELETE RESTRICT,\n\n    assigned_by         UUID,\n    assigned_at         TIMESTAMPTZ NOT NULL DEFAULT now(),\n    expires_at          TIMESTAMPTZ,\n\n    UNIQUE (membership_id, role_id)\n)","CREATE INDEX IF NOT EXISTS idx_membership_roles_membership\n    ON public.membership_roles(membership_id)","CREATE INDEX IF NOT EXISTS idx_membership_roles_role\n    ON public.membership_roles(role_id)","COMMENT ON TABLE public.membership_roles IS\n    'Which roles each membership has. A user can have multiple roles in an org.'","-- ############################################################################\n-- PART 8: TABLE — identity_providers\n-- ############################################################################\n--\n-- SSO / OIDC identity providers. Starts with Supabase Auth, supports migration\n-- to Azure AD, Okta, etc. without changing the domain model.\n-- (Blueprint §4.4 — OIDC-ready abstraction)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.identity_providers (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    provider_type       identity_provider_type NOT NULL,\n    provider_name       TEXT NOT NULL,\n    issuer_url          TEXT,\n    client_id           TEXT,                            -- stored encrypted in production\n    is_active           BOOLEAN NOT NULL DEFAULT true,\n    config              JSONB DEFAULT '{}',\n\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","COMMENT ON TABLE public.identity_providers IS\n    'SSO/OIDC identity providers. Kadarn starts with Supabase Auth.'","-- Seed default Supabase provider\nINSERT INTO public.identity_providers (provider_type, provider_name, is_active)\nVALUES ('supabase', 'Kadarn Supabase Auth', true)\nON CONFLICT DO NOTHING","-- ############################################################################\n-- PART 9: TABLE — user_profiles\n-- ############################################################################\n--\n-- Kadarn user identity layer. Linked 1:1 to auth.users. OIDC-ready.\n-- (Blueprint §4.4)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.user_profiles (\n    id                  UUID PRIMARY KEY,                -- same as auth.users.id\n    email               TEXT NOT NULL,\n    full_name           TEXT NOT NULL DEFAULT 'User',\n    preferred_name      TEXT,\n    avatar_url          TEXT,\n\n    -- Identity provider link\n    primary_identity_provider_id UUID REFERENCES public.identity_providers(id) ON DELETE SET NULL,\n    external_identity_id         TEXT,\n\n    -- Account status\n    is_active           BOOLEAN NOT NULL DEFAULT true,\n    last_sign_in_at     TIMESTAMPTZ,\n    locale              TEXT DEFAULT 'en',\n    timezone            TEXT DEFAULT 'UTC',\n\n    metadata            JSONB DEFAULT '{}',\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE\n)","CREATE INDEX IF NOT EXISTS idx_user_profiles_email\n    ON public.user_profiles(email)","CREATE INDEX IF NOT EXISTS idx_user_profiles_active\n    ON public.user_profiles(is_active)","COMMENT ON TABLE public.user_profiles IS\n    'Kadarn user profiles. Linked 1:1 to auth.users. OIDC-ready.'","-- ############################################################################\n-- PART 10: TABLE — external_identity_links\n-- ############################################################################\n--\n-- Links a Kadarn user profile to external identity provider accounts.\n-- Enables multi-SSO for the same Kadarn account.\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.external_identity_links (\n    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    user_profile_id         UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,\n    identity_provider_id    UUID NOT NULL REFERENCES public.identity_providers(id) ON DELETE CASCADE,\n    external_user_id        TEXT NOT NULL,\n    external_email          TEXT,\n    external_username       TEXT,\n    raw_attributes          JSONB DEFAULT '{}',\n    linked_at               TIMESTAMPTZ NOT NULL DEFAULT now(),\n    last_authenticated_at   TIMESTAMPTZ,\n\n    UNIQUE (identity_provider_id, external_user_id)\n)","CREATE INDEX IF NOT EXISTS idx_external_links_profile\n    ON public.external_identity_links(user_profile_id)","CREATE INDEX IF NOT EXISTS idx_external_links_provider\n    ON public.external_identity_links(identity_provider_id)","COMMENT ON TABLE public.external_identity_links IS\n    'Links Kadarn user profiles to external SSO accounts. Multi-SSO support.'","-- ############################################################################\n-- PART 11: UPDATED_AT HELPER FUNCTION\n-- ############################################################################\n--\n-- Idempotent: safe to re-run across migrations.\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.update_updated_at_column()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW;\nEND;\n$$","-- ############################################################################\n-- PART 12: TRIGGERS — updated_at\n-- ############################################################################\n\nCREATE TRIGGER trg_organizations_updated_at\n    BEFORE UPDATE ON public.organizations\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_org_capabilities_updated_at\n    BEFORE UPDATE ON public.organization_capabilities\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_org_memberships_updated_at\n    BEFORE UPDATE ON public.organization_memberships\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_user_profiles_updated_at\n    BEFORE UPDATE ON public.user_profiles\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","-- ############################################################################\n-- PART 13: AUTO-CREATE PROFILE ON SIGNUP (Supabase Auth hook)\n-- ############################################################################\n--\n-- Creates a user_profiles row when a user signs up via Supabase Auth.\n-- (Blueprint §19.2 — migration rules: idempotent)\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.handle_new_user_signup()\nRETURNS TRIGGER\nSECURITY DEFINER\nSET search_path = public\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    INSERT INTO public.user_profiles (id, email, full_name, metadata)\n    VALUES (\n        NEW.id,\n        COALESCE(NEW.email, ''),\n        COALESCE(NEW.raw_user_meta_data ->> 'full_name', NEW.email, 'User'),\n        jsonb_build_object(\n            'signup_provider', NEW.raw_user_meta_data ->> 'provider'\n        )\n    )\n    ON CONFLICT (id) DO NOTHING;\n\n    RETURN NEW;\nEND;\n$$","DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users","CREATE TRIGGER on_auth_user_created\n    AFTER INSERT ON auth.users\n    FOR EACH ROW\n    EXECUTE FUNCTION public.handle_new_user_signup()","-- ############################################################################\n-- PART 14: JWT CLAIM SYNC — user_profiles → auth.users → JWT\n-- ############################################################################\n--\n-- Syncs selected profile fields into auth.users raw_app_meta_data so JWT\n-- tokens include them on next refresh. (Blueprint §4.3 — RLS fast path)\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.sync_profile_to_auth_meta()\nRETURNS TRIGGER\nSECURITY DEFINER\nSET search_path = public\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    UPDATE auth.users\n    SET raw_app_meta_data = raw_app_meta_data || jsonb_build_object(\n        'kadarn_profile_id', NEW.id::text,\n        'kadarn_email', NEW.email,\n        'kadarn_name', NEW.full_name,\n        'kadarn_active', NEW.is_active\n    )\n    WHERE id = NEW.id;\n\n    RETURN NEW;\nEND;\n$$","DROP TRIGGER IF EXISTS trg_user_profiles_auth_sync ON public.user_profiles","CREATE TRIGGER trg_user_profiles_auth_sync\n    AFTER INSERT OR UPDATE OF email, full_name, is_active ON public.user_profiles\n    FOR EACH ROW\n    EXECUTE FUNCTION public.sync_profile_to_auth_meta()","-- ############################################################################\n-- PART 15: ADMIN USER CREATION FUNCTION\n-- ############################################################################\n--\n-- Helper for seeding and admin dashboard. Creates auth.users + profile\n-- + optional organization membership in one call.\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.admin_create_user(\n    p_email TEXT,\n    p_password TEXT,\n    p_full_name TEXT,\n    p_organization_id UUID DEFAULT NULL\n)\nRETURNS UUID\nSECURITY DEFINER\nSET search_path = public\nLANGUAGE plpgsql\nAS $$\nDECLARE\n    v_user_id UUID;\nBEGIN\n    -- Only service_role or superuser may directly create users\n    -- Allow null or empty auth context (direct psql/superuser access)\n    IF auth.role() IS DISTINCT FROM NULL\n       AND auth.role() != ''\n       AND auth.role() != 'service_role'\n       AND auth.role() != 'superuser' THEN\n        RAISE EXCEPTION 'Only service_role can create users directly';\n    END IF;\n\n    v_user_id := gen_random_uuid();\n\n    INSERT INTO auth.users (\n        id, instance_id, email, encrypted_password, email_confirmed_at,\n        confirmation_token, recovery_token, email_change_token_new, email_change,\n        email_change_token_current, reauthentication_token, phone_change, phone_change_token,\n        raw_app_meta_data, raw_user_meta_data,\n        aud, role, is_sso_user, is_anonymous, created_at, updated_at\n    ) VALUES (\n        v_user_id,\n        '00000000-0000-0000-0000-000000000000',\n        p_email,\n        extensions.crypt(p_password, extensions.gen_salt('bf', 10)),\n        now(),\n        '', '', '', '',\n        '', '', '', '',\n        jsonb_build_object(\n            'provider', 'email',\n            'providers', ARRAY['email']\n        ),\n        jsonb_build_object(\n            'full_name', p_full_name,\n            'organization_id', p_organization_id::text\n        ),\n        'authenticated', 'authenticated',\n        false, false,\n        now(), now()\n    );\n\n    -- Create identity entry (required by Supabase Auth for password sign-in)\n    INSERT INTO auth.identities (\n        id, user_id, identity_data, provider, provider_id,\n        last_sign_in_at, created_at, updated_at\n    ) VALUES (\n        v_user_id, v_user_id,\n        jsonb_build_object(\n            'sub', v_user_id::text,\n            'email', p_email,\n            'email_verified', true,\n            'full_name', p_full_name,\n            'phone_verified', false\n        ),\n        'email', v_user_id::text,\n        now(), now(), now()\n    )\n    ON CONFLICT (provider_id, provider) DO NOTHING;\n\n    -- Ensure profile exists (trigger handles this, but safeguard)\n    INSERT INTO public.user_profiles (id, email, full_name)\n    VALUES (v_user_id, p_email, p_full_name)\n    ON CONFLICT (id) DO NOTHING;\n\n    -- Create active membership if organization specified\n    IF p_organization_id IS NOT NULL THEN\n        INSERT INTO public.organization_memberships (\n            user_id, organization_id, status, invited_by, invited_at, joined_at\n        ) VALUES (\n            v_user_id, p_organization_id, 'active', v_user_id, now(), now()\n        )\n        ON CONFLICT (user_id, organization_id) DO NOTHING;\n    END IF;\n\n    RETURN v_user_id;\nEND;\n$$","-- ############################################################################\n-- PART 16: VERIFICATION FUNCTION\n-- ############################################################################\n\nCREATE OR REPLACE FUNCTION public.my_auth_context()\nRETURNS JSONB\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT jsonb_build_object(\n        'user_id', auth.uid(),\n        'is_authenticated', auth.role() = 'authenticated',\n        'jwt_payload', auth.jwt()\n    );\n$$","-- ============================================================================\n-- END OF MIGRATION 008 — Sprint 0A: Core Identity & Organizations\n-- ============================================================================"}	organizations_capabilities
009	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 0B: RLS Foundation\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Design: ADR-002 — Shared database + RLS for multi-tenancy\n-- Blueprint: §4 — Tenant / RLS Model, §19 — Migration Rules\n-- Dependencies: 008_organizations_capabilities.sql\n--\n-- This migration creates:\n--   1. RLS helper functions for fast JWT-based and DB-based checks\n--   2. Row-Level Security policies for all Sprint 0A tables\n--   3. Default deny-by-default for unlisted operations\n--\n-- Key design (Blueprint §4.3):\n--   - Fast path: JWT app_metadata claims for frequent checks\n--   - Slow path: DB queries for complex checks (program access, capabilities)\n--   - Deny-by-default: only explicitly granted operations are allowed\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: RLS HELPER FUNCTIONS\n-- ############################################################################\n--\n-- Naming convention (Blueprint §19.4):\n--   current_*()   — reads from JWT (fast, no DB)\n--   is_*()        — DB lookup for membership/role checks\n--   has_*()       — DB lookup for capability checks\n-- ===========================================================================\n\n-- ============================================================================\n-- 1a. current_user_id()\n-- Shorthand for auth.uid(). Avoids repeating auth.uid() in every policy.\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.current_user_id()\nRETURNS UUID\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT auth.uid();\n$$","-- ============================================================================\n-- 1b. current_user_email()\n-- Reads email from JWT claims (fast, avoids user_profiles query).\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.current_user_email()\nRETURNS TEXT\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT auth.jwt() ->> 'email';\n$$","-- ============================================================================\n-- 1c. is_org_member(p_user_id, p_org_id)\n-- Checks if a user has an active membership in an organization.\n-- (Blueprint §4.4 — RLS helper functions table)\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.is_org_member(\n    p_user_id UUID,\n    p_org_id UUID\n)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT EXISTS (\n        SELECT 1 FROM public.organization_memberships\n        WHERE user_id = p_user_id\n          AND organization_id = p_org_id\n          AND status = 'active'\n    );\n$$","-- ============================================================================\n-- 1d. is_org_member(p_org_id)\n-- Overload: checks current user against an organization.\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.is_org_member(\n    p_org_id UUID\n)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT public.is_org_member(auth.uid(), p_org_id);\n$$","-- ============================================================================\n-- 1e. has_org_capability(p_org_id, p_capability_key)\n-- Checks if an organization has a specific capability.\n-- (Blueprint §5.2 — capability model)\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.has_org_capability(\n    p_org_id UUID,\n    p_capability_key TEXT\n)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT EXISTS (\n        SELECT 1\n        FROM public.organization_capabilities oc\n        JOIN public.organization_capability_types oct ON oct.id = oc.capability_type_id\n        WHERE oc.organization_id = p_org_id\n          AND oct.key = p_capability_key\n    );\n$$","-- ============================================================================\n-- 1f. has_current_user_capability(p_capability_key)\n-- Checks if ANY organization the current user belongs to has a capability.\n-- (Blueprint §4.4 — feature-level access check)\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.has_current_user_capability(\n    p_capability_key TEXT\n)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT EXISTS (\n        SELECT 1\n        FROM public.organization_memberships om\n        JOIN public.organization_capabilities oc ON oc.organization_id = om.organization_id\n        JOIN public.organization_capability_types oct ON oct.id = oc.capability_type_id\n        WHERE om.user_id = auth.uid()\n          AND om.status = 'active'\n          AND oct.key = p_capability_key\n    );\n$$","-- ============================================================================\n-- 1g. has_org_role(p_user_id, p_org_id, p_role_key)\n-- Checks if a user has a specific role within an organization.\n-- (Blueprint §5.3 — organization roles)\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.has_org_role(\n    p_user_id UUID,\n    p_org_id UUID,\n    p_role_key TEXT\n)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT EXISTS (\n        SELECT 1\n        FROM public.organization_memberships om\n        JOIN public.membership_roles mr ON mr.membership_id = om.id\n        JOIN public.organization_roles r ON r.id = mr.role_id\n        WHERE om.user_id = p_user_id\n          AND om.organization_id = p_org_id\n          AND om.status = 'active'\n          AND r.key = p_role_key\n    );\n$$","-- ============================================================================\n-- 1h. has_org_role(p_org_id, p_role_key)\n-- Overload: checks current user in an organization.\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.has_org_role(\n    p_org_id UUID,\n    p_role_key TEXT\n)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT public.has_org_role(auth.uid(), p_org_id, p_role_key);\n$$","-- ============================================================================\n-- 1i. is_org_admin()\n-- Convenience: checks if current user is an org_admin in ANY organization.\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.is_org_admin()\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT EXISTS (\n        SELECT 1\n        FROM public.organization_memberships om\n        JOIN public.membership_roles mr ON mr.membership_id = om.id\n        JOIN public.organization_roles r ON r.id = mr.role_id\n        WHERE om.user_id = auth.uid()\n          AND om.status = 'active'\n          AND r.key = 'org_admin'\n    );\n$$","-- ============================================================================\n-- 1j. is_org_admin(p_org_id)\n-- Convenience: checks if current user is an org_admin in a specific org.\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.is_org_admin(\n    p_org_id UUID\n)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT public.has_org_role(auth.uid(), p_org_id, 'org_admin');\n$$","-- ============================================================================\n-- 1k. can_access_program(p_user_id, p_program_id)\n-- Checks if a user can access a program (via org membership + program participation).\n-- Depends on programs + program_participants from migration 010.\n-- Safe to create now — resolves at runtime; returns false if tables don't exist.\n-- (Blueprint §6 — Program Engine)\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.can_access_program(\n    p_user_id UUID,\n    p_program_id UUID\n)\nRETURNS BOOLEAN\nLANGUAGE plpgsql\nSTABLE\nAS $$\nBEGIN\n    -- Return false if the programs table doesn't exist yet (migration 010 not applied)\n    IF NOT EXISTS (\n        SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'program_participants'\n    ) THEN\n        RETURN false;\n    END IF;\n\n    RETURN EXISTS (\n        SELECT 1\n        FROM public.organization_memberships om\n        JOIN public.program_participants pp ON pp.organization_id = om.organization_id\n        WHERE om.user_id = p_user_id\n          AND om.status = 'active'\n          AND pp.program_id = p_program_id\n          AND pp.status = 'active'\n    );\nEND;\n$$","-- ============================================================================\n-- 1l. can_access_program(p_program_id)\n-- Overload: checks current user against a program.\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.can_access_program(\n    p_program_id UUID\n)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT public.can_access_program(auth.uid(), p_program_id);\n$$","-- ============================================================================\n-- 1m. check_visibility(p_organization_id, p_visibility_scope)\n-- Reusable visibility check for multi-tenant tables.\n-- (Blueprint §4.2 — visibility scopes)\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.check_visibility(\n    p_organization_id UUID,\n    p_visibility_scope visibility_scope\n)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT\n        CASE p_visibility_scope\n            WHEN 'public' THEN true\n            WHEN 'organization' THEN public.is_org_member(p_organization_id)\n            WHEN 'program' THEN false  -- requires program_id context, handled per-policy\n            WHEN 'network' THEN\n                EXISTS (\n                    SELECT 1\n                    FROM public.organization_memberships om\n                    WHERE om.user_id = auth.uid()\n                      AND om.status = 'active'\n                )\n            ELSE false\n        END;\n$$","-- ############################################################################\n-- PART 1G: USER ORGANIZATIONS VIEW\n-- ############################################################################\n--\n-- Convenience view mapping users to their active organizations.\n-- Used throughout all engine RLS policies.\n-- ============================================================================\n\nCREATE OR REPLACE VIEW public.user_organizations AS\n    SELECT DISTINCT m.user_id, m.organization_id, r.key AS role\n    FROM public.organization_memberships m\n    JOIN public.membership_roles mr ON mr.membership_id = m.id\n    JOIN public.organization_roles r ON r.id = mr.role_id\n    WHERE m.status = 'active'","-- ############################################################################\n-- PART 2: ROW LEVEL SECURITY — ENABLE\n-- ############################################################################\n--\n-- (Blueprint §4 — every sensitive table must have RLS enabled)\n-- ============================================================================\n\nALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY","ALTER TABLE public.organization_capability_types ENABLE ROW LEVEL SECURITY","ALTER TABLE public.organization_capabilities ENABLE ROW LEVEL SECURITY","ALTER TABLE public.organization_roles ENABLE ROW LEVEL SECURITY","ALTER TABLE public.organization_memberships ENABLE ROW LEVEL SECURITY","ALTER TABLE public.membership_roles ENABLE ROW LEVEL SECURITY","ALTER TABLE public.user_profiles ENABLE ROW LEVEL SECURITY","ALTER TABLE public.identity_providers ENABLE ROW LEVEL SECURITY","ALTER TABLE public.external_identity_links ENABLE ROW LEVEL SECURITY","-- ############################################################################\n-- PART 3: RLS POLICIES — organizations\n-- ############################################################################\n--\n-- (Blueprint §20.1 — Sprint 0 acceptance: RLS isolation verified)\n-- ============================================================================\n\n-- SELECT:\n--   - Public/network visibility: all authenticated users\n--   - Organization scope: members only\n--   - Admins: full visibility across the network\nCREATE POLICY organizations_select ON public.organizations\n    FOR SELECT\n    USING (\n        auth.role() = 'authenticated'\n        AND (\n            visibility_scope IN ('public', 'network')\n            OR public.is_org_member(id)\n            OR public.is_org_admin()\n        )\n    )","-- INSERT: any authenticated user can create an org (they become creator)\nCREATE POLICY organizations_insert ON public.organizations\n    FOR INSERT\n    WITH CHECK (\n        auth.role() = 'authenticated'\n        AND created_by = auth.uid()\n    )","-- UPDATE: org_admins within their own org\nCREATE POLICY organizations_update ON public.organizations\n    FOR UPDATE\n    USING (public.is_org_admin(id))\n    WITH CHECK (public.is_org_admin(id))","-- DELETE: org_admins only\nCREATE POLICY organizations_delete ON public.organizations\n    FOR DELETE\n    USING (public.is_org_admin(id))","-- ############################################################################\n-- PART 4: RLS POLICIES — organization_capability_types\n-- ############################################################################\n\n-- SELECT: all authenticated users (reference data)\nCREATE POLICY org_cap_types_select ON public.organization_capability_types\n    FOR SELECT\n    USING (auth.role() = 'authenticated')","-- INSERT/UPDATE/DELETE: org_admin required\nCREATE POLICY org_cap_types_insert ON public.organization_capability_types\n    FOR INSERT\n    WITH CHECK (public.is_org_admin())","CREATE POLICY org_cap_types_update ON public.organization_capability_types\n    FOR UPDATE\n    USING (public.is_org_admin())","CREATE POLICY org_cap_types_delete ON public.organization_capability_types\n    FOR DELETE\n    USING (public.is_org_admin())","-- ############################################################################\n-- PART 5: RLS POLICIES — organization_capabilities\n-- ############################################################################\n\n-- SELECT: visible if the organization itself is visible\nCREATE POLICY org_capabilities_select ON public.organization_capabilities\n    FOR SELECT\n    USING (\n        auth.role() = 'authenticated'\n        AND EXISTS (\n            SELECT 1 FROM public.organizations o\n            WHERE o.id = organization_id\n            AND (\n                o.visibility_scope IN ('public', 'network')\n                OR public.is_org_member(o.id)\n            )\n        )\n    )","-- INSERT/UPDATE/DELETE: org_admin in the owning org\nCREATE POLICY org_capabilities_insert ON public.organization_capabilities\n    FOR INSERT\n    WITH CHECK (\n        created_by = auth.uid()\n        AND public.is_org_admin(organization_id)\n    )","CREATE POLICY org_capabilities_update ON public.organization_capabilities\n    FOR UPDATE\n    USING (public.is_org_admin(organization_id))\n    WITH CHECK (public.is_org_admin(organization_id))","CREATE POLICY org_capabilities_delete ON public.organization_capabilities\n    FOR DELETE\n    USING (public.is_org_admin(organization_id))","-- ############################################################################\n-- PART 6: RLS POLICIES — organization_roles\n-- ############################################################################\n\n-- SELECT: all authenticated users (reference data)\nCREATE POLICY org_roles_select ON public.organization_roles\n    FOR SELECT\n    USING (auth.role() = 'authenticated')","-- INSERT: org_admin\nCREATE POLICY org_roles_insert ON public.organization_roles\n    FOR INSERT\n    WITH CHECK (public.is_org_admin())","-- UPDATE: org_admin, cannot change is_system_role\nCREATE POLICY org_roles_update ON public.organization_roles\n    FOR UPDATE\n    USING (public.is_org_admin())\n    WITH CHECK (\n        public.is_org_admin()\n        AND is_system_role = (SELECT original.is_system_role FROM public.organization_roles original WHERE original.id = organization_roles.id)\n    )","-- DELETE: org_admin, cannot delete system roles\nCREATE POLICY org_roles_delete ON public.organization_roles\n    FOR DELETE\n    USING (\n        public.is_org_admin()\n        AND is_system_role = false\n    )","-- ############################################################################\n-- PART 7: RLS POLICIES — organization_memberships\n-- ############################################################################\n\n-- SELECT:\n--   - Users see their own memberships\n--   - Org_admins see all memberships in their org\n--   - Org members see other active members in the same org\nCREATE POLICY org_memberships_select_self ON public.organization_memberships\n    FOR SELECT\n    USING (user_id = auth.uid())","CREATE POLICY org_memberships_select_admin ON public.organization_memberships\n    FOR SELECT\n    USING (public.is_org_admin(organization_id))","CREATE POLICY org_memberships_select_members ON public.organization_memberships\n    FOR SELECT\n    USING (\n        status = 'active'\n        AND public.is_org_member(organization_id)\n    )","-- INSERT: org_admin or self-registration as 'invited'\nCREATE POLICY org_memberships_insert_admin ON public.organization_memberships\n    FOR INSERT\n    WITH CHECK (public.is_org_admin(organization_id))","CREATE POLICY org_memberships_insert_self ON public.organization_memberships\n    FOR INSERT\n    WITH CHECK (\n        user_id = auth.uid()\n        AND status = 'invited'\n    )","-- UPDATE: org_admin, or user accepting own invitation\nCREATE POLICY org_memberships_update_admin ON public.organization_memberships\n    FOR UPDATE\n    USING (public.is_org_admin(organization_id))\n    WITH CHECK (public.is_org_admin(organization_id))","CREATE POLICY org_memberships_update_self ON public.organization_memberships\n    FOR UPDATE\n    USING (user_id = auth.uid())\n    WITH CHECK (\n        user_id = auth.uid()\n        AND organization_id = (SELECT original.organization_id FROM public.organization_memberships original WHERE original.id = organization_memberships.id)\n    )","-- DELETE: org_admin or self\nCREATE POLICY org_memberships_delete_admin ON public.organization_memberships\n    FOR DELETE\n    USING (public.is_org_admin(organization_id))","CREATE POLICY org_memberships_delete_self ON public.organization_memberships\n    FOR DELETE\n    USING (user_id = auth.uid())","-- ############################################################################\n-- PART 8: RLS POLICIES — membership_roles\n-- ############################################################################\n\n-- SELECT: via parent membership visibility\nCREATE POLICY membership_roles_select_admin ON public.membership_roles\n    FOR SELECT\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.organization_memberships om\n            WHERE om.id = membership_id\n            AND public.is_org_admin(om.organization_id)\n        )\n    )","CREATE POLICY membership_roles_select_self ON public.membership_roles\n    FOR SELECT\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.organization_memberships om\n            WHERE om.id = membership_id\n            AND om.user_id = auth.uid()\n        )\n    )","-- INSERT/UPDATE/DELETE: org_admin only (via parent org)\nCREATE POLICY membership_roles_insert ON public.membership_roles\n    FOR INSERT\n    WITH CHECK (\n        EXISTS (\n            SELECT 1 FROM public.organization_memberships om\n            WHERE om.id = membership_id\n            AND public.is_org_admin(om.organization_id)\n        )\n    )","CREATE POLICY membership_roles_update ON public.membership_roles\n    FOR UPDATE\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.organization_memberships om\n            WHERE om.id = membership_id\n            AND public.is_org_admin(om.organization_id)\n        )\n    )","CREATE POLICY membership_roles_delete ON public.membership_roles\n    FOR DELETE\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.organization_memberships om\n            WHERE om.id = membership_id\n            AND public.is_org_admin(om.organization_id)\n        )\n    )","-- ############################################################################\n-- PART 9: RLS POLICIES — user_profiles\n-- ############################################################################\n\n-- SELECT: own profile, or org_admin seeing members\nCREATE POLICY user_profiles_select_self ON public.user_profiles\n    FOR SELECT\n    USING (id = auth.uid())","CREATE POLICY user_profiles_select_admin ON public.user_profiles\n    FOR SELECT\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.organization_memberships om\n            WHERE om.user_id = user_profiles.id\n            AND public.is_org_admin(om.organization_id)\n        )\n    )","-- UPDATE: users update non-critical own fields only\nCREATE POLICY user_profiles_update_self ON public.user_profiles\n    FOR UPDATE\n    USING (id = auth.uid())\n    WITH CHECK (\n        id = auth.uid()\n        AND email = (SELECT original.email FROM public.user_profiles original WHERE original.id = user_profiles.id)  -- email managed by auth provider, not direct update\n    )","-- ############################################################################\n-- PART 10: RLS POLICIES — identity_providers\n-- ############################################################################\n\n-- SELECT: all authenticated users\nCREATE POLICY identity_providers_select ON public.identity_providers\n    FOR SELECT\n    USING (auth.role() = 'authenticated')","-- INSERT/UPDATE/DELETE: org_admin only\nCREATE POLICY identity_providers_insert ON public.identity_providers\n    FOR INSERT\n    WITH CHECK (public.is_org_admin())","CREATE POLICY identity_providers_update ON public.identity_providers\n    FOR UPDATE\n    USING (public.is_org_admin())","CREATE POLICY identity_providers_delete ON public.identity_providers\n    FOR DELETE\n    USING (public.is_org_admin())","-- ############################################################################\n-- PART 11: RLS POLICIES — external_identity_links\n-- ############################################################################\n\n-- SELECT: users see their own links\nCREATE POLICY ext_identity_links_select_self ON public.external_identity_links\n    FOR SELECT\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.user_profiles up\n            WHERE up.id = user_profile_id\n            AND up.id = auth.uid()\n        )\n    )","-- INSERT/DELETE: users manage their own links\nCREATE POLICY ext_identity_links_insert_self ON public.external_identity_links\n    FOR INSERT\n    WITH CHECK (\n        EXISTS (\n            SELECT 1 FROM public.user_profiles up\n            WHERE up.id = user_profile_id\n            AND up.id = auth.uid()\n        )\n    )","CREATE POLICY ext_identity_links_delete_self ON public.external_identity_links\n    FOR DELETE\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.user_profiles up\n            WHERE up.id = user_profile_id\n            AND up.id = auth.uid()\n        )\n    )","-- ############################################################################\n-- PART 12: SPRINT 1 TODOs\n-- ############################################################################\n--\n-- TODO Sprint 1: Introduce platform_admin role for managing global reference data:\n--   - organization_capability_types (INSERT/UPDATE/DELETE)\n--   - organization_roles (INSERT/UPDATE/DELETE)\n--   Currently gated by is_org_admin() which allows any org admin to modify global data.\n--\n-- TODO Sprint 1: Add onboarding status for organizations:\n--   pending_review / active / suspended\n--   Currently all orgs are immediately visible at network scope after creation.\n--   An onboarding workflow would gate visibility until review.\n-- ============================================================================\n\n-- ############################################################################\n-- PART 13: VERIFICATION\n-- ############################################################################\n--\n-- Run after migration to list all policies:\n--   SELECT * FROM pg_policies WHERE schemaname = 'public'\n--   ORDER BY tablename, policyname;\n-- ============================================================================\n\n-- ============================================================================\n-- END OF MIGRATION 009 — Sprint 0B: RLS Foundation\n-- ============================================================================"}	rls_foundation
010	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 0C: Audit & Programs\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Design: ADR-002 — Audit from Sprint 0, Program-centric architecture\n-- Blueprint: §6 — Program Engine, §4.2 — Visibility Scopes\n-- Dependencies: 008_organizations_capabilities.sql, 009_rls_foundation.sql\n--\n-- This migration creates:\n--   1. audit_events — unified audit trail (immutable log)\n--   2. programs — cross-organization collaboration units\n--   3. program_participants — orgs within programs\n--   4. program_access_policies — data sharing rules\n--\n-- Design principles:\n--   - \\"No audit = no action\\" (Blueprint §2.4)\n--   - Program is the central object (Blueprint §2.6)\n--   - Every table has RLS + updated_at triggers (Blueprint §19.2)\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: ENUMS\n-- ############################################################################\n\n-- Audit action types (Blueprint §2.4)\nDO $$ BEGIN\n    CREATE TYPE audit_action AS ENUM (\n        'create', 'read', 'update', 'delete',\n        'login', 'logout',\n        'invite', 'approve', 'reject', 'submit', 'withdraw',\n        'fulfill', 'complete', 'cancel',\n        'system', 'other'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- Resource types tracked in audit (extensible)\nDO $$ BEGIN\n    CREATE TYPE audit_resource_type AS ENUM (\n        'organization',\n        'organization_membership',\n        'organization_capability',\n        'user_profile',\n        'program',\n        'program_participant',\n        'program_access_policy',\n        'supply_item',\n        'collection',\n        'donor',\n        'sample',\n        'access_request',\n        'negotiation_message',\n        'exchange_deal',\n        'chain_telemetry',\n        'identity_provider',\n        'other'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- Program lifecycle (Blueprint §6.2)\nDO $$ BEGIN\n    CREATE TYPE program_status AS ENUM (\n        'draft', 'active', 'paused', 'completed', 'archived', 'cancelled'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- Participant roles within a program (Blueprint §6.4)\nDO $$ BEGIN\n    CREATE TYPE participant_role AS ENUM (\n        'sponsor',      -- funds the program\n        'lead',         -- leads/coordinates\n        'contributor',  -- contributes data or samples\n        'consumer',     -- consumes data or samples\n        'processor',    -- processes samples or data\n        'reviewer',     -- reviews access requests\n        'observer'      -- read-only access\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- Participant status lifecycle\nDO $$ BEGIN\n    CREATE TYPE participant_status AS ENUM (\n        'invited', 'active', 'suspended', 'inactive', 'removed'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- Data sharing scope within programs (Blueprint §6.5)\nDO $$ BEGIN\n    CREATE TYPE data_sharing_scope AS ENUM (\n        'no_sharing',           -- coordination only\n        'metadata_only',        -- catalog-level metadata\n        'aggregate_only',       -- counts and summaries\n        'de_identified',        -- de-identified individual-level\n        'pseudonymized',        -- pseudonymized (Multi-PID protected)\n        'identified',           -- fully identified (limited, audited)\n        'full_access'           -- unrestricted within program\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: TABLE — audit_events\n-- ############################################################################\n--\n-- Unified audit trail for all significant actions.\n-- Immutable: no UPDATE or DELETE policies.\n-- (Blueprint §2.4 — \\"No audit = no action\\", Sprint 0 requirement)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.audit_events (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n\n    -- Who\n    actor_id            UUID NOT NULL,\n    actor_email         TEXT,                             -- denormalized for speed\n    impersonated_by     UUID,\n\n    -- What\n    action              audit_action NOT NULL,\n    resource_type       audit_resource_type NOT NULL,\n    resource_id         UUID,\n    resource_owner_org_id UUID,\n\n    -- Context\n    organization_id     UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\n    program_id          UUID,                             -- FK added in this migration (no cycle)\n    session_id          TEXT,\n    ip_address          INET,\n    user_agent          TEXT,\n\n    -- Details\n    old_values          JSONB,\n    new_values          JSONB,\n    summary             TEXT,\n    metadata            JSONB DEFAULT '{}',\n\n    -- Timing\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","-- Indexes for common audit queries\nCREATE INDEX IF NOT EXISTS idx_audit_actor\n    ON public.audit_events(actor_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_audit_resource\n    ON public.audit_events(resource_type, resource_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_audit_org\n    ON public.audit_events(organization_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_audit_program\n    ON public.audit_events(program_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_audit_created\n    ON public.audit_events(created_at DESC)","COMMENT ON TABLE public.audit_events IS\n    'Unified audit trail. Immutable log — no UPDATE or DELETE.'","-- ############################################################################\n-- PART 3: TABLE — programs\n-- ############################################################################\n--\n-- The central object of Kadarn. A program is a cross-organization\n-- collaboration around biospecimen and/or clinical data needs.\n-- (Blueprint §6 — Program Engine, §2.6 — Program-Centric)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.programs (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n\n    -- Identity\n    name                TEXT NOT NULL,\n    short_name          TEXT,\n    description         TEXT,\n    program_identifier  TEXT UNIQUE,                      -- external ID (NCT, grant, etc.)\n\n    -- Classification\n    program_type        TEXT[] DEFAULT '{}',\n    therapeutic_areas   TEXT[] DEFAULT '{}',\n    diseases            JSONB DEFAULT '[]',\n\n    -- Timeline\n    start_date          DATE,\n    end_date            DATE,\n    status              program_status NOT NULL DEFAULT 'draft',\n\n    -- Governance\n    sponsor_org_id      UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\n    lead_org_id         UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\n    created_by_organization_id UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\n\n    -- Data sharing defaults (Blueprint §6.5)\n    default_data_scope  data_sharing_scope NOT NULL DEFAULT 'metadata_only',\n    allow_commercial_use BOOLEAN NOT NULL DEFAULT false,\n    require_ethics_approval BOOLEAN NOT NULL DEFAULT true,\n\n    -- Visibility\n    visibility_scope    visibility_scope NOT NULL DEFAULT 'network',\n\n    -- Audit\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_programs_status\n    ON public.programs(status)","CREATE INDEX IF NOT EXISTS idx_programs_sponsor\n    ON public.programs(sponsor_org_id)","CREATE INDEX IF NOT EXISTS idx_programs_lead\n    ON public.programs(lead_org_id)","CREATE INDEX IF NOT EXISTS idx_programs_visibility\n    ON public.programs(visibility_scope)","COMMENT ON TABLE public.programs IS\n    'Central object. Cross-organization collaboration units.'","-- The creating org must be known for RLS on first participant insert\nALTER TABLE public.programs\nADD CONSTRAINT programs_created_by_org_required\nCHECK (created_by_organization_id IS NOT NULL) NOT VALID","-- ############################################################################\n-- PART 4: TABLE — program_participants\n-- ############################################################################\n--\n-- Which organizations participate in which programs, and in what role.\n-- Core of multi-tenant program-based data sharing.\n-- (Blueprint §6.4 — participant roles)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.program_participants (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    program_id          UUID NOT NULL REFERENCES public.programs(id) ON DELETE CASCADE,\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    role                participant_role NOT NULL DEFAULT 'contributor',\n    status              participant_status NOT NULL DEFAULT 'invited',\n\n    data_scope_override data_sharing_scope,               -- NULL = use program default\n\n    invited_at          TIMESTAMPTZ,\n    joined_at           TIMESTAMPTZ,\n    deactivated_at      TIMESTAMPTZ,\n    deactivated_reason  TEXT,\n\n    primary_contact_id  UUID,\n\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (program_id, organization_id)\n)","CREATE INDEX IF NOT EXISTS idx_prog_participants_program\n    ON public.program_participants(program_id)","CREATE INDEX IF NOT EXISTS idx_prog_participants_org\n    ON public.program_participants(organization_id)","CREATE INDEX IF NOT EXISTS idx_prog_participants_status\n    ON public.program_participants(status)","CREATE INDEX IF NOT EXISTS idx_prog_participants_role\n    ON public.program_participants(role)","COMMENT ON TABLE public.program_participants IS\n    'Organizations participating in programs. Core of multi-tenant data sharing.'","-- ############################################################################\n-- PART 5: TABLE — program_access_policies\n-- ############################################################################\n--\n-- Fine-grained data sharing rules within a program.\n-- (Blueprint §6.5 — data sharing scopes)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.program_access_policies (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    program_id          UUID NOT NULL REFERENCES public.programs(id) ON DELETE CASCADE,\n\n    name                TEXT NOT NULL,\n    description         TEXT,\n    policy_type         TEXT NOT NULL DEFAULT 'default',\n\n    resource_type       audit_resource_type,               -- NULL = all types\n    target_role         participant_role,                  -- NULL = all roles\n\n    allowed_data_scope  data_sharing_scope NOT NULL DEFAULT 'metadata_only',\n    allow_export        BOOLEAN NOT NULL DEFAULT false,\n    require_approval    BOOLEAN NOT NULL DEFAULT false,\n    max_record_count    INTEGER,\n\n    valid_from          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    valid_until         TIMESTAMPTZ,\n\n    approved_by         UUID,\n    approval_ref        TEXT,\n    metadata            JSONB DEFAULT '{}',\n\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_prog_access_policies_program\n    ON public.program_access_policies(program_id)","CREATE INDEX IF NOT EXISTS idx_prog_access_policies_type\n    ON public.program_access_policies(policy_type)","CREATE INDEX IF NOT EXISTS idx_prog_access_policies_valid\n    ON public.program_access_policies(program_id, valid_from, valid_until)\n    WHERE valid_until IS NULL","COMMENT ON TABLE public.program_access_policies IS\n    'Data sharing rules within programs. Controls role-based access to resource types.'","-- ############################################################################\n-- PART 6: TRIGGERS — updated_at\n-- ############################################################################\n\nCREATE TRIGGER trg_programs_updated_at\n    BEFORE UPDATE ON public.programs\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_program_participants_updated_at\n    BEFORE UPDATE ON public.program_participants\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_program_access_policies_updated_at\n    BEFORE UPDATE ON public.program_access_policies\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","-- ############################################################################\n-- PART 7: AUDIT EVENT HELPERS\n-- ############################################################################\n--\n-- Functions to emit audit events from triggers or application code.\n-- (Blueprint §2.4 — audit from Sprint 0)\n-- ============================================================================\n\n-- Low-level function to emit a single audit event\nCREATE OR REPLACE FUNCTION public.emit_audit_event(\n    p_action            audit_action,\n    p_resource_type     audit_resource_type,\n    p_resource_id       UUID,\n    p_resource_owner_org_id UUID DEFAULT NULL,\n    p_organization_id   UUID DEFAULT NULL,\n    p_program_id        UUID DEFAULT NULL,\n    p_summary           TEXT DEFAULT NULL,\n    p_old_values        JSONB DEFAULT NULL,\n    p_new_values        JSONB DEFAULT NULL,\n    p_metadata          JSONB DEFAULT '{}'\n)\nRETURNS UUID\nSECURITY DEFINER\nSET search_path = public\nLANGUAGE plpgsql\nAS $$\nDECLARE\n    v_id UUID;\n    v_actor_email TEXT;\nBEGIN\n    BEGIN\n        v_actor_email := auth.jwt() ->> 'email';\n    EXCEPTION WHEN OTHERS THEN\n        v_actor_email := NULL;\n    END;\n\n    INSERT INTO public.audit_events (\n        actor_id, actor_email, action, resource_type, resource_id,\n        resource_owner_org_id, organization_id, program_id, summary,\n        old_values, new_values, metadata\n    ) VALUES (\n        COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000'),\n        v_actor_email, p_action, p_resource_type, p_resource_id,\n        p_resource_owner_org_id, p_organization_id, p_program_id, p_summary,\n        p_old_values, p_new_values, p_metadata\n    )\n    RETURNING id INTO v_id;\n\n    RETURN v_id;\nEND;\n$$","-- Trigger function: generic audit for any table\n-- Attach with: CREATE TRIGGER ... AFTER INSERT OR UPDATE OR DELETE\nCREATE OR REPLACE FUNCTION public.audit_table_trigger()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nDECLARE\n    v_action audit_action;\n    v_resource_type audit_resource_type;\n    v_summary TEXT;\n    v_old_json JSONB;\n    v_new_json JSONB;\nBEGIN\n    IF TG_OP = 'INSERT' THEN\n        v_action := 'create';\n        v_new_json := to_jsonb(NEW);\n        v_summary := TG_TABLE_NAME || ' created';\n    ELSIF TG_OP = 'UPDATE' THEN\n        v_action := 'update';\n        v_old_json := to_jsonb(OLD);\n        v_new_json := to_jsonb(NEW);\n        v_summary := TG_TABLE_NAME || ' updated';\n    ELSIF TG_OP = 'DELETE' THEN\n        v_action := 'delete';\n        v_old_json := to_jsonb(OLD);\n        v_summary := TG_TABLE_NAME || ' deleted';\n        v_new_json := NULL;\n    ELSE\n        RETURN NULL;\n    END IF;\n\n    BEGIN\n        -- Map plural table names to singular enum values\n        v_resource_type := CASE TG_TABLE_NAME\n            WHEN 'programs' THEN 'program'::audit_resource_type\n            WHEN 'organizations' THEN 'organization'::audit_resource_type\n            WHEN 'organization_memberships' THEN 'organization_membership'::audit_resource_type\n            WHEN 'organization_capabilities' THEN 'organization_capability'::audit_resource_type\n            WHEN 'user_profiles' THEN 'user_profile'::audit_resource_type\n            WHEN 'program_participants' THEN 'program_participant'::audit_resource_type\n            WHEN 'program_access_policies' THEN 'program_access_policy'::audit_resource_type\n            WHEN 'identity_providers' THEN 'identity_provider'::audit_resource_type\n            ELSE TG_TABLE_NAME::audit_resource_type\n        END;\n    EXCEPTION WHEN others THEN\n        v_resource_type := 'other';\n    END;\n\n    PERFORM public.emit_audit_event(\n        p_action        => v_action,\n        p_resource_type => v_resource_type,\n        p_resource_id   => COALESCE(NEW.id, OLD.id),\n        p_summary       => v_summary,\n        p_old_values    => v_old_json,\n        p_new_values    => v_new_json\n    );\n\n    RETURN COALESCE(NEW, OLD);\nEND;\n$$","-- ############################################################################\n-- PART 8: RLS — ENABLE\n-- ############################################################################\n\nALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY","ALTER TABLE public.programs ENABLE ROW LEVEL SECURITY","ALTER TABLE public.program_participants ENABLE ROW LEVEL SECURITY","ALTER TABLE public.program_access_policies ENABLE ROW LEVEL SECURITY","-- ############################################################################\n-- PART 9: RLS POLICIES — audit_events\n-- ############################################################################\n--\n-- Audit is an immutable log: SELECT and INSERT only, no UPDATE or DELETE.\n-- (Blueprint §2.4)\n-- ============================================================================\n\n-- SELECT: users see their own events; org_admins see org events\nCREATE POLICY audit_events_select_self ON public.audit_events\n    FOR SELECT\n    USING (actor_id = auth.uid())","CREATE POLICY audit_events_select_admin ON public.audit_events\n    FOR SELECT\n    USING (public.is_org_admin(organization_id))","-- INSERT: any authenticated user (emit_audit_event is SECURITY DEFINER)\nCREATE POLICY audit_events_insert ON public.audit_events\n    FOR INSERT\n    WITH CHECK (actor_id = auth.uid())","-- ############################################################################\n-- PART 10: RLS POLICIES — programs\n-- ############################################################################\n--\n-- (Blueprint §6 — Program Engine, §20.1 — Sprint 0 acceptance)\n-- ============================================================================\n\n-- SELECT:\n--   - Participants of the program\n--   - Network/public visibility\n--   - Org_admins\nCREATE POLICY programs_select ON public.programs\n    FOR SELECT\n    USING (\n        auth.role() = 'authenticated'\n        AND (\n            visibility_scope IN ('public', 'network')\n            OR EXISTS (\n                SELECT 1 FROM public.program_participants pp\n                WHERE pp.program_id = id\n                  AND pp.status = 'active'\n                  AND public.is_org_member(pp.organization_id)\n            )\n            OR public.is_org_admin()\n        )\n    )","-- INSERT: any authenticated user (creator)\nCREATE POLICY programs_insert ON public.programs\n    FOR INSERT\n    WITH CHECK (\n        auth.role() = 'authenticated'\n        AND created_by = auth.uid()\n    )","-- UPDATE: sponsor or lead org_admin\nCREATE POLICY programs_update ON public.programs\n    FOR UPDATE\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.program_participants pp\n            WHERE pp.program_id = id\n              AND pp.role IN ('sponsor', 'lead')\n              AND pp.status = 'active'\n              AND public.is_org_admin(pp.organization_id)\n        )\n    )","-- DELETE: sponsor or lead org_admin\nCREATE POLICY programs_delete ON public.programs\n    FOR DELETE\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.program_participants pp\n            WHERE pp.program_id = id\n              AND pp.role IN ('sponsor', 'lead')\n              AND pp.status = 'active'\n              AND public.is_org_admin(pp.organization_id)\n        )\n    )","-- ############################################################################\n-- PART 11: RLS POLICIES — program_participants\n-- ############################################################################\n\n-- SELECT: org members of participating orgs, or org_admin\nCREATE POLICY program_participants_select ON public.program_participants\n    FOR SELECT\n    USING (\n        public.is_org_member(organization_id)\n        OR public.is_org_admin()\n    )","-- INSERT: sponsor/lead org_admin of the program\nDROP POLICY IF EXISTS program_participants_insert ON public.program_participants","CREATE POLICY program_participants_insert ON public.program_participants\n    FOR INSERT\n    WITH CHECK (\n        created_by = auth.uid()\n        AND (\n            -- First participant: creator org of the program\n            organization_id = (\n                SELECT p.created_by_organization_id\n                FROM public.programs p\n                WHERE p.id = program_id\n                  AND p.created_by = auth.uid()\n            )\n            OR\n            -- Subsequent participants: active sponsor/lead org admin\n            EXISTS (\n                SELECT 1\n                FROM public.program_participants pp\n                WHERE pp.program_id = program_id\n                  AND pp.role IN ('sponsor', 'lead')\n                  AND pp.status = 'active'\n                  AND public.is_org_admin(pp.organization_id)\n            )\n        )\n    )","-- UPDATE: sponsor/lead org_admin\nCREATE POLICY program_participants_update ON public.program_participants\n    FOR UPDATE\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.program_participants pp\n            WHERE pp.program_id = program_id\n              AND pp.role IN ('sponsor', 'lead')\n              AND pp.status = 'active'\n              AND public.is_org_admin(pp.organization_id)\n        )\n    )","-- DELETE: sponsor/lead org_admin\nCREATE POLICY program_participants_delete ON public.program_participants\n    FOR DELETE\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.program_participants pp\n            WHERE pp.program_id = program_id\n              AND pp.role IN ('sponsor', 'lead')\n              AND pp.status = 'active'\n              AND public.is_org_admin(pp.organization_id)\n        )\n    )","-- ############################################################################\n-- PART 12: RLS POLICIES — program_access_policies\n-- ############################################################################\n\n-- SELECT: program participants\nCREATE POLICY program_access_policies_select ON public.program_access_policies\n    FOR SELECT\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.program_participants pp\n            WHERE pp.program_id = program_id\n              AND pp.status = 'active'\n              AND public.is_org_member(pp.organization_id)\n        )\n    )","-- INSERT/UPDATE/DELETE: program sponsor/lead org_admin\nCREATE POLICY program_access_policies_insert ON public.program_access_policies\n    FOR INSERT\n    WITH CHECK (\n        created_by = auth.uid()\n        AND EXISTS (\n            SELECT 1 FROM public.program_participants pp\n            WHERE pp.program_id = program_id\n              AND pp.role IN ('sponsor', 'lead')\n              AND pp.status = 'active'\n              AND public.is_org_admin(pp.organization_id)\n        )\n    )","CREATE POLICY program_access_policies_update ON public.program_access_policies\n    FOR UPDATE\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.program_participants pp\n            WHERE pp.program_id = program_id\n              AND pp.role IN ('sponsor', 'lead')\n              AND pp.status = 'active'\n              AND public.is_org_admin(pp.organization_id)\n        )\n    )","CREATE POLICY program_access_policies_delete ON public.program_access_policies\n    FOR DELETE\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.program_participants pp\n            WHERE pp.program_id = program_id\n              AND pp.role IN ('sponsor', 'lead')\n              AND pp.status = 'active'\n              AND public.is_org_admin(pp.organization_id)\n        )\n    )","-- ############################################################################\n-- PART 13: AUDIT TRIGGERS — programs\n-- ############################################################################\n--\n-- Automatic audit events for program lifecycle changes.\n-- (Blueprint §20.1 — Sprint 0 acceptance: audit captures critical actions)\n-- ============================================================================\n\nCREATE TRIGGER trg_programs_audit\n    AFTER INSERT OR UPDATE OR DELETE ON public.programs\n    FOR EACH ROW EXECUTE FUNCTION public.audit_table_trigger()","CREATE TRIGGER trg_program_participants_audit\n    AFTER INSERT OR UPDATE OR DELETE ON public.program_participants\n    FOR EACH ROW EXECUTE FUNCTION public.audit_table_trigger()","CREATE TRIGGER trg_program_access_policies_audit\n    AFTER INSERT OR UPDATE OR DELETE ON public.program_access_policies\n    FOR EACH ROW EXECUTE FUNCTION public.audit_table_trigger()","-- ============================================================================\n-- END OF MIGRATION 010 — Sprint 0C: Audit & Programs\n-- ============================================================================\n-- Next: 011_seed_data.sql — demo organizations, users, programs\n-- ============================================================================"}	audit_programs
011	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 0D: Seed Data\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Dependencies: 008_organizations_capabilities.sql, 009_rls_foundation.sql,\n--               010_audit_programs.sql\n--\n-- Seeds demo data covering all actor types from Blueprint §3:\n--   ✅ sponsor, CRO, clinical_site, biobank, lab, courier, IRB\n--   ✅ Users with memberships and roles\n--   ✅ Programs connecting multiple organizations\n--   ✅ Program access policies\n--\n-- (Blueprint §20 — Sprint 0 acceptance criteria)\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: HELPER — ensure seed idempotency\n-- ############################################################################\n--\n-- We use ON CONFLICT DO NOTHING and manual UUIDs so the seed can be\n-- re-run safely. All IDs are fixed for test consistency.\n-- ============================================================================\n\n-- ############################################################################\n-- PART 2: ORGANIZATIONS\n-- ############################################################################\n--\n-- 7 organizations covering the 7 required actor types.\n-- (Blueprint §3 — Ecosystem map: Sites, Labs, Biobanks, Sponsors, etc.)\n-- ============================================================================\n\nINSERT INTO public.organizations (id, name, legal_name, country, region, description, created_by, visibility_scope) VALUES\n    ('a0000000-0000-0000-0000-000000000001', 'PharmaCorp',       'PharmaCorp International Inc.',  'US', 'Massachusetts',  'Global pharmaceutical company funding oncology and rare disease programs',                    '00000000-0000-0000-0000-000000000000', 'network'),\n    ('a0000000-0000-0000-0000-000000000002', 'ClinResearch CRO', 'ClinResearch Organization LLC',   'US', 'North Carolina',  'Full-service CRO managing multi-site biospecimen programs',                                   '00000000-0000-0000-0000-000000000000', 'network'),\n    ('a0000000-0000-0000-0000-000000000003', 'Univ Medical Center', 'University Medical Center',   'US', 'California',     'Academic medical center with clinical research site and biorepository',                       '00000000-0000-0000-0000-000000000000', 'network'),\n    ('a0000000-0000-0000-0000-000000000004', 'National Biobank', 'National Biobank Repository',      'US', 'Maryland',       'Large-scale biobank with 500K+ samples across 50+ collections',                               '00000000-0000-0000-0000-000000000000', 'network'),\n    ('a0000000-0000-0000-0000-000000000005', 'Advanced Path Lab','Advanced Pathology Laboratories',  'DE', 'Bavaria',        'ISO 20387-certified laboratory specializing in IHC, NGS, and digital pathology',              '00000000-0000-0000-0000-000000000000', 'network'),\n    ('a0000000-0000-0000-0000-000000000006', 'Global Cold Chain','Global Cold Chain Logistics GmbH', 'DE', 'Hesse',          'Cold-chain logistics provider specializing in UN 3373 biological substances',                 '00000000-0000-0000-0000-000000000000', 'network'),\n    ('a0000000-0000-0000-0000-000000000007', 'Central IRB',      'Central Ethics Review Board',     'US', 'District of Columbia', 'Central IRB providing ethics review for multi-site biospecimen programs',                   '00000000-0000-0000-0000-000000000000', 'network')\nON CONFLICT (id) DO NOTHING","-- ############################################################################\n-- PART 3: ORGANIZATION CAPABILITIES\n-- ############################################################################\n--\n-- Each org gets its primary capability(s).\n-- (Blueprint §5.2 — capability types)\n-- ============================================================================\n\n-- PharmaCorp → sponsor\nINSERT INTO public.organization_capabilities (organization_id, capability_type_id, is_primary, created_by)\nSELECT 'a0000000-0000-0000-0000-000000000001', id, true, '00000000-0000-0000-0000-000000000000'\nFROM public.organization_capability_types WHERE key = 'sponsor'\nON CONFLICT DO NOTHING","-- ClinResearch CRO → cro\nINSERT INTO public.organization_capabilities (organization_id, capability_type_id, is_primary, created_by)\nSELECT 'a0000000-0000-0000-0000-000000000002', id, true, '00000000-0000-0000-0000-000000000000'\nFROM public.organization_capability_types WHERE key = 'cro'\nON CONFLICT DO NOTHING","-- Univ Medical Center → clinical_site + biobank\nINSERT INTO public.organization_capabilities (organization_id, capability_type_id, is_primary, created_by)\nSELECT 'a0000000-0000-0000-0000-000000000003', id, true, '00000000-0000-0000-0000-000000000000'\nFROM public.organization_capability_types WHERE key = 'clinical_site'\nON CONFLICT DO NOTHING","INSERT INTO public.organization_capabilities (organization_id, capability_type_id, is_primary, created_by)\nSELECT 'a0000000-0000-0000-0000-000000000003', id, false, '00000000-0000-0000-0000-000000000000'\nFROM public.organization_capability_types WHERE key = 'biobank'\nON CONFLICT DO NOTHING","-- National Biobank → biobank + storage_facility\nINSERT INTO public.organization_capabilities (organization_id, capability_type_id, is_primary, created_by)\nSELECT 'a0000000-0000-0000-0000-000000000004', id, true, '00000000-0000-0000-0000-000000000000'\nFROM public.organization_capability_types WHERE key = 'biobank'\nON CONFLICT DO NOTHING","INSERT INTO public.organization_capabilities (organization_id, capability_type_id, is_primary, created_by)\nSELECT 'a0000000-0000-0000-0000-000000000004', id, false, '00000000-0000-0000-0000-000000000000'\nFROM public.organization_capability_types WHERE key = 'storage_facility'\nON CONFLICT DO NOTHING","-- Advanced Path Lab → processing_lab + diagnostic_lab\nINSERT INTO public.organization_capabilities (organization_id, capability_type_id, is_primary, created_by)\nSELECT 'a0000000-0000-0000-0000-000000000005', id, true, '00000000-0000-0000-0000-000000000000'\nFROM public.organization_capability_types WHERE key = 'processing_lab'\nON CONFLICT DO NOTHING","INSERT INTO public.organization_capabilities (organization_id, capability_type_id, is_primary, created_by)\nSELECT 'a0000000-0000-0000-0000-000000000005', id, false, '00000000-0000-0000-0000-000000000000'\nFROM public.organization_capability_types WHERE key = 'diagnostic_lab'\nON CONFLICT DO NOTHING","-- Global Cold Chain → logistics_vendor\nINSERT INTO public.organization_capabilities (organization_id, capability_type_id, is_primary, created_by)\nSELECT 'a0000000-0000-0000-0000-000000000006', id, true, '00000000-0000-0000-0000-000000000000'\nFROM public.organization_capability_types WHERE key = 'logistics_vendor'\nON CONFLICT DO NOTHING","-- Central IRB → irb\nINSERT INTO public.organization_capabilities (organization_id, capability_type_id, is_primary, created_by)\nSELECT 'a0000000-0000-0000-0000-000000000007', id, true, '00000000-0000-0000-0000-000000000000'\nFROM public.organization_capability_types WHERE key = 'irb'\nON CONFLICT DO NOTHING","-- ############################################################################\n-- PART 4: USERS (via auth.users + user_profiles)\n-- ############################################################################\n--\n-- One user per organization plus a platform-level admin.\n-- Passwords are for local dev only (Test123!).\n-- Uses admin_create_user (defined in migration 008).\n-- ============================================================================\n\n-- Platform admin (cross-org, not tied to a single org)\nSELECT public.admin_create_user(\n    'admin@kadarn.test', 'Test123!', 'Kadarn Admin'\n)","-- PharmaCorp (sponsor)\nSELECT public.admin_create_user(\n    'sponsor@kadarn.test', 'Test123!', 'Sarah Chen',\n    'a0000000-0000-0000-0000-000000000001'\n)","-- ClinResearch CRO\nSELECT public.admin_create_user(\n    'cro@kadarn.test', 'Test123!', 'Miguel Torres',\n    'a0000000-0000-0000-0000-000000000002'\n)","-- Univ Medical Center (site + biobank)\nSELECT public.admin_create_user(\n    'site@kadarn.test', 'Test123!', 'Emily Nakamura',\n    'a0000000-0000-0000-0000-000000000003'\n)","-- National Biobank\nSELECT public.admin_create_user(\n    'biobank@kadarn.test', 'Test123!', 'James Okafor',\n    'a0000000-0000-0000-0000-000000000004'\n)","-- Advanced Path Lab\nSELECT public.admin_create_user(\n    'lab@kadarn.test', 'Test123!', 'Anna Weber',\n    'a0000000-0000-0000-0000-000000000005'\n)","-- Global Cold Chain\nSELECT public.admin_create_user(\n    'courier@kadarn.test', 'Test123!', 'Klaus Mueller',\n    'a0000000-0000-0000-0000-000000000006'\n)","-- Central IRB\nSELECT public.admin_create_user(\n    'irb@kadarn.test', 'Test123!', 'Patricia Okonkwo',\n    'a0000000-0000-0000-0000-000000000007'\n)","-- ############################################################################\n-- PART 5: ORG_ADMIN ROLES FOR SEED USERS\n-- ############################################################################\n--\n-- Assign org_admin role to each org's user so they can manage their org\n-- in smoke tests and development.\n-- ============================================================================\n\n-- Grant org_admin to each org's primary user\nINSERT INTO public.membership_roles (membership_id, role_id, assigned_by)\nSELECT om.id, r.id, om.user_id\nFROM public.organization_memberships om\nCROSS JOIN public.organization_roles r\nWHERE r.key = 'org_admin'\n  AND om.status = 'active'\n  -- Only for memberships created by admin_create_user (where invited_by = user_id)\n  AND om.invited_by = om.user_id\nON CONFLICT DO NOTHING","-- Also give the platform admin org_admin at PharmaCorp (for testing)\nINSERT INTO public.organization_memberships (user_id, organization_id, status, invited_by, invited_at, joined_at)\nSELECT up.id, 'a0000000-0000-0000-0000-000000000001', 'active', up.id, now(), now()\nFROM public.user_profiles up\nWHERE up.email = 'admin@kadarn.test'\n  AND NOT EXISTS (\n    SELECT 1 FROM public.organization_memberships om\n    WHERE om.user_id = up.id AND om.organization_id = 'a0000000-0000-0000-0000-000000000001'\n  )","INSERT INTO public.membership_roles (membership_id, role_id, assigned_by)\nSELECT om.id, r.id, om.user_id\nFROM public.organization_memberships om\nCROSS JOIN public.organization_roles r\nWHERE r.key = 'org_admin'\n  AND om.user_id = (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test')\n  AND om.organization_id = 'a0000000-0000-0000-0000-000000000001'\n  AND NOT EXISTS (\n    SELECT 1 FROM public.membership_roles mr WHERE mr.membership_id = om.id AND mr.role_id = r.id\n  )","-- Also add the admin to Central IRB (multi-org user for RLS testing)\nINSERT INTO public.organization_memberships (user_id, organization_id, status, invited_by, invited_at, joined_at)\nSELECT up.id, 'a0000000-0000-0000-0000-000000000007', 'active', up.id, now(), now()\nFROM public.user_profiles up\nWHERE up.email = 'admin@kadarn.test'\n  AND NOT EXISTS (\n    SELECT 1 FROM public.organization_memberships om\n    WHERE om.user_id = up.id AND om.organization_id = 'a0000000-0000-0000-0000-000000000007'\n  )","INSERT INTO public.membership_roles (membership_id, role_id, assigned_by)\nSELECT om.id, r.id, om.user_id\nFROM public.organization_memberships om\nCROSS JOIN public.organization_roles r\nWHERE r.key = 'org_admin'\n  AND om.user_id = (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test')\n  AND om.organization_id = 'a0000000-0000-0000-0000-000000000007'\n  AND NOT EXISTS (\n    SELECT 1 FROM public.membership_roles mr WHERE mr.membership_id = om.id AND mr.role_id = r.id\n  )","-- ############################################################################\n-- PART 6: PROGRAMS\n-- ############################################################################\n--\n-- Two demo programs connecting multiple organizations.\n-- (Blueprint §6 — Program Engine, §20.1 — Sprint 0 acceptance)\n-- ============================================================================\n\n-- Program 1: Retrospective breast cancer study\nINSERT INTO public.programs (id, name, short_name, description, program_type, therapeutic_areas, diseases,\n                             start_date, end_date, status, sponsor_org_id, lead_org_id,\n                             default_data_scope, created_by, created_by_organization_id)\nVALUES (\n    'b0000000-0000-0000-0000-000000000001',\n    'Triple-Negative Breast Cancer Retrospective Cohort',\n    'TNBC-RETRO-001',\n    'Multi-center retrospective study requiring 500 FFPE blocks and matched clinical data from triple-negative breast cancer patients.',\n    ARRAY['retrospective_study', 'multi_center'],\n    ARRAY['oncology'],\n    '[{\\"code\\": \\"ICD-10:C50.9\\", \\"label\\": \\"Malignant neoplasm of breast\\"}, {\\"code\\": \\"ICD-10:C50.0\\", \\"label\\": \\"Nipple and areola\\"}]'::jsonb,\n    '2026-07-01', '2027-06-30', 'active',\n    'a0000000-0000-0000-0000-000000000001',  -- PharmaCorp (sponsor)\n    'a0000000-0000-0000-0000-000000000002',  -- ClinResearch CRO (lead)\n    'de_identified',\n    (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test'),\n    'a0000000-0000-0000-0000-000000000001'   -- PharmaCorp (creator org)\n) ON CONFLICT (id) DO NOTHING","-- Program 2: Prospective liquid biopsy collection\nINSERT INTO public.programs (id, name, short_name, description, program_type, therapeutic_areas, diseases,\n                             start_date, end_date, status, sponsor_org_id, lead_org_id,\n                             default_data_scope, created_by, created_by_organization_id)\nVALUES (\n    'b0000000-0000-0000-0000-000000000002',\n    'NSCLC Liquid Biopsy Prospective Collection',\n    'NSCLC-LBIO-002',\n    'Prospective collection of 200 liquid biopsy samples from Stage IV NSCLC patients across 5 clinical sites in Brazil and Argentina.',\n    ARRAY['prospective_collection', 'multi_center', 'international'],\n    ARRAY['oncology', 'pulmonology'],\n    '[{\\"code\\": \\"ICD-10:C34.9\\", \\"label\\": \\"Malignant neoplasm of bronchus or lung\\"}]'::jsonb,\n    '2026-08-01', '2027-12-31', 'active',\n    'a0000000-0000-0000-0000-000000000001',  -- PharmaCorp (sponsor)\n    'a0000000-0000-0000-0000-000000000002',  -- ClinResearch CRO (lead)\n    'de_identified',\n    (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test'),\n    'a0000000-0000-0000-0000-000000000001'   -- PharmaCorp (creator org)\n) ON CONFLICT (id) DO NOTHING","-- ############################################################################\n-- PART 7: PROGRAM PARTICIPANTS\n-- ############################################################################\n--\n-- Programs connect multiple organizations with specific roles.\n-- (Blueprint §6.4 — participant roles)\n-- ============================================================================\n\n-- Program 1 participants\nINSERT INTO public.program_participants (program_id, organization_id, role, status, joined_at, created_by)\nVALUES\n    ('b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'sponsor', 'active', now(),\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test')),\n    ('b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000002', 'lead', 'active', now(),\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test')),\n    ('b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000003', 'contributor', 'active', now(),\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test')),\n    ('b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000004', 'contributor', 'active', now(),\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test')),\n    ('b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000005', 'processor', 'active', now(),\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test')),\n    ('b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000006', 'processor', 'active', now(),\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test')),\n    ('b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000007', 'reviewer', 'active', now(),\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test'))\nON CONFLICT (program_id, organization_id) DO NOTHING","-- Program 2 participants\nINSERT INTO public.program_participants (program_id, organization_id, role, status, joined_at, created_by)\nVALUES\n    ('b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000001', 'sponsor', 'active', now(),\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test')),\n    ('b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'lead', 'active', now(),\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test')),\n    ('b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000003', 'contributor', 'active', now(),\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test')),\n    ('b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000005', 'processor', 'active', now(),\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test')),\n    ('b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000007', 'reviewer', 'active', now(),\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test'))\nON CONFLICT (program_id, organization_id) DO NOTHING","-- ############################################################################\n-- PART 8: PROGRAM ACCESS POLICIES\n-- ############################################################################\n--\n-- Default access policies for each program.\n-- (Blueprint §6.5 — data sharing scopes)\n-- ============================================================================\n\n-- Program 1: TNBC study — de-identified data, no export, requires approval\nINSERT INTO public.program_access_policies (program_id, name, policy_type, allowed_data_scope, allow_export, require_approval, created_by)\nVALUES\n    ('b0000000-0000-0000-0000-000000000001', 'Default Data Access', 'default', 'de_identified', false, true,\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test'))\nON CONFLICT DO NOTHING","-- Program 2: NSCLC collection — metadata only until collection complete\nINSERT INTO public.program_access_policies (program_id, name, policy_type, allowed_data_scope, allow_export, require_approval, created_by)\nVALUES\n    ('b0000000-0000-0000-0000-000000000002', 'Interim Metadata Access', 'default', 'metadata_only', false, true,\n     (SELECT id FROM public.user_profiles WHERE email = 'admin@kadarn.test'))\nON CONFLICT DO NOTHING","-- ############################################################################\n-- PART 9: VERIFICATION\n-- ############################################################################\n--\n-- After seeding, verify with:\n--\n-- SELECT 'organizations' AS entity, COUNT(*) FROM public.organizations\n-- UNION ALL\n-- SELECT 'capabilities', COUNT(*) FROM public.organization_capabilities\n-- UNION ALL\n-- SELECT 'memberships', COUNT(*) FROM public.organization_memberships\n-- UNION ALL\n-- SELECT 'membership_roles', COUNT(*) FROM public.membership_roles\n-- UNION ALL\n-- SELECT 'programs', COUNT(*) FROM public.programs\n-- UNION ALL\n-- SELECT 'program_participants', COUNT(*) FROM public.program_participants\n-- ORDER BY entity;\n-- ============================================================================\n\n-- ============================================================================\n-- END OF MIGRATION 011 — Sprint 0D: Seed Data\n-- ============================================================================"}	seed_data
012	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 0D: Smoke Tests\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Dependencies: Migrations 008–011 applied with seed data\n--\n-- These smoke tests validate multi-tenant RLS infrastructure and data integrity.\n-- Run as superuser or with bypassrls after migrations are applied.\n--\n-- (Blueprint §20 — Sprint 0 acceptance criteria)\n--\n-- TODO Sprint 1: Add real RLS functional tests with Supabase auth context / JWT users.\n--   Current tests run as superuser (bypasses RLS). To validate RLS properly:\n--   1. Start Supabase local with auth enabled\n--   2. Run queries as each demo user via Supabase auth.uid() context\n--   3. Verify Org A user CANNOT see Org B data\n--   4. Verify multi-org user CAN see both orgs\n--   5. Verify non-member CANNOT insert/update\n--   These will be added as 013_rls_functional_tests.sql or as API-level integration tests.\n--\n-- HOW TO RUN:\n--   psql -d <database> -f 012_smoke_tests.sql\n--\n-- Each test prints PASS/FAIL.\n-- ============================================================================\n\n-- ############################################################################\n-- PART 0: TEST FRAMEWORK HELPER\n-- ############################################################################\n\nCREATE OR REPLACE FUNCTION public.test_result(\n    p_test_name TEXT,\n    p_passed BOOLEAN,\n    p_detail TEXT DEFAULT NULL\n)\nRETURNS TABLE (result TEXT)\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    IF p_passed THEN\n        RETURN QUERY SELECT format('  ✅ PASS: %s', p_test_name)::TEXT;\n    ELSE\n        RETURN QUERY SELECT format('  ❌ FAIL: %s — %s', p_test_name, COALESCE(p_detail, 'unexpected result'))::TEXT;\n    END IF;\nEND;\n$$","-- ############################################################################\n-- PART 1: SEED DATA INTEGRITY\n-- ############################################################################\n\n-- Test 1.1: 7 organizations exist\nSELECT public.test_result(\n    'Seed data: 7 organizations created',\n    (SELECT COUNT(*) FROM public.organizations) = 7,\n    format('Found %s orgs, expected 7', (SELECT COUNT(*) FROM public.organizations)::TEXT)\n)","-- Test 1.2: 12 capability types seeded\nSELECT public.test_result(\n    'Seed data: 12 capability types',\n    (SELECT COUNT(*) FROM public.organization_capability_types WHERE is_active = true) = 12,\n    format('Found %s types, expected 12', (SELECT COUNT(*) FROM public.organization_capability_types)::TEXT)\n)","-- Test 1.3: 12 capability types have standard keys\nSELECT public.test_result(\n    'Seed data: capability types include sponsor, cro, biobank, clinical_site, irb',\n    (SELECT COUNT(*) FROM public.organization_capability_types\n     WHERE key IN ('sponsor', 'cro', 'biobank', 'clinical_site', 'irb', 'processing_lab',\n                   'storage_facility', 'logistics_vendor', 'regulatory_body',\n                   'diagnostic_lab', 'data_processor', 'technology_provider')) = 12\n)","-- Test 1.4: Organization capabilities are seeded\nSELECT public.test_result(\n    'Seed data: organization capabilities exist',\n    (SELECT COUNT(*) FROM public.organization_capabilities) >= 9,\n    format('Found %s capabilities', (SELECT COUNT(*) FROM public.organization_capabilities)::TEXT)\n)","-- Test 1.5: 6 system roles seeded\nSELECT public.test_result(\n    'Seed data: 6 system roles',\n    (SELECT COUNT(*) FROM public.organization_roles WHERE is_system_role = true) = 6\n)","-- Test 1.6: 8 users created (1 admin + 7 org users)\nSELECT public.test_result(\n    'Seed data: 8 demo users',\n    (SELECT COUNT(*) FROM public.user_profiles) >= 8,\n    format('Found %s users', (SELECT COUNT(*) FROM public.user_profiles)::TEXT)\n)","-- Test 1.7: At least 8 memberships (7 org users + 1 admin in 2 orgs = 9 total)\nSELECT public.test_result(\n    'Seed data: memberships created',\n    (SELECT COUNT(*) FROM public.organization_memberships) >= 9,\n    format('Found %s memberships', (SELECT COUNT(*) FROM public.organization_memberships)::TEXT)\n)","-- Test 1.7b: At least one user belongs to multiple orgs\nSELECT public.test_result(\n    'Seed data: multi-org user exists',\n    EXISTS (\n        SELECT user_id, COUNT(*) FROM public.organization_memberships\n        WHERE status = 'active'\n        GROUP BY user_id\n        HAVING COUNT(*) > 1\n    ),\n    'No user has memberships in multiple organizations'\n)","-- Test 1.8: 2 programs exist\nSELECT public.test_result(\n    'Seed data: 2 programs',\n    (SELECT COUNT(*) FROM public.programs) = 2,\n    format('Found %s programs', (SELECT COUNT(*) FROM public.programs)::TEXT)\n)","-- Test 1.9: Program 1 (TNBC) has 7 participants (sponsor, CRO, site, biobank, lab, courier, IRB)\nSELECT public.test_result(\n    'Seed data: Program 1 (TNBC) has 7 participants',\n    (SELECT COUNT(*) FROM public.program_participants\n     WHERE program_id = 'b0000000-0000-0000-0000-000000000001') = 7,\n    format('Found %s participants', (SELECT COUNT(*) FROM public.program_participants\n           WHERE program_id = 'b0000000-0000-0000-0000-000000000001')::TEXT)\n)","-- Test 1.10: Program 2 (NSCLC) has 5 participants\nSELECT public.test_result(\n    'Seed data: Program 2 (NSCLC) has 5 participants',\n    (SELECT COUNT(*) FROM public.program_participants\n     WHERE program_id = 'b0000000-0000-0000-0000-000000000002') = 5,\n    format('Found %s participants', (SELECT COUNT(*) FROM public.program_participants\n           WHERE program_id = 'b0000000-0000-0000-0000-000000000002')::TEXT)\n)","-- Test 1.11: Programs have created_by_organization_id\nSELECT public.test_result(\n    'Seed data: programs have created_by_organization_id',\n    (SELECT COUNT(*) FROM public.programs WHERE created_by_organization_id IS NOT NULL) = 2,\n    format('Found %s programs with creator org', (SELECT COUNT(*) FROM public.programs WHERE created_by_organization_id IS NOT NULL)::TEXT)\n)","-- Test 1.12: Program creator org matches first participant\nSELECT public.test_result(\n    'Seed data: Program 1 creator org is participant',\n    EXISTS (\n        SELECT 1 FROM public.programs p\n        JOIN public.program_participants pp ON pp.program_id = p.id\n        WHERE p.id = 'b0000000-0000-0000-0000-000000000001'\n          AND pp.organization_id = p.created_by_organization_id\n          AND pp.role = 'sponsor'\n    ),\n    'Program 1 creator org is not a participant or not sponsor'\n)","-- ############################################################################\n-- PART 2: RLS — ROW LEVEL SECURITY ENABLED\n-- ############################################################################\n\n-- Test 2.1: All tables have RLS enabled\nSELECT public.test_result(\n    'RLS: enabled on organizations',\n    (SELECT relrowsecurity FROM pg_class WHERE relname = 'organizations' AND relnamespace = 'public'::regnamespace),\n    'RLS not enabled'\n)","SELECT public.test_result(\n    'RLS: enabled on organization_capabilities',\n    (SELECT relrowsecurity FROM pg_class WHERE relname = 'organization_capabilities' AND relnamespace = 'public'::regnamespace)\n)","SELECT public.test_result(\n    'RLS: enabled on organization_memberships',\n    (SELECT relrowsecurity FROM pg_class WHERE relname = 'organization_memberships' AND relnamespace = 'public'::regnamespace)\n)","SELECT public.test_result(\n    'RLS: enabled on membership_roles',\n    (SELECT relrowsecurity FROM pg_class WHERE relname = 'membership_roles' AND relnamespace = 'public'::regnamespace)\n)","SELECT public.test_result(\n    'RLS: enabled on user_profiles',\n    (SELECT relrowsecurity FROM pg_class WHERE relname = 'user_profiles' AND relnamespace = 'public'::regnamespace)\n)","SELECT public.test_result(\n    'RLS: enabled on programs',\n    (SELECT relrowsecurity FROM pg_class WHERE relname = 'programs' AND relnamespace = 'public'::regnamespace)\n)","SELECT public.test_result(\n    'RLS: enabled on program_participants',\n    (SELECT relrowsecurity FROM pg_class WHERE relname = 'program_participants' AND relnamespace = 'public'::regnamespace)\n)","SELECT public.test_result(\n    'RLS: enabled on audit_events',\n    (SELECT relrowsecurity FROM pg_class WHERE relname = 'audit_events' AND relnamespace = 'public'::regnamespace)\n)","-- ############################################################################\n-- PART 3: RLS — POLICY COUNT\n-- ############################################################################\n\n-- Test 3.1: Each table has at least one policy\nCREATE OR REPLACE FUNCTION public.check_table_has_policies(p_table TEXT)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT COUNT(*) > 0\n    FROM pg_policies\n    WHERE schemaname = 'public' AND tablename = p_table;\n$$","SELECT public.test_result(\n    'Policies: organizations has policies',\n    public.check_table_has_policies('organizations')\n)","SELECT public.test_result(\n    'Policies: organization_capability_types has policies',\n    public.check_table_has_policies('organization_capability_types')\n)","SELECT public.test_result(\n    'Policies: organization_capabilities has policies',\n    public.check_table_has_policies('organization_capabilities')\n)","SELECT public.test_result(\n    'Policies: organization_roles has policies',\n    public.check_table_has_policies('organization_roles')\n)","SELECT public.test_result(\n    'Policies: organization_memberships has policies',\n    public.check_table_has_policies('organization_memberships')\n)","SELECT public.test_result(\n    'Policies: membership_roles has policies',\n    public.check_table_has_policies('membership_roles')\n)","SELECT public.test_result(\n    'Policies: user_profiles has policies',\n    public.check_table_has_policies('user_profiles')\n)","SELECT public.test_result(\n    'Policies: programs has policies',\n    public.check_table_has_policies('programs')\n)","SELECT public.test_result(\n    'Policies: program_participants has policies',\n    public.check_table_has_policies('program_participants')\n)","SELECT public.test_result(\n    'Policies: program_access_policies has policies',\n    public.check_table_has_policies('program_access_policies')\n)","SELECT public.test_result(\n    'Policies: audit_events has policies',\n    public.check_table_has_policies('audit_events')\n)","-- ############################################################################\n-- PART 4: RLS — HELPER FUNCTIONS EXIST\n-- ############################################################################\n\n-- Test 4.1: All RLS helper functions exist\nCREATE OR REPLACE FUNCTION public.check_function_exists(p_schema TEXT, p_name TEXT, p_args TEXT DEFAULT NULL)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nAS $$\n    SELECT EXISTS (\n        SELECT 1 FROM pg_proc p\n        JOIN pg_namespace n ON n.oid = p.pronamespace\n        WHERE n.nspname = p_schema\n          AND p.proname = p_name\n    );\n$$","SELECT public.test_result(\n    'Helper: current_user_id() exists',\n    public.check_function_exists('public', 'current_user_id')\n)","SELECT public.test_result(\n    'Helper: is_org_member(UUID) exists',\n    public.check_function_exists('public', 'is_org_member')\n)","SELECT public.test_result(\n    'Helper: has_org_capability(UUID, TEXT) exists',\n    public.check_function_exists('public', 'has_org_capability')\n)","SELECT public.test_result(\n    'Helper: has_current_user_capability(TEXT) exists',\n    public.check_function_exists('public', 'has_current_user_capability')\n)","SELECT public.test_result(\n    'Helper: has_org_role(UUID, TEXT) exists',\n    public.check_function_exists('public', 'has_org_role')\n)","SELECT public.test_result(\n    'Helper: is_org_admin() exists',\n    public.check_function_exists('public', 'is_org_admin')\n)","SELECT public.test_result(\n    'Helper: can_access_program(UUID) exists',\n    public.check_function_exists('public', 'can_access_program')\n)","SELECT public.test_result(\n    'Helper: check_visibility(UUID, visibility_scope) exists',\n    public.check_function_exists('public', 'check_visibility')\n)","SELECT public.test_result(\n    'Helper: emit_audit_event(...) exists',\n    public.check_function_exists('public', 'emit_audit_event')\n)","-- ############################################################################\n-- PART 5: TRIGGERS EXIST\n-- ############################################################################\n\n-- Test 5.1: updated_at triggers exist\nSELECT public.test_result(\n    'Trigger: organizations updated_at',\n    EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_organizations_updated_at')\n)","SELECT public.test_result(\n    'Trigger: programs updated_at',\n    EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_programs_updated_at')\n)","SELECT public.test_result(\n    'Trigger: program_participants updated_at',\n    EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_program_participants_updated_at')\n)","-- Test 5.2: Audit triggers exist\nSELECT public.test_result(\n    'Trigger: programs audit',\n    EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_programs_audit')\n)","SELECT public.test_result(\n    'Trigger: program_participants audit',\n    EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_program_participants_audit')\n)","-- Test 5.3: Auth triggers exist\nSELECT public.test_result(\n    'Trigger: on_auth_user_created exists',\n    EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'on_auth_user_created')\n)","SELECT public.test_result(\n    'Trigger: user_profiles auth sync exists',\n    EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_user_profiles_auth_sync')\n)","-- ############################################################################\n-- PART 6: DATA INTEGRITY — CONSTRAINTS\n-- ############################################################################\n\n-- Test 6.1: No duplicate org names within same country\nSELECT public.test_result(\n    'Constraint: no duplicate org names per country',\n    NOT EXISTS (\n        SELECT name, country, COUNT(*)\n        FROM public.organizations\n        GROUP BY name, country\n        HAVING COUNT(*) > 1\n    )\n)","-- Test 6.2: All capabilities reference valid orgs\nSELECT public.test_result(\n    'Integrity: all capabilities reference valid orgs',\n    NOT EXISTS (\n        SELECT 1 FROM public.organization_capabilities oc\n        LEFT JOIN public.organizations o ON o.id = oc.organization_id\n        WHERE o.id IS NULL\n    )\n)","-- Test 6.3: All memberships reference valid users (may be system users)\nSELECT public.test_result(\n    'Integrity: all memberships reference valid orgs',\n    NOT EXISTS (\n        SELECT 1 FROM public.organization_memberships om\n        LEFT JOIN public.organizations o ON o.id = om.organization_id\n        WHERE o.id IS NULL\n    )\n)","-- Test 6.4: All program participants reference valid orgs and programs\nSELECT public.test_result(\n    'Integrity: program_participants orgs exist',\n    NOT EXISTS (\n        SELECT 1 FROM public.program_participants pp\n        LEFT JOIN public.organizations o ON o.id = pp.organization_id\n        WHERE o.id IS NULL\n    )\n)","SELECT public.test_result(\n    'Integrity: program_participants programs exist',\n    NOT EXISTS (\n        SELECT 1 FROM public.program_participants pp\n        LEFT JOIN public.programs p ON p.id = pp.program_id\n        WHERE p.id IS NULL\n    )\n)","-- Test 6.5: Program 1 has all 7 required actor types\nSELECT public.test_result(\n    'Integrity: Program 1 has sponsor, lead, 2 contributors, processor, processor, reviewer',\n    (\n        SELECT COUNT(DISTINCT role) FROM public.program_participants\n        WHERE program_id = 'b0000000-0000-0000-0000-000000000001'\n    ) >= 4  -- sponsor, lead, contributor, processor, reviewer\n    AND (\n        SELECT COUNT(*) FROM public.program_participants\n        WHERE program_id = 'b0000000-0000-0000-0000-000000000001'\n        AND role = 'contributor'\n    ) = 2\n)","-- ############################################################################\n-- PART 7: AUDIT — BASIC VERIFICATION\n-- ############################################################################\n\n-- Test 7.1: Audit events capture program creation (trigger auto-fires)\n-- Note: seed data was inserted with INSERT ... ON CONFLICT DO NOTHING\n-- which does NOT fire AFTER INSERT triggers if the row already exists.\n-- This test verifies the mechanism, not the seed events.\nSELECT public.test_result(\n    'Audit: emit_audit_event function works',\n    public.emit_audit_event(\n        'system'::audit_action,\n        'other'::audit_resource_type,\n        gen_random_uuid(),\n        NULL, NULL, NULL,\n        'Smoke test audit event'\n    ) IS NOT NULL\n)","-- ############################################################################\n-- PART 8: SUMMARY\n-- ############################################################################\n\nWITH test_summary AS (\n    SELECT COUNT(*) AS total\n    FROM (SELECT 1 AS t WHERE public.check_table_has_policies('organizations')) dummy\n)\nSELECT '🏁 Sprint 0 smoke tests complete.' AS result","-- Clean up test helpers\nDROP FUNCTION IF EXISTS public.test_result(TEXT, BOOLEAN, TEXT)","DROP FUNCTION IF EXISTS public.check_table_has_policies(TEXT)","DROP FUNCTION IF EXISTS public.check_function_exists(TEXT, TEXT, TEXT)","-- ============================================================================\n-- END OF MIGRATION 012 — Sprint 0D: Smoke Tests\n-- ============================================================================"}	smoke_tests
013	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 3: Discovery Engine\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Dependencies: 008_organizations_capabilities.sql, 009_rls_foundation.sql\n--\n-- This migration creates the Discovery Engine foundation:\n--   1. supply_item_type enum (7 types — Blueprint §7.2)\n--   2. supply_items table with full-text search\n--   3. RLS policies for discovery\n--   4. Search indexes for faceted filtering\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: ENUM\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE supply_item_type AS ENUM (\n        'existing_collection',      -- Archived biospecimen cohort\n        'prospective_collection',   -- Planned collection program\n        'laboratory_service',       -- IHC, NGS, extraction, etc.\n        'clinical_service',         -- Pathology review, radiology read\n        'data_resource',            -- Genomic dataset, imaging archive\n        'storage_logistics',        -- Cryo-storage, cold-chain transport\n        'equipment_capability'      -- Digital pathology scanner, etc.\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: TABLE — supply_items\n-- ############################################################################\n--\n-- The primary searchable object in the Discovery Engine.\n-- Each item represents something a researcher can request.\n-- (Blueprint §7.2 — Supply Items)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.supply_items (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n\n    -- Multi-tenant ownership (Blueprint §4)\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n    program_id          UUID REFERENCES public.programs(id) ON DELETE SET NULL,\n    created_by          UUID NOT NULL,\n\n    -- Typing (Blueprint §7.2)\n    type                supply_item_type NOT NULL,\n    title               TEXT NOT NULL,\n    description         TEXT,\n\n    -- Optional link to existing collection (for type = existing_collection)\n    collection_id       UUID,\n\n    -- Disease targeting\n    disease_icd10       TEXT,\n    disease_label       TEXT,\n\n    -- Categorization for faceted filtering\n    sample_types        TEXT[] DEFAULT '{}',\n    data_categories     TEXT[] DEFAULT '{}',\n    service_categories  TEXT[] DEFAULT '{}',\n\n    -- Geographic scope\n    country             TEXT,\n    region              TEXT,\n    city                TEXT,\n\n    -- Access & commercial\n    commercial_use_allowed     BOOLEAN NOT NULL DEFAULT false,\n    non_profit_use_allowed     BOOLEAN NOT NULL DEFAULT true,\n\n    -- Prospective collection fields\n    prospective_available              BOOLEAN NOT NULL DEFAULT false,\n    estimated_recruitment_per_month    INTEGER,\n    estimated_turnaround_days          INTEGER,\n\n    -- Service flags\n    processing_available               BOOLEAN NOT NULL DEFAULT false,\n    shipping_available                 BOOLEAN NOT NULL DEFAULT false,\n    international_shipping_available   BOOLEAN NOT NULL DEFAULT false,\n\n    -- Quality\n    quality_labels   TEXT[] DEFAULT '{}',\n    certifications   TEXT[] DEFAULT '{}',\n\n    -- Lifecycle\n    status           TEXT NOT NULL DEFAULT 'active'\n                     CHECK (status IN ('draft', 'active', 'inactive', 'archived')),\n\n    -- Visibility (Blueprint §4.2)\n    visibility_scope visibility_scope NOT NULL DEFAULT 'network',\n\n    -- Flexible metadata\n    metadata         JSONB NOT NULL DEFAULT '{}',\n\n    -- Full-text search vector\n    search_vector    tsvector\n                     GENERATED ALWAYS AS (\n                         to_tsvector('english',\n                             coalesce(title, '') || ' ' ||\n                             coalesce(description, '') || ' ' ||\n                             coalesce(disease_label, '') || ' ' ||\n                             coalesce(city, '') || ' ' ||\n                             coalesce(region, '') || ' ' ||\n                             coalesce(country, '')\n                         )\n                     ) STORED,\n\n    -- Audit\n    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()\n)","-- ############################################################################\n-- PART 3: INDEXES\n-- ############################################################################\n\n-- Full-text search index (primary search index)\nCREATE INDEX IF NOT EXISTS idx_supply_items_search\n    ON public.supply_items USING GIN(search_vector)","-- Faceted filter indexes\nCREATE INDEX IF NOT EXISTS idx_supply_items_org\n    ON public.supply_items(organization_id)","CREATE INDEX IF NOT EXISTS idx_supply_items_type\n    ON public.supply_items(type)","CREATE INDEX IF NOT EXISTS idx_supply_items_disease\n    ON public.supply_items(disease_icd10)","CREATE INDEX IF NOT EXISTS idx_supply_items_country\n    ON public.supply_items(country)","CREATE INDEX IF NOT EXISTS idx_supply_items_status\n    ON public.supply_items(status)","CREATE INDEX IF NOT EXISTS idx_supply_items_visibility\n    ON public.supply_items(visibility_scope)","CREATE INDEX IF NOT EXISTS idx_supply_items_created\n    ON public.supply_items(created_at DESC)","-- GIN indexes for array columns (faceted filtering)\nCREATE INDEX IF NOT EXISTS idx_supply_items_sample_types\n    ON public.supply_items USING GIN(sample_types)","CREATE INDEX IF NOT EXISTS idx_supply_items_data_categories\n    ON public.supply_items USING GIN(data_categories)","CREATE INDEX IF NOT EXISTS idx_supply_items_service_categories\n    ON public.supply_items USING GIN(service_categories)","-- Partial index for active items (most common query)\nCREATE INDEX IF NOT EXISTS idx_supply_items_active\n    ON public.supply_items(id)\n    WHERE status = 'active'","-- ############################################################################\n-- PART 4: TRIGGERS — updated_at\n-- ############################################################################\n\nCREATE TRIGGER trg_supply_items_updated_at\n    BEFORE UPDATE ON public.supply_items\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","-- ############################################################################\n-- PART 5: ROW LEVEL SECURITY\n-- ############################################################################\n\nALTER TABLE public.supply_items ENABLE ROW LEVEL SECURITY","-- SELECT: network/public visibility or org member or admin\nCREATE POLICY supply_items_select ON public.supply_items\n    FOR SELECT\n    USING (\n        auth.role() = 'authenticated'\n        AND (\n            visibility_scope IN ('public', 'network')\n            OR public.is_org_member(organization_id)\n            OR public.is_org_admin()\n        )\n    )","-- INSERT: org_admin in the owning organization\nCREATE POLICY supply_items_insert ON public.supply_items\n    FOR INSERT\n    WITH CHECK (\n        created_by = auth.uid()\n        AND public.is_org_admin(organization_id)\n    )","-- UPDATE: org_admin in the owning organization\nCREATE POLICY supply_items_update ON public.supply_items\n    FOR UPDATE\n    USING (public.is_org_admin(organization_id))\n    WITH CHECK (public.is_org_admin(organization_id))","-- DELETE: org_admin in the owning organization\nCREATE POLICY supply_items_delete ON public.supply_items\n    FOR DELETE\n    USING (public.is_org_admin(organization_id))","-- ############################################################################\n-- PART 6: SEARCH FUNCTION\n-- ############################################################################\n--\n-- Reusable search function for the Discovery Engine.\n-- Supports full-text search + faceted filtering.\n-- (Blueprint §7.3 — Search Capabilities)\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.discovery_search(\n    p_search_text      TEXT DEFAULT NULL,\n    p_types            supply_item_type[] DEFAULT NULL,\n    p_sample_types     TEXT[] DEFAULT NULL,\n    p_disease_icd10    TEXT DEFAULT NULL,\n    p_country          TEXT DEFAULT NULL,\n    p_commercial_only  BOOLEAN DEFAULT NULL,\n    p_limit            INTEGER DEFAULT 20,\n    p_offset           INTEGER DEFAULT 0\n)\nRETURNS TABLE (\n    id                  UUID,\n    organization_id     UUID,\n    type                supply_item_type,\n    title               TEXT,\n    description         TEXT,\n    disease_icd10       TEXT,\n    disease_label       TEXT,\n    sample_types        TEXT[],\n    country             TEXT,\n    commercial_use_allowed BOOLEAN,\n    status              TEXT,\n    search_rank         REAL,\n    total_count         BIGINT\n)\nLANGUAGE SQL\nSTABLE\nAS $$\n    WITH filtered AS (\n        SELECT\n            si.id,\n            si.organization_id,\n            si.type,\n            si.title,\n            si.description,\n            si.disease_icd10,\n            si.disease_label,\n            si.sample_types,\n            si.country,\n            si.commercial_use_allowed,\n            si.status,\n            -- Calculate search rank (0 if no search text)\n            CASE\n                WHEN p_search_text IS NOT NULL AND p_search_text != ''\n                THEN ts_rank(si.search_vector, plainto_tsquery('english', p_search_text))\n                ELSE 1.0\n            END AS rank\n        FROM public.supply_items si\n        WHERE si.status = 'active'\n          AND (p_search_text IS NULL OR p_search_text = '' OR si.search_vector @@ plainto_tsquery('english', p_search_text))\n          AND (p_types IS NULL OR si.type = ANY(p_types))\n          AND (p_sample_types IS NULL OR si.sample_types && p_sample_types)\n          AND (p_disease_icd10 IS NULL OR si.disease_icd10 = p_disease_icd10)\n          AND (p_country IS NULL OR si.country = p_country)\n          AND (p_commercial_only IS NULL OR (p_commercial_only = true AND si.commercial_use_allowed = true))\n    )\n    SELECT\n        f.id, f.organization_id, f.type, f.title, f.description,\n        f.disease_icd10, f.disease_label, f.sample_types, f.country,\n        f.commercial_use_allowed, f.status,\n        f.rank AS search_rank,\n        COUNT(*) OVER() AS total_count\n    FROM filtered f\n    ORDER BY f.rank DESC, f.title ASC\n    LIMIT p_limit\n    OFFSET p_offset;\n$$","COMMENT ON FUNCTION public.discovery_search IS\n    'Discovery Engine search. Supports full-text search, faceted filtering by type, sample type, disease, and country. Returns ranked results with total count.'","-- ############################################################################\n-- PART 7: SEED DATA — demo supply items\n-- ############################################################################\n\nINSERT INTO public.supply_items (organization_id, created_by, type, title, description, disease_icd10, disease_label, sample_types, country, status, visibility_scope) VALUES\n    ('a0000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000000', 'existing_collection',\n     'TNBC FFPE Tissue Cohort', '500 FFPE blocks from triple-negative breast cancer patients with matched clinical data. Ages 25-75, all stages.',\n     'ICD-10:C50.9', 'Malignant neoplasm of breast', ARRAY['tissue_frozen', 'tissue_ffpe'], 'US', 'active', 'network'),\n\n    ('a0000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000000', 'existing_collection',\n     'Healthy Donor Plasma Bank', '10,000 plasma samples from healthy donors aged 18-65. Volume: 1mL per aliquot. Collected under IRB-approved protocol.',\n     NULL, NULL, ARRAY['plasma'], 'US', 'active', 'network'),\n\n    ('a0000000-0000-0000-0000-000000000005', '00000000-0000-0000-0000-000000000000', 'laboratory_service',\n     'NGS Whole Exome Sequencing', 'Whole exome sequencing service with 150x coverage. Includes library preparation, sequencing, and standard bioinformatics pipeline.',\n     NULL, NULL, ARRAY['dna'], 'DE', 'active', 'network'),\n\n    ('a0000000-0000-0000-0000-000000000005', '00000000-0000-0000-0000-000000000000', 'laboratory_service',\n     'IHC Biomarker Panel', 'Immunohistochemistry service for biomarker analysis. CLIA-certified. Available markers: PD-L1, HER2, ER, PR, Ki-67, AR.',\n     NULL, NULL, ARRAY['tissue_ffpe'], 'DE', 'active', 'network'),\n\n    ('a0000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000000', 'prospective_collection',\n     'NSCLC Liquid Biopsy Collection', 'Prospective collection of 200 liquid biopsy samples from Stage IV NSCLC patients. 5 clinical sites in Brazil and Argentina.',\n     'ICD-10:C34.9', 'Malignant neoplasm of bronchus or lung', ARRAY['liquid_biopsy', 'plasma'], 'BR', 'active', 'network'),\n\n    ('a0000000-0000-0000-0000-000000000006', '00000000-0000-0000-0000-000000000000', 'storage_logistics',\n     'International Cold Chain Shipping', 'UN 3373 compliant cold chain shipping. Temperature monitoring included. Service areas: US, EU, LATAM.',\n     NULL, NULL, ARRAY['tissue_frozen', 'plasma', 'serum'], 'DE', 'active', 'network')\nON CONFLICT DO NOTHING","-- ############################################################################\n-- PART 8: POSTGREST PERMISSIONS\n-- ############################################################################\n\nGRANT ALL ON public.supply_items TO anon, authenticated, service_role","-- ============================================================================\n-- END OF MIGRATION 013 — Sprint 3: Discovery Engine\n-- ============================================================================"}	discovery_engine
014	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 4: Feasibility Engine\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Dependencies: 008, 009, 010, 013 (supply_items)\n--\n-- This migration creates the Feasibility Engine foundation:\n--   1. feasibility_assessments — store assessment requests and results\n--   2. feasibility_scores — per-organization scoring within assessments\n--   3. feasibility_scoring function — algorithmic org matching\n--   4. RLS policies\n-- (Blueprint §8 — Feasibility Engine)\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: ENUMS\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE feasibility_status AS ENUM (\n        'draft', 'pending', 'completed', 'failed'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE feasibility_dimension AS ENUM (\n        'capacity', 'timeline', 'quality', 'regulatory', 'cost', 'risk'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: TABLE — feasibility_assessments\n-- ############################################################################\n--\n-- A feasibility assessment evaluates whether a program can succeed\n-- given the current network state.\n-- (Blueprint §8.3 — Output)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.feasibility_assessments (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n\n    -- Who requested this assessment\n    created_by          UUID NOT NULL,\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    -- Assessment input (the program requirements)\n    program_name        TEXT NOT NULL,\n    program_description TEXT,\n    program_type        TEXT,\n    therapeutic_area    TEXT,\n    disease_icd10       TEXT,\n    disease_label       TEXT,\n    required_sample_types TEXT[] DEFAULT '{}',\n    required_capabilities TEXT[] DEFAULT '{}',  -- capability keys (sponsor, cro, biobank, etc.)\n    target_countries    TEXT[] DEFAULT '{}',\n    estimated_sample_count INTEGER,\n    urgency             TEXT DEFAULT 'standard'\n                        CHECK (urgency IN ('standard', 'fast', 'flexible')),\n\n    -- Assessment configuration\n    dimensions          feasibility_dimension[] DEFAULT '{capacity,quality,regulatory,cost,risk,timeline}',\n\n    -- Assessment result\n    status              feasibility_status NOT NULL DEFAULT 'draft',\n    summary             TEXT,                 -- human-readable summary\n    risk_level          TEXT,                 -- low, medium, high\n    overall_score       NUMERIC(5,2),         -- 0-100 composite score\n    estimated_timeline_days INTEGER,          -- estimated days to complete\n    estimated_cost_min   NUMERIC(12,2),\n    estimated_cost_max   NUMERIC(12,2),\n    candidate_count     INTEGER,              -- number of candidate orgs found\n    metadata            JSONB DEFAULT '{}',\n\n    -- Audit\n    completed_at        TIMESTAMPTZ,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_feasibility_org\n    ON public.feasibility_assessments(organization_id)","CREATE INDEX IF NOT EXISTS idx_feasibility_status\n    ON public.feasibility_assessments(status)","CREATE INDEX IF NOT EXISTS idx_feasibility_created\n    ON public.feasibility_assessments(created_by)","CREATE INDEX IF NOT EXISTS idx_feasibility_disease\n    ON public.feasibility_assessments(disease_icd10)","COMMENT ON TABLE public.feasibility_assessments IS\n    'Feasibility assessments. Each assessment evaluates whether a program can succeed given the current network state.'","-- ############################################################################\n-- PART 3: TABLE — feasibility_scores\n-- ############################################################################\n--\n-- Per-organization scoring within an assessment.\n-- (Blueprint §8.3 — Candidate site list with capability fit scores)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.feasibility_scores (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    assessment_id       UUID NOT NULL REFERENCES public.feasibility_assessments(id) ON DELETE CASCADE,\n\n    -- The candidate organization\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n    organization_name   TEXT NOT NULL,        -- denormalized for convenience\n    organization_country CHAR(2),\n\n    -- Fit scoring\n    capability_score    NUMERIC(5,2) NOT NULL DEFAULT 0,  -- how well capabilities match\n    capacity_score      NUMERIC(5,2) NOT NULL DEFAULT 0,  -- available capacity\n    quality_score       NUMERIC(5,2) NOT NULL DEFAULT 0,  -- certifications and quality\n    geographic_score    NUMERIC(5,2) NOT NULL DEFAULT 0,  -- geographic fit\n    overall_score       NUMERIC(5,2) NOT NULL DEFAULT 0,  -- weighted composite\n\n    -- Details\n    matched_capabilities TEXT[] DEFAULT '{}',\n    certifications      TEXT[] DEFAULT '{}',\n    country             TEXT,\n    notes               TEXT,\n\n    UNIQUE (assessment_id, organization_id)\n)","CREATE INDEX IF NOT EXISTS idx_feasibility_scores_assessment\n    ON public.feasibility_scores(assessment_id)","CREATE INDEX IF NOT EXISTS idx_feasibility_scores_org\n    ON public.feasibility_scores(organization_id)","COMMENT ON TABLE public.feasibility_scores IS\n    'Per-organization scoring within a feasibility assessment.'","-- ############################################################################\n-- PART 4: FEASIBILITY SCORING FUNCTION\n-- ############################################################################\n--\n-- Runs a feasibility assessment based on program requirements.\n-- Scores organizations by:\n--   1. Capability match (do they have the required capabilities?)\n--   2. Supply item match (do they have relevant supply items?)\n--   3. Geographic match (are they in the target countries?)\n--   4. Quality (certifications)\n-- (Blueprint §8.2 — Feasibility Dimensions)\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.run_feasibility_assessment(\n    p_assessment_id UUID\n)\nRETURNS BOOLEAN\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_assessment RECORD;\n    v_org_record RECORD;\n    v_capability_score NUMERIC(5,2);\n    v_supply_score NUMERIC(5,2);\n    v_geo_score NUMERIC(5,2);\n    v_quality_score NUMERIC(5,2);\n    v_overall NUMERIC(5,2);\n    v_candidate_count INTEGER := 0;\n    v_total_score NUMERIC(5,2) := 0;\nBEGIN\n    -- Get the assessment\n    SELECT * INTO v_assessment\n    FROM public.feasibility_assessments\n    WHERE id = p_assessment_id;\n\n    IF NOT FOUND THEN\n        RETURN false;\n    END IF;\n\n    -- Delete existing scores for this assessment\n    DELETE FROM public.feasibility_scores\n    WHERE assessment_id = p_assessment_id;\n\n    -- Score each active organization\n    FOR v_org_record IN\n        SELECT o.id, o.name, o.country, o.certifications\n        FROM public.organizations o\n        WHERE o.is_active = true\n    LOOP\n        -- 1. Capability score (0-100)\n        SELECT COALESCE(\n            (SELECT COUNT(*)::NUMERIC * 20\n             FROM public.organization_capabilities oc\n             JOIN public.organization_capability_types oct ON oct.id = oc.capability_type_id\n             WHERE oc.organization_id = v_org_record.id\n               AND oct.key = ANY(v_assessment.required_capabilities)\n            ), 0\n        ) INTO v_capability_score;\n\n        -- Cap: 100 max\n        v_capability_score := LEAST(v_capability_score, 100);\n\n        -- 2. Supply item score (0-100)\n        SELECT COALESCE(\n            (SELECT COUNT(*)::NUMERIC * 25\n             FROM public.supply_items si\n             WHERE si.organization_id = v_org_record.id\n               AND si.status = 'active'\n               AND (v_assessment.disease_icd10 IS NULL OR si.disease_icd10 = v_assessment.disease_icd10)\n            ), 0\n        ) INTO v_supply_score;\n        v_supply_score := LEAST(v_supply_score, 100);\n\n        -- 3. Geographic score (0-100)\n        IF v_assessment.target_countries IS NULL OR array_length(v_assessment.target_countries, 1) IS NULL THEN\n            v_geo_score := 50; -- neutral if no country filter\n        ELSIF v_org_record.country = ANY(v_assessment.target_countries) THEN\n            v_geo_score := 100;\n        ELSE\n            v_geo_score := 0;\n        END IF;\n\n        -- 4. Quality score (0-100) based on certifications\n        IF v_org_record.certifications IS NOT NULL AND array_length(v_org_record.certifications, 1) > 0 THEN\n            v_quality_score := LEAST(array_length(v_org_record.certifications, 1)::NUMERIC * 25, 100);\n        ELSE\n            v_quality_score := 20; -- base score for having no certifications\n        END IF;\n\n        -- Composite score (weighted average)\n        v_overall := (\n            v_capability_score * 0.40 +\n            v_supply_score * 0.25 +\n            v_geo_score * 0.20 +\n            v_quality_score * 0.15\n        );\n\n        -- Only insert if at least one capability matches\n        IF v_capability_score > 0 THEN\n            INSERT INTO public.feasibility_scores (\n                assessment_id, organization_id, organization_name, organization_country,\n                capability_score, capacity_score, quality_score, geographic_score, overall_score,\n                matched_capabilities, certifications, country\n            ) VALUES (\n                p_assessment_id, v_org_record.id, v_org_record.name, v_org_record.country,\n                v_capability_score, 50, v_quality_score, v_geo_score, v_overall,\n                (SELECT ARRAY_AGG(oct.key)\n                 FROM public.organization_capabilities oc\n                 JOIN public.organization_capability_types oct ON oct.id = oc.capability_type_id\n                 WHERE oc.organization_id = v_org_record.id\n                   AND oct.key = ANY(v_assessment.required_capabilities)),\n                v_org_record.certifications,\n                v_org_record.country\n            );\n\n            v_candidate_count := v_candidate_count + 1;\n            v_total_score := v_total_score + v_overall;\n        END IF;\n    END LOOP;\n\n    -- Update assessment with results\n    UPDATE public.feasibility_assessments\n    SET\n        status = 'completed',\n        candidate_count = v_candidate_count,\n        overall_score = CASE WHEN v_candidate_count > 0\n                         THEN ROUND(v_total_score / v_candidate_count, 2)\n                         ELSE 0 END,\n        risk_level = CASE\n            WHEN v_candidate_count >= 5 THEN 'low'\n            WHEN v_candidate_count >= 2 THEN 'medium'\n            ELSE 'high'\n        END,\n        estimated_timeline_days = CASE\n            WHEN v_candidate_count >= 5 THEN 90\n            WHEN v_candidate_count >= 2 THEN 180\n            ELSE 365\n        END,\n        completed_at = now()\n    WHERE id = p_assessment_id;\n\n    RETURN true;\nEND;\n$$","COMMENT ON FUNCTION public.run_feasibility_assessment IS\n    'Scores organizations against program requirements. Returns true if assessment was completed.'","-- ############################################################################\n-- PART 5: TRIGGERS\n-- ############################################################################\n\nCREATE TRIGGER trg_feasibility_assessments_updated_at\n    BEFORE UPDATE ON public.feasibility_assessments\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","-- ############################################################################\n-- PART 6: RLS\n-- ############################################################################\n\nALTER TABLE public.feasibility_assessments ENABLE ROW LEVEL SECURITY","ALTER TABLE public.feasibility_scores ENABLE ROW LEVEL SECURITY","-- Assessments: users see their own, org_admins see org's\nCREATE POLICY feasibility_assessments_select_self ON public.feasibility_assessments\n    FOR SELECT\n    USING (created_by = auth.uid())","CREATE POLICY feasibility_assessments_select_admin ON public.feasibility_assessments\n    FOR SELECT\n    USING (public.is_org_admin(organization_id))","CREATE POLICY feasibility_assessments_insert ON public.feasibility_assessments\n    FOR INSERT\n    WITH CHECK (created_by = auth.uid())","CREATE POLICY feasibility_assessments_update ON public.feasibility_assessments\n    FOR UPDATE\n    USING (public.is_org_admin(organization_id))\n    WITH CHECK (public.is_org_admin(organization_id))","CREATE POLICY feasibility_assessments_delete ON public.feasibility_assessments\n    FOR DELETE\n    USING (public.is_org_admin(organization_id))","-- Scores: visible to assessment owner or org_admin\nCREATE POLICY feasibility_scores_select_assessment ON public.feasibility_scores\n    FOR SELECT\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.feasibility_assessments fa\n            WHERE fa.id = assessment_id\n              AND (fa.created_by = auth.uid() OR public.is_org_admin(fa.organization_id))\n        )\n    )","-- ############################################################################\n-- PART 7: POSTGREST PERMISSIONS\n-- ############################################################################\n\nGRANT ALL ON public.feasibility_assessments TO anon, authenticated, service_role","GRANT ALL ON public.feasibility_scores TO anon, authenticated, service_role","-- ============================================================================\n-- END OF MIGRATION 014 — Sprint 4: Feasibility Engine\n-- ============================================================================"}	feasibility_engine
015	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 5: Program Engine\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Dependencies: 010_audit_programs.sql (programs, program_participants)\n--\n-- This migration enhances the Program Engine with:\n--   1. program_milestones — track key program milestones\n--   2. program_requirements — structured program requirements\n--   3. program_activity_log — rich activity feed per program\n--   4. Status transition validation\n--   5. RLS policies\n-- (Blueprint §6 — Program Engine)\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: ENUMS\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE milestone_type AS ENUM (\n        'program_definition',\n        'site_selection',\n        'irb_submission',\n        'irb_approval',\n        'mta_execution',\n        'collection_start',\n        'collection_complete',\n        'processing_start',\n        'processing_complete',\n        'qc_review',\n        'data_delivery',\n        'program_close'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE milestone_status AS ENUM (\n        'pending', 'in_progress', 'completed', 'blocked', 'cancelled'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: TABLE — program_milestones\n-- ############################################################################\n--\n-- Key milestones within a program lifecycle.\n-- (Blueprint §6.2 — Program Lifecycle)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.program_milestones (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    program_id          UUID NOT NULL REFERENCES public.programs(id) ON DELETE CASCADE,\n\n    -- Milestone identity\n    milestone_type      milestone_type NOT NULL,\n    title               TEXT NOT NULL,\n    description         TEXT,\n\n    -- Dates\n    planned_start_date  DATE,\n    planned_end_date    DATE,\n    actual_start_date   DATE,\n    actual_end_date     DATE,\n\n    -- Status\n    status              milestone_status NOT NULL DEFAULT 'pending',\n\n    -- Assignment\n    assigned_org_id     UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\n    assigned_to         UUID,  -- auth.users\n\n    -- Metadata\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_prog_milestones_program\n    ON public.program_milestones(program_id)","CREATE INDEX IF NOT EXISTS idx_prog_milestones_status\n    ON public.program_milestones(status)","CREATE INDEX IF NOT EXISTS idx_prog_milestones_type\n    ON public.program_milestones(milestone_type)","COMMENT ON TABLE public.program_milestones IS\n    'Key milestones within a program lifecycle. Tracks planned vs actual dates.'","-- ############################################################################\n-- PART 3: TABLE — program_requirements\n-- ############################################################################\n--\n-- Structured requirements for a program.\n-- Used by Discovery and Feasibility engines.\n-- (Blueprint §6.3 — Program Structure)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.program_requirements (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    program_id          UUID NOT NULL REFERENCES public.programs(id) ON DELETE CASCADE,\n\n    -- Sample requirements\n    sample_types        TEXT[] DEFAULT '{}',\n    total_sample_count  INTEGER,\n    storage_conditions  TEXT[],  -- room_temperature, refrigerated, frozen, cryo\n\n    -- Disease focus\n    disease_icd10       TEXT,\n    disease_label       TEXT,\n    therapeutic_areas   TEXT[] DEFAULT '{}',\n\n    -- Geographic scope\n    target_countries    TEXT[] DEFAULT '{}',\n\n    -- Clinical data requirements\n    clinical_data_needed    TEXT[] DEFAULT '{}',  -- diagnosis, treatment, outcome, imaging, genomics\n    min_follow_up_months    INTEGER,\n\n    -- Metadata\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (program_id)\n)","COMMENT ON TABLE public.program_requirements IS\n    'Structured program requirements. One per program.'","-- ############################################################################\n-- PART 4: TABLE — program_activity_log\n-- ############################################################################\n--\n-- Rich activity feed per program, complementing the global audit_events.\n-- (Blueprint §6 — Program Engine)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.program_activity_log (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    program_id          UUID NOT NULL REFERENCES public.programs(id) ON DELETE CASCADE,\n    organization_id     UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\n\n    -- Activity\n    action              TEXT NOT NULL,  -- e.g. 'milestone_completed', 'participant_added', 'status_changed'\n    description         TEXT,\n    actor_id            UUID,\n    actor_name          TEXT,\n\n    -- Reference to related entity\n    ref_type            TEXT,  -- 'milestone', 'participant', 'document'\n    ref_id              UUID,\n\n    -- Metadata\n    metadata            JSONB DEFAULT '{}',\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_prog_activity_program\n    ON public.program_activity_log(program_id, created_at DESC)","COMMENT ON TABLE public.program_activity_log IS\n    'Rich activity feed per program. Complements the global audit_events table.'","-- ############################################################################\n-- PART 5: STATUS TRANSITION FUNCTION\n-- ############################################################################\n--\n-- Validates and executes program status transitions.\n-- (Blueprint §6.2 — Program Lifecycle)\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.transition_program_status(\n    p_program_id UUID,\n    p_new_status program_status,\n    p_user_id UUID\n)\nRETURNS BOOLEAN\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_current_status program_status;\n    v_allowed BOOLEAN;\nBEGIN\n    -- Get current status\n    SELECT status INTO v_current_status\n    FROM public.programs\n    WHERE id = p_program_id;\n\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Program not found';\n    END IF;\n\n    -- Validate transition\n    SELECT CASE\n        WHEN v_current_status = 'draft' AND p_new_status IN ('active', 'cancelled') THEN true\n        WHEN v_current_status = 'active' AND p_new_status IN ('paused', 'completed', 'cancelled') THEN true\n        WHEN v_current_status = 'paused' AND p_new_status IN ('active', 'cancelled') THEN true\n        WHEN v_current_status = 'completed' AND p_new_status IN ('archived') THEN true\n        ELSE false\n    END INTO v_allowed;\n\n    IF NOT v_allowed THEN\n        RAISE EXCEPTION 'Invalid status transition: % -> %', v_current_status, p_new_status;\n    END IF;\n\n    -- Update status\n    UPDATE public.programs\n    SET status = p_new_status\n    WHERE id = p_program_id;\n\n    -- Log activity\n    INSERT INTO public.program_activity_log (program_id, action, description, actor_id)\n    VALUES (p_program_id, 'status_changed',\n            format('Status changed from %s to %s', v_current_status, p_new_status),\n            p_user_id);\n\n    RETURN true;\nEND;\n$$","COMMENT ON FUNCTION public.transition_program_status IS\n    'Validates and executes program status transitions per Blueprint §6.2.'","-- ############################################################################\n-- PART 6: TRIGGERS\n-- ############################################################################\n\nCREATE TRIGGER trg_program_milestones_updated_at\n    BEFORE UPDATE ON public.program_milestones\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_program_requirements_updated_at\n    BEFORE UPDATE ON public.program_requirements\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","-- ############################################################################\n-- PART 7: RLS\n-- ############################################################################\n\nALTER TABLE public.program_milestones ENABLE ROW LEVEL SECURITY","ALTER TABLE public.program_requirements ENABLE ROW LEVEL SECURITY","ALTER TABLE public.program_activity_log ENABLE ROW LEVEL SECURITY","-- Milestones: visible to program participants\nCREATE POLICY program_milestones_select ON public.program_milestones\n    FOR SELECT\n    USING (\n        public.can_access_program(program_id)\n        OR public.is_org_admin()\n    )","CREATE POLICY program_milestones_insert ON public.program_milestones\n    FOR INSERT\n    WITH CHECK (\n        EXISTS (\n            SELECT 1 FROM public.program_participants pp\n            WHERE pp.program_id = program_id\n              AND pp.role IN ('sponsor', 'lead')\n              AND pp.status = 'active'\n              AND public.is_org_admin(pp.organization_id)\n        )\n    )","CREATE POLICY program_milestones_update ON public.program_milestones\n    FOR UPDATE\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.program_participants pp\n            WHERE pp.program_id = program_id\n              AND pp.role IN ('sponsor', 'lead')\n              AND pp.status = 'active'\n              AND public.is_org_admin(pp.organization_id)\n        )\n    )","CREATE POLICY program_milestones_delete ON public.program_milestones\n    FOR DELETE\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.program_participants pp\n            WHERE pp.program_id = program_id\n              AND pp.role IN ('sponsor', 'lead')\n              AND pp.status = 'active'\n              AND public.is_org_admin(pp.organization_id)\n        )\n    )","-- Requirements: visible to program participants\nCREATE POLICY program_requirements_select ON public.program_requirements\n    FOR SELECT\n    USING (\n        public.can_access_program(program_id)\n        OR public.is_org_admin()\n    )","CREATE POLICY program_requirements_insert ON public.program_requirements\n    FOR INSERT\n    WITH CHECK (\n        EXISTS (\n            SELECT 1 FROM public.program_participants pp\n            WHERE pp.program_id = program_id\n              AND pp.role IN ('sponsor', 'lead')\n              AND pp.status = 'active'\n              AND public.is_org_admin(pp.organization_id)\n        )\n    )","CREATE POLICY program_requirements_update ON public.program_requirements\n    FOR UPDATE\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.program_participants pp\n            WHERE pp.program_id = program_id\n              AND pp.role IN ('sponsor', 'lead')\n              AND pp.status = 'active'\n              AND public.is_org_admin(pp.organization_id)\n        )\n    )","-- Activity log: visible to program participants\nCREATE POLICY program_activity_log_select ON public.program_activity_log\n    FOR SELECT\n    USING (\n        public.can_access_program(program_id)\n        OR public.is_org_admin()\n    )","CREATE POLICY program_activity_log_insert ON public.program_activity_log\n    FOR INSERT\n    WITH CHECK (\n        public.can_access_program(program_id)\n        OR public.is_org_admin()\n    )","-- ############################################################################\n-- PART 8: POSTGREST PERMISSIONS\n-- ############################################################################\n\nGRANT ALL ON public.program_milestones TO anon, authenticated, service_role","GRANT ALL ON public.program_requirements TO anon, authenticated, service_role","GRANT ALL ON public.program_activity_log TO anon, authenticated, service_role","-- ============================================================================\n-- END OF MIGRATION 015 — Sprint 5: Program Engine\n-- ============================================================================"}	program_engine
016	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 6: Exchange Engine\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Dependencies: 008, 009, 010, 013 (supply_items)\n--\n-- This migration creates the Exchange Engine:\n--   1. exchange_requests — research access requests (Interest phase)\n--   2. exchange_messages — multi-party negotiation messaging\n--   3. exchange_deals — deal state machine (Agreement → Settlement)\n--   4. exchange_escrow — escrow tracking\n--   5. RLS policies\n-- (Blueprint §9 — Exchange / Commercial Engine)\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: ENUMS\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE exchange_request_status AS ENUM (\n        'draft', 'submitted', 'under_review', 'negotiation', 'accepted', 'declined', 'withdrawn'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE exchange_deal_status AS ENUM (\n        'pending_acceptance', 'active', 'fulfillment', 'completed', 'cancelled', 'disputed'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE escrow_status AS ENUM (\n        'pending', 'funded', 'partially_released', 'released', 'refunded', 'disputed'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: TABLE — exchange_requests\n-- ############################################################################\n--\n-- A researcher submits a request to access supply items or join a program.\n-- (Blueprint §9.2 — Interest phase)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.exchange_requests (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n\n    -- Who is requesting\n    requester_id        UUID NOT NULL,\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    -- What they want\n    program_id          UUID REFERENCES public.programs(id) ON DELETE SET NULL,\n    supply_item_id      UUID REFERENCES public.supply_items(id) ON DELETE SET NULL,\n\n    -- Request details\n    title               TEXT NOT NULL,\n    description         TEXT,\n    status              exchange_request_status NOT NULL DEFAULT 'draft',\n\n    -- Target organizations (who can respond)\n    target_org_ids      UUID[] DEFAULT '{}',\n\n    -- Terms requested\n    requested_sample_count  INTEGER,\n    requested_data_categories TEXT[] DEFAULT '{}',\n    requested_timeline_days  INTEGER,\n    budget_range_min        NUMERIC(12,2),\n    budget_range_max        NUMERIC(12,2),\n\n    -- Commercial\n    commercial_use      BOOLEAN NOT NULL DEFAULT false,\n    nonprofit_use       BOOLEAN NOT NULL DEFAULT true,\n\n    -- Metadata\n    metadata            JSONB DEFAULT '{}',\n    submitted_at        TIMESTAMPTZ,\n    resolved_at         TIMESTAMPTZ,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_exchange_req_requester\n    ON public.exchange_requests(requester_id)","CREATE INDEX IF NOT EXISTS idx_exchange_req_org\n    ON public.exchange_requests(organization_id)","CREATE INDEX IF NOT EXISTS idx_exchange_req_program\n    ON public.exchange_requests(program_id)","CREATE INDEX IF NOT EXISTS idx_exchange_req_status\n    ON public.exchange_requests(status)","COMMENT ON TABLE public.exchange_requests IS\n    'Research access requests. Submitted by researchers to express interest in supply items or programs.'","-- ############################################################################\n-- PART 3: TABLE — exchange_deals\n-- ############################################################################\n--\n-- A deal represents an agreed exchange between parties.\n-- (Blueprint §9.2 — Agreement → Settlement)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.exchange_deals (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    request_id          UUID NOT NULL REFERENCES public.exchange_requests(id) ON DELETE CASCADE,\n\n    -- Parties\n    sponsor_org_id      UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n    provider_org_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n    program_id          UUID REFERENCES public.programs(id) ON DELETE SET NULL,\n\n    -- Deal terms\n    title               TEXT NOT NULL,\n    description         TEXT,\n    status              exchange_deal_status NOT NULL DEFAULT 'pending_acceptance',\n\n    -- Financial terms\n    total_value         NUMERIC(12,2),\n    milestone_amounts   JSONB DEFAULT '{}',  -- {milestone: amount, ...}\n    currency            TEXT DEFAULT 'USD',\n\n    -- MTA (Material Transfer Agreement)\n    mta_signed_by_sponsor   BOOLEAN NOT NULL DEFAULT false,\n    mta_signed_by_provider  BOOLEAN NOT NULL DEFAULT false,\n    mta_signed_at           TIMESTAMPTZ,\n    mta_document_id         TEXT,\n\n    -- Timeline\n    expected_start_date     DATE,\n    expected_end_date       DATE,\n    actual_start_date       DATE,\n    actual_end_date         DATE,\n\n    -- Delivery tracking\n    sample_count_expected   INTEGER,\n    sample_count_delivered  INTEGER DEFAULT 0,\n    delivery_percentage     NUMERIC(5,2) GENERATED ALWAYS AS\n        (CASE WHEN sample_count_expected > 0\n              THEN ROUND((sample_count_delivered::NUMERIC / sample_count_expected) * 100, 2)\n              ELSE 0 END) STORED,\n\n    -- Metadata\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_exchange_deals_request\n    ON public.exchange_deals(request_id)","CREATE INDEX IF NOT EXISTS idx_exchange_deals_sponsor\n    ON public.exchange_deals(sponsor_org_id)","CREATE INDEX IF NOT EXISTS idx_exchange_deals_provider\n    ON public.exchange_deals(provider_org_id)","CREATE INDEX IF NOT EXISTS idx_exchange_deals_status\n    ON public.exchange_deals(status)","COMMENT ON TABLE public.exchange_deals IS\n    'Exchange deals — the commercial agreement between sponsor and provider.'","-- ############################################################################\n-- PART 4: TABLE — exchange_messages\n-- ############################################################################\n--\n-- Multi-party negotiation messaging.\n-- (Blueprint §9.2 — Negotiation phase)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.exchange_messages (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    request_id          UUID NOT NULL REFERENCES public.exchange_requests(id) ON DELETE CASCADE,\n    deal_id             UUID REFERENCES public.exchange_deals(id) ON DELETE SET NULL,\n\n    -- Who sent it\n    sender_id           UUID NOT NULL,\n    sender_org_id       UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\n    sender_name         TEXT,\n\n    -- Content\n    message             TEXT NOT NULL,\n    message_type        TEXT NOT NULL DEFAULT 'general'\n                        CHECK (message_type IN ('general', 'offer', 'counter', 'acceptance', 'rejection', 'question', 'file')),\n\n    -- Attachments (file IDs)\n    attachments         UUID[] DEFAULT '{}',\n\n    -- Metadata\n    metadata            JSONB DEFAULT '{}',\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_exchange_msg_request\n    ON public.exchange_messages(request_id, created_at ASC)","CREATE INDEX IF NOT EXISTS idx_exchange_msg_deal\n    ON public.exchange_messages(deal_id)","COMMENT ON TABLE public.exchange_messages IS\n    'Multi-party negotiation messages. Threaded by request_id.'","-- ############################################################################\n-- PART 5: TABLE — exchange_escrow\n-- ############################################################################\n--\n-- Escrow tracking for deal payments.\n-- (Blueprint §9.2 — Settlement phase)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.exchange_escrow (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    deal_id             UUID NOT NULL REFERENCES public.exchange_deals(id) ON DELETE CASCADE,\n\n    -- Escrow details\n    status              escrow_status NOT NULL DEFAULT 'pending',\n    total_amount        NUMERIC(12,2) NOT NULL,\n    released_amount     NUMERIC(12,2) NOT NULL DEFAULT 0,\n    refunded_amount     NUMERIC(12,2) NOT NULL DEFAULT 0,\n\n    -- Milestone-based release\n    milestones          JSONB DEFAULT '[]',  -- [{name, amount, due_date, released_at}, ...]\n\n    -- Third-party escrow provider (future)\n    escrow_provider     TEXT,\n    escrow_reference    TEXT,\n\n    -- Audit\n    funded_at           TIMESTAMPTZ,\n    released_at         TIMESTAMPTZ,\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (deal_id)\n)","COMMENT ON TABLE public.exchange_escrow IS\n    'Escrow accounts for exchange deals. Tracks funding, milestone release, and refunds.'","-- ############################################################################\n-- PART 6: TRIGGERS\n-- ############################################################################\n\nCREATE TRIGGER trg_exchange_requests_updated_at\n    BEFORE UPDATE ON public.exchange_requests\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_exchange_deals_updated_at\n    BEFORE UPDATE ON public.exchange_deals\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_exchange_escrow_updated_at\n    BEFORE UPDATE ON public.exchange_escrow\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","-- ############################################################################\n-- PART 7: RLS\n-- ############################################################################\n\nALTER TABLE public.exchange_requests ENABLE ROW LEVEL SECURITY","ALTER TABLE public.exchange_messages ENABLE ROW LEVEL SECURITY","ALTER TABLE public.exchange_deals ENABLE ROW LEVEL SECURITY","ALTER TABLE public.exchange_escrow ENABLE ROW LEVEL SECURITY","-- Exchange Requests: requester sees own; org_admin sees org's\nCREATE POLICY exchange_requests_select_self ON public.exchange_requests\n    FOR SELECT\n    USING (requester_id = auth.uid())","CREATE POLICY exchange_requests_select_admin ON public.exchange_requests\n    FOR SELECT\n    USING (public.is_org_admin(organization_id))","CREATE POLICY exchange_requests_insert ON public.exchange_requests\n    FOR INSERT\n    WITH CHECK (requester_id = auth.uid())","CREATE POLICY exchange_requests_update ON public.exchange_requests\n    FOR UPDATE\n    USING (requester_id = auth.uid() OR public.is_org_admin(organization_id))\n    WITH CHECK (requester_id = auth.uid() OR public.is_org_admin(organization_id))","-- Messages: participants in the request thread can read/write\nCREATE POLICY exchange_messages_select ON public.exchange_messages\n    FOR SELECT\n    USING (\n        EXISTS (SELECT 1 FROM public.exchange_requests er\n                WHERE er.id = request_id\n                  AND (er.requester_id = auth.uid() OR public.is_org_admin(er.organization_id)))\n    )","CREATE POLICY exchange_messages_insert ON public.exchange_messages\n    FOR INSERT\n    WITH CHECK (sender_id = auth.uid())","-- Deals: participating orgs can see\nCREATE POLICY exchange_deals_select ON public.exchange_deals\n    FOR SELECT\n    USING (\n        public.is_org_member(sponsor_org_id)\n        OR public.is_org_member(provider_org_id)\n        OR public.is_org_admin()\n    )","CREATE POLICY exchange_deals_insert ON public.exchange_deals\n    FOR INSERT\n    WITH CHECK (\n        EXISTS (SELECT 1 FROM public.exchange_requests er\n                WHERE er.id = request_id\n                  AND (er.requester_id = auth.uid() OR public.is_org_admin(er.organization_id)))\n    )","CREATE POLICY exchange_deals_update ON public.exchange_deals\n    FOR UPDATE\n    USING (public.is_org_admin(sponsor_org_id) OR public.is_org_admin(provider_org_id))","-- Escrow: deal participants can see\nCREATE POLICY exchange_escrow_select ON public.exchange_escrow\n    FOR SELECT\n    USING (\n        EXISTS (SELECT 1 FROM public.exchange_deals ed\n                WHERE ed.id = deal_id\n                  AND (public.is_org_member(ed.sponsor_org_id) OR public.is_org_member(ed.provider_org_id)))\n    )","CREATE POLICY exchange_escrow_insert ON public.exchange_escrow\n    FOR INSERT\n    WITH CHECK (\n        EXISTS (SELECT 1 FROM public.exchange_deals ed\n                WHERE ed.id = deal_id AND public.is_org_admin(ed.sponsor_org_id))\n    )","CREATE POLICY exchange_escrow_update ON public.exchange_escrow\n    FOR UPDATE\n    USING (\n        EXISTS (SELECT 1 FROM public.exchange_deals ed\n                WHERE ed.id = deal_id AND public.is_org_admin(ed.sponsor_org_id))\n    )","-- ############################################################################\n-- PART 8: POSTGREST PERMISSIONS\n-- ############################################################################\n\nGRANT ALL ON public.exchange_requests TO anon, authenticated, service_role","GRANT ALL ON public.exchange_messages TO anon, authenticated, service_role","GRANT ALL ON public.exchange_deals TO anon, authenticated, service_role","GRANT ALL ON public.exchange_escrow TO anon, authenticated, service_role","-- ============================================================================\n-- END OF MIGRATION 016 — Sprint 6: Exchange Engine\n-- ============================================================================"}	exchange_engine
017	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 7: Processing Engine\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Dependencies: 008, 009, 010 (programs), 013 (supply_items)\n--\n-- This migration creates the Processing Engine:\n--   1. processing_samples — sample lifecycle state machine\n--   2. processing_aliquots — aliquot management (Sample → Aliquot)\n--   3. processing_workflows — configurable workflow definitions\n--   4. processing_workflow_steps — steps within workflows\n--   5. quality_control_results — QC parameter tracking\n--   6. storage_locations — physical location model\n--   7. instrument_runs — minimal run recording\n--   8. sample_movements — chain of custody\n--   9. RLS policies\n-- (Blueprint §12 — Kadarn Processing Engine)\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: ENUMS\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE sample_state AS ENUM (\n        'collected', 'received', 'accepted', 'processing', 'processed',\n        'qc_pending', 'qc_approved', 'qc_rejected',\n        'stored', 'reserved', 'shipped', 'consumed', 'archived'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE qc_decision AS ENUM ('pass', 'fail', 'borderline');\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: TABLE — processing_samples\n-- ############################################################################\n--\n-- A sample within a Kadarn program. Follows the lifecycle state machine.\n-- (Blueprint §12.2 — Sample Lifecycle, §12.4 — Aliquot Management)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.processing_samples (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    program_id          UUID NOT NULL REFERENCES public.programs(id) ON DELETE CASCADE,\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    -- Identity\n    sample_id           TEXT NOT NULL,                -- human-readable ID within program\n    barcode             TEXT,                         -- physical barcode/QR\n    sample_type         TEXT NOT NULL,                -- serum, plasma, pbmc, dna, rna, ffpe, tissue, etc.\n    parent_sample_id    UUID REFERENCES public.processing_samples(id) ON DELETE SET NULL, -- for derived samples\n\n    -- Lifecycle\n    current_state       sample_state NOT NULL DEFAULT 'collected',\n    state_changed_at    TIMESTAMPTZ,\n    state_changed_by    UUID,\n\n    -- Collection\n    collection_date     DATE,\n    collected_by        TEXT,\n    collection_site     TEXT,\n    container_type      TEXT,                         -- tube, vial, slide, block, etc.\n    initial_quantity    NUMERIC(10,2),\n    quantity_unit       TEXT,                         -- ml, mg, µg, etc.\n\n    -- Program linkage\n    program_requirement_id UUID,\n\n    -- Audit\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (program_id, sample_id)\n)","CREATE INDEX IF NOT EXISTS idx_proc_samples_program ON public.processing_samples(program_id)","CREATE INDEX IF NOT EXISTS idx_proc_samples_org ON public.processing_samples(organization_id)","CREATE INDEX IF NOT EXISTS idx_proc_samples_state ON public.processing_samples(current_state)","CREATE INDEX IF NOT EXISTS idx_proc_samples_type ON public.processing_samples(sample_type)","CREATE INDEX IF NOT EXISTS idx_proc_samples_parent ON public.processing_samples(parent_sample_id)","COMMENT ON TABLE public.processing_samples IS\n    'Samples within Kadarn programs. Each follows the lifecycle state machine from collected to archived.'","-- ############################################################################\n-- PART 3: TABLE — processing_aliquots\n-- ############################################################################\n--\n-- Child aliquots derived from a parent sample.\n-- (Blueprint §12.4 — Aliquot Management)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.processing_aliquots (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    sample_id           UUID NOT NULL REFERENCES public.processing_samples(id) ON DELETE CASCADE,\n    program_id          UUID NOT NULL REFERENCES public.programs(id) ON DELETE CASCADE,\n\n    -- Identity\n    aliquot_id          TEXT NOT NULL,                -- human-readable ID\n    barcode             TEXT,\n\n    -- Quantity\n    quantity            NUMERIC(10,2),\n    quantity_unit       TEXT,\n    concentration       NUMERIC(10,4),\n    concentration_unit  TEXT,\n\n    -- Lifecycle (inherits from sample initially, tracks independently)\n    current_state       sample_state NOT NULL DEFAULT 'stored',\n    state_changed_at    TIMESTAMPTZ,\n    state_changed_by    UUID,\n\n    -- Storage\n    storage_location_id UUID,\n    storage_condition   TEXT,                         -- room_temp, refrigerated, frozen_minus_20, frozen_minus_80, ln2\n\n    -- QC status\n    qc_status           TEXT DEFAULT 'pending' CHECK (qc_status IN ('pending', 'pass', 'fail', 'borderline')),\n\n    -- Audit\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (program_id, aliquot_id)\n)","CREATE INDEX IF NOT EXISTS idx_proc_aliq_sample ON public.processing_aliquots(sample_id)","CREATE INDEX IF NOT EXISTS idx_proc_aliq_program ON public.processing_aliquots(program_id)","CREATE INDEX IF NOT EXISTS idx_proc_aliq_state ON public.processing_aliquots(current_state)","CREATE INDEX IF NOT EXISTS idx_proc_aliq_qc ON public.processing_aliquots(qc_status)","COMMENT ON TABLE public.processing_aliquots IS\n    'Child aliquots derived from parent samples. Each aliquot can have an independent lifecycle.'","-- ############################################################################\n-- PART 4: TABLE — processing_workflows\n-- ############################################################################\n--\n-- Configurable workflow definitions by sample type.\n-- (Blueprint §12.3 — Processing Workflows)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.processing_workflows (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    name                TEXT NOT NULL,\n    sample_type         TEXT NOT NULL,                -- serum, plasma, pbmc, dna, rna, ffpe, etc.\n    description         TEXT,\n    version             INTEGER NOT NULL DEFAULT 1,\n    is_active           BOOLEAN NOT NULL DEFAULT true,\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (sample_type, version)\n)","CREATE INDEX IF NOT EXISTS idx_proc_workflows_type ON public.processing_workflows(sample_type)","COMMENT ON TABLE public.processing_workflows IS\n    'Configurable processing workflow definitions by sample type.'","-- ############################################################################\n-- PART 5: TABLE — processing_workflow_steps\n-- ############################################################################\n--\n-- Individual steps within a workflow.\n-- (Blueprint §12.3 — Processing Workflows)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.processing_workflow_steps (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    workflow_id         UUID NOT NULL REFERENCES public.processing_workflows(id) ON DELETE CASCADE,\n\n    step_order          INTEGER NOT NULL,\n    step_name           TEXT NOT NULL,                -- centrifugation, aliquoting, extraction, etc.\n    description         TEXT,\n    expected_duration_minutes INTEGER,\n    required_equipment  TEXT[] DEFAULT '{}',\n    required_sop        TEXT,                         -- SOP reference\n    qc_required         BOOLEAN NOT NULL DEFAULT false,\n    metadata            JSONB DEFAULT '{}',\n\n    UNIQUE (workflow_id, step_order)\n)","CREATE INDEX IF NOT EXISTS idx_proc_wf_steps_workflow ON public.processing_workflow_steps(workflow_id)","COMMENT ON TABLE public.processing_workflow_steps IS\n    'Individual steps within a processing workflow. Ordered by step_order.'","-- ############################################################################\n-- PART 6: TABLE — quality_control_results\n-- ############################################################################\n--\n-- QC parameter tracking for samples and aliquots.\n-- (Blueprint §12.5 — Quality Control)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.quality_control_results (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    sample_id           UUID REFERENCES public.processing_samples(id) ON DELETE CASCADE,\n    aliquot_id          UUID REFERENCES public.processing_aliquots(id) ON DELETE CASCADE,\n\n    -- QC parameters (Blueprint §12.5)\n    parameter           TEXT NOT NULL,                -- yield, concentration, purity_260_280, purity_260_230, rin, viability, hemolysis\n    value               NUMERIC(15,4),\n    unit                TEXT,\n    decision            qc_decision,\n    operator            TEXT,\n    instrument_used     TEXT,\n    sop_reference       TEXT,\n    notes               TEXT,\n    performed_at        TIMESTAMPTZ NOT NULL DEFAULT now(),\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    CHECK (sample_id IS NOT NULL OR aliquot_id IS NOT NULL)\n)","CREATE INDEX IF NOT EXISTS idx_qc_sample ON public.quality_control_results(sample_id)","CREATE INDEX IF NOT EXISTS idx_qc_aliquot ON public.quality_control_results(aliquot_id)","CREATE INDEX IF NOT EXISTS idx_qc_parameter ON public.quality_control_results(parameter)","COMMENT ON TABLE public.quality_control_results IS\n    'QC parameter results for samples and aliquots. Supports yield, concentration, purity, RIN, viability, hemolysis.'","-- ############################################################################\n-- PART 7: TABLE — storage_locations\n-- ############################################################################\n--\n-- Simplified physical location model for tracking aliquot positions.\n-- (Blueprint §12.6 — Storage Management)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.storage_locations (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n    name                TEXT NOT NULL,\n    location_type       TEXT NOT NULL CHECK (location_type IN ('facility', 'room', 'freezer', 'rack', 'shelf', 'box', 'position')),\n\n    -- Parent location in hierarchy\n    parent_location_id  UUID REFERENCES public.storage_locations(id) ON DELETE CASCADE,\n\n    -- Details\n    description         TEXT,\n    barcode             TEXT,\n    temperature_celsius NUMERIC(5,1),\n    capacity            INTEGER,\n    is_active           BOOLEAN NOT NULL DEFAULT true,\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (organization_id, name, location_type)\n)","CREATE INDEX IF NOT EXISTS idx_storage_org ON public.storage_locations(organization_id)","CREATE INDEX IF NOT EXISTS idx_storage_parent ON public.storage_locations(parent_location_id)","CREATE INDEX IF NOT EXISTS idx_storage_type ON public.storage_locations(location_type)","COMMENT ON TABLE public.storage_locations IS\n    'Physical storage locations. Hierarchy: facility → room → freezer → rack → shelf → box → position.'","-- ############################################################################\n-- PART 8: TABLE — instrument_runs\n-- ############################################################################\n--\n-- Minimal instrument run recording.\n-- (Blueprint §12.8 — Instrument Runs)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.instrument_runs (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    program_id          UUID REFERENCES public.programs(id) ON DELETE SET NULL,\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    instrument          TEXT NOT NULL,                -- instrument name or ID\n    operator            TEXT NOT NULL,                -- person who ran it\n    run_id              TEXT,                         -- instrument run identifier\n    sop_reference       TEXT,                         -- SOP followed\n    run_date            DATE NOT NULL DEFAULT CURRENT_DATE,\n    notes               TEXT,\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_instr_runs_program ON public.instrument_runs(program_id)","CREATE INDEX IF NOT EXISTS idx_instr_runs_org ON public.instrument_runs(organization_id)","CREATE INDEX IF NOT EXISTS idx_instr_runs_instrument ON public.instrument_runs(instrument)","COMMENT ON TABLE public.instrument_runs IS\n    'Minimal instrument run recording. Does NOT control instruments or store raw data.'","-- ############################################################################\n-- PART 9: TABLE — sample_movements\n-- ############################################################################\n--\n-- Chain of custody for sample movements.\n-- (Blueprint §12.7 — Chain of Custody)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.sample_movements (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    sample_id           UUID REFERENCES public.processing_samples(id) ON DELETE CASCADE,\n    aliquot_id          UUID REFERENCES public.processing_aliquots(id) ON DELETE CASCADE,\n\n    program_id          UUID NOT NULL REFERENCES public.programs(id) ON DELETE CASCADE,\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    -- Movement details\n    action              TEXT NOT NULL,                -- received, processed, transferred, shipped, consumed, archived\n    from_location_id    UUID REFERENCES public.storage_locations(id) ON DELETE SET NULL,\n    to_location_id      UUID REFERENCES public.storage_locations(id) ON DELETE SET NULL,\n\n    -- Who\n    performed_by        UUID,\n    performed_by_name   TEXT,\n\n    -- Environmental\n    temperature_celsius NUMERIC(5,1),\n    notes               TEXT,\n\n    -- Chain of custody\n    custody_from        TEXT,                         -- organization/person transferring custody\n    custody_to          TEXT,                         -- organization/person receiving custody\n\n    metadata            JSONB DEFAULT '{}',\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    CHECK (sample_id IS NOT NULL OR aliquot_id IS NOT NULL)\n)","CREATE INDEX IF NOT EXISTS idx_sample_mov_sample ON public.sample_movements(sample_id)","CREATE INDEX IF NOT EXISTS idx_sample_mov_aliquot ON public.sample_movements(aliquot_id)","CREATE INDEX IF NOT EXISTS idx_sample_mov_program ON public.sample_movements(program_id)","CREATE INDEX IF NOT EXISTS idx_sample_mov_created ON public.sample_movements(created_at DESC)","COMMENT ON TABLE public.sample_movements IS\n    'Chain of custody records for sample and aliquot movements. Complements the audit trail.'","-- ############################################################################\n-- PART 10: TRIGGERS\n-- ############################################################################\n\nCREATE TRIGGER trg_processing_samples_updated_at\n    BEFORE UPDATE ON public.processing_samples\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_processing_aliquots_updated_at\n    BEFORE UPDATE ON public.processing_aliquots\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_processing_workflows_updated_at\n    BEFORE UPDATE ON public.processing_workflows\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","-- ############################################################################\n-- PART 11: SAMPLE STATE TRANSITION HELPER\n-- ############################################################################\n\nCREATE OR REPLACE FUNCTION public.transition_sample_state(\n    p_sample_id UUID,\n    p_new_state sample_state,\n    p_user_id UUID\n)\nRETURNS BOOLEAN\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_current sample_state;\n    v_new_ord INTEGER;\n    v_cur_ord INTEGER;\nBEGIN\n    SELECT current_state INTO v_current FROM public.processing_samples WHERE id = p_sample_id;\n    IF NOT FOUND THEN RAISE EXCEPTION 'Sample not found'; END IF;\n\n    SELECT ord INTO v_new_ord FROM (VALUES\n        ('collected'::sample_state, 1), ('received'::sample_state, 2), ('accepted'::sample_state, 3),\n        ('processing'::sample_state, 4), ('processed'::sample_state, 5), ('qc_pending'::sample_state, 6),\n        ('qc_approved'::sample_state, 7), ('qc_rejected'::sample_state, 7),\n        ('stored'::sample_state, 8), ('reserved'::sample_state, 9),\n        ('shipped'::sample_state, 10), ('consumed'::sample_state, 11), ('archived'::sample_state, 12)\n    ) AS t(s, ord) WHERE s = p_new_state;\n\n    SELECT ord INTO v_cur_ord FROM (VALUES\n        ('collected'::sample_state, 1), ('received'::sample_state, 2), ('accepted'::sample_state, 3),\n        ('processing'::sample_state, 4), ('processed'::sample_state, 5), ('qc_pending'::sample_state, 6),\n        ('qc_approved'::sample_state, 7), ('qc_rejected'::sample_state, 7),\n        ('stored'::sample_state, 8), ('reserved'::sample_state, 9),\n        ('shipped'::sample_state, 10), ('consumed'::sample_state, 11), ('archived'::sample_state, 12)\n    ) AS t(s, ord) WHERE s = v_current;\n\n    IF v_new_ord IS NULL OR v_cur_ord IS NULL THEN\n        RAISE EXCEPTION 'Unknown sample state: new=\\"%\\" current=\\"%\\"', p_new_state, v_current;\n    END IF;\n\n    -- Must move forward in lifecycle, unless special case\n    IF v_new_ord <= v_cur_ord THEN\n        -- Allow QC rejected -> qc_pending (retest)\n        IF NOT (v_current = 'qc_rejected' AND p_new_state = 'qc_pending') THEN\n            RAISE EXCEPTION 'Invalid sample state transition: % -> %', v_current, p_new_state;\n        END IF;\n    END IF;\n\n    UPDATE public.processing_samples\n    SET current_state = p_new_state, state_changed_at = now(), state_changed_by = p_user_id\n    WHERE id = p_sample_id;\n\n    RETURN true;\nEND;\n$$","COMMENT ON FUNCTION public.transition_sample_state IS\n    'Validates and executes sample state transitions per Blueprint §12.2.'","-- ############################################################################\n-- PART 12: RLS\n-- ############################################################################\n\nALTER TABLE public.processing_samples ENABLE ROW LEVEL SECURITY","ALTER TABLE public.processing_aliquots ENABLE ROW LEVEL SECURITY","ALTER TABLE public.processing_workflows ENABLE ROW LEVEL SECURITY","ALTER TABLE public.processing_workflow_steps ENABLE ROW LEVEL SECURITY","ALTER TABLE public.quality_control_results ENABLE ROW LEVEL SECURITY","ALTER TABLE public.storage_locations ENABLE ROW LEVEL SECURITY","ALTER TABLE public.instrument_runs ENABLE ROW LEVEL SECURITY","ALTER TABLE public.sample_movements ENABLE ROW LEVEL SECURITY","-- Processing Samples: program participants can view; org_admin of owning org can manage\nCREATE POLICY processing_samples_select ON public.processing_samples\n    FOR SELECT\n    USING (public.can_access_program(program_id) OR public.is_org_admin(organization_id))","CREATE POLICY processing_samples_insert ON public.processing_samples\n    FOR INSERT\n    WITH CHECK (public.is_org_admin(organization_id))","CREATE POLICY processing_samples_update ON public.processing_samples\n    FOR UPDATE\n    USING (public.is_org_admin(organization_id))","CREATE POLICY processing_samples_delete ON public.processing_samples\n    FOR DELETE\n    USING (public.is_org_admin(organization_id))","-- Same pattern for aliquots\nCREATE POLICY processing_aliquots_select ON public.processing_aliquots\n    FOR SELECT\n    USING (public.can_access_program(program_id) OR public.is_org_admin())","CREATE POLICY processing_aliquots_insert ON public.processing_aliquots\n    FOR INSERT\n    WITH CHECK (EXISTS (SELECT 1 FROM public.processing_samples s WHERE s.id = processing_aliquots.sample_id AND public.is_org_admin(s.organization_id)))","CREATE POLICY processing_aliquots_update ON public.processing_aliquots\n    FOR UPDATE\n    USING (EXISTS (SELECT 1 FROM public.processing_samples s WHERE s.id = processing_aliquots.sample_id AND public.is_org_admin(s.organization_id)))","-- Workflows: read for all authenticated, manage for org_admin\nCREATE POLICY processing_workflows_select ON public.processing_workflows\n    FOR SELECT USING (auth.role() = 'authenticated')","CREATE POLICY processing_workflows_insert ON public.processing_workflows\n    FOR INSERT WITH CHECK (public.is_org_admin())","-- QC: program participants\nCREATE POLICY qc_results_select ON public.quality_control_results\n    FOR SELECT\n    USING (EXISTS (SELECT 1 FROM public.processing_samples s WHERE s.id = quality_control_results.sample_id AND public.can_access_program(s.program_id)))","CREATE POLICY qc_results_insert ON public.quality_control_results\n    FOR INSERT\n    WITH CHECK (EXISTS (SELECT 1 FROM public.processing_samples s WHERE s.id = quality_control_results.sample_id AND public.is_org_admin(s.organization_id)))","-- Storage: org_admin manages own org locations\nCREATE POLICY storage_locations_select ON public.storage_locations\n    FOR SELECT USING (public.is_org_member(organization_id) OR public.is_org_admin())","CREATE POLICY storage_locations_insert ON public.storage_locations\n    FOR INSERT WITH CHECK (public.is_org_admin(organization_id))","-- Instrument runs: program visibility\nCREATE POLICY instrument_runs_select ON public.instrument_runs\n    FOR SELECT\n    USING (public.can_access_program(program_id) OR public.is_org_admin(organization_id))","CREATE POLICY instrument_runs_insert ON public.instrument_runs\n    FOR INSERT WITH CHECK (public.is_org_admin(organization_id))","-- Movements: program visibility\nCREATE POLICY sample_movements_select ON public.sample_movements\n    FOR SELECT\n    USING (public.can_access_program(program_id) OR public.is_org_admin(organization_id))","CREATE POLICY sample_movements_insert ON public.sample_movements\n    FOR INSERT\n    WITH CHECK (EXISTS (SELECT 1 FROM public.processing_samples s WHERE s.id = sample_movements.sample_id AND public.is_org_admin(s.organization_id)))","-- ############################################################################\n-- PART 13: POSTGREST PERMISSIONS\n-- ############################################################################\n\nGRANT ALL ON public.processing_samples TO anon, authenticated, service_role","GRANT ALL ON public.processing_aliquots TO anon, authenticated, service_role","GRANT ALL ON public.processing_workflows TO anon, authenticated, service_role","GRANT ALL ON public.processing_workflow_steps TO anon, authenticated, service_role","GRANT ALL ON public.quality_control_results TO anon, authenticated, service_role","GRANT ALL ON public.storage_locations TO anon, authenticated, service_role","GRANT ALL ON public.instrument_runs TO anon, authenticated, service_role","GRANT ALL ON public.sample_movements TO anon, authenticated, service_role","-- ============================================================================\n-- END OF MIGRATION 017 — Sprint 7: Processing Engine\n-- ============================================================================"}	processing_engine
018	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 8: Logistics Engine\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Dependencies: 008, 009, 010 (programs), 013 (supply_items)\n--\n-- This migration creates the Logistics Engine:\n--   1. logistics_shipments — shipping records with carrier tracking\n--   2. logistics_shipment_items — samples/items within a shipment\n--   3. logistics_containers — dry ice, LN2, and other shipping containers\n--   4. logistics_telemetry — temperature monitoring during transit\n--   5. logistics_customs_docs — international shipping documentation\n--   6. logistics_carriers — configured carrier integrations\n--   7. RLS policies\n-- (Blueprint §14 — Logistics Engine)\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: ENUMS\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE shipment_status AS ENUM (\n        'pending', 'label_created', 'picked_up', 'in_transit',\n        'customs_clearance', 'out_for_delivery', 'delivered',\n        'exception', 'lost', 'returned', 'cancelled'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE container_type AS ENUM (\n        'dry_ice_box', 'liquid_nitrogen_dry_shipper', 'refrigerated',\n        'ambient', 'frozen_gel_packs', 'temperature_controlled_container'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE carrier AS ENUM (\n        'fedex', 'dhl', 'world_courier', 'marken', 'ups', 'other'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: TABLE — logistics_shipments\n-- ############################################################################\n--\n-- A shipment record tracking physical transport of biospecimens.\n-- (Blueprint §14.2 — Logistics Components)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.logistics_shipments (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    program_id          UUID NOT NULL REFERENCES public.programs(id) ON DELETE CASCADE,\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    -- Shipment identity\n    shipment_name       TEXT NOT NULL,\n    shipment_type       TEXT NOT NULL DEFAULT 'standard' CHECK (shipment_type IN ('standard', 'express', 'priority_overnight', 'dry_ice', 'cryo')),\n    status              shipment_status NOT NULL DEFAULT 'pending',\n\n    -- Carrier\n    carrier             carrier NOT NULL,\n    carrier_account     TEXT,\n    service_type        TEXT,  -- e.g. 'FedEx Priority Overnight', 'DHL Express Worldwide'\n    tracking_number     TEXT,\n    tracking_url        TEXT,\n\n    -- Shipping addresses\n    origin_org_id       UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\n    origin_address      TEXT,\n    origin_contact      TEXT,\n    origin_phone        TEXT,\n\n    destination_org_id  UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\n    destination_address TEXT,\n    destination_contact TEXT,\n    destination_phone   TEXT,\n\n    -- Scheduling\n    pick_up_date        TIMESTAMPTZ,\n    estimated_delivery  TIMESTAMPTZ,\n    actual_delivery     TIMESTAMPTZ,\n    shipped_date        TIMESTAMPTZ,\n\n    -- Documentation\n    waybill_url         TEXT,\n    label_url           TEXT,\n    commercial_invoice_url TEXT,\n\n    -- Container\n    container_type      container_type,\n    container_prepared_by TEXT,\n\n    -- Tracking metadata\n    last_tracking_event TEXT,\n    last_tracking_at    TIMESTAMPTZ,\n    metadata            JSONB DEFAULT '{}',\n\n    -- Audit\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_log_ship_program ON public.logistics_shipments(program_id)","CREATE INDEX IF NOT EXISTS idx_log_ship_org ON public.logistics_shipments(organization_id)","CREATE INDEX IF NOT EXISTS idx_log_ship_carrier ON public.logistics_shipments(carrier)","CREATE INDEX IF NOT EXISTS idx_log_ship_status ON public.logistics_shipments(status)","CREATE INDEX IF NOT EXISTS idx_log_ship_tracking ON public.logistics_shipments(tracking_number)","COMMENT ON TABLE public.logistics_shipments IS\n    'Shipping records for biospecimen transport. Tracks carrier, status, and documentation.'","-- ############################################################################\n-- PART 3: TABLE — logistics_containers\n-- ############################################################################\n--\n-- Shipping containers for biospecimen transport.\n-- (Blueprint §14.2 — Dry Ice / LN2)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.logistics_containers (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    container_type      container_type NOT NULL,\n    container_name      TEXT NOT NULL,\n    serial_number       TEXT,\n    weight_kg           NUMERIC(8,2),\n    notes               TEXT,\n    is_active           BOOLEAN NOT NULL DEFAULT true,\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_log_containers_org ON public.logistics_containers(organization_id)","COMMENT ON TABLE public.logistics_containers IS\n    'Shipping containers (dry ice boxes, LN2 dry shippers, etc.).'","-- ############################################################################\n-- PART 4: TABLE — logistics_shipment_items\n-- ############################################################################\n--\n-- Links samples/aliquots to shipments.\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.logistics_shipment_items (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    shipment_id         UUID NOT NULL REFERENCES public.logistics_shipments(id) ON DELETE CASCADE,\n    sample_id           UUID REFERENCES public.processing_samples(id) ON DELETE SET NULL,\n    aliquot_id          UUID REFERENCES public.processing_aliquots(id) ON DELETE SET NULL,\n    container_id        UUID REFERENCES public.logistics_containers(id) ON DELETE SET NULL,\n\n    description         TEXT,  -- description of what's being shipped\n    quantity            INTEGER NOT NULL DEFAULT 1,\n    unit                TEXT,\n    declared_value      NUMERIC(12,2),\n\n    CHECK (sample_id IS NOT NULL OR aliquot_id IS NOT NULL)\n)","CREATE INDEX IF NOT EXISTS idx_log_ship_items_shipment ON public.logistics_shipment_items(shipment_id)","CREATE INDEX IF NOT EXISTS idx_log_ship_items_sample ON public.logistics_shipment_items(sample_id)","-- ############################################################################\n-- PART 5: TABLE — logistics_telemetry\n-- ############################################################################\n--\n-- Temperature monitoring during transit.\n-- (Blueprint §14.2 — Temperature Monitoring)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.logistics_telemetry (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    shipment_id         UUID NOT NULL REFERENCES public.logistics_shipments(id) ON DELETE CASCADE,\n\n    recorded_at         TIMESTAMPTZ NOT NULL DEFAULT now(),\n    temperature_celsius NUMERIC(6,2) NOT NULL,\n    humidity_percent    NUMERIC(5,1),\n    battery_level       INTEGER CHECK (battery_level IS NULL OR (battery_level BETWEEN 0 AND 100)),\n\n    -- GPS\n    latitude            NUMERIC(9,6),\n    longitude           NUMERIC(9,6),\n\n    -- Device\n    device_id           TEXT,\n    device_type         TEXT,\n    metadata            JSONB DEFAULT '{}'\n)","CREATE INDEX IF NOT EXISTS idx_log_telemetry_shipment ON public.logistics_telemetry(shipment_id, recorded_at DESC)","CREATE INDEX IF NOT EXISTS idx_log_telemetry_temp ON public.logistics_telemetry(shipment_id, temperature_celsius)","COMMENT ON TABLE public.logistics_telemetry IS\n    'Temperature telemetry from data loggers during transit.'","-- ############################################################################\n-- PART 6: TABLE — logistics_customs_docs\n-- ############################################################################\n--\n-- International shipping customs documentation.\n-- (Blueprint §14.2 — Customs Documentation)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.logistics_customs_docs (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    shipment_id         UUID NOT NULL REFERENCES public.logistics_shipments(id) ON DELETE CASCADE,\n\n    document_type       TEXT NOT NULL CHECK (document_type IN ('commercial_invoice', 'proforma_invoice', 'packing_list', 'certificate_of_origin', 'export_declaration', 'import_permit', 'msds')),\n    document_number     TEXT,\n    document_url        TEXT,\n    content             JSONB DEFAULT '{}',  -- structured document data\n\n    -- HS / commodity codes\n    hs_code             TEXT,\n    commodity           TEXT,\n\n    -- Value\n    declared_value      NUMERIC(12,2),\n    currency            TEXT DEFAULT 'USD',\n\n    -- Status\n    is_ready            BOOLEAN NOT NULL DEFAULT false,\n    filed_at            TIMESTAMPTZ,\n    filed_by            UUID,\n\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_log_customs_shipment ON public.logistics_customs_docs(shipment_id)","CREATE INDEX IF NOT EXISTS idx_log_customs_type ON public.logistics_customs_docs(document_type)","COMMENT ON TABLE public.logistics_customs_docs IS\n    'International shipping customs documentation.'","-- ############################################################################\n-- PART 7: TABLE — logistics_carriers\n-- ############################################################################\n--\n-- Configured carrier integrations for organizations.\n-- (Blueprint §14.2 — Carrier Integration)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.logistics_carriers (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n    carrier             carrier NOT NULL,\n    account_number      TEXT,\n    api_key_encrypted   TEXT,  -- encrypted API key\n    is_active           BOOLEAN NOT NULL DEFAULT true,\n    config              JSONB DEFAULT '{}',  -- carrier-specific configuration\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (organization_id, carrier)\n)","COMMENT ON TABLE public.logistics_carriers IS\n    'Configured carrier accounts for organizations. API keys stored encrypted.'","-- ############################################################################\n-- PART 8: TRIGGERS\n-- ############################################################################\n\nCREATE TRIGGER trg_logistics_shipments_updated_at\n    BEFORE UPDATE ON public.logistics_shipments\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","-- ############################################################################\n-- PART 9: TEMPERATURE BREACH DETECTION\n-- ############################################################################\n\nCREATE OR REPLACE FUNCTION public.check_shipment_temperature_breach(\n    p_shipment_id UUID,\n    p_temperature NUMERIC,\n    p_threshold NUMERIC DEFAULT -50.0\n)\nRETURNS BOOLEAN\nLANGUAGE SQL\nIMMUTABLE\nAS $$\n    SELECT p_temperature > p_threshold;\n$$","COMMENT ON FUNCTION public.check_shipment_temperature_breach IS\n    'Checks if a temperature reading exceeds the threshold for frozen biospecimens.'","-- ############################################################################\n-- PART 10: RLS\n-- ############################################################################\n\nALTER TABLE public.logistics_shipments ENABLE ROW LEVEL SECURITY","ALTER TABLE public.logistics_shipment_items ENABLE ROW LEVEL SECURITY","ALTER TABLE public.logistics_containers ENABLE ROW LEVEL SECURITY","ALTER TABLE public.logistics_telemetry ENABLE ROW LEVEL SECURITY","ALTER TABLE public.logistics_customs_docs ENABLE ROW LEVEL SECURITY","ALTER TABLE public.logistics_carriers ENABLE ROW LEVEL SECURITY","-- Shipments: program participants can view; org_admin of sending/receiving org can manage\nCREATE POLICY logistics_shipments_select ON public.logistics_shipments\n    FOR SELECT\n    USING (public.can_access_program(program_id) OR public.is_org_admin(organization_id))","CREATE POLICY logistics_shipments_insert ON public.logistics_shipments\n    FOR INSERT\n    WITH CHECK (auth.role() = 'authenticated' AND public.is_org_admin(organization_id))","CREATE POLICY logistics_shipments_update ON public.logistics_shipments\n    FOR UPDATE\n    USING (public.is_org_admin(organization_id))","CREATE POLICY logistics_shipments_delete ON public.logistics_shipments\n    FOR DELETE\n    USING (public.is_org_admin(organization_id))","-- Shipment items: same as parent shipment\nCREATE POLICY logistics_shipment_items_select ON public.logistics_shipment_items\n    FOR SELECT\n    USING (EXISTS (SELECT 1 FROM public.logistics_shipments s WHERE s.id = shipment_id AND public.can_access_program(s.program_id)))","CREATE POLICY logistics_shipment_items_insert ON public.logistics_shipment_items\n    FOR INSERT\n    WITH CHECK (auth.role() = 'authenticated')","-- Containers: org members can see, org_admin can manage\nCREATE POLICY logistics_containers_select ON public.logistics_containers\n    FOR SELECT\n    USING (public.is_org_member(organization_id) OR public.is_org_admin())","CREATE POLICY logistics_containers_insert ON public.logistics_containers\n    FOR INSERT\n    WITH CHECK (auth.role() = 'authenticated' AND public.is_org_admin(organization_id))","-- Telemetry: program participants\nCREATE POLICY logistics_telemetry_select ON public.logistics_telemetry\n    FOR SELECT\n    USING (EXISTS (SELECT 1 FROM public.logistics_shipments s WHERE s.id = shipment_id AND public.can_access_program(s.program_id)))","CREATE POLICY logistics_telemetry_insert ON public.logistics_telemetry\n    FOR INSERT\n    WITH CHECK (auth.role() = 'authenticated')","-- Customs docs: same as shipment\nCREATE POLICY logistics_customs_docs_select ON public.logistics_customs_docs\n    FOR SELECT\n    USING (EXISTS (SELECT 1 FROM public.logistics_shipments s WHERE s.id = shipment_id AND public.can_access_program(s.program_id)))","CREATE POLICY logistics_customs_docs_insert ON public.logistics_customs_docs\n    FOR INSERT\n    WITH CHECK (auth.role() = 'authenticated')","-- Carriers: org admin only\nCREATE POLICY logistics_carriers_select ON public.logistics_carriers\n    FOR SELECT\n    USING (public.is_org_admin(organization_id) OR public.is_org_member(organization_id))","CREATE POLICY logistics_carriers_insert ON public.logistics_carriers\n    FOR INSERT\n    WITH CHECK (auth.role() = 'authenticated' AND public.is_org_admin(organization_id))","CREATE POLICY logistics_carriers_update ON public.logistics_carriers\n    FOR UPDATE\n    USING (public.is_org_admin(organization_id))","-- ############################################################################\n-- PART 11: POSTGREST PERMISSIONS\n-- ############################################################################\n\nGRANT ALL ON public.logistics_shipments TO anon, authenticated, service_role","GRANT ALL ON public.logistics_shipment_items TO anon, authenticated, service_role","GRANT ALL ON public.logistics_containers TO anon, authenticated, service_role","GRANT ALL ON public.logistics_telemetry TO anon, authenticated, service_role","GRANT ALL ON public.logistics_customs_docs TO anon, authenticated, service_role","GRANT ALL ON public.logistics_carriers TO anon, authenticated, service_role","-- ============================================================================\n-- END OF MIGRATION 018 — Sprint 8: Logistics Engine\n-- ============================================================================"}	logistics_engine
019	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 9: Regulatory Engine\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Dependencies: 008, 009, 010 (programs)\n--\n-- This migration creates the Regulatory Engine:\n--   1. regulatory_protocols — master protocol library\n--   2. regulatory_icf_templates — informed consent form templates\n--   3. regulatory_sops — standard operating procedures\n--   4. regulatory_submissions — IRB/ethics submission tracking\n--   5. regulatory_documents — secure document exchange\n--   6. regulatory_document_access — document access control\n--   7. RLS policies\n-- (Blueprint §11 — Regulatory Engine)\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: ENUMS\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE submission_status AS ENUM (\n        'draft', 'preparing', 'submitted', 'under_review',\n        'revisions_requested', 'approved', 'exempt', 'rejected', 'withdrawn'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE document_category AS ENUM (\n        'protocol', 'icf', 'sop', 'regulatory_approval', 'contract',\n        'insurance', 'investigator_cv', 'financial_disclosure',\n        'device_documentation', 'lab_certification', 'other'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: TABLE — regulatory_protocols\n-- ############################################################################\n--\n-- Reusable master protocol library.\n-- (Blueprint §11.2 — Protocol Library)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.regulatory_protocols (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    -- Protocol identity\n    protocol_id         TEXT NOT NULL,  -- e.g. 'KAD-PRO-001'\n    title               TEXT NOT NULL,\n    version             TEXT NOT NULL DEFAULT '1.0',\n    description         TEXT,\n    short_name          TEXT,\n\n    -- Classification\n    therapeutic_area    TEXT[] DEFAULT '{}',\n    sample_types        TEXT[] DEFAULT '{}',\n    phase               TEXT,  -- I, II, III, IV, OBS, etc.\n    study_type          TEXT,  -- retrospective, prospective, longitudinal, etc.\n\n    -- Content (stored as markdown or document reference)\n    document_url        TEXT,\n    content_markdown    TEXT,\n\n    -- Status\n    is_active           BOOLEAN NOT NULL DEFAULT true,\n    is_template         BOOLEAN NOT NULL DEFAULT false,  -- reusable template\n    approval_status     TEXT DEFAULT 'draft' CHECK (approval_status IN ('draft', 'under_review', 'approved', 'superseded')),\n\n    -- Versioning\n    superseded_by       UUID REFERENCES public.regulatory_protocols(id) ON DELETE SET NULL,\n\n    -- Metadata\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (organization_id, protocol_id)\n)","CREATE INDEX IF NOT EXISTS idx_reg_protocols_org ON public.regulatory_protocols(organization_id)","CREATE INDEX IF NOT EXISTS idx_reg_protocols_area ON public.regulatory_protocols USING GIN(therapeutic_area)","CREATE INDEX IF NOT EXISTS idx_reg_protocols_active ON public.regulatory_protocols(is_active)","COMMENT ON TABLE public.regulatory_protocols IS\n    'Master protocol library. Reusable templates for biospecimen programs. Key compounding asset (Blueprint §11.3).'","-- ############################################################################\n-- PART 3: TABLE — regulatory_icf_templates\n-- ############################################################################\n--\n-- Informed Consent Form templates by region and study type.\n-- (Blueprint §11.2 — ICF Templates)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.regulatory_icf_templates (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    template_id         TEXT NOT NULL,  -- e.g. 'ICF-TPL-001'\n    title               TEXT NOT NULL,\n    version             TEXT NOT NULL DEFAULT '1.0',\n    description         TEXT,\n    region              TEXT,  -- US, EU, LATAM, APAC, etc.\n    language            TEXT DEFAULT 'en',\n\n    -- Content\n    document_url        TEXT,\n    content_markdown    TEXT,\n\n    -- Applicability\n    study_types         TEXT[] DEFAULT '{}',\n    sample_types        TEXT[] DEFAULT '{}',\n    requires_signature  BOOLEAN NOT NULL DEFAULT true,\n    requires_witness    BOOLEAN NOT NULL DEFAULT false,\n    is_active           BOOLEAN NOT NULL DEFAULT true,\n    is_template         BOOLEAN NOT NULL DEFAULT true,\n\n    -- Metadata\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (organization_id, template_id)\n)","CREATE INDEX IF NOT EXISTS idx_reg_icf_org ON public.regulatory_icf_templates(organization_id)","CREATE INDEX IF NOT EXISTS idx_reg_icf_region ON public.regulatory_icf_templates(region)","COMMENT ON TABLE public.regulatory_icf_templates IS\n    'Informed Consent Form templates. Reusable by region and study type.'","-- ############################################################################\n-- PART 4: TABLE — regulatory_sops\n-- ############################################################################\n--\n-- Standard Operating Procedures for collection, processing, and shipping.\n-- (Blueprint §11.2 — SOP Library)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.regulatory_sops (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    sop_id              TEXT NOT NULL,  -- e.g. 'SOP-COL-001'\n    title               TEXT NOT NULL,\n    version             TEXT NOT NULL DEFAULT '1.0',\n    description         TEXT,\n    category            TEXT NOT NULL CHECK (category IN ('collection', 'processing', 'shipping', 'qc', 'data_management', 'general')),\n    document_url        TEXT,\n    content_markdown    TEXT,\n    is_active           BOOLEAN NOT NULL DEFAULT true,\n    effective_date      DATE,\n    review_date         DATE,  -- next required review\n\n    -- Metadata\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (organization_id, sop_id)\n)","CREATE INDEX IF NOT EXISTS idx_reg_sops_org ON public.regulatory_sops(organization_id)","CREATE INDEX IF NOT EXISTS idx_reg_sops_category ON public.regulatory_sops(category)","COMMENT ON TABLE public.regulatory_sops IS\n    'Standard Operating Procedures for biospecimen handling.'","-- ############################################################################\n-- PART 5: TABLE — regulatory_submissions\n-- ############################################################################\n--\n-- IRB/ethics submission tracking across sites and programs.\n-- (Blueprint §11.2 — Submission Tracker)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.regulatory_submissions (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    program_id          UUID NOT NULL REFERENCES public.programs(id) ON DELETE CASCADE,\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n    site_org_id         UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\n\n    -- Submission\n    submission_type     TEXT NOT NULL CHECK (submission_type IN ('initial', 'amendment', 'continuing_review', 'protocol_deviation', 'adverse_event', 'closure')),\n    status              submission_status NOT NULL DEFAULT 'draft',\n\n    -- IRB details\n    irb_name            TEXT,\n    irb_number          TEXT,  -- assigned IRB number\n    irb_contact         TEXT,\n\n    -- Protocol reference\n    protocol_id         UUID REFERENCES public.regulatory_protocols(id) ON DELETE SET NULL,\n\n    -- Dates\n    submitted_at        TIMESTAMPTZ,\n    decision_at         TIMESTAMPTZ,\n    expiration_at       DATE,\n    last_review_at      TIMESTAMPTZ,\n\n    -- Documents\n    submission_doc_url  TEXT,\n    approval_letter_url TEXT,\n\n    -- Notes\n    notes               TEXT,\n    metadata            JSONB DEFAULT '{}',\n\n    created_by          UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_reg_sub_program ON public.regulatory_submissions(program_id)","CREATE INDEX IF NOT EXISTS idx_reg_sub_org ON public.regulatory_submissions(organization_id)","CREATE INDEX IF NOT EXISTS idx_reg_sub_status ON public.regulatory_submissions(status)","CREATE INDEX IF NOT EXISTS idx_reg_sub_irb ON public.regulatory_submissions(irb_name)","COMMENT ON TABLE public.regulatory_submissions IS\n    'IRB/ethics submission tracking. Tracks status across sites and programs.'","-- ############################################################################\n-- PART 6: TABLE — regulatory_documents\n-- ############################################################################\n--\n-- Secure document exchange with access control.\n-- (Blueprint §11.2 — Document Exchange)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.regulatory_documents (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    program_id          UUID REFERENCES public.programs(id) ON DELETE CASCADE,\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    document_category   document_category NOT NULL,\n    title               TEXT NOT NULL,\n    description         TEXT,\n    file_name           TEXT,\n    file_url            TEXT,\n    file_size           BIGINT,\n    mime_type           TEXT,\n\n    -- Version tracking\n    version             TEXT DEFAULT '1.0',\n    supersedes          UUID REFERENCES public.regulatory_documents(id) ON DELETE SET NULL,\n\n    -- Status\n    is_confidential     BOOLEAN NOT NULL DEFAULT true,\n    requires_nda        BOOLEAN NOT NULL DEFAULT false,\n    is_active           BOOLEAN NOT NULL DEFAULT true,\n\n    -- Audit\n    metadata            JSONB DEFAULT '{}',\n    uploaded_by         UUID NOT NULL,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_reg_docs_program ON public.regulatory_documents(program_id)","CREATE INDEX IF NOT EXISTS idx_reg_docs_org ON public.regulatory_documents(organization_id)","CREATE INDEX IF NOT EXISTS idx_reg_docs_category ON public.regulatory_documents(document_category)","COMMENT ON TABLE public.regulatory_documents IS\n    'Secure document exchange. Supports versioning and confidentiality controls.'","-- ############################################################################\n-- PART 7: TABLE — regulatory_document_access\n-- ############################################################################\n--\n-- Document access control for confidential documents.\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.regulatory_document_access (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    document_id         UUID NOT NULL REFERENCES public.regulatory_documents(id) ON DELETE CASCADE,\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    granted_by          UUID NOT NULL,\n    granted_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    expires_at          TIMESTAMPTZ,\n    is_active           BOOLEAN NOT NULL DEFAULT true,\n\n    UNIQUE (document_id, organization_id)\n)","CREATE INDEX IF NOT EXISTS idx_reg_doc_access_doc ON public.regulatory_document_access(document_id)","CREATE INDEX IF NOT EXISTS idx_reg_doc_access_org ON public.regulatory_document_access(organization_id)","COMMENT ON TABLE public.regulatory_document_access IS\n    'Document access control. Tracks which organizations can access confidential documents.'","-- ############################################################################\n-- PART 8: TRIGGERS\n-- ############################################################################\n\nCREATE TRIGGER trg_regulatory_protocols_updated_at\n    BEFORE UPDATE ON public.regulatory_protocols\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_regulatory_icf_templates_updated_at\n    BEFORE UPDATE ON public.regulatory_icf_templates\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_regulatory_sops_updated_at\n    BEFORE UPDATE ON public.regulatory_sops\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_regulatory_submissions_updated_at\n    BEFORE UPDATE ON public.regulatory_submissions\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_regulatory_documents_updated_at\n    BEFORE UPDATE ON public.regulatory_documents\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","-- ############################################################################\n-- PART 9: RLS\n-- ############################################################################\n\nALTER TABLE public.regulatory_protocols ENABLE ROW LEVEL SECURITY","ALTER TABLE public.regulatory_icf_templates ENABLE ROW LEVEL SECURITY","ALTER TABLE public.regulatory_sops ENABLE ROW LEVEL SECURITY","ALTER TABLE public.regulatory_submissions ENABLE ROW LEVEL SECURITY","ALTER TABLE public.regulatory_documents ENABLE ROW LEVEL SECURITY","ALTER TABLE public.regulatory_document_access ENABLE ROW LEVEL SECURITY","-- Protocols: all authenticated can read templates, org_admin manages own\nCREATE POLICY regulatory_protocols_select ON public.regulatory_protocols\n    FOR SELECT USING (auth.role() = 'authenticated')","CREATE POLICY regulatory_protocols_insert ON public.regulatory_protocols\n    FOR INSERT WITH CHECK (auth.role() = 'authenticated' AND public.is_org_admin(organization_id))","CREATE POLICY regulatory_protocols_update ON public.regulatory_protocols\n    FOR UPDATE USING (public.is_org_admin(organization_id))","CREATE POLICY regulatory_protocols_delete ON public.regulatory_protocols\n    FOR DELETE USING (public.is_org_admin(organization_id))","-- ICF templates: same pattern\nCREATE POLICY regulatory_icf_select ON public.regulatory_icf_templates\n    FOR SELECT USING (auth.role() = 'authenticated')","CREATE POLICY regulatory_icf_insert ON public.regulatory_icf_templates\n    FOR INSERT WITH CHECK (auth.role() = 'authenticated' AND public.is_org_admin(organization_id))","-- SOPs: same pattern\nCREATE POLICY regulatory_sops_select ON public.regulatory_sops\n    FOR SELECT USING (auth.role() = 'authenticated')","CREATE POLICY regulatory_sops_insert ON public.regulatory_sops\n    FOR INSERT WITH CHECK (auth.role() = 'authenticated' AND public.is_org_admin(organization_id))","-- Submissions: program participants\nCREATE POLICY regulatory_submissions_select ON public.regulatory_submissions\n    FOR SELECT USING (public.can_access_program(program_id) OR public.is_org_admin(organization_id))","CREATE POLICY regulatory_submissions_insert ON public.regulatory_submissions\n    FOR INSERT WITH CHECK (auth.role() = 'authenticated')","CREATE POLICY regulatory_submissions_update ON public.regulatory_submissions\n    FOR UPDATE USING (public.is_org_admin(organization_id))","-- Documents: program participants or org_admin\nCREATE POLICY regulatory_documents_select ON public.regulatory_documents\n    FOR SELECT\n    USING (\n        public.can_access_program(program_id)\n        OR public.is_org_admin(organization_id)\n        OR EXISTS (SELECT 1 FROM public.regulatory_document_access da WHERE da.document_id = id AND public.is_org_member(da.organization_id))\n    )","CREATE POLICY regulatory_documents_insert ON public.regulatory_documents\n    FOR INSERT WITH CHECK (auth.role() = 'authenticated')","-- Document access: org_admin can grant access\nCREATE POLICY regulatory_doc_access_select ON public.regulatory_document_access\n    FOR SELECT\n    USING (public.is_org_member(organization_id) OR public.is_org_admin())","CREATE POLICY regulatory_doc_access_insert ON public.regulatory_document_access\n    FOR INSERT WITH CHECK (auth.role() = 'authenticated')","-- ############################################################################\n-- PART 10: POSTGREST PERMISSIONS\n-- ############################################################################\n\nGRANT ALL ON public.regulatory_protocols TO anon, authenticated, service_role","GRANT ALL ON public.regulatory_icf_templates TO anon, authenticated, service_role","GRANT ALL ON public.regulatory_sops TO anon, authenticated, service_role","GRANT ALL ON public.regulatory_submissions TO anon, authenticated, service_role","GRANT ALL ON public.regulatory_documents TO anon, authenticated, service_role","GRANT ALL ON public.regulatory_document_access TO anon, authenticated, service_role","-- ============================================================================\n-- END OF MIGRATION 019 — Sprint 9: Regulatory Engine\n-- ============================================================================"}	regulatory_engine
020	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 10: Analytics Engine\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Dependencies: All prior migrations (008-019)\n--\n-- This migration creates the Analytics Engine:\n--   1. analytics_network_snapshots — periodic network health\n--   2. analytics_program_metrics — program performance\n--   3. analytics_supplier_metrics — supplier quality tracking\n--   4. analytics_search_queries — search/discovery analytics\n--   5. Materialized views for dashboards\n--   6. RLS policies\n-- (Blueprint §16 — Analytics Engine)\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: TABLE — analytics_network_snapshots\n-- ############################################################################\n--\n-- Periodic snapshots of network health.\n-- (Blueprint §16.2 — Network Health)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.analytics_network_snapshots (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n\n    -- Snapshot period\n    period_start        DATE NOT NULL,\n    period_end          DATE NOT NULL,\n    snapshot_type       TEXT NOT NULL DEFAULT 'daily' CHECK (snapshot_type IN ('daily', 'weekly', 'monthly')),\n\n    -- Organization metrics\n    total_organizations     INTEGER NOT NULL DEFAULT 0,\n    active_organizations    INTEGER NOT NULL DEFAULT 0,\n    total_capabilities      INTEGER NOT NULL DEFAULT 0,\n    orgs_by_country         JSONB DEFAULT '{}',\n\n    -- Program metrics\n    total_programs          INTEGER NOT NULL DEFAULT 0,\n    active_programs         INTEGER NOT NULL DEFAULT 0,\n    completed_programs      INTEGER NOT NULL DEFAULT 0,\n\n    -- Supply metrics\n    total_supply_items      INTEGER NOT NULL DEFAULT 0,\n    supply_items_by_type    JSONB DEFAULT '{}',\n\n    -- Network activity\n    total_exchange_requests INTEGER NOT NULL DEFAULT 0,\n    total_deals             INTEGER NOT NULL DEFAULT 0,\n    active_deals            INTEGER NOT NULL DEFAULT 0,\n    total_audit_events      INTEGER NOT NULL DEFAULT 0,\n\n    metadata                JSONB DEFAULT '{}',\n    computed_at             TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (period_start, snapshot_type)\n)","CREATE INDEX IF NOT EXISTS idx_analytics_snapshots_period\n    ON public.analytics_network_snapshots(period_start DESC)","COMMENT ON TABLE public.analytics_network_snapshots IS\n    'Periodic network health snapshots for trend analysis.'","-- ############################################################################\n-- PART 2: TABLE — analytics_program_metrics\n-- ############################################################################\n--\n-- Per-program performance metrics.\n-- (Blueprint §16.2 — Program Performance)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.analytics_program_metrics (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    program_id          UUID NOT NULL REFERENCES public.programs(id) ON DELETE CASCADE,\n\n    -- Timeline metrics\n    days_in_draft       INTEGER,\n    days_active         INTEGER,\n    days_to_completion  INTEGER,   -- draft → completed\n    days_to_first_milestone INTEGER,\n\n    -- Participant metrics\n    participant_count   INTEGER NOT NULL DEFAULT 0,\n    org_countries       TEXT[] DEFAULT '{}',\n\n    -- Milestone metrics\n    total_milestones    INTEGER NOT NULL DEFAULT 0,\n    completed_milestones INTEGER NOT NULL DEFAULT 0,\n    milestone_completion_rate NUMERIC(5,2),  -- percentage\n\n    -- Sample metrics (from processing engine)\n    total_samples       INTEGER NOT NULL DEFAULT 0,\n    processed_samples   INTEGER NOT NULL DEFAULT 0,\n\n    -- Exchange metrics\n    total_requests      INTEGER NOT NULL DEFAULT 0,\n    total_deals         INTEGER NOT NULL DEFAULT 0,\n    deal_value_total    NUMERIC(14,2),\n\n    -- Audit\n    metadata            JSONB DEFAULT '{}',\n    computed_at         TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (program_id)\n)","CREATE INDEX IF NOT EXISTS idx_analytics_program_metrics_prog\n    ON public.analytics_program_metrics(program_id)","COMMENT ON TABLE public.analytics_program_metrics IS\n    'Per-program performance metrics. Updated by periodic computation.'","-- ############################################################################\n-- PART 3: TABLE — analytics_supplier_metrics\n-- ############################################################################\n--\n-- Supplier quality and performance tracking.\n-- (Blueprint §16.2 — Supplier Quality)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.analytics_supplier_metrics (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\n\n    -- Time period\n    period_start        DATE NOT NULL,\n    period_end          DATE NOT NULL,\n\n    -- Program involvement\n    programs_participated   INTEGER NOT NULL DEFAULT 0,\n    programs_completed      INTEGER NOT NULL DEFAULT 0,\n\n    -- Delivery metrics\n    total_deliveries        INTEGER NOT NULL DEFAULT 0,\n    on_time_deliveries      INTEGER NOT NULL DEFAULT 0,\n    on_time_rate            NUMERIC(5,2),  -- percentage\n    avg_fulfillment_days    NUMERIC(8,2),\n\n    -- Quality metrics\n    total_qc_checks         INTEGER NOT NULL DEFAULT 0,\n    qc_pass_count           INTEGER NOT NULL DEFAULT 0,\n    qc_pass_rate            NUMERIC(5,2),\n\n    -- Temperature compliance (for logistics providers)\n    total_shipments         INTEGER NOT NULL DEFAULT 0,\n    breach_free_shipments   INTEGER NOT NULL DEFAULT 0,\n    temp_compliance_rate    NUMERIC(5,2),\n\n    -- Exchange metrics\n    deals_as_provider       INTEGER NOT NULL DEFAULT 0,\n    deals_completed         INTEGER NOT NULL DEFAULT 0,\n    deal_completion_rate    NUMERIC(5,2),\n\n    -- Computed\n    metadata            JSONB DEFAULT '{}',\n    computed_at         TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (organization_id, period_start)\n)","CREATE INDEX IF NOT EXISTS idx_analytics_supplier_org\n    ON public.analytics_supplier_metrics(organization_id)","CREATE INDEX IF NOT EXISTS idx_analytics_supplier_period\n    ON public.analytics_supplier_metrics(period_start DESC)","COMMENT ON TABLE public.analytics_supplier_metrics IS\n    'Supplier quality and performance metrics. Key for feasibility engine.'","-- ############################################################################\n-- PART 4: TABLE — analytics_search_queries\n-- ############################################################################\n--\n-- Tracks search queries for discovery analytics.\n-- (Blueprint §16.3 — Data Sources)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.analytics_search_queries (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n\n    -- Query\n    search_text         TEXT,\n    filters_used        JSONB DEFAULT '{}',\n    result_count        INTEGER,\n    user_id             UUID,\n\n    -- Timing\n    query_date          DATE NOT NULL DEFAULT CURRENT_DATE,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_analytics_search_date\n    ON public.analytics_search_queries(query_date DESC)","CREATE INDEX IF NOT EXISTS idx_analytics_search_text\n    ON public.analytics_search_queries(search_text)","COMMENT ON TABLE public.analytics_search_queries IS\n    'Search query tracking for discovery analytics.'","-- ############################################################################\n-- PART 5: ANALYTICS FUNCTIONS\n-- ############################################################################\n\n-- Compute network snapshot\nCREATE OR REPLACE FUNCTION public.compute_network_snapshot(\n    p_period_start DATE,\n    p_period_end DATE,\n    p_snapshot_type TEXT DEFAULT 'daily'\n)\nRETURNS UUID\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_snapshot_id UUID;\nBEGIN\n    INSERT INTO public.analytics_network_snapshots (\n        period_start, period_end, snapshot_type,\n        total_organizations, active_organizations, total_capabilities, orgs_by_country,\n        total_programs, active_programs, completed_programs,\n        total_supply_items, supply_items_by_type,\n        total_exchange_requests, total_deals, active_deals,\n        total_audit_events\n    )\n    SELECT\n        p_period_start, p_period_end, p_snapshot_type,\n        (SELECT COUNT(*) FROM public.organizations),\n        (SELECT COUNT(*) FROM public.organizations WHERE is_active = true),\n        (SELECT COUNT(*) FROM public.organization_capabilities),\n        (SELECT COALESCE(jsonb_object_agg(country, cnt), '{}'::jsonb)\n         FROM (SELECT country, COUNT(*) as cnt FROM public.organizations GROUP BY country) AS orgs),\n        (SELECT COUNT(*) FROM public.programs),\n        (SELECT COUNT(*) FROM public.programs WHERE status = 'active'),\n        (SELECT COUNT(*) FROM public.programs WHERE status = 'completed'),\n        (SELECT COUNT(*) FROM public.supply_items),\n        (SELECT COALESCE(jsonb_object_agg(type, cnt), '{}'::jsonb)\n         FROM (SELECT type::text, COUNT(*) as cnt FROM public.supply_items GROUP BY type) AS si),\n        (SELECT COUNT(*) FROM public.exchange_requests),\n        (SELECT COUNT(*) FROM public.exchange_deals),\n        (SELECT COUNT(*) FROM public.exchange_deals WHERE status IN ('active', 'fulfillment')),\n        (SELECT COUNT(*) FROM public.audit_events)\n    RETURNING id INTO v_snapshot_id;\n\n    RETURN v_snapshot_id;\nEND;\n$$","COMMENT ON FUNCTION public.compute_network_snapshot IS\n    'Computes a periodic network health snapshot from all data sources.'","-- Compute program metrics\nCREATE OR REPLACE FUNCTION public.compute_program_metrics(p_program_id UUID)\nRETURNS UUID\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_metrics_id UUID;\nBEGIN\n    INSERT INTO public.analytics_program_metrics (\n        program_id,\n        days_in_draft, days_active, days_to_completion,\n        participant_count, org_countries,\n        total_milestones, completed_milestones, milestone_completion_rate,\n        total_samples, processed_samples,\n        total_requests, total_deals, deal_value_total\n    )\n    SELECT\n        p_program_id,\n        -- days in draft\n        (SELECT CASE WHEN status = 'draft' THEN EXTRACT(DAY FROM now() - created_at)::INTEGER ELSE NULL END\n         FROM public.programs WHERE id = p_program_id),\n        -- days active\n        (SELECT CASE WHEN status = 'active' THEN EXTRACT(DAY FROM now() - created_at)::INTEGER ELSE NULL END\n         FROM public.programs WHERE id = p_program_id),\n        -- days to completion\n        (SELECT EXTRACT(DAY FROM updated_at - created_at)::INTEGER\n         FROM public.programs WHERE id = p_program_id AND status = 'completed'),\n        -- participants\n        (SELECT COUNT(*) FROM public.program_participants WHERE program_id = p_program_id),\n        -- org countries\n        (SELECT ARRAY_AGG(DISTINCT o.country) FROM public.program_participants pp\n         JOIN public.organizations o ON o.id = pp.organization_id WHERE pp.program_id = p_program_id),\n        -- milestones\n        (SELECT COUNT(*) FROM public.program_milestones WHERE program_id = p_program_id),\n        (SELECT COUNT(*) FROM public.program_milestones WHERE program_id = p_program_id AND status = 'completed'),\n        -- milestone completion rate\n        (SELECT CASE WHEN COUNT(*) > 0 THEN ROUND(SUM(CASE WHEN status = 'completed' THEN 1 ELSE 0 END)::NUMERIC / COUNT(*) * 100, 2) ELSE 0 END\n         FROM public.program_milestones WHERE program_id = p_program_id),\n        -- samples\n        (SELECT COUNT(*) FROM public.processing_samples WHERE program_id = p_program_id),\n        (SELECT COUNT(*) FROM public.processing_samples WHERE program_id = p_program_id AND current_state IN ('stored', 'shipped', 'consumed', 'archived')),\n        -- exchange\n        (SELECT COUNT(*) FROM public.exchange_requests WHERE program_id = p_program_id),\n        (SELECT COUNT(*) FROM public.exchange_deals WHERE program_id = p_program_id),\n        (SELECT SUM(total_value) FROM public.exchange_deals WHERE program_id = p_program_id)\n    RETURNING id INTO v_metrics_id;\n\n    RETURN v_metrics_id;\nEND;\n$$","COMMENT ON FUNCTION public.compute_program_metrics IS\n    'Computes performance metrics for a specific program.'","-- ############################################################################\n-- PART 6: MATERIALIZED VIEWS\n-- ############################################################################\n\n-- Network overview dashboard\nCREATE MATERIALIZED VIEW IF NOT EXISTS public.vw_network_overview AS\nSELECT\n    COUNT(DISTINCT o.id) AS total_organizations,\n    COUNT(DISTINCT o.id) FILTER (WHERE o.is_active) AS active_organizations,\n    COUNT(DISTINCT oct.key) AS capability_types,\n    COUNT(DISTINCT oc.id) AS total_capabilities,\n    COUNT(DISTINCT p.id) AS total_programs,\n    COUNT(DISTINCT p.id) FILTER (WHERE p.status = 'active') AS active_programs,\n    COUNT(DISTINCT si.id) AS supply_items,\n    COUNT(DISTINCT er.id) AS exchange_requests,\n    COUNT(DISTINCT ed.id) AS exchange_deals,\n    COUNT(DISTINCT ps.id) AS processing_samples\nFROM public.organizations o\nLEFT JOIN public.organization_capabilities oc ON oc.organization_id = o.id\nLEFT JOIN public.organization_capability_types oct ON oct.id = oc.capability_type_id\nLEFT JOIN public.programs p ON true\nLEFT JOIN public.supply_items si ON true\nLEFT JOIN public.exchange_requests er ON true\nLEFT JOIN public.exchange_deals ed ON true\nLEFT JOIN public.processing_samples ps ON true","COMMENT ON MATERIALIZED VIEW public.vw_network_overview IS\n    'Network overview dashboard — aggregate counts across all entities.'","-- Program performance view\nCREATE MATERIALIZED VIEW IF NOT EXISTS public.vw_program_performance AS\nSELECT\n    p.id AS program_id,\n    p.name AS program_name,\n    p.status,\n    p.created_at,\n    p.updated_at,\n    COUNT(DISTINCT pp.organization_id) AS participant_count,\n    COUNT(DISTINCT pm.id) AS milestone_count,\n    COUNT(DISTINCT pm.id) FILTER (WHERE pm.status = 'completed') AS milestones_completed,\n    COUNT(DISTINCT ps.id) AS sample_count,\n    COUNT(DISTINCT ed.id) AS deal_count\nFROM public.programs p\nLEFT JOIN public.program_participants pp ON pp.program_id = p.id\nLEFT JOIN public.program_milestones pm ON pm.program_id = p.id\nLEFT JOIN public.processing_samples ps ON ps.program_id = p.id\nLEFT JOIN public.exchange_deals ed ON ed.program_id = p.id\nGROUP BY p.id, p.name, p.status, p.created_at, p.updated_at","COMMENT ON MATERIALIZED VIEW public.vw_program_performance IS\n    'Program performance view — aggregate metrics per program.'","-- Supplier quality view\nCREATE MATERIALIZED VIEW IF NOT EXISTS public.vw_supplier_quality AS\nSELECT\n    o.id AS organization_id,\n    o.name AS organization_name,\n    o.country,\n    COUNT(DISTINCT pp.program_id) AS programs_participated,\n    COUNT(DISTINCT ed.id) AS deals_as_provider,\n    COUNT(DISTINCT ed.id) FILTER (WHERE ed.status = 'completed') AS deals_completed\nFROM public.organizations o\nLEFT JOIN public.program_participants pp ON pp.organization_id = o.id\nLEFT JOIN public.exchange_deals ed ON ed.provider_org_id = o.id\nGROUP BY o.id, o.name, o.country","COMMENT ON MATERIALIZED VIEW public.vw_supplier_quality IS\n    'Supplier quality view — aggregate metrics per organization.'","-- ############################################################################\n-- PART 7: RLS\n-- ############################################################################\n\nALTER TABLE public.analytics_network_snapshots ENABLE ROW LEVEL SECURITY","ALTER TABLE public.analytics_program_metrics ENABLE ROW LEVEL SECURITY","ALTER TABLE public.analytics_supplier_metrics ENABLE ROW LEVEL SECURITY","ALTER TABLE public.analytics_search_queries ENABLE ROW LEVEL SECURITY","-- Network snapshots: visible to all authenticated (no sensitive data)\nCREATE POLICY analytics_snapshots_select ON public.analytics_network_snapshots\n    FOR SELECT USING (auth.role() = 'authenticated')","-- Program metrics: program participants\nCREATE POLICY analytics_program_metrics_select ON public.analytics_program_metrics\n    FOR SELECT USING (public.can_access_program(program_id) OR public.is_org_admin())","-- Supplier metrics: visible to all authenticated (quality data)\nCREATE POLICY analytics_supplier_metrics_select ON public.analytics_supplier_metrics\n    FOR SELECT USING (auth.role() = 'authenticated')","-- Search queries: insertable by any authenticated user\nCREATE POLICY analytics_search_queries_insert ON public.analytics_search_queries\n    FOR INSERT WITH CHECK (auth.role() = 'authenticated')","CREATE POLICY analytics_search_queries_select ON public.analytics_search_queries\n    FOR SELECT USING (auth.role() = 'authenticated')","-- Materialized views RLS\nALTER MATERIALIZED VIEW public.vw_network_overview OWNER TO postgres","ALTER MATERIALIZED VIEW public.vw_program_performance OWNER TO postgres","ALTER MATERIALIZED VIEW public.vw_supplier_quality OWNER TO postgres","-- Grant select on views\nGRANT SELECT ON public.vw_network_overview TO anon, authenticated, service_role","GRANT SELECT ON public.vw_program_performance TO anon, authenticated, service_role","GRANT SELECT ON public.vw_supplier_quality TO anon, authenticated, service_role","-- ############################################################################\n-- PART 8: POSTGREST PERMISSIONS\n-- ############################################################################\n\nGRANT ALL ON public.analytics_network_snapshots TO anon, authenticated, service_role","GRANT ALL ON public.analytics_program_metrics TO anon, authenticated, service_role","GRANT ALL ON public.analytics_supplier_metrics TO anon, authenticated, service_role","GRANT ALL ON public.analytics_search_queries TO anon, authenticated, service_role","-- ============================================================================\n-- END OF MIGRATION 020 — Sprint 10: Analytics Engine\n-- ============================================================================"}	analytics_engine
021	{"-- ============================================================================\n-- KADARN PLATFORM — Sprint 11: AI Layer\n-- ============================================================================\n-- Dependencies: All prior migrations (008-020)\n--\n-- This migration creates the AI Layer foundation:\n--   1. ai_models — model registry\n--   2. ai_inferences — inference tracking\n--   3. ai_embeddings — vector embeddings for semantic search (pgvector)\n--   4. ai_training_data — training data collection\n--   5. ai_suggestions — AI-generated suggestions across engines\n--   6. RLS policies\n-- (Blueprint §17 — AI Layer)\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: EXTENSION (pgvector if available)\n-- ############################################################################\n\n-- pgvector enables semantic/vector search for the AI Layer.\n-- If not available, the platform falls back to full-text search.\n-- CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA extensions;\n\n-- ############################################################################\n-- PART 2: ENUMS\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE ai_capability AS ENUM (\n        'natural_language_search', 'capability_matching', 'timeline_prediction',\n        'anomaly_detection', 'document_generation', 'smart_negotiation'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE ai_model_status AS ENUM (\n        'dev', 'staging', 'production', 'deprecated', 'archived'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE ai_suggestion_type AS ENUM (\n        'org_recommendation', 'timeline_estimate', 'risk_assessment',\n        'search_expansion', 'document_template', 'negotiation_term',\n        'anomaly_alert', 'capability_gap'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 3: TABLE — ai_models\n-- ############################################################################\n--\n-- Registry of AI models used across the platform.\n-- (Blueprint §17 — AI Layer)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.ai_models (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n\n    model_name          TEXT NOT NULL,\n    model_version       TEXT NOT NULL,\n    capability          ai_capability NOT NULL,\n    description         TEXT,\n\n    -- Model metadata\n    framework           TEXT,  -- pytorch, tensorflow, sklearn, etc.\n    model_url           TEXT,  -- URL to model artifact\n    metrics             JSONB DEFAULT '{}',  -- accuracy, f1, etc.\n\n    -- Lifecycle\n    status              ai_model_status NOT NULL DEFAULT 'dev',\n    is_active           BOOLEAN NOT NULL DEFAULT false,\n    deployed_at         TIMESTAMPTZ,\n    deprecated_at       TIMESTAMPTZ,\n\n    created_by          UUID,\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    UNIQUE (model_name, model_version)\n)","CREATE INDEX IF NOT EXISTS idx_ai_models_capability ON public.ai_models(capability)","CREATE INDEX IF NOT EXISTS idx_ai_models_active ON public.ai_models(is_active)","COMMENT ON TABLE public.ai_models IS\n    'Registry of AI models across the platform. Tracks deployment lifecycle.'","-- ############################################################################\n-- PART 4: TABLE — ai_inferences\n-- ############################################################################\n--\n-- Tracks AI inference requests and results.\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.ai_inferences (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    model_id            UUID REFERENCES public.ai_models(id) ON DELETE SET NULL,\n\n    capability          ai_capability NOT NULL,\n    input_data          JSONB NOT NULL,\n    output_data         JSONB,\n    confidence          NUMERIC(5,4),  -- 0-1 confidence score\n    latency_ms          INTEGER,\n\n    -- Context\n    user_id             UUID,\n    organization_id     UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\n    program_id          UUID REFERENCES public.programs(id) ON DELETE SET NULL,\n\n    -- Audit\n    metadata            JSONB DEFAULT '{}',\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_ai_inferences_capability ON public.ai_inferences(capability)","CREATE INDEX IF NOT EXISTS idx_ai_inferences_model ON public.ai_inferences(model_id)","CREATE INDEX IF NOT EXISTS idx_ai_inferences_created ON public.ai_inferences(created_at DESC)","COMMENT ON TABLE public.ai_inferences IS\n    'AI inference request/response tracking. Used for monitoring and training data collection.'","-- ############################################################################\n-- PART 5: TABLE — ai_suggestions\n-- ############################################################################\n--\n-- AI-generated suggestions surfaced to users across engines.\n-- (Blueprint §17.2 — AI Capabilities)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.ai_suggestions (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    suggestion_type     ai_suggestion_type NOT NULL,\n\n    -- Where the suggestion applies\n    engine              TEXT NOT NULL,  -- discovery, feasibility, exchange, chain, regulatory\n    organization_id     UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\n    program_id          UUID REFERENCES public.programs(id) ON DELETE SET NULL,\n\n    -- Suggestion content\n    title               TEXT NOT NULL,\n    description         TEXT,\n    confidence          NUMERIC(5,4),\n    payload             JSONB DEFAULT '{}',  -- structured suggestion data\n\n    -- Status\n    is_applied          BOOLEAN NOT NULL DEFAULT false,\n    is_dismissed        BOOLEAN NOT NULL DEFAULT false,\n    applied_at          TIMESTAMPTZ,\n\n    -- Metadata\n    metadata            JSONB DEFAULT '{}',\n    created_by          UUID,  -- NULL = system-generated\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_ai_suggestions_engine ON public.ai_suggestions(engine, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_ai_suggestions_type ON public.ai_suggestions(suggestion_type)","CREATE INDEX IF NOT EXISTS idx_ai_suggestions_program ON public.ai_suggestions(program_id)","COMMENT ON TABLE public.ai_suggestions IS\n    'AI-generated suggestions across all engines. Users can apply or dismiss.'","-- ############################################################################\n-- PART 6: TABLE — ai_training_data\n-- ############################################################################\n--\n-- Collected training data for future model improvements.\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS public.ai_training_data (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    capability          ai_capability NOT NULL,\n\n    -- Input/output pairs\n    input_text          TEXT,\n    input_data          JSONB DEFAULT '{}',\n    output_text         TEXT,\n    output_data         JSONB DEFAULT '{}',\n\n    -- Label (for supervised learning)\n    human_label         TEXT,\n    human_labeled_by    UUID,\n    human_labeled_at    TIMESTAMPTZ,\n\n    -- Source\n    source              TEXT,  -- inference_log, user_feedback, manual_curation\n    is_used_for_training BOOLEAN NOT NULL DEFAULT false,\n\n    metadata            JSONB DEFAULT '{}',\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_ai_training_capability ON public.ai_training_data(capability)","CREATE INDEX IF NOT EXISTS idx_ai_training_used ON public.ai_training_data(is_used_for_training)","COMMENT ON TABLE public.ai_training_data IS\n    'Training data collected from inferences and user feedback.'","-- ############################################################################\n-- PART 7: AI HELPER FUNCTIONS\n-- ############################################################################\n\n-- Log an inference\nCREATE OR REPLACE FUNCTION public.log_ai_inference(\n    p_capability ai_capability,\n    p_input JSONB,\n    p_output JSONB DEFAULT NULL,\n    p_confidence NUMERIC DEFAULT NULL,\n    p_user_id UUID DEFAULT NULL,\n    p_organization_id UUID DEFAULT NULL,\n    p_program_id UUID DEFAULT NULL\n)\nRETURNS UUID\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_id UUID;\nBEGIN\n    INSERT INTO public.ai_inferences (capability, input_data, output_data, confidence, user_id, organization_id, program_id)\n    VALUES (p_capability, p_input, p_output, p_confidence, p_user_id, p_organization_id, p_program_id)\n    RETURNING id INTO v_id;\n    RETURN v_id;\nEND;\n$$","-- Generate a capability matching suggestion\nCREATE OR REPLACE FUNCTION public.suggest_organizations(\n    p_required_capabilities TEXT[],\n    p_disease_icd10 TEXT DEFAULT NULL,\n    p_target_country TEXT DEFAULT NULL,\n    p_limit INTEGER DEFAULT 5\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSTABLE\nAS $$\nDECLARE\n    v_result JSONB;\nBEGIN\n    SELECT jsonb_agg(jsonb_build_object(\n        'organization_id', o.id,\n        'organization_name', o.name,\n        'country', o.country,\n        'matched_capabilities', (\n            SELECT jsonb_agg(oct.key)\n            FROM public.organization_capabilities oc\n            JOIN public.organization_capability_types oct ON oct.id = oc.capability_type_id\n            WHERE oc.organization_id = o.id AND oct.key = ANY(p_required_capabilities)\n        ),\n        'score', (\n            SELECT COUNT(*)::NUMERIC / array_length(p_required_capabilities, 1)\n            FROM public.organization_capabilities oc\n            JOIN public.organization_capability_types oct ON oct.id = oc.capability_type_id\n            WHERE oc.organization_id = o.id AND oct.key = ANY(p_required_capabilities)\n        )\n    ) ORDER BY score DESC)\n    INTO v_result\n    FROM public.organizations o\n    WHERE o.is_active = true\n      AND (p_target_country IS NULL OR o.country = p_target_country)\n      AND EXISTS (\n          SELECT 1 FROM public.organization_capabilities oc\n          JOIN public.organization_capability_types oct ON oct.id = oc.capability_type_id\n          WHERE oc.organization_id = o.id AND oct.key = ANY(p_required_capabilities)\n      )\n    LIMIT p_limit;\n\n    RETURN COALESCE(v_result, '[]'::jsonb);\nEND;\n$$","COMMENT ON FUNCTION public.suggest_organizations IS\n    'AI-powered organization suggestion based on required capabilities. Used by Feasibility Engine.'","-- ############################################################################\n-- PART 8: RLS\n-- ############################################################################\n\nALTER TABLE public.ai_models ENABLE ROW LEVEL SECURITY","ALTER TABLE public.ai_inferences ENABLE ROW LEVEL SECURITY","ALTER TABLE public.ai_suggestions ENABLE ROW LEVEL SECURITY","ALTER TABLE public.ai_training_data ENABLE ROW LEVEL SECURITY","-- Models: all authenticated can read\nCREATE POLICY ai_models_select ON public.ai_models\n    FOR SELECT USING (auth.role() = 'authenticated')","CREATE POLICY ai_models_insert ON public.ai_models\n    FOR INSERT WITH CHECK (auth.role() = 'authenticated')","-- Inferences: users see their own, org_admins see org's\nCREATE POLICY ai_inferences_select_self ON public.ai_inferences\n    FOR SELECT USING (user_id = auth.uid())","CREATE POLICY ai_inferences_select_admin ON public.ai_inferences\n    FOR SELECT USING (public.is_org_admin(organization_id))","CREATE POLICY ai_inferences_insert ON public.ai_inferences\n    FOR INSERT WITH CHECK (auth.role() = 'authenticated')","-- Suggestions: visible to relevant participants\nCREATE POLICY ai_suggestions_select ON public.ai_suggestions\n    FOR SELECT\n    USING (\n        (organization_id IS NULL OR public.is_org_member(organization_id))\n        OR (program_id IS NULL OR public.can_access_program(program_id))\n        OR public.is_org_admin()\n    )","-- Training data: admin only (sensitive)\nCREATE POLICY ai_training_data_select ON public.ai_training_data\n    FOR SELECT USING (public.is_org_admin())","-- ############################################################################\n-- PART 9: POSTGREST PERMISSIONS\n-- ############################################################################\n\nGRANT ALL ON public.ai_models TO anon, authenticated, service_role","GRANT ALL ON public.ai_inferences TO anon, authenticated, service_role","GRANT ALL ON public.ai_suggestions TO anon, authenticated, service_role","GRANT ALL ON public.ai_training_data TO anon, authenticated, service_role","-- ============================================================================\n-- END OF MIGRATION 021 — Sprint 11: AI Layer\n-- ============================================================================"}	ai_layer
022	{"-- ============================================================================\n-- KADARN PLATFORM — Policy Engine (P0 Engine)\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Domain: Declarative policy evaluation for governance, financial, regulatory,\n--         and operational decisions\n-- Design: ADR-010 — Policy Engine: Declarative Policy Evaluation\n-- Reference: KRM-RAO §2.4 (Policy), §5.2 (Policy Engine)\n-- Dependencies: 008_organizations_capabilities.sql (organizations table)\n--\n-- This migration creates the data layer for the Policy Engine. The engine\n-- itself is a pure function in packages/policy-engine/ — stateless, no\n-- database calls.\n-- ============================================================================\n\n-- ############################################################################\n-- PART 0: EXTENSION SAFETY\n-- ############################################################################\n\n-- pgcrypto for gen_random_uuid()\n-- Already loaded by 008, but safe to repeat\n\n-- ############################################################################\n-- PART 1: ENUMS\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE policy_domain AS ENUM (\n        'governance',\n        'financial',\n        'regulatory',\n        'operational'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE policy_status AS ENUM (\n        'draft',\n        'active',\n        'inactive',\n        'deprecated'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE policy_outcome AS ENUM (\n        'allow',\n        'deny',\n        'conditional'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: POLICIES TABLE\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS policies (\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    name            VARCHAR(255) NOT NULL,\n    description     TEXT,\n    domain          policy_domain NOT NULL,\n    status          policy_status NOT NULL DEFAULT 'draft',\n    version         INTEGER NOT NULL DEFAULT 1,\n    priority        INTEGER NOT NULL DEFAULT 1000,\n    rules           JSONB NOT NULL DEFAULT '[]'::jsonb,\n    metadata        JSONB DEFAULT '{}'::jsonb,\n    organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE,\n    created_by      UUID REFERENCES auth.users(id),\n    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    -- A policy must have at least one rule\n    CONSTRAINT policies_rules_not_empty\n        CHECK (jsonb_array_length(rules) > 0),\n\n    -- Each rule must have condition, effect, and optional reason\n    CONSTRAINT policies_rules_valid\n        CHECK (rules @> '[{\\"effect\\": \\"allow\\"}]'::jsonb OR\n               rules @> '[{\\"effect\\": \\"deny\\"}]'::jsonb),\n\n    -- Unique name per organization (global policies have NULL org)\n    CONSTRAINT policies_name_unique\n        UNIQUE NULLS NOT DISTINCT (organization_id, name)\n)","COMMENT ON TABLE policies IS\n    'Declarative policy definitions. Rules are stored as JSONB condition trees.'","COMMENT ON COLUMN policies.rules IS\n    'Array of {condition: PolicyCondition, effect: \\"allow\\"|\\"deny\\", reason?: string}'","COMMENT ON COLUMN policies.priority IS\n    'Lower values = higher priority. Default 1000. Evaluated in ascending order.'","COMMENT ON COLUMN policies.organization_id IS\n    'NULL = global policy (applies to all orgs). Non-NULL = org-scoped policy.'","-- ############################################################################\n-- PART 3: POLICY EVALUATIONS (APPEND-ONLY AUDIT LOG)\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS policy_evaluations (\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    policy_id       UUID NOT NULL REFERENCES policies(id) ON DELETE CASCADE,\n    context         JSONB NOT NULL,\n    outcome         policy_outcome NOT NULL,\n    matched_rules   TEXT[] DEFAULT '{}',\n    trace           JSONB NOT NULL DEFAULT '[]'::jsonb,\n    evaluated_by    UUID REFERENCES auth.users(id),\n    evaluated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),\n    organization_id UUID REFERENCES organizations(id) ON DELETE SET NULL\n)","COMMENT ON TABLE policy_evaluations IS\n    'Append-only audit log of policy evaluation results. No UPDATE or DELETE.'","CREATE INDEX IF NOT EXISTS idx_policy_evaluations_policy_id\n    ON policy_evaluations(policy_id)","CREATE INDEX IF NOT EXISTS idx_policy_evaluations_outcome\n    ON policy_evaluations(outcome)","CREATE INDEX IF NOT EXISTS idx_policy_evaluations_evaluated_at\n    ON policy_evaluations(evaluated_at DESC)","-- ############################################################################\n-- PART 4: INDEXES\n-- ############################################################################\n\nCREATE INDEX IF NOT EXISTS idx_policies_domain\n    ON policies(domain)","CREATE INDEX IF NOT EXISTS idx_policies_status\n    ON policies(status)","CREATE INDEX IF NOT EXISTS idx_policies_organization_id\n    ON policies(organization_id)","CREATE INDEX IF NOT EXISTS idx_policies_priority\n    ON policies(priority ASC)","-- GIN index for JSONB queries on rules\nCREATE INDEX IF NOT EXISTS idx_policies_rules_gin\n    ON policies USING GIN (rules jsonb_path_ops)","-- ############################################################################\n-- PART 5: UPDATED_AT TRIGGER\n-- ############################################################################\n\nCREATE OR REPLACE FUNCTION update_policies_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql","DROP TRIGGER IF EXISTS trg_policies_updated_at ON policies","CREATE TRIGGER trg_policies_updated_at\n    BEFORE UPDATE ON policies\n    FOR EACH ROW\n    EXECUTE FUNCTION update_policies_updated_at()","-- ############################################################################\n-- PART 6: ROW-LEVEL SECURITY\n-- ############################################################################\n\nALTER TABLE policies ENABLE ROW LEVEL SECURITY","ALTER TABLE policy_evaluations ENABLE ROW LEVEL SECURITY","-- Policies: SELECT — users see global policies + their org's policies\nCREATE POLICY policies_select ON policies\n    FOR SELECT\n    USING (\n        organization_id IS NULL\n        OR organization_id IN (\n            SELECT organization_id FROM user_organizations\n            WHERE user_id = auth.uid()\n        )\n    )","-- Policies: INSERT — org_admins and platform_admins can create\nCREATE POLICY policies_insert ON policies\n    FOR INSERT\n    WITH CHECK (\n        auth.role() = 'authenticated'\n        AND (\n            organization_id IS NULL\n            OR organization_id IN (\n                SELECT organization_id FROM user_organizations\n                WHERE user_id = auth.uid()\n                AND role IN ('org_admin', 'platform_admin')\n            )\n        )\n    )","-- Policies: UPDATE — same as INSERT\nCREATE POLICY policies_update ON policies\n    FOR UPDATE\n    USING (\n        auth.role() = 'authenticated'\n        AND (\n            organization_id IS NULL\n            OR organization_id IN (\n                SELECT organization_id FROM user_organizations\n                WHERE user_id = auth.uid()\n                AND role IN ('org_admin', 'platform_admin')\n            )\n        )\n    )","-- Policies: DELETE — same as INSERT\nCREATE POLICY policies_delete ON policies\n    FOR DELETE\n    USING (\n        auth.role() = 'authenticated'\n        AND (\n            organization_id IS NULL\n            OR organization_id IN (\n                SELECT organization_id FROM user_organizations\n                WHERE user_id = auth.uid()\n                AND role IN ('org_admin', 'platform_admin')\n            )\n        )\n    )","-- Policy evaluations: SELECT — users see evaluations for policies they can access\nCREATE POLICY policy_evaluations_select ON policy_evaluations\n    FOR SELECT\n    USING (\n        organization_id IS NULL\n        OR organization_id IN (\n            SELECT organization_id FROM user_organizations\n            WHERE user_id = auth.uid()\n        )\n    )","-- Policy evaluations: INSERT — via service role or SECURITY DEFINER\n-- Regular users do not insert directly — the engine calls via API\nCREATE POLICY policy_evaluations_insert ON policy_evaluations\n    FOR INSERT\n    WITH CHECK (auth.role() = 'service_role')","-- ############################################################################\n-- PART 7: SEED DATA — EXAMPLE POLICIES\n-- ############################################################################\n\n-- Inserted only if no policies exist yet (idempotent for dev environments)\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM policies LIMIT 1) THEN\n        INSERT INTO policies (name, description, domain, status, version, priority, rules, metadata)\n        VALUES (\n            'Oncology Use Only',\n            'Specimens collected under oncology IRBs may only be used for oncology research',\n            'governance',\n            'active',\n            1,\n            100,\n            '[\n                {\n                    \\"id\\": \\"rule-001\\",\n                    \\"condition\\": {\n                        \\"any\\": [\n                            {\n                                \\"neq\\": [\n                                    {\\"var\\": \\"request.consent.scope\\"},\n                                    \\"oncology\\"\n                                ]\n                            },\n                            {\n                                \\"not\\": {\n                                    \\"in\\": [\n                                        {\\"var\\": \\"request.purpose\\"},\n                                        [\\"research\\", \\"qa\\", \\"assay_development\\"]\n                                    ]\n                                }\n                            }\n                        ]\n                    },\n                    \\"effect\\": \\"deny\\",\n                    \\"reason\\": \\"Specimens under oncology IRB #2024-05 are restricted to oncology research purposes\\"\n                }\n            ]'::jsonb,\n            '{\\"irb\\": \\"IRB #2024-05\\", \\"category\\": \\"consent_scope\\"}'\n        );\n\n        INSERT INTO policies (name, description, domain, status, version, priority, rules, metadata)\n        VALUES (\n            'High-Value Shipment Authorization',\n            'Shipments exceeding $10,000 require dual authorization',\n            'financial',\n            'active',\n            1,\n            200,\n            '[\n                {\n                    \\"id\\": \\"rule-002\\",\n                    \\"condition\\": {\n                        \\"gt\\": [\n                            {\\"var\\": \\"fulfillment.estimatedValue\\"},\n                            10000\n                        ]\n                    },\n                    \\"effect\\": \\"deny\\",\n                    \\"reason\\": \\"Shipments over $10,000 require dual authorization\\"\n                }\n            ]'::jsonb,\n            '{\\"category\\": \\"financial_control\\", \\"threshold\\": 10000}'\n        );\n\n        INSERT INTO policies (name, description, domain, status, version, priority, rules, metadata)\n        VALUES (\n            'Minimum Trust Score',\n            'Only route specimens to organizations with trust score >= 0.7',\n            'operational',\n            'active',\n            1,\n            150,\n            '[\n                {\n                    \\"id\\": \\"rule-003\\",\n                    \\"condition\\": {\n                        \\"lt\\": [\n                            {\\"var\\": \\"destination.trustScore\\"},\n                            0.7\n                        ]\n                    },\n                    \\"effect\\": \\"deny\\",\n                    \\"reason\\": \\"Destination organization trust score is below minimum threshold of 0.7\\"\n                }\n            ]'::jsonb,\n            '{\\"category\\": \\"trust_control\\", \\"threshold\\": 0.7}'\n        );\n    END IF;\nEND;\n$$"}	policy_engine
023	{"-- ============================================================================\n-- KADARN PLATFORM — Trust Engine (P0 Engine)\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Domain: Evidence-based trust computation for organizations in the Kadarn\n--         network. Scores decay over time without new evidence.\n-- Design: ADR-011 — Trust Engine: Evidence-Based Trust Computation\n-- Reference: KRM-RAO §2.7 (Trust), §4.4 (Trust Graph), §5.4 (Trust Engine)\n-- Dependencies: 008_organizations_capabilities.sql (organizations table)\n--\n-- This migration creates the data layer for the Trust Engine. The scoring\n-- functions live in packages/trust-engine/.\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: ENUMS\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE trust_dimension AS ENUM (\n        'operational',\n        'regulatory',\n        'financial',\n        'technical'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE trust_event_severity AS ENUM (\n        'low',\n        'normal',\n        'high',\n        'critical'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE challenge_status AS ENUM (\n        'filed',\n        'under_review',\n        'accepted',\n        'rejected',\n        'escalated'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: ORGANIZATION TRUST — CURRENT SCORES\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS organization_trust (\n    organization_id         UUID PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE,\n\n    -- Per-dimension scores (0.0–1.0)\n    operational_score       NUMERIC(5,3) NOT NULL DEFAULT 0.500,\n    regulatory_score        NUMERIC(5,3) NOT NULL DEFAULT 0.500,\n    financial_score         NUMERIC(5,3) NOT NULL DEFAULT 0.500,\n    technical_score         NUMERIC(5,3) NOT NULL DEFAULT 0.500,\n\n    -- Composite overall score (weighted average)\n    overall_score           NUMERIC(5,3) NOT NULL DEFAULT 0.500,\n\n    -- Tracking metadata\n    last_event_at           TIMESTAMPTZ,\n    last_decay_at           TIMESTAMPTZ NOT NULL DEFAULT now(),\n    total_fulfillments      INTEGER NOT NULL DEFAULT 0,\n    successful_fulfillments INTEGER NOT NULL DEFAULT 0,\n    incident_count          INTEGER NOT NULL DEFAULT 0,\n\n    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    CONSTRAINT trust_score_range CHECK (\n        operational_score BETWEEN 0.000 AND 1.000\n        AND regulatory_score BETWEEN 0.000 AND 1.000\n        AND financial_score BETWEEN 0.000 AND 1.000\n        AND technical_score BETWEEN 0.000 AND 1.000\n        AND overall_score BETWEEN 0.000 AND 1.000\n    )\n)","COMMENT ON TABLE organization_trust IS\n    'Current trust scores per organization. Scores decay over time without new evidence.'","COMMENT ON COLUMN organization_trust.overall_score IS\n    'Weighted composite of the four dimension scores. Default weights: equal (0.25 each).'","-- Trigger function for updated_at\nCREATE OR REPLACE FUNCTION update_organization_trust_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql","DROP TRIGGER IF EXISTS trg_organization_trust_updated_at ON organization_trust","CREATE TRIGGER trg_organization_trust_updated_at\n    BEFORE UPDATE ON organization_trust\n    FOR EACH ROW\n    EXECUTE FUNCTION update_organization_trust_updated_at()","-- ############################################################################\n-- PART 3: TRUST EVENTS — APPEND-ONLY AUDIT LOG\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS trust_events (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    organization_id     UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n    dimension           trust_dimension NOT NULL,\n    impact              NUMERIC(6,4) NOT NULL,\n    impact_after_decay  NUMERIC(6,4),  -- calculated after decay is applied\n    evidence_ref        TEXT NOT NULL,  -- reference to evidence (fulfillment ID, breach ID, cert ID)\n    source              VARCHAR(100) NOT NULL,  -- e.g. 'fulfillment.completed', 'temperature.breach'\n    severity            trust_event_severity NOT NULL DEFAULT 'normal',\n    description         TEXT,\n    score_before        NUMERIC(5,3),  -- dimension score before this event\n    score_after         NUMERIC(5,3),  -- dimension score after this event\n    created_by          UUID REFERENCES auth.users(id),\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","COMMENT ON TABLE trust_events IS\n    'Append-only log of trust-affecting events. Each event records its impact on the relevant dimension.'","COMMENT ON COLUMN trust_events.evidence_ref IS\n    'Reference to the evidence supporting this event — e.g. fulfillment ID, accreditation cert ID, breach report ID.'","COMMENT ON COLUMN trust_events.source IS\n    'Canonical event source name, e.g. fulfillment.completed, temperature.breach, accreditation.verified'","CREATE INDEX IF NOT EXISTS idx_trust_events_organization\n    ON trust_events(organization_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_trust_events_dimension\n    ON trust_events(dimension)","CREATE INDEX IF NOT EXISTS idx_trust_events_source\n    ON trust_events(source)","CREATE INDEX IF NOT EXISTS idx_trust_events_created_at\n    ON trust_events(created_at DESC)","-- ############################################################################\n-- PART 4: TRUST CHALLENGES\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS trust_challenges (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    organization_id     UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n    dimension           trust_dimension NOT NULL,\n    challenged_score    NUMERIC(5,3) NOT NULL,  -- the score being challenged\n    proposed_score      NUMERIC(5,3),           -- what the org believes it should be\n    evidence_ref        TEXT NOT NULL,           -- counter-evidence\n    reason              TEXT NOT NULL,\n    status              challenge_status NOT NULL DEFAULT 'filed',\n    reviewed_by         UUID REFERENCES auth.users(id),\n    reviewed_at         TIMESTAMPTZ,\n    resolution_notes    TEXT,\n    created_by          UUID REFERENCES auth.users(id),\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()\n)","COMMENT ON TABLE trust_challenges IS\n    'Trust score challenges. Organizations may challenge their scores with counter-evidence.'","CREATE INDEX IF NOT EXISTS idx_trust_challenges_organization\n    ON trust_challenges(organization_id)","CREATE INDEX IF NOT EXISTS idx_trust_challenges_status\n    ON trust_challenges(status)","CREATE OR REPLACE FUNCTION update_trust_challenges_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql","DROP TRIGGER IF EXISTS trg_trust_challenges_updated_at ON trust_challenges","CREATE TRIGGER trg_trust_challenges_updated_at\n    BEFORE UPDATE ON trust_challenges\n    FOR EACH ROW\n    EXECUTE FUNCTION update_trust_challenges_updated_at()","-- ############################################################################\n-- PART 5: ROW-LEVEL SECURITY\n-- ############################################################################\n\nALTER TABLE organization_trust ENABLE ROW LEVEL SECURITY","ALTER TABLE trust_events ENABLE ROW LEVEL SECURITY","ALTER TABLE trust_challenges ENABLE ROW LEVEL SECURITY","-- Organization trust: visible to members of the org + program partners\nCREATE POLICY organization_trust_select ON organization_trust\n    FOR SELECT\n    USING (\n        organization_id IN (\n            SELECT organization_id FROM user_organizations\n            WHERE user_id = auth.uid()\n        )\n        OR auth.role() = 'service_role'\n    )","-- Trust events: visible to org members + service role\nCREATE POLICY trust_events_select ON trust_events\n    FOR SELECT\n    USING (\n        organization_id IN (\n            SELECT organization_id FROM user_organizations\n            WHERE user_id = auth.uid()\n        )\n        OR auth.role() = 'service_role'\n    )","-- Trust events: insert via service role (engines call the API)\nCREATE POLICY trust_events_insert ON trust_events\n    FOR INSERT\n    WITH CHECK (auth.role() = 'service_role')","-- Trust challenges: org members can file challenges for their org\nCREATE POLICY trust_challenges_select ON trust_challenges\n    FOR SELECT\n    USING (\n        organization_id IN (\n            SELECT organization_id FROM user_organizations\n            WHERE user_id = auth.uid()\n        )\n        OR auth.role() = 'service_role'\n    )","CREATE POLICY trust_challenges_insert ON trust_challenges\n    FOR INSERT\n    WITH CHECK (\n        organization_id IN (\n            SELECT organization_id FROM user_organizations\n            WHERE user_id = auth.uid()\n        )\n    )","CREATE POLICY trust_challenges_update ON trust_challenges\n    FOR UPDATE\n    USING (\n        auth.role() = 'service_role'\n        OR auth.uid() IN (\n            SELECT user_id FROM user_organizations\n            WHERE organization_id = trust_challenges.organization_id\n            AND role IN ('org_admin', 'platform_admin')\n        )\n    )","-- ############################################################################\n-- PART 6: DEFAULT SCORES — INITIALIZE ON ORGANIZATION CREATION\n-- ############################################################################\n\n-- When a new organization is created, auto-initialize their trust record\n-- with neutral scores (0.5).\nCREATE OR REPLACE FUNCTION initialize_organization_trust()\nRETURNS TRIGGER AS $$\nBEGIN\n    INSERT INTO organization_trust (organization_id)\n    VALUES (NEW.id)\n    ON CONFLICT (organization_id) DO NOTHING;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER","DROP TRIGGER IF EXISTS trg_initialize_organization_trust ON organizations","CREATE TRIGGER trg_initialize_organization_trust\n    AFTER INSERT ON organizations\n    FOR EACH ROW\n    EXECUTE FUNCTION initialize_organization_trust()","-- Initialize trust for any existing organizations that don't have it\nINSERT INTO organization_trust (organization_id)\nSELECT id FROM organizations o\nWHERE NOT EXISTS (SELECT 1 FROM organization_trust t WHERE t.organization_id = o.id)\nON CONFLICT (organization_id) DO NOTHING"}	trust_engine
024	{"-- ============================================================================\n-- KADARN PLATFORM — Operational Twins (Event-Sourced Digital Representations)\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Domain: Event-sourced Operational Twins for biospecimen, transaction,\n--         shipment, and collection lifecycle tracking\n-- Design: ADR-012 — Operational Twins: Event-Sourced Digital Representations\n-- Reference: KRM-RAO §2.2 (Operational Twin), §3.4 (Twins)\n--            KRM-BNO §4 (Operational Twin Specialization)\n-- Dependencies: 008_organizations_capabilities.sql (organizations table)\n--               013_policy_engine.sql (policies — for consent/policy references)\n--\n-- This migration creates the shared event store and the Specimen Twin\n-- as the first Operational Twin implementation.\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: ENUMS\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE twin_type AS ENUM (\n        'specimen',\n        'transaction',\n        'shipment',\n        'organization',\n        'collection'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE twin_event_type AS ENUM (\n        -- Specimen events\n        'SpecimenCollected',\n        'AliquotCreated',\n        'QCPassed',\n        'QCFailed',\n        'FreezeThawRecorded',\n        'VolumeAdjusted',\n        'ShipmentInitiated',\n        'Consumed',\n        'Destroyed',\n        'LocationChanged',\n        'ConsentUpdated',\n        -- Transaction events\n        'TransactionInitiated',\n        'GovernanceReviewStarted',\n        'PolicyApproved',\n        'PolicyDenied',\n        'MTASigned',\n        'FulfillmentStarted',\n        'FulfillmentCompleted',\n        'SettlementCompleted',\n        -- Shipment events\n        'ShipmentScheduled',\n        'ShipmentPickedUp',\n        'TemperatureReading',\n        'TemperatureBreach',\n        'ShipmentDelivered',\n        'ShipmentAccepted',\n        'ShipmentDisputed',\n        -- Organization events\n        'OrganizationRegistered',\n        'AccreditationAdded',\n        'AccreditationExpired',\n        'TrustScoreUpdated',\n        -- Collection events\n        'CollectionRegistered',\n        'DonorEnrolled',\n        'DonorWithdrawn'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: SHARED EVENT STORE\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS twin_events (\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    twin_type       twin_type NOT NULL,\n    twin_id         UUID NOT NULL,\n    event_type      twin_event_type NOT NULL,\n    payload         JSONB NOT NULL DEFAULT '{}'::jsonb,\n    sequence        BIGINT NOT NULL,\n    occurred_at     TIMESTAMPTZ NOT NULL DEFAULT now(),\n    recorded_at     TIMESTAMPTZ NOT NULL DEFAULT now(),\n    actor_id        UUID REFERENCES auth.users(id),\n    evidence_ref    TEXT,\n\n    -- Sequence must be unique per twin\n    CONSTRAINT twin_events_unique_sequence\n        UNIQUE (twin_type, twin_id, sequence),\n\n    -- Sequence must be positive\n    CONSTRAINT twin_events_positive_sequence\n        CHECK (sequence > 0)\n)","COMMENT ON TABLE twin_events IS\n    'Immutable event store for all Operational Twins. Events are append-only.'","COMMENT ON COLUMN twin_events.sequence IS\n    'Monotonic, gapless sequence number per twin. Used for deterministic reconstruction.'","COMMENT ON COLUMN twin_events.payload IS\n    'Event-specific data. Schema depends on event_type.'","COMMENT ON COLUMN twin_events.evidence_ref IS\n    'Optional reference to supporting evidence (document hash, external event ID).'","-- Index for event replay: get all events for a twin in order\nCREATE INDEX IF NOT EXISTS idx_twin_events_replay\n    ON twin_events(twin_type, twin_id, sequence ASC)","-- Index for time-range queries (reconstruction at time T)\nCREATE INDEX IF NOT EXISTS idx_twin_events_time\n    ON twin_events(twin_type, twin_id, recorded_at DESC)","-- Index for event type queries\nCREATE INDEX IF NOT EXISTS idx_twin_events_event_type\n    ON twin_events(event_type)","-- ############################################################################\n-- PART 3: SPECIMEN TWINS — CURRENT STATE TABLE\n-- ############################################################################\n\nCREATE TYPE specimen_status AS ENUM (\n    'collected',\n    'stored',\n    'shipped',\n    'received',\n    'consumed',\n    'destroyed',\n    'quarantined'\n)","CREATE TABLE IF NOT EXISTS specimen_twins (\n    id                  UUID PRIMARY KEY,  -- same as the specimen/research asset ID\n    organization_id     UUID NOT NULL REFERENCES organizations(id),\n    parent_id           UUID,              -- NULL for primary specimens, set for aliquots\n\n    -- Current derived state\n    status              specimen_status NOT NULL DEFAULT 'collected',\n    specimen_type       VARCHAR(100),      -- whole_blood, plasma, ffpe, etc.\n    container_type      VARCHAR(100),      -- vial, slide, block, cryovial\n    preservation_type   VARCHAR(100),      -- ffpe, fresh_frozen, rna_later\n    storage_temperature  VARCHAR(50),      -- ambient, 4c, minus_80, ln2\n    current_location     JSONB DEFAULT '{}'::jsonb,  -- {org, facility, freezer, rack, box, position}\n\n    -- Tracking\n    remaining_quantity   NUMERIC(10,4),    -- mL, mg, units (NULL for non-quantifiable)\n    unit                 VARCHAR(20),      -- mL, mg, units, slides\n    freeze_thaw_count    INTEGER NOT NULL DEFAULT 0,\n    last_qc_result       VARCHAR(20),      -- passed, failed, pending\n    last_qc_at           TIMESTAMPTZ,\n    consent_status       VARCHAR(50),      -- active, withdrawn, expired\n    consent_id           UUID,\n\n    -- Event stream tracking\n    twin_sequence        BIGINT NOT NULL DEFAULT 0,  -- last applied event sequence\n    twin_updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    -- Metadata\n    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),\n    collected_at         TIMESTAMPTZ,\n    collected_by         UUID REFERENCES auth.users(id),\n    notes                TEXT,\n\n    CONSTRAINT specimen_twins_positive_sequence\n        CHECK (twin_sequence >= 0)\n)","COMMENT ON TABLE specimen_twins IS\n    'Current derived state of Specimen Twins. Updated atomically when events are recorded.'","COMMENT ON COLUMN specimen_twins.id IS\n    'Same as the specimen Research Asset ID. The twin IS the authoritative record.'","COMMENT ON COLUMN specimen_twins.twin_sequence IS\n    'The sequence number of the last event applied. Used for conflict detection.'","CREATE INDEX IF NOT EXISTS idx_specimen_twins_organization\n    ON specimen_twins(organization_id)","CREATE INDEX IF NOT EXISTS idx_specimen_twins_status\n    ON specimen_twins(status)","CREATE INDEX IF NOT EXISTS idx_specimen_twins_parent\n    ON specimen_twins(parent_id)","-- ############################################################################\n-- PART 4: ROW-LEVEL SECURITY\n-- ############################################################################\n\nALTER TABLE twin_events ENABLE ROW LEVEL SECURITY","ALTER TABLE specimen_twins ENABLE ROW LEVEL SECURITY","-- Twin events: visible to members of the owning organization\nCREATE POLICY twin_events_select ON twin_events\n    FOR SELECT\n    USING (auth.role() = 'service_role')","-- Twin events: insert via service role (engines call the API)\nCREATE POLICY twin_events_insert ON twin_events\n    FOR INSERT\n    WITH CHECK (auth.role() = 'service_role')","-- Specimen twins: visible to org members\nCREATE POLICY specimen_twins_select ON specimen_twins\n    FOR SELECT\n    USING (\n        organization_id IN (\n            SELECT organization_id FROM user_organizations\n            WHERE user_id = auth.uid()\n        )\n        OR auth.role() = 'service_role'\n    )","-- Specimen twins: insert/update via service role\nCREATE POLICY specimen_twins_insert ON specimen_twins\n    FOR INSERT\n    WITH CHECK (auth.role() = 'service_role')","CREATE POLICY specimen_twins_update ON specimen_twins\n    FOR UPDATE\n    USING (auth.role() = 'service_role')","-- ############################################################################\n-- PART 5: EVENT APPLICATION FUNCTION (SECURITY DEFINER)\n-- ############################################################################\n\n-- This function atomically records an event and updates the twin state.\n-- It is called by the application layer — not exposed as an API endpoint.\n\nCREATE OR REPLACE FUNCTION apply_twin_event(\n    p_twin_type         twin_type,\n    p_twin_id           UUID,\n    p_event_type        twin_event_type,\n    p_payload           JSONB,\n    p_actor_id          UUID,\n    p_occurred_at       TIMESTAMPTZ,\n    p_evidence_ref      TEXT DEFAULT NULL\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_next_sequence BIGINT;\n    v_result JSONB;\nBEGIN\n    -- Get next sequence number for this twin\n    SELECT COALESCE(MAX(sequence), 0) + 1\n    INTO v_next_sequence\n    FROM twin_events\n    WHERE twin_type = p_twin_type AND twin_id = p_twin_id;\n\n    -- Insert the event\n    INSERT INTO twin_events (\n        twin_type, twin_id, event_type, payload, sequence,\n        occurred_at, actor_id, evidence_ref\n    ) VALUES (\n        p_twin_type, p_twin_id, p_event_type, p_payload, v_next_sequence,\n        p_occurred_at, p_actor_id, p_evidence_ref\n    );\n\n    -- For specimen twins, update state based on event type\n    IF p_twin_type = 'specimen' THEN\n        -- Ensure the twin row exists\n        INSERT INTO specimen_twins (id, organization_id, twin_sequence)\n        VALUES (\n            p_twin_id,\n            (p_payload ->> 'organization_id')::UUID,\n            v_next_sequence\n        )\n        ON CONFLICT (id) DO UPDATE SET\n            twin_sequence = v_next_sequence,\n            twin_updated_at = now();\n\n        -- Apply event-specific state changes\n        CASE p_event_type\n            WHEN 'SpecimenCollected' THEN\n                UPDATE specimen_twins SET\n                    status = 'collected',\n                    specimen_type = p_payload ->> 'specimen_type',\n                    container_type = p_payload ->> 'container_type',\n                    preservation_type = p_payload ->> 'preservation_type',\n                    storage_temperature = p_payload ->> 'storage_temperature',\n                    collected_at = p_occurred_at,\n                    collected_by = p_actor_id,\n                    remaining_quantity = (p_payload ->> 'initial_quantity')::NUMERIC,\n                    unit = p_payload ->> 'unit',\n                    consent_status = p_payload ->> 'consent_status',\n                    consent_id = (p_payload ->> 'consent_id')::UUID,\n                    current_location = jsonb_build_object(\n                        'organization_id', p_payload ->> 'organization_id'\n                    )\n                WHERE id = p_twin_id;\n\n            WHEN 'QCPassed' THEN\n                UPDATE specimen_twins SET\n                    last_qc_result = 'passed',\n                    last_qc_at = p_occurred_at\n                WHERE id = p_twin_id;\n\n            WHEN 'QCFailed' THEN\n                UPDATE specimen_twins SET\n                    last_qc_result = 'failed',\n                    last_qc_at = p_occurred_at,\n                    status = 'quarantined'\n                WHERE id = p_twin_id;\n\n            WHEN 'FreezeThawRecorded' THEN\n                UPDATE specimen_twins SET\n                    freeze_thaw_count = freeze_thaw_count + 1\n                WHERE id = p_twin_id;\n\n            WHEN 'VolumeAdjusted' THEN\n                UPDATE specimen_twins SET\n                    remaining_quantity = remaining_quantity - (p_payload ->> 'volume_used')::NUMERIC\n                WHERE id = p_twin_id;\n\n            WHEN 'ShipmentInitiated' THEN\n                UPDATE specimen_twins SET\n                    status = 'shipped',\n                    current_location = jsonb_build_object(\n                        'shipment_id', p_payload ->> 'shipment_id',\n                        'status', 'in_transit'\n                    )\n                WHERE id = p_twin_id;\n\n            WHEN 'Consumed' THEN\n                UPDATE specimen_twins SET\n                    status = 'consumed'\n                WHERE id = p_twin_id;\n\n            WHEN 'Destroyed' THEN\n                UPDATE specimen_twins SET\n                    status = 'destroyed'\n                WHERE id = p_twin_id;\n\n            WHEN 'LocationChanged' THEN\n                UPDATE specimen_twins SET\n                    current_location = jsonb_build_object(\n                        'organization_id', p_payload ->> 'organization_id',\n                        'facility', p_payload ->> 'facility',\n                        'freezer', p_payload ->> 'freezer',\n                        'rack', p_payload ->> 'rack',\n                        'box', p_payload ->> 'box',\n                        'position', p_payload ->> 'position'\n                    )\n                WHERE id = p_twin_id;\n\n            WHEN 'ConsentUpdated' THEN\n                UPDATE specimen_twins SET\n                    consent_status = p_payload ->> 'consent_status',\n                    consent_id = (p_payload ->> 'consent_id')::UUID\n                WHERE id = p_twin_id;\n\n            ELSE\n                -- Unknown event type — still recorded, no state update\n        END CASE;\n    END IF;\n\n    -- Return the recorded event\n    SELECT jsonb_build_object(\n        'event_id', id,\n        'sequence', sequence,\n        'event_type', event_type\n    ) INTO v_result\n    FROM twin_events\n    WHERE twin_type = p_twin_type AND twin_id = p_twin_id AND sequence = v_next_sequence;\n\n    RETURN v_result;\nEND;\n$$","COMMENT ON FUNCTION apply_twin_event IS\n    'Atomically records a twin event and updates the twin state table. '\n    'Called by the application layer. SECURITY DEFINER — the function has '\n    'elevated privileges to write to both tables.'","-- ############################################################################\n-- PART 6: SEED DATA — DEMO SPECIMEN TWIN\n-- ############################################################################\n\n-- No seed data for specimens (requires an organization to exist).\n-- The twin is created when the first event is recorded."}	operational_twins
025	{"-- ============================================================================\n-- KADARN PLATFORM — Provenance Graph (P0 Engine)\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Domain: Cross-entity lineage tracking — specimen → processing → shipment\n--         → dataset, with supporting evidence links\n-- Design: ADR-014 — Provenance Graph: Cross-Entity Lineage\n-- Reference: KRM-RAO §2.6 (Provenance), §4.2 (Provenance Graph)\n-- Dependencies: 008_organizations_capabilities.sql\n--               015_operational_twins.sql (twin_events)\n--\n-- This migration creates the Provenance Graph storage layer.\n-- The query logic lives in packages/provenance-graph/.\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: ENUMS\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE provenance_node_type AS ENUM (\n        'specimen', 'aliquot', 'consent', 'protocol',\n        'processing_event', 'qc_result', 'shipment',\n        'temperature_log', 'receipt', 'dataset', 'document',\n        'organization', 'program', 'access_request', 'policy_evaluation'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE provenance_edge_type AS ENUM (\n        'derived_from',\n        'authorized_by',\n        'processed_by',\n        'verified_by',\n        'shipped_with',\n        'linked_to',\n        'generated_from',\n        'requested_by',\n        'approved_by',\n        'owned_by'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: PROVENANCE NODES\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS provenance_nodes (\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    node_type       provenance_node_type NOT NULL,\n    external_id     VARCHAR(255) NOT NULL,  -- ID in the source system/table\n    label           VARCHAR(500),           -- Human-readable name\n    properties      JSONB DEFAULT '{}'::jsonb,\n    organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE,\n    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n    recorded_at     TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    -- Each external ID within a node type must be unique\n    CONSTRAINT provenance_nodes_unique_external\n        UNIQUE (node_type, external_id)\n)","COMMENT ON TABLE provenance_nodes IS\n    'Entities tracked in the Provenance Graph. Each node represents a real-world entity or event.'","COMMENT ON COLUMN provenance_nodes.external_id IS\n    'The ID of this entity in its source table (e.g., specimen ID, shipment ID, consent ID).'","CREATE INDEX IF NOT EXISTS idx_provenance_nodes_type\n    ON provenance_nodes(node_type)","CREATE INDEX IF NOT EXISTS idx_provenance_nodes_external\n    ON provenance_nodes(node_type, external_id)","CREATE INDEX IF NOT EXISTS idx_provenance_nodes_org\n    ON provenance_nodes(organization_id)","-- ############################################################################\n-- PART 3: PROVENANCE EDGES\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS provenance_edges (\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    edge_type       provenance_edge_type NOT NULL,\n    source_node_id  UUID NOT NULL REFERENCES provenance_nodes(id) ON DELETE CASCADE,\n    target_node_id  UUID NOT NULL REFERENCES provenance_nodes(id) ON DELETE CASCADE,\n    properties      JSONB DEFAULT '{}'::jsonb,\n    recorded_at     TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    -- Each edge must be unique (no duplicate edges between same nodes)\n    CONSTRAINT provenance_edges_unique\n        UNIQUE (edge_type, source_node_id, target_node_id)\n)","COMMENT ON TABLE provenance_edges IS\n    'Directed, typed relationships between provenance nodes. Forms a DAG.'","CREATE INDEX IF NOT EXISTS idx_provenance_edges_source\n    ON provenance_edges(source_node_id)","CREATE INDEX IF NOT EXISTS idx_provenance_edges_target\n    ON provenance_edges(target_node_id)","CREATE INDEX IF NOT EXISTS idx_provenance_edges_type\n    ON provenance_edges(edge_type)","CREATE INDEX IF NOT EXISTS idx_provenance_edges_source_type\n    ON provenance_edges(source_node_id, edge_type)","CREATE INDEX IF NOT EXISTS idx_provenance_edges_target_type\n    ON provenance_edges(target_node_id, edge_type)","-- ############################################################################\n-- PART 4: PROVENANCE EVIDENCE\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS provenance_evidence (\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    node_id         UUID NOT NULL REFERENCES provenance_nodes(id) ON DELETE CASCADE,\n    evidence_type   VARCHAR(100) NOT NULL,  -- 'mta_pdf', 'temperature_log', 'qc_report', etc.\n    reference       TEXT NOT NULL,           -- URL, file path, or external ID\n    hash            TEXT,                    -- Content hash for integrity verification\n    description     TEXT,\n    recorded_at     TIMESTAMPTZ NOT NULL DEFAULT now()\n)","COMMENT ON TABLE provenance_evidence IS\n    'Verifiable evidence linked to provenance nodes. Supports integrity checking.'","CREATE INDEX IF NOT EXISTS idx_provenance_evidence_node\n    ON provenance_evidence(node_id)","-- ############################################################################\n-- PART 5: ROW-LEVEL SECURITY\n-- ############################################################################\n\nALTER TABLE provenance_nodes ENABLE ROW LEVEL SECURITY","ALTER TABLE provenance_edges ENABLE ROW LEVEL SECURITY","ALTER TABLE provenance_evidence ENABLE ROW LEVEL SECURITY","CREATE POLICY provenance_nodes_select ON provenance_nodes\n    FOR SELECT USING (\n        organization_id IS NULL\n        OR organization_id IN (\n            SELECT organization_id FROM user_organizations WHERE user_id = auth.uid()\n        )\n        OR auth.role() = 'service_role'\n    )","CREATE POLICY provenance_nodes_insert ON provenance_nodes\n    FOR INSERT WITH CHECK (auth.role() = 'service_role')","CREATE POLICY provenance_nodes_update ON provenance_nodes\n    FOR UPDATE USING (auth.role() = 'service_role')","CREATE POLICY provenance_edges_select ON provenance_edges\n    FOR SELECT USING (\n        EXISTS (\n            SELECT 1 FROM provenance_nodes n\n            WHERE (n.id = provenance_edges.source_node_id OR n.id = provenance_edges.target_node_id)\n            AND (n.organization_id IS NULL\n                OR n.organization_id IN (\n                    SELECT organization_id FROM user_organizations WHERE user_id = auth.uid()\n                ))\n        )\n        OR auth.role() = 'service_role'\n    )","CREATE POLICY provenance_edges_insert ON provenance_edges\n    FOR INSERT WITH CHECK (auth.role() = 'service_role')","CREATE POLICY provenance_evidence_select ON provenance_evidence\n    FOR SELECT USING (\n        EXISTS (\n            SELECT 1 FROM provenance_nodes n\n            WHERE n.id = provenance_evidence.node_id\n            AND (n.organization_id IS NULL\n                OR n.organization_id IN (\n                    SELECT organization_id FROM user_organizations WHERE user_id = auth.uid()\n                ))\n        )\n        OR auth.role() = 'service_role'\n    )","CREATE POLICY provenance_evidence_insert ON provenance_evidence\n    FOR INSERT WITH CHECK (auth.role() = 'service_role')","-- ############################################################################\n-- PART 6: HELPER FUNCTIONS\n-- ############################################################################\n\n-- Ensure a provenance node exists (insert or return existing)\nCREATE OR REPLACE FUNCTION ensure_provenance_node(\n    p_node_type     provenance_node_type,\n    p_external_id   VARCHAR(255),\n    p_label         VARCHAR(500) DEFAULT NULL,\n    p_properties    JSONB DEFAULT '{}'::jsonb,\n    p_organization_id UUID DEFAULT NULL\n) RETURNS UUID\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_node_id UUID;\nBEGIN\n    INSERT INTO provenance_nodes (node_type, external_id, label, properties, organization_id)\n    VALUES (p_node_type, p_external_id, p_label, p_properties, p_organization_id)\n    ON CONFLICT (node_type, external_id) DO UPDATE SET\n        label = COALESCE(p_label, provenance_nodes.label),\n        properties = CASE\n            WHEN p_properties = '{}'::jsonb THEN provenance_nodes.properties\n            ELSE provenance_nodes.properties || p_properties\n        END,\n        recorded_at = now()\n    RETURNING id INTO v_node_id;\n\n    RETURN v_node_id;\nEND;\n$$","-- Create a provenance edge (idempotent)\nCREATE OR REPLACE FUNCTION ensure_provenance_edge(\n    p_edge_type       provenance_edge_type,\n    p_source_node_id  UUID,\n    p_target_node_id  UUID,\n    p_properties      JSONB DEFAULT '{}'::jsonb\n) RETURNS UUID\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_edge_id UUID;\nBEGIN\n    INSERT INTO provenance_edges (edge_type, source_node_id, target_node_id, properties)\n    VALUES (p_edge_type, p_source_node_id, p_target_node_id, p_properties)\n    ON CONFLICT (edge_type, source_node_id, target_node_id) DO NOTHING\n    RETURNING id INTO v_edge_id;\n\n    RETURN v_edge_id;\nEND;\n$$"}	provenance_graph
026	{"-- ============================================================================\n-- KADARN PLATFORM — Knowledge Engine (Semantic Layer)\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n-- Domain: Controlled vocabularies, term normalization, synonym resolution,\n--         and external code mapping\n-- Design: ADR-015 — Knowledge Engine: Semantic Understanding Layer\n-- Reference: KRM-RAO §4.3 (Knowledge Graph)\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: VOCABULARY SETS\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE vocabulary_set AS ENUM (\n        'specimen_type',\n        'processing_method',\n        'storage_condition',\n        'container_type',\n        'regulatory_doc_type',\n        'diagnosis'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: ONTOLOGY TERMS\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS ontology_terms (\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    vocabulary      vocabulary_set NOT NULL,\n    preferred_label VARCHAR(255) NOT NULL,  -- canonical name, snake_case\n    display_name    VARCHAR(255) NOT NULL,  -- human-readable: \\"Whole Blood\\"\n    description     TEXT,\n    parent_id       UUID REFERENCES ontology_terms(id) ON DELETE SET NULL,\n    is_active       BOOLEAN NOT NULL DEFAULT true,\n    sort_order      INTEGER DEFAULT 0,\n    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    -- Unique per vocabulary\n    CONSTRAINT ontology_terms_unique_vocab_label\n        UNIQUE (vocabulary, preferred_label)\n)","COMMENT ON TABLE ontology_terms IS\n    'Controlled vocabulary terms organized by vocabulary set.'","CREATE INDEX IF NOT EXISTS idx_ontology_terms_vocabulary\n    ON ontology_terms(vocabulary)","CREATE INDEX IF NOT EXISTS idx_ontology_terms_parent\n    ON ontology_terms(parent_id)","CREATE INDEX IF NOT EXISTS idx_ontology_terms_active\n    ON ontology_terms(vocabulary, is_active)","-- ############################################################################\n-- PART 3: SYNONYMS\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS ontology_synonyms (\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    term_id         UUID NOT NULL REFERENCES ontology_terms(id) ON DELETE CASCADE,\n    synonym         VARCHAR(255) NOT NULL,  -- alternative name\n    source          VARCHAR(100),           -- where this synonym came from\n    is_abbreviation BOOLEAN NOT NULL DEFAULT false,\n    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    CONSTRAINT ontology_synonyms_unique\n        UNIQUE (term_id, synonym)\n)","CREATE INDEX IF NOT EXISTS idx_ontology_synonyms_term\n    ON ontology_synonyms(term_id)","CREATE INDEX IF NOT EXISTS idx_ontology_synonyms_search\n    ON ontology_synonyms(synonym)","-- ############################################################################\n-- PART 4: EXTERNAL CODE MAPPINGS\n-- ############################################################################\n\nDO $$ BEGIN\n    CREATE TYPE coding_system AS ENUM (\n        'icd10', 'icd11', 'snomed_ct', 'loinc', 'ncit', 'mondo', 'fhir'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","CREATE TABLE IF NOT EXISTS ontology_mappings (\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    term_id         UUID NOT NULL REFERENCES ontology_terms(id) ON DELETE CASCADE,\n    coding_system   coding_system NOT NULL,\n    external_code   VARCHAR(50) NOT NULL,\n    external_label  VARCHAR(255),\n    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    CONSTRAINT ontology_mappings_unique\n        UNIQUE (term_id, coding_system, external_code)\n)","CREATE INDEX IF NOT EXISTS idx_ontology_mappings_term\n    ON ontology_mappings(term_id)","CREATE INDEX IF NOT EXISTS idx_ontology_mappings_code\n    ON ontology_mappings(coding_system, external_code)","-- ############################################################################\n-- PART 5: RLS\n-- ############################################################################\n\nALTER TABLE ontology_terms ENABLE ROW LEVEL SECURITY","ALTER TABLE ontology_synonyms ENABLE ROW LEVEL SECURITY","ALTER TABLE ontology_mappings ENABLE ROW LEVEL SECURITY","CREATE POLICY ontology_terms_select ON ontology_terms\n    FOR SELECT USING (true)","-- read-only for all authenticated users\n\nCREATE POLICY ontology_terms_insert ON ontology_terms\n    FOR INSERT WITH CHECK (auth.role() = 'service_role')","CREATE POLICY ontology_terms_update ON ontology_terms\n    FOR UPDATE USING (auth.role() = 'service_role')","CREATE POLICY ontology_synonyms_select ON ontology_synonyms\n    FOR SELECT USING (true)","CREATE POLICY ontology_synonyms_insert ON ontology_synonyms\n    FOR INSERT WITH CHECK (auth.role() = 'service_role')","CREATE POLICY ontology_mappings_select ON ontology_mappings\n    FOR SELECT USING (true)","CREATE POLICY ontology_mappings_insert ON ontology_mappings\n    FOR INSERT WITH CHECK (auth.role() = 'service_role')","-- ############################################################################\n-- PART 6: SEED VOCABULARIES\n-- ############################################################################\n\n-- Specimen types\nINSERT INTO ontology_terms (vocabulary, preferred_label, display_name, description, sort_order) VALUES\n    ('specimen_type', 'whole_blood', 'Whole Blood', 'Whole blood collected in anticoagulant', 1),\n    ('specimen_type', 'plasma', 'Plasma', 'Plasma separated from whole blood', 2),\n    ('specimen_type', 'serum', 'Serum', 'Serum separated from clotted blood', 3),\n    ('specimen_type', 'ffpe', 'FFPE Tissue', 'Formalin-fixed, paraffin-embedded tissue', 4),\n    ('specimen_type', 'fresh_frozen_tissue', 'Fresh Frozen Tissue', 'Snap-frozen tissue, OCT or cryoprotected', 5),\n    ('specimen_type', 'dna', 'DNA', 'Extracted genomic DNA', 6),\n    ('specimen_type', 'rna', 'RNA', 'Extracted RNA', 7),\n    ('specimen_type', 'urine', 'Urine', 'Urine specimen', 8),\n    ('specimen_type', 'csf', 'Cerebrospinal Fluid', 'CSF from lumbar puncture', 9),\n    ('specimen_type', 'saliva', 'Saliva', 'Saliva/oral fluid', 10),\n    ('specimen_type', 'stool', 'Stool', 'Stool/feces specimen', 11),\n    ('specimen_type', 'bone_marrow', 'Bone Marrow', 'Bone marrow aspirate or biopsy', 12),\n    ('specimen_type', 'buffy_coat', 'Buffy Coat', 'White blood cell concentrate from whole blood', 13),\n    ('specimen_type', 'pbmc', 'PBMC', 'Peripheral blood mononuclear cells', 14),\n    ('specimen_type', 'tissue', 'Tissue', 'Generic tissue specimen', 15)\nON CONFLICT (vocabulary, preferred_label) DO NOTHING","-- Synonyms for specimen types\nWITH spec AS (SELECT id FROM ontology_terms WHERE preferred_label = 'whole_blood' AND vocabulary = 'specimen_type')\nINSERT INTO ontology_synonyms (term_id, synonym, source, is_abbreviation)\nSELECT id, 'WB', 'common', true FROM spec\nUNION ALL SELECT id, 'Blood (venous)', 'common', false FROM spec\nUNION ALL SELECT id, 'EDTA whole blood', 'common', false FROM spec\nUNION ALL SELECT id, 'Peripheral blood', 'common', false FROM spec","WITH spec AS (SELECT id FROM ontology_terms WHERE preferred_label = 'ffpe' AND vocabulary = 'specimen_type')\nINSERT INTO ontology_synonyms (term_id, synonym, source, is_abbreviation)\nSELECT id, 'Formalin-fixed paraffin-embedded', 'common', false FROM spec\nUNION ALL SELECT id, 'FFPET', 'common', true FROM spec\nUNION ALL SELECT id, 'Paraffin block', 'common', false FROM spec","WITH spec AS (SELECT id FROM ontology_terms WHERE preferred_label = 'pbmc' AND vocabulary = 'specimen_type')\nINSERT INTO ontology_synonyms (term_id, synonym, source, is_abbreviation)\nSELECT id, 'Peripheral blood mononuclear cell', 'common', false FROM spec\nUNION ALL SELECT id, 'Mononuclear cells', 'common', false FROM spec","-- Processing methods\nINSERT INTO ontology_terms (vocabulary, preferred_label, display_name, sort_order) VALUES\n    ('processing_method', 'centrifugation', 'Centrifugation', 1),\n    ('processing_method', 'aliquoting', 'Aliquoting', 2),\n    ('processing_method', 'fixation', 'Fixation', 3),\n    ('processing_method', 'embedding', 'Embedding', 4),\n    ('processing_method', 'sectioning', 'Sectioning', 5),\n    ('processing_method', 'dna_extraction', 'DNA Extraction', 6),\n    ('processing_method', 'rna_extraction', 'RNA Extraction', 7),\n    ('processing_method', 'protein_extraction', 'Protein Extraction', 8),\n    ('processing_method', 'filtration', 'Filtration', 9),\n    ('processing_method', 'lyophilization', 'Lyophilization', 10)\nON CONFLICT (vocabulary, preferred_label) DO NOTHING","-- Storage conditions\nINSERT INTO ontology_terms (vocabulary, preferred_label, display_name, sort_order) VALUES\n    ('storage_condition', 'ambient', 'Ambient / Room Temperature', 1),\n    ('storage_condition', 'refrigerated_4c', 'Refrigerated (4°C)', 2),\n    ('storage_condition', 'frozen_minus_20', 'Frozen (-20°C)', 3),\n    ('storage_condition', 'frozen_minus_80', 'Frozen (-80°C)', 4),\n    ('storage_condition', 'ln2_vapor', 'LN2 Vapor Phase', 5),\n    ('storage_condition', 'ln2_liquid', 'LN2 Liquid Phase', 6),\n    ('storage_condition', 'ffpe_ambient', 'FFPE Block (Ambient)', 7),\n    ('storage_condition', 'rna_later', 'RNAlater (4°C or -20°C)', 8)\nON CONFLICT (vocabulary, preferred_label) DO NOTHING","-- Container types\nINSERT INTO ontology_terms (vocabulary, preferred_label, display_name, sort_order) VALUES\n    ('container_type', 'sst_vial', 'SST Vial (Serum Separator)', 1),\n    ('container_type', 'edta_tube', 'EDTA Tube (Lavender Top)', 2),\n    ('container_type', 'heparin_tube', 'Heparin Tube (Green Top)', 3),\n    ('container_type', 'citrate_tube', 'Citrate Tube (Blue Top)', 4),\n    ('container_type', 'cryovial', 'Cryovial', 5),\n    ('container_type', 'microtainer', 'Microtainer', 6),\n    ('container_type', 'slide', 'Glass Slide', 7),\n    ('container_type', 'block', 'Paraffin Block', 8),\n    ('container_type', 'paxgene_tube', 'PAXgene Tube', 9),\n    ('container_type', 'urine_cup', 'Urine Collection Cup', 10),\n    ('container_type', 'sterile_container', 'Sterile Container', 11),\n    ('container_type', 'tissue_cassette', 'Tissue Cassette', 12)\nON CONFLICT (vocabulary, preferred_label) DO NOTHING","-- Regulatory document types\nINSERT INTO ontology_terms (vocabulary, preferred_label, display_name, sort_order) VALUES\n    ('regulatory_doc_type', 'mta', 'Material Transfer Agreement', 1),\n    ('regulatory_doc_type', 'dua', 'Data Use Agreement', 2),\n    ('regulatory_doc_type', 'irb_approval', 'IRB Approval', 3),\n    ('regulatory_doc_type', 'informed_consent', 'Informed Consent', 4),\n    ('regulatory_doc_type', 'hipaa_baa', 'HIPAA Business Associate Agreement', 5),\n    ('regulatory_doc_type', 'dpa', 'Data Processing Agreement', 6),\n    ('regulatory_doc_type', 'export_permit', 'Export Permit', 7),\n    ('regulatory_doc_type', 'import_permit', 'Import Permit', 8)\nON CONFLICT (vocabulary, preferred_label) DO NOTHING","-- Diagnosis (starter taxonomy — ICD-10 top-level)\nINSERT INTO ontology_terms (vocabulary, preferred_label, display_name, parent_id, sort_order) VALUES\n    ('diagnosis', 'C00-D49', 'Neoplasms', NULL, 1),\n    ('diagnosis', 'C50', 'Breast Cancer', NULL, 2),\n    ('diagnosis', 'C61', 'Prostate Cancer', NULL, 3),\n    ('diagnosis', 'C18-C20', 'Colorectal Cancer', NULL, 4),\n    ('diagnosis', 'C34', 'Lung Cancer', NULL, 5),\n    ('diagnosis', 'D50-D89', 'Diseases of the Blood', NULL, 6),\n    ('diagnosis', 'E00-E89', 'Endocrine/Metabolic', NULL, 7),\n    ('diagnosis', 'I00-I99', 'Circulatory System', NULL, 8),\n    ('diagnosis', 'M00-M99', 'Musculoskeletal', NULL, 9),\n    ('diagnosis', 'G00-G99', 'Nervous System', NULL, 10)\nON CONFLICT (vocabulary, preferred_label) DO NOTHING"}	knowledge_engine
027	{"-- ============================================================================\n-- KADARN PLATFORM — Workflow Engine 2.0 (Dynamic, Policy-Driven)\n-- ============================================================================\n-- Design: ADR-017 — Workflow Engine: Dynamic, Policy-Driven Orchestration\n-- Reference: KRM-RAO §5.3 (Workflow Engine)\n-- Dependencies: 013_policy_engine.sql (policies — for policy_check steps)\n-- ============================================================================\n\nDO $$ BEGIN\n    CREATE TYPE workflow_status AS ENUM (\n        'draft', 'active', 'deprecated'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE instance_status AS ENUM (\n        'running', 'suspended', 'completed', 'blocked', 'cancelled'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    CREATE TYPE task_status AS ENUM (\n        'pending', 'assigned', 'in_progress', 'completed', 'skipped', 'failed'\n    );\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- WORKFLOW DEFINITIONS\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS workflow_definitions (\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    name            VARCHAR(255) NOT NULL,\n    description     TEXT,\n    version         INTEGER NOT NULL DEFAULT 1,\n    status          workflow_status NOT NULL DEFAULT 'draft',\n    steps           JSONB NOT NULL DEFAULT '[]'::jsonb,\n    metadata        JSONB DEFAULT '{}'::jsonb,\n    created_by      UUID REFERENCES auth.users(id),\n    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    CONSTRAINT workflow_definitions_unique_name_version\n        UNIQUE (name, version)\n)","COMMENT ON TABLE workflow_definitions IS\n    'Versioned workflow templates. Steps are stored as JSONB array.'","COMMENT ON COLUMN workflow_definitions.steps IS\n    'Array of {id, type, config, assignee_role?, timeout_minutes?}'","-- ############################################################################\n-- WORKFLOW INSTANCES\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS workflow_instances (\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    definition_id   UUID NOT NULL REFERENCES workflow_definitions(id),\n    status          instance_status NOT NULL DEFAULT 'running',\n    context         JSONB NOT NULL DEFAULT '{}'::jsonb,\n    current_step_id VARCHAR(255),\n    current_step_index INTEGER NOT NULL DEFAULT 0,\n    organization_id UUID REFERENCES organizations(id),\n    started_by      UUID REFERENCES auth.users(id),\n    started_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n    completed_at    TIMESTAMPTZ,\n    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_workflow_instances_status\n    ON workflow_instances(status)","CREATE INDEX IF NOT EXISTS idx_workflow_instances_definition\n    ON workflow_instances(definition_id)","CREATE INDEX IF NOT EXISTS idx_workflow_instances_org\n    ON workflow_instances(organization_id)","-- ############################################################################\n-- WORKFLOW TASKS\n-- ############################################################################\n\nCREATE TABLE IF NOT EXISTS workflow_tasks (\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    instance_id     UUID NOT NULL REFERENCES workflow_instances(id) ON DELETE CASCADE,\n    step_id         VARCHAR(255) NOT NULL,\n    step_type       VARCHAR(50) NOT NULL,\n    status          task_status NOT NULL DEFAULT 'pending',\n    assigned_to     UUID REFERENCES auth.users(id),\n    config          JSONB DEFAULT '{}'::jsonb,\n    result          JSONB,\n    notes           TEXT,\n    assigned_at     TIMESTAMPTZ,\n    completed_at    TIMESTAMPTZ,\n    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_workflow_tasks_instance\n    ON workflow_tasks(instance_id)","CREATE INDEX IF NOT EXISTS idx_workflow_tasks_assignee\n    ON workflow_tasks(assigned_to)","CREATE INDEX IF NOT EXISTS idx_workflow_tasks_status\n    ON workflow_tasks(status)","-- ############################################################################\n-- RLS\n-- ############################################################################\n\nALTER TABLE workflow_definitions ENABLE ROW LEVEL SECURITY","ALTER TABLE workflow_instances ENABLE ROW LEVEL SECURITY","ALTER TABLE workflow_tasks ENABLE ROW LEVEL SECURITY","CREATE POLICY workflow_definitions_select ON workflow_definitions\n    FOR SELECT USING (true)","CREATE POLICY workflow_definitions_insert ON workflow_definitions\n    FOR INSERT WITH CHECK (auth.role() = 'service_role')","CREATE POLICY workflow_instances_select ON workflow_instances\n    FOR SELECT USING (\n        organization_id IN (SELECT organization_id FROM user_organizations WHERE user_id = auth.uid())\n        OR auth.role() = 'service_role'\n    )","CREATE POLICY workflow_instances_insert ON workflow_instances\n    FOR INSERT WITH CHECK (auth.role() = 'service_role')","CREATE POLICY workflow_instances_update ON workflow_instances\n    FOR UPDATE USING (auth.role() = 'service_role')","CREATE POLICY workflow_tasks_select ON workflow_tasks\n    FOR SELECT USING (\n        auth.role() = 'service_role'\n        OR assigned_to = auth.uid()\n    )","CREATE POLICY workflow_tasks_insert ON workflow_tasks\n    FOR INSERT WITH CHECK (auth.role() = 'service_role')","CREATE POLICY workflow_tasks_update ON workflow_tasks\n    FOR UPDATE USING (auth.role() = 'service_role' OR assigned_to = auth.uid())"}	workflow_engine
028	{"-- ============================================================================\n-- KADARN PLATFORM — Transaction Twin + Shipment Twin\n-- ============================================================================\n-- Extends the Operational Twins foundation (migration 015) with Transaction\n-- and Shipment twin types.\n-- Reference: KRM-BNO §4.2 (Transaction Twin), §4.4 (Shipment Twin)\n-- Dependencies: 015_operational_twins.sql (twin_events, apply_twin_event)\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: EXTEND TWIN EVENT TYPE ENUM\n-- ############################################################################\n\n-- ALTER TYPE ... ADD VALUE cannot be in a transaction block in older PG\n-- versions, but we wrap each in DO $$ for safety.\n\nDO $$ BEGIN\n    ALTER TYPE twin_event_type ADD VALUE IF NOT EXISTS 'TransactionInitiated';\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    ALTER TYPE twin_event_type ADD VALUE IF NOT EXISTS 'GovernanceReviewStarted';\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    ALTER TYPE twin_event_type ADD VALUE IF NOT EXISTS 'MTASigned';\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    ALTER TYPE twin_event_type ADD VALUE IF NOT EXISTS 'PaymentEscrowed';\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    ALTER TYPE twin_event_type ADD VALUE IF NOT EXISTS 'FulfillmentCompleted';\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    ALTER TYPE twin_event_type ADD VALUE IF NOT EXISTS 'SettlementCompleted';\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    ALTER TYPE twin_event_type ADD VALUE IF NOT EXISTS 'DisputeRaised';\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","DO $$ BEGIN\n    ALTER TYPE twin_event_type ADD VALUE IF NOT EXISTS 'DisputeResolved';\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","-- ############################################################################\n-- PART 2: TRANSACTION TWINS\n-- ############################################################################\n\nCREATE TYPE transaction_status AS ENUM (\n    'initiated',\n    'governance_review',\n    'mta_pending',\n    'fulfilling',\n    'completed',\n    'disputed',\n    'settled',\n    'cancelled'\n)","CREATE TABLE IF NOT EXISTS transaction_twins (\n    id                  UUID PRIMARY KEY,\n    organization_id     UUID NOT NULL REFERENCES organizations(id),\n\n    status              transaction_status NOT NULL DEFAULT 'initiated',\n    transaction_type    VARCHAR(50),        -- mta, dua, purchase, etc.\n    provider_org_id     UUID REFERENCES organizations(id),\n    recipient_org_id    UUID REFERENCES organizations(id),\n    total_value         NUMERIC(12,2),\n    currency            VARCHAR(3) DEFAULT 'USD',\n    mta_id              UUID,\n    payment_status      VARCHAR(50),        -- pending, escrowed, released, disputed\n\n    twin_sequence       BIGINT NOT NULL DEFAULT 0,\n    twin_updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    initiated_at        TIMESTAMPTZ,\n    completed_at        TIMESTAMPTZ,\n    initiated_by        UUID REFERENCES auth.users(id),\n    notes               TEXT,\n\n    CONSTRAINT transaction_twins_positive_sequence\n        CHECK (twin_sequence >= 0)\n)","CREATE INDEX IF NOT EXISTS idx_transaction_twins_org\n    ON transaction_twins(organization_id)","CREATE INDEX IF NOT EXISTS idx_transaction_twins_status\n    ON transaction_twins(status)","ALTER TABLE transaction_twins ENABLE ROW LEVEL SECURITY","CREATE POLICY transaction_twins_select ON transaction_twins\n    FOR SELECT USING (\n        organization_id IN (SELECT organization_id FROM user_organizations WHERE user_id = auth.uid())\n        OR provider_org_id IN (SELECT organization_id FROM user_organizations WHERE user_id = auth.uid())\n        OR recipient_org_id IN (SELECT organization_id FROM user_organizations WHERE user_id = auth.uid())\n        OR auth.role() = 'service_role'\n    )","CREATE POLICY transaction_twins_insert ON transaction_twins\n    FOR INSERT WITH CHECK (auth.role() = 'service_role')","CREATE POLICY transaction_twins_update ON transaction_twins\n    FOR UPDATE USING (auth.role() = 'service_role')","-- ############################################################################\n-- PART 3: SHIPMENT TWINS\n-- ############################################################################\n\n-- Extend shipment_status enum with twin-specific values\n-- (base values defined in 018_logistics_engine.sql)\nDO $$ BEGIN\n    ALTER TYPE shipment_status ADD VALUE IF NOT EXISTS 'scheduled';\n    ALTER TYPE shipment_status ADD VALUE IF NOT EXISTS 'preparing';\n    ALTER TYPE shipment_status ADD VALUE IF NOT EXISTS 'customs_hold';\n    ALTER TYPE shipment_status ADD VALUE IF NOT EXISTS 'accepted';\n    ALTER TYPE shipment_status ADD VALUE IF NOT EXISTS 'disputed';\nEXCEPTION WHEN duplicate_object THEN NULL;\nEND $$","CREATE TABLE IF NOT EXISTS shipment_twins (\n    id                  UUID PRIMARY KEY,\n    organization_id     UUID NOT NULL REFERENCES organizations(id),\n\n    status              shipment_status NOT NULL,\n    courier             VARCHAR(100),\n    tracking_number     VARCHAR(100),\n    origin_org_id       UUID REFERENCES organizations(id),\n    destination_org_id  UUID REFERENCES organizations(id),\n    temperature_range   VARCHAR(50),        -- e.g. 'minus_80', 'ln2', 'ambient'\n    current_temp        NUMERIC(5,1),       -- latest temperature reading\n    breach_count        INTEGER NOT NULL DEFAULT 0,\n    last_breach_at      TIMESTAMPTZ,\n    chain_of_custody    JSONB DEFAULT '[]'::jsonb,\n\n    twin_sequence       BIGINT NOT NULL DEFAULT 0,\n    twin_updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),\n\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\n    dispatched_at       TIMESTAMPTZ,\n    delivered_at        TIMESTAMPTZ,\n    dispatched_by       UUID REFERENCES auth.users(id),\n    notes               TEXT,\n\n    CONSTRAINT shipment_twins_positive_sequence\n        CHECK (twin_sequence >= 0)\n)","CREATE INDEX IF NOT EXISTS idx_shipment_twins_org\n    ON shipment_twins(organization_id)","CREATE INDEX IF NOT EXISTS idx_shipment_twins_status\n    ON shipment_twins(status)","CREATE INDEX IF NOT EXISTS idx_shipment_twins_courier\n    ON shipment_twins(courier)","ALTER TABLE shipment_twins ENABLE ROW LEVEL SECURITY","CREATE POLICY shipment_twins_select ON shipment_twins\n    FOR SELECT USING (\n        organization_id IN (SELECT organization_id FROM user_organizations WHERE user_id = auth.uid())\n        OR origin_org_id IN (SELECT organization_id FROM user_organizations WHERE user_id = auth.uid())\n        OR destination_org_id IN (SELECT organization_id FROM user_organizations WHERE user_id = auth.uid())\n        OR auth.role() = 'service_role'\n    )","CREATE POLICY shipment_twins_insert ON shipment_twins\n    FOR INSERT WITH CHECK (auth.role() = 'service_role')","CREATE POLICY shipment_twins_update ON shipment_twins\n    FOR UPDATE USING (auth.role() = 'service_role')"}	transaction_shipment_twins
029	{"-- Collection Twin + Organization Twin extension\nDO $$ BEGIN CREATE TYPE collection_status AS ENUM ('planned','active','paused','completed','closed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$","CREATE TABLE IF NOT EXISTS collection_twins (\n  id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id),\n  status collection_status NOT NULL DEFAULT 'planned',\n  protocol VARCHAR(500), irb_ref VARCHAR(255), consent_model VARCHAR(50),\n  target_enrollment INTEGER, actual_enrollment INTEGER DEFAULT 0,\n  twin_sequence BIGINT NOT NULL DEFAULT 0, twin_updated_at TIMESTAMPTZ DEFAULT now(),\n  created_at TIMESTAMPTZ DEFAULT now()\n)","ALTER TABLE collection_twins ENABLE ROW LEVEL SECURITY","CREATE POLICY collection_twins_select ON collection_twins FOR SELECT USING (organization_id IN (SELECT organization_id FROM user_organizations WHERE user_id = auth.uid()) OR auth.role()='service_role')","CREATE POLICY collection_twins_insert ON collection_twins FOR INSERT WITH CHECK (auth.role()='service_role')","CREATE POLICY collection_twins_update ON collection_twins FOR UPDATE USING (auth.role()='service_role')","-- Organization Twin extends existing organizations table\n-- Uses organization_trust from migration 014 for trust scores\n-- This view provides the Organization Twin query interface\nCREATE OR REPLACE VIEW organization_twins AS\nSELECT o.id, o.name, o.country,\n  COALESCE(\n    (SELECT JSONB_AGG(oct.key) FROM organization_capabilities oc\n     JOIN organization_capability_types oct ON oct.id = oc.capability_type_id\n     WHERE oc.organization_id = o.id),\n    '[]'::jsonb\n  ) AS capabilities,\n  t.operational_score, t.regulatory_score, t.financial_score, t.technical_score, t.overall_score,\n  t.total_fulfillments, t.successful_fulfillments, t.incident_count,\n  t.last_event_at, t.last_decay_at, t.updated_at as trust_updated_at\nFROM organizations o LEFT JOIN organization_trust t ON o.id = t.organization_id"}	collection_organization_twins
030	{"-- ============================================================================\n-- KADARN PLATFORM — Test Auth Users\n-- ============================================================================\n-- Target: local dev + CI only. Never run against production.\n-- Dependencies: 008_organizations_capabilities.sql, 011_seed_data.sql\n--\n-- Adds 3 test users covering access scenarios not in the main seed:\n--   1. noorg@kadarn.test     — authenticated, no org membership\n--   2. koc@kadarn.test       — Kadarn internal (kadarn_role = kadarn_internal)\n--   3. multiorg@kadarn.test  — member of 2 orgs, no active_org_id set\n--\n-- All passwords: Test123! (local dev only)\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: noorg@kadarn.test\n-- ############################################################################\n-- Authenticated user who has not joined any organization.\n-- Expected: login OK → allowed_experiences = ['marketplace']\n--           default_redirect = '/marketplace'\n-- ============================================================================\n\nSELECT public.admin_create_user(\n    'noorg@kadarn.test',\n    'Test123!',\n    'No Org User'\n)","-- ############################################################################\n-- PART 2: koc@kadarn.test\n-- ############################################################################\n-- Kadarn internal operator. No org membership — platform-level access.\n-- Expected: kadarn_role = 'kadarn_internal' → default_redirect = '/koc'\n--           allowed_experiences = ['marketplace', 'workspace', 'koc']\n-- ============================================================================\n\nSELECT public.admin_create_user(\n    'koc@kadarn.test',\n    'Test123!',\n    'KOC Operator'\n)","UPDATE auth.users\nSET raw_user_meta_data = raw_user_meta_data || jsonb_build_object('kadarn_role', 'kadarn_internal')\nWHERE email = 'koc@kadarn.test'","-- ############################################################################\n-- PART 3: multiorg@kadarn.test\n-- ############################################################################\n-- Regular user with active memberships in 2 orgs (PharmaCorp + National Biobank).\n-- No active_org_id set in metadata — org selector must be shown.\n-- Expected: default_redirect = '/auth/select-org'\n--           After selecting org → default_redirect = '/workspace'\n-- ============================================================================\n\nSELECT public.admin_create_user(\n    'multiorg@kadarn.test',\n    'Test123!',\n    'Multi Org User'\n    -- no org_id — we add memberships manually below\n)","-- Membership 1: PharmaCorp (sponsor)\nINSERT INTO public.organization_memberships (user_id, organization_id, status, invited_by, invited_at, joined_at)\nSELECT up.id, 'a0000000-0000-0000-0000-000000000001', 'active', up.id, now(), now()\nFROM public.user_profiles up\nWHERE up.email = 'multiorg@kadarn.test'\nON CONFLICT (user_id, organization_id) DO NOTHING","INSERT INTO public.membership_roles (membership_id, role_id, assigned_by)\nSELECT om.id, r.id, om.user_id\nFROM public.organization_memberships om\nJOIN public.user_profiles up ON up.id = om.user_id\nCROSS JOIN public.organization_roles r\nWHERE up.email = 'multiorg@kadarn.test'\n  AND om.organization_id = 'a0000000-0000-0000-0000-000000000001'\n  AND r.key = 'org_member'\nON CONFLICT DO NOTHING","-- Membership 2: National Biobank (biobank)\nINSERT INTO public.organization_memberships (user_id, organization_id, status, invited_by, invited_at, joined_at)\nSELECT up.id, 'a0000000-0000-0000-0000-000000000004', 'active', up.id, now(), now()\nFROM public.user_profiles up\nWHERE up.email = 'multiorg@kadarn.test'\nON CONFLICT (user_id, organization_id) DO NOTHING","INSERT INTO public.membership_roles (membership_id, role_id, assigned_by)\nSELECT om.id, r.id, om.user_id\nFROM public.organization_memberships om\nJOIN public.user_profiles up ON up.id = om.user_id\nCROSS JOIN public.organization_roles r\nWHERE up.email = 'multiorg@kadarn.test'\n  AND om.organization_id = 'a0000000-0000-0000-0000-000000000004'\n  AND r.key = 'org_member'\nON CONFLICT DO NOTHING","-- ############################################################################\n-- PART 4: VERIFICATION\n-- ############################################################################\n--\n-- SELECT u.email,\n--        u.raw_user_meta_data->>'kadarn_role' AS kadarn_role,\n--        COUNT(om.id) AS membership_count\n-- FROM auth.users u\n-- LEFT JOIN public.user_profiles up ON up.id = u.id\n-- LEFT JOIN public.organization_memberships om ON om.user_id = u.id AND om.status = 'active'\n-- WHERE u.email IN ('noorg@kadarn.test', 'koc@kadarn.test', 'multiorg@kadarn.test')\n-- GROUP BY u.email, u.raw_user_meta_data->>'kadarn_role';\n--\n-- Expected:\n--   noorg@kadarn.test    | NULL              | 0\n--   koc@kadarn.test      | kadarn_internal   | 0\n--   multiorg@kadarn.test | NULL              | 2\n-- ============================================================================\n\n-- ============================================================================\n-- END OF MIGRATION 030 — Test Auth Users\n-- ============================================================================"}	test_auth_users
031	{"-- ============================================================================\n-- KADARN PLATFORM — Operational Seed Data\n-- ============================================================================\n-- Target: local dev + CI only. Never run against production.\n-- Dependencies: All migrations 008–030 must run first.\n--\n-- Populates the platform with realistic operational data so that:\n--   Marketplace search returns results\n--   Workspace shows org-scoped programs, requests, shipments\n--   KOC dashboards have real KPIs, trust scores, exceptions, KPE data\n--\n-- Scenario: \\"Oncology Biomarker Validation Program\\"\n--   Sponsor: PharmaCorp\n--   CRO: ClinResearch CRO\n--   Sites: Univ Medical Center\n--   Biobank: National Biobank\n--   Lab: Advanced Path Lab\n--   Courier: Global Cold Chain\n--   IRB: Central IRB\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: PROGRAMS\n-- ############################################################################\n\nDO $$\nDECLARE\n    v_sponsor  CONSTANT UUID := 'a0000000-0000-0000-0000-000000000001';\n    v_cro      CONSTANT UUID := 'a0000000-0000-0000-0000-000000000002';\n    v_site     CONSTANT UUID := 'a0000000-0000-0000-0000-000000000003';\n    v_biobank  CONSTANT UUID := 'a0000000-0000-0000-0000-000000000004';\n    v_lab      CONSTANT UUID := 'a0000000-0000-0000-0000-000000000005';\n    v_courier  CONSTANT UUID := 'a0000000-0000-0000-0000-000000000006';\n    v_admin1   CONSTANT UUID := '00000000-0000-0000-0000-000000000001';\n    v_irb      CONSTANT UUID := 'a0000000-0000-0000-0000-000000000007';\n\n    v_prog1 UUID; v_prog2 UUID;\n    v_deal1 UUID; v_deal2 UUID; v_deal3 UUID;\n    v_ship1 UUID; v_ship2 UUID;\n    v_spec1 UUID; v_spec2 UUID; v_spec3 UUID; v_spec4 UUID; v_spec5 UUID;\n    v_twin1 UUID; v_twin2 UUID;\nBEGIN\n\n-- Programs\nINSERT INTO public.programs (id, name, short_name, description, program_type, therapeutic_areas, status, sponsor_org_id, start_date, end_date, created_by, created_by_organization_id)\nVALUES (gen_random_uuid(), 'Oncology Biomarker Validation 2024-05', 'OBV-2024-05', 'Multi-site validation of PD-L1 and HER2 biomarkers in NSCLC and breast cancer', ARRAY['biomarker_validation'], ARRAY['oncology', 'immuno-oncology'], 'active', v_sponsor, '2024-06-01', '2026-12-31', v_admin1, v_sponsor)\nRETURNING id INTO v_prog1;\n\nINSERT INTO public.programs (id, name, short_name, description, program_type, therapeutic_areas, status, sponsor_org_id, start_date, end_date, created_by, created_by_organization_id)\nVALUES (gen_random_uuid(), 'Rare Disease Registry — ALD', 'RDR-ALD', 'Longitudinal biospecimen collection for adrenoleukodystrophy research', ARRAY['registry'], ARRAY['rare_disease', 'neurology'], 'active', v_sponsor, '2025-01-01', '2028-12-31', v_admin1, v_sponsor)\nRETURNING id INTO v_prog2;\n\n-- Program participants\nINSERT INTO public.program_participants (program_id, organization_id, role, created_by) VALUES\n    (v_prog1, v_sponsor,  'sponsor', v_admin1),\n    (v_prog1, v_cro,      'lead', v_admin1),\n    (v_prog1, v_site,     'contributor', v_admin1),\n    (v_prog1, v_biobank,  'contributor', v_admin1),\n    (v_prog1, v_lab,      'processor', v_admin1),\n    (v_prog1, v_courier,  'processor', v_admin1),\n    (v_prog1, v_irb,      'reviewer', v_admin1),\n    (v_prog2, v_sponsor,  'sponsor', v_admin1),\n    (v_prog2, v_site,     'contributor', v_admin1),\n    (v_prog2, v_biobank,  'contributor', v_admin1);\n\n-- ############################################################################\n-- PART 2: EXCHANGE DEALS (requests + MTA + fulfillment)\n-- ############################################################################\n\nINSERT INTO public.exchange_requests (id, organization_id, program_id, status, title, description, requester_id)\nVALUES\n        (gen_random_uuid(), v_biobank, v_prog1, 'accepted', 'NSCLC FFPE blocks — 200 cases', 'Requesting 200 FFPE blocks from NSCLC stage III-IV with PD-L1 IHC results', v_biobank) RETURNING id INTO v_deal1;\n\nINSERT INTO public.exchange_requests (id, organization_id, program_id, status, title, description, requester_id)\nVALUES\n        (gen_random_uuid(), v_biobank, v_prog1, 'accepted', 'Breast cancer plasma — 500 aliquots', 'Matched plasma aliquots from HR+ HER2- breast cancer patients pre/post treatment', v_biobank) RETURNING id INTO v_deal2;\n\nINSERT INTO public.exchange_requests (id, organization_id, program_id, status, title, description, requester_id)\nVALUES\n    (gen_random_uuid(), v_biobank, v_prog2, 'submitted', 'ALD whole blood — 50 donors', 'Longitudinal whole blood collection from ALD patients, 4 timepoints each', v_biobank) RETURNING id INTO v_deal3;\n\n-- ############################################################################\n-- PART 3: SPECIMENS + SPECIMEN TWINS\n-- ############################################################################\n\n-- Create specimens and their twins via twin events\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES\n    ('specimen', gen_random_uuid(), 'SpecimenCollected', '{\\"organization_id\\":\\"a0000000-0000-0000-0000-000000000004\\",\\"specimen_type\\":\\"ffpe\\",\\"container_type\\":\\"block\\",\\"preservation_type\\":\\"ffpe\\",\\"storage_temperature\\":\\"ambient\\",\\"initial_quantity\\":1,\\"unit\\":\\"block\\",\\"consent_status\\":\\"active\\",\\"collection_protocol\\":\\"OBV-NSCLC-001\\"}', 1, '2025-03-15T10:00:00Z', (SELECT id FROM auth.users LIMIT 1))\nRETURNING twin_id INTO v_spec1;\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('specimen', v_spec1, 'QCPassed', '{\\"qcResult\\":\\"passed\\",\\"qcType\\":\\"morphology\\",\\"qcPerformedBy\\":\\"path-001\\"}', 2, '2025-03-16T14:00:00Z', (SELECT id FROM auth.users LIMIT 1));\n\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('specimen', gen_random_uuid(), 'SpecimenCollected', '{\\"organization_id\\":\\"a0000000-0000-0000-0000-000000000004\\",\\"specimen_type\\":\\"ffpe\\",\\"container_type\\":\\"block\\",\\"preservation_type\\":\\"ffpe\\",\\"storage_temperature\\":\\"ambient\\",\\"initial_quantity\\":1,\\"unit\\":\\"block\\",\\"consent_status\\":\\"active\\"}', 1, '2025-04-01T09:00:00Z', (SELECT id FROM auth.users LIMIT 1))\nRETURNING twin_id INTO v_spec2;\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('specimen', v_spec2, 'QCPassed', '{\\"qcResult\\":\\"passed\\",\\"qcType\\":\\"morphology\\",\\"qcPerformedBy\\":\\"path-001\\"}', 2, '2025-04-02T11:00:00Z', (SELECT id FROM auth.users LIMIT 1));\n\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('specimen', gen_random_uuid(), 'SpecimenCollected', '{\\"organization_id\\":\\"a0000000-0000-0000-0000-000000000004\\",\\"specimen_type\\":\\"plasma\\",\\"container_type\\":\\"cryovial\\",\\"preservation_type\\":\\"fresh_frozen\\",\\"storage_temperature\\":\\"minus_80\\",\\"initial_quantity\\":1.5,\\"unit\\":\\"mL\\",\\"consent_status\\":\\"active\\"}', 1, '2025-03-20T08:00:00Z', (SELECT id FROM auth.users LIMIT 1))\nRETURNING twin_id INTO v_spec3;\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('specimen', v_spec3, 'QCPassed', '{\\"qcResult\\":\\"passed\\",\\"qcType\\":\\"hemolysis\\",\\"qcPerformedBy\\":\\"lab-002\\"}', 2, '2025-03-20T14:00:00Z', (SELECT id FROM auth.users LIMIT 1));\n\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('specimen', gen_random_uuid(), 'SpecimenCollected', '{\\"organization_id\\":\\"a0000000-0000-0000-0000-000000000004\\",\\"specimen_type\\":\\"whole_blood\\",\\"container_type\\":\\"edta_tube\\",\\"preservation_type\\":\\"fresh\\",\\"storage_temperature\\":\\"refrigerated_4c\\",\\"initial_quantity\\":8,\\"unit\\":\\"mL\\",\\"consent_status\\":\\"active\\"}', 1, '2025-05-10T07:00:00Z', (SELECT id FROM auth.users LIMIT 1))\nRETURNING twin_id INTO v_spec4;\n\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('specimen', gen_random_uuid(), 'SpecimenCollected', '{\\"organization_id\\":\\"a0000000-0000-0000-0000-000000000004\\",\\"specimen_type\\":\\"ffpe\\",\\"container_type\\":\\"block\\",\\"preservation_type\\":\\"ffpe\\",\\"storage_temperature\\":\\"ambient\\",\\"initial_quantity\\":1,\\"unit\\":\\"block\\",\\"consent_status\\":\\"active\\"}', 1, '2025-06-01T10:00:00Z', (SELECT id FROM auth.users LIMIT 1))\nRETURNING twin_id INTO v_spec5;\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('specimen', v_spec5, 'QCFailed', '{\\"qcResult\\":\\"failed\\",\\"qcType\\":\\"morphology\\",\\"qcPerformedBy\\":\\"path-003\\",\\"notes\\":\\"Tissue fragmentation exceeds threshold\\"}', 2, '2025-06-02T09:00:00Z', (SELECT id FROM auth.users LIMIT 1));\n\n-- ############################################################################\n-- PART 4: SHIPMENTS + SHIPMENT TWINS\n-- ############################################################################\n\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('shipment', gen_random_uuid(), 'ShipmentScheduled', '{\\"organization_id\\":\\"a0000000-0000-0000-0000-000000000006\\",\\"courier\\":\\"Global Cold Chain\\",\\"originOrgId\\":\\"a0000000-0000-0000-0000-000000000004\\",\\"destinationOrgId\\":\\"a0000000-0000-0000-0000-000000000005\\",\\"temperatureRange\\":\\"minus_80\\"}', 1, '2025-06-10T08:00:00Z', (SELECT id FROM auth.users LIMIT 1))\nRETURNING twin_id INTO v_ship1;\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('shipment', v_ship1, 'ShipmentPickedUp', '{\\"trackingNumber\\":\\"GCC-2025-0610-01\\"}', 2, '2025-06-10T14:00:00Z', (SELECT id FROM auth.users LIMIT 1));\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('shipment', v_ship1, 'TemperatureReading', '{\\"temperature\\":-78,\\"timestamp\\":\\"2025-06-10T16:00:00Z\\"}', 3, '2025-06-10T16:00:00Z', (SELECT id FROM auth.users LIMIT 1));\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('shipment', v_ship1, 'ShipmentDelivered', '{}', 4, '2025-06-12T10:00:00Z', (SELECT id FROM auth.users LIMIT 1));\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('shipment', v_ship1, 'ShipmentAccepted', '{}', 5, '2025-06-12T14:00:00Z', (SELECT id FROM auth.users LIMIT 1));\n\n-- Second shipment — with temperature breach (exception)\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('shipment', gen_random_uuid(), 'ShipmentScheduled', '{\\"organization_id\\":\\"a0000000-0000-0000-0000-000000000006\\",\\"courier\\":\\"Global Cold Chain\\",\\"originOrgId\\":\\"a0000000-0000-0000-0000-000000000004\\",\\"destinationOrgId\\":\\"a0000000-0000-0000-0000-000000000005\\",\\"temperatureRange\\":\\"minus_80\\"}', 1, '2025-06-20T08:00:00Z', (SELECT id FROM auth.users LIMIT 1))\nRETURNING twin_id INTO v_ship2;\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('shipment', v_ship2, 'ShipmentPickedUp', '{\\"trackingNumber\\":\\"GCC-2025-0620-01\\"}', 2, '2025-06-20T14:00:00Z', (SELECT id FROM auth.users LIMIT 1));\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('shipment', v_ship2, 'TemperatureReading', '{\\"temperature\\":-82,\\"timestamp\\":\\"2025-06-20T18:00:00Z\\"}', 3, '2025-06-20T18:00:00Z', (SELECT id FROM auth.users LIMIT 1));\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('shipment', v_ship2, 'TemperatureBreach', '{\\"temperature\\":-45,\\"threshold\\":-50,\\"durationMinutes\\":15}', 4, '2025-06-21T02:00:00Z', (SELECT id FROM auth.users LIMIT 1));\nINSERT INTO twin_events (twin_type, twin_id, event_type, payload, sequence, occurred_at, actor_id)\nVALUES ('shipment', v_ship2, 'ShipmentDelivered', '{}', 5, '2025-06-22T10:00:00Z', (SELECT id FROM auth.users LIMIT 1));\n-- Shipment disputed — no ShipmentAccepted recorded\n\n-- ############################################################################\n-- PART 5: TRUST SCORES + TRUST EVENTS\n-- ############################################################################\n\nINSERT INTO organization_trust (organization_id, operational_score, regulatory_score, financial_score, technical_score, overall_score, total_fulfillments, successful_fulfillments, incident_count)\nVALUES\n    (v_sponsor,  0.92, 0.95, 0.98, 0.90, 0.94, 45, 44, 0),\n    (v_cro,      0.85, 0.90, 0.82, 0.88, 0.86, 120, 115, 2),\n    (v_site,     0.78, 0.92, 0.75, 0.80, 0.81, 230, 220, 3),\n    (v_biobank,  0.95, 0.97, 0.90, 0.93, 0.94, 890, 875, 1),\n    (v_lab,      0.88, 0.93, 0.85, 0.91, 0.89, 560, 548, 4),\n    (v_courier,  0.82, 0.88, 0.90, 0.85, 0.86, 1200, 1150, 12),\n    (v_irb,      0.90, 0.98, 0.85, 0.87, 0.90, 340, 340, 0)\nON CONFLICT (organization_id) DO UPDATE SET\n    operational_score = EXCLUDED.operational_score,\n    regulatory_score = EXCLUDED.regulatory_score,\n    financial_score = EXCLUDED.financial_score,\n    technical_score = EXCLUDED.technical_score,\n    overall_score = EXCLUDED.overall_score,\n    total_fulfillments = EXCLUDED.total_fulfillments,\n    successful_fulfillments = EXCLUDED.successful_fulfillments,\n    incident_count = EXCLUDED.incident_count;\n\n-- Trust events\nINSERT INTO trust_events (organization_id, dimension, impact, evidence_ref, source, severity, description, score_before, score_after)\nVALUES\n    (v_biobank, 'operational', 0.02, 'f-890', 'fulfillment.completed', 'normal', 'Fulfillment #890 completed successfully — 200 FFPE blocks', 0.93, 0.95),\n    (v_courier, 'operational', -0.10, 'breach-0620', 'temperature.breach', 'high', 'Temperature breach on shipment GCC-2025-0620-01: -45°C for 15 min', 0.92, 0.82),\n    (v_lab, 'operational', 0.01, 'qc-pass-4501', 'qc.passed', 'normal', 'QC passed for batch OBV-NSCLC-047', 0.87, 0.88),\n    (v_site, 'regulatory', 0.05, 'irb-renewal-2025', 'accreditation.verified', 'normal', 'IRB approval renewed for oncology protocols', 0.87, 0.92),\n    (v_biobank, 'regulatory', -0.08, 'cap-expiry', 'accreditation.expired', 'high', 'CAP accreditation expired — renewal in process', 0.97, 0.89);\n\n-- ############################################################################\n-- PART 6: PROVENANCE NODES + EDGES\n-- ############################################################################\n\n-- Create provenance nodes for the specimen flow\nINSERT INTO provenance_nodes (node_type, external_id, label, organization_id)\nVALUES\n    ('specimen', v_spec1, 'NSCLC FFPE Block S-001', v_biobank),\n    ('specimen', v_spec2::TEXT, 'NSCLC FFPE Block S-002', v_biobank),\n    ('specimen', v_spec3::TEXT, 'Plasma Aliquot P-001', v_biobank),\n    ('consent', 'consent-objv-001', 'Patient Consent OBV-NSCLC-001', v_site),\n    ('processing_event', 'proc-ffpe-001', 'FFPE Sectioning — 5µm slides', v_lab),\n    ('qc_result', 'qc-001', 'QC Pass — morphology', v_biobank),\n    ('qc_result', 'qc-002', 'QC Fail — tissue fragmentation', v_biobank),\n    ('shipment', v_ship1, 'Shipment GCC-2025-0610-01', v_courier),\n    ('shipment', v_ship2, 'Shipment GCC-2025-0620-01 (breached)', v_courier),\n    ('dataset', 'ds-rnaseq-001', 'RNAseq Dataset — OBV NSCLC cohort', v_lab),\n    ('document', 'mta-objv-001', 'MTA — PharmaCorp / National Biobank', v_sponsor)\nON CONFLICT (node_type, external_id) DO NOTHING;\n\n-- Link provenance edges\nINSERT INTO provenance_edges (edge_type, source_node_id, target_node_id)\nSELECT 'authorized_by', n1.id, n2.id\nFROM provenance_nodes n1, provenance_nodes n2\nWHERE n1.node_type = 'specimen' AND n1.external_id = v_spec1::TEXT\n  AND n2.node_type = 'consent' AND n2.external_id = 'consent-objv-001'\nON CONFLICT DO NOTHING;\n\nINSERT INTO provenance_edges (edge_type, source_node_id, target_node_id)\nSELECT 'verified_by', n1.id, n2.id\nFROM provenance_nodes n1, provenance_nodes n2\nWHERE n1.node_type = 'specimen' AND n1.external_id = v_spec1::TEXT\n  AND n2.node_type = 'qc_result' AND n2.external_id = 'qc-001'\nON CONFLICT DO NOTHING;\n\nINSERT INTO provenance_edges (edge_type, source_node_id, target_node_id)\nSELECT 'shipped_with', n1.id, n2.id\nFROM provenance_nodes n1, provenance_nodes n2\nWHERE n1.node_type = 'specimen' AND n1.external_id = v_spec1::TEXT\n  AND n2.node_type = 'shipment' AND n2.external_id = v_ship1::TEXT\nON CONFLICT DO NOTHING;\n\nINSERT INTO provenance_edges (edge_type, source_node_id, target_node_id)\nSELECT 'derived_from', n1.id, n2.id\nFROM provenance_nodes n1, provenance_nodes n2\nWHERE n1.node_type = 'dataset' AND n1.external_id = 'ds-rnaseq-001'\n  AND n2.node_type = 'specimen' AND n2.external_id = v_spec1::TEXT\nON CONFLICT DO NOTHING;\n\n-- ############################################################################\n-- PART 7: POLICY EVALUATIONS\n-- ############################################################################\n\nINSERT INTO policy_evaluations (policy_id, context, outcome, matched_rules, trace)\nSELECT id, '{\\"request\\":{\\"purpose\\":\\"research\\",\\"consent\\":{\\"scope\\":\\"oncology\\"}}}'::jsonb, 'allow', ARRAY['rule-001'],\n       '[{\\"ruleId\\":\\"rule-001\\",\\"condition\\":{\\"eq\\":[{\\"var\\":\\"request.consent.scope\\"},\\"oncology\\"]},\\"result\\":true}]'::jsonb\nFROM policies WHERE name = 'Oncology Use Only' AND status = 'active' LIMIT 1;\n\n-- ############################################################################\n-- PART 8: AUDIT EVENTS\n-- ############################################################################\n\nINSERT INTO public.audit_events (action, resource_type, resource_id, organization_id, actor_id, summary)\nVALUES\n    ('create', 'program', v_prog1, v_sponsor, (SELECT id FROM auth.users LIMIT 1), 'Oncology Biomarker Validation program created'),\n    ('submit', 'access_request', v_deal1, v_biobank, (SELECT id FROM auth.users LIMIT 1), 'NSCLC FFPE blocks requested for OBV program'),\n    ('create', 'sample', v_spec1, v_biobank, (SELECT id FROM auth.users LIMIT 1), 'FFPE block collected for NSCLC case'),\n    ('create', 'other', NULL, v_biobank, (SELECT id FROM auth.users LIMIT 1), 'QC passed — morphology acceptable'),\n    ('create', 'other', v_ship1, v_courier, (SELECT id FROM auth.users LIMIT 1), 'Shipment scheduled: National Biobank → Advanced Path Lab'),\n    ('other', 'other', v_ship2, v_courier, (SELECT id FROM auth.users LIMIT 1), 'Temperature breach: -45°C for 15 min'),\n    ('create', 'other', NULL, v_lab, (SELECT id FROM auth.users LIMIT 1), 'RNAseq dataset generated from OBV NSCLC cohort');\n\n-- ############################################################################\n-- PART 9: WORKFLOW INSTANCES\n-- ############################################################################\n\nINSERT INTO workflow_instances (definition_id, status, context, current_step_index, organization_id)\nSELECT id, 'running', '{\\"program\\":\\"OBV-2024-05\\",\\"requestType\\":\\"specimen_request\\"}'::jsonb, 2, v_biobank\nFROM workflow_definitions WHERE name = 'Specimen Access Request' AND status = 'active' LIMIT 1;\n\nINSERT INTO workflow_instances (definition_id, status, context, current_step_index, organization_id)\nSELECT id, 'blocked', '{\\"program\\":\\"OBV-2024-05\\",\\"requestType\\":\\"specimen_request\\",\\"blockedBy\\":\\"export_permit\\"}'::jsonb, 1, v_biobank\nFROM workflow_definitions WHERE name = 'Specimen Access Request' AND status = 'active' LIMIT 1;\n\n-- ############################################################################\n-- PART 10: CONFIRMATION\n-- ############################################################################\n\nRAISE NOTICE 'Operational seed data loaded: 2 programs, 3 deals, 5 specimens, 2 shipments, trust scores, provenance, audit trail';\nEND $$"}	operational_seed_data
032	{"-- ============================================================================\n-- KADARN PLATFORM — Provenance Append-Only Enforcement\n-- ============================================================================\n-- Depends on: 025_provenance_graph.sql\n-- KAA: KAA-003 (W3C PROV Provenance Engine), Section 12\n--\n-- Provenance records are append-only by design. This is not a technical\n-- preference — it is a regulatory requirement. A chain of custody that can\n-- be retroactively modified is not a chain of custody.\n--\n-- This migration enforces that constraint at the database level so that no\n-- application bug, migration mistake, or direct DB access can violate it.\n--\n-- Corrections use the wasRevisionOf pattern: a new node is appended that\n-- references the incorrect node. The original is never modified.\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: APPEND-ONLY TRIGGERS\n-- ############################################################################\n\n-- Block UPDATE on provenance_nodes\nCREATE OR REPLACE FUNCTION provenance_nodes_no_update()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    RAISE EXCEPTION\n        'provenance_nodes is append-only. To correct a record, append a new node '\n        'with node_type = ''correction'' and link it via a derived_from edge to '\n        'the node being corrected. Original node id: %', OLD.id\n        USING ERRCODE = 'restrict_violation';\nEND;\n$$","DROP TRIGGER IF EXISTS trg_provenance_nodes_no_update ON provenance_nodes","CREATE TRIGGER trg_provenance_nodes_no_update\n    BEFORE UPDATE ON provenance_nodes\n    FOR EACH ROW\n    EXECUTE FUNCTION provenance_nodes_no_update()","-- Block DELETE on provenance_nodes\nCREATE OR REPLACE FUNCTION provenance_nodes_no_delete()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    RAISE EXCEPTION\n        'provenance_nodes is append-only. Provenance records cannot be deleted. '\n        'Original node id: %', OLD.id\n        USING ERRCODE = 'restrict_violation';\nEND;\n$$","DROP TRIGGER IF EXISTS trg_provenance_nodes_no_delete ON provenance_nodes","CREATE TRIGGER trg_provenance_nodes_no_delete\n    BEFORE DELETE ON provenance_nodes\n    FOR EACH ROW\n    EXECUTE FUNCTION provenance_nodes_no_delete()","-- Block UPDATE on provenance_edges\nCREATE OR REPLACE FUNCTION provenance_edges_no_update()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    RAISE EXCEPTION\n        'provenance_edges is append-only. Edge id: %', OLD.id\n        USING ERRCODE = 'restrict_violation';\nEND;\n$$","DROP TRIGGER IF EXISTS trg_provenance_edges_no_update ON provenance_edges","CREATE TRIGGER trg_provenance_edges_no_update\n    BEFORE UPDATE ON provenance_edges\n    FOR EACH ROW\n    EXECUTE FUNCTION provenance_edges_no_update()","-- Block DELETE on provenance_edges\nCREATE OR REPLACE FUNCTION provenance_edges_no_delete()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    RAISE EXCEPTION\n        'provenance_edges is append-only. Edge id: %', OLD.id\n        USING ERRCODE = 'restrict_violation';\nEND;\n$$","DROP TRIGGER IF EXISTS trg_provenance_edges_no_delete ON provenance_edges","CREATE TRIGGER trg_provenance_edges_no_delete\n    BEFORE DELETE ON provenance_edges\n    FOR EACH ROW\n    EXECUTE FUNCTION provenance_edges_no_delete()","-- Block UPDATE on provenance_evidence\nCREATE OR REPLACE FUNCTION provenance_evidence_no_update()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    RAISE EXCEPTION\n        'provenance_evidence is append-only. Evidence id: %', OLD.id\n        USING ERRCODE = 'restrict_violation';\nEND;\n$$","DROP TRIGGER IF EXISTS trg_provenance_evidence_no_update ON provenance_evidence","CREATE TRIGGER trg_provenance_evidence_no_update\n    BEFORE UPDATE ON provenance_evidence\n    FOR EACH ROW\n    EXECUTE FUNCTION provenance_evidence_no_update()","-- Block DELETE on provenance_evidence\nCREATE OR REPLACE FUNCTION provenance_evidence_no_delete()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    RAISE EXCEPTION\n        'provenance_evidence is append-only. Evidence id: %', OLD.id\n        USING ERRCODE = 'restrict_violation';\nEND;\n$$","DROP TRIGGER IF EXISTS trg_provenance_evidence_no_delete ON provenance_evidence","CREATE TRIGGER trg_provenance_evidence_no_delete\n    BEFORE DELETE ON provenance_evidence\n    FOR EACH ROW\n    EXECUTE FUNCTION provenance_evidence_no_delete()","-- ############################################################################\n-- PART 2: REPLACE ensure_provenance_node WITH APPEND-ONLY VERSION\n-- ############################################################################\n\n-- The original ensure_provenance_node used ON CONFLICT DO UPDATE, which\n-- mutates existing nodes. This violates the append-only constraint now\n-- enforced above. The new version uses ON CONFLICT DO NOTHING and returns\n-- the existing id without modification.\n--\n-- Callers that need to update a node must instead:\n--   1. Call upsert_provenance_node (below) which uses the correction pattern\n--   2. Or insert a new correction node manually\n\nCREATE OR REPLACE FUNCTION ensure_provenance_node(\n    p_node_type       provenance_node_type,\n    p_external_id     VARCHAR(255),\n    p_label           VARCHAR(500)  DEFAULT NULL,\n    p_properties      JSONB         DEFAULT '{}'::jsonb,\n    p_organization_id UUID          DEFAULT NULL\n) RETURNS UUID\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_node_id UUID;\nBEGIN\n    INSERT INTO provenance_nodes (node_type, external_id, label, properties, organization_id)\n    VALUES (p_node_type, p_external_id, p_label, p_properties, p_organization_id)\n    ON CONFLICT (node_type, external_id) DO NOTHING\n    RETURNING id INTO v_node_id;\n\n    -- If the node already existed, return its id\n    IF v_node_id IS NULL THEN\n        SELECT id INTO v_node_id\n        FROM provenance_nodes\n        WHERE node_type = p_node_type AND external_id = p_external_id;\n    END IF;\n\n    RETURN v_node_id;\nEND;\n$$","-- ############################################################################\n-- PART 3: upsert_provenance_node — CORRECTION PATTERN\n-- ############################################################################\n\n-- Used by the POST /api/v1/operations/provenance route when a node needs to\n-- be \\"updated.\\" Instead of mutating, appends a new node linked via derived_from.\n-- Returns the id of the new correction node (not the original).\n\nCREATE OR REPLACE FUNCTION upsert_provenance_node(\n    p_node_type       provenance_node_type,\n    p_external_id     VARCHAR(255),\n    p_label           VARCHAR(500)  DEFAULT NULL,\n    p_properties      JSONB         DEFAULT '{}'::jsonb,\n    p_organization_id UUID          DEFAULT NULL\n) RETURNS UUID\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_existing_id UUID;\n    v_new_id      UUID;\nBEGIN\n    SELECT id INTO v_existing_id\n    FROM provenance_nodes\n    WHERE node_type = p_node_type AND external_id = p_external_id;\n\n    IF v_existing_id IS NULL THEN\n        -- First time: plain insert\n        INSERT INTO provenance_nodes (node_type, external_id, label, properties, organization_id)\n        VALUES (p_node_type, p_external_id, p_label, p_properties, p_organization_id)\n        RETURNING id INTO v_new_id;\n        RETURN v_new_id;\n    ELSE\n        -- Subsequent call: correction pattern\n        -- Insert a new node with the corrected data\n        INSERT INTO provenance_nodes (\n            node_type, external_id, label, properties, organization_id\n        ) VALUES (\n            p_node_type,\n            p_external_id || ':correction:' || extract(epoch from now())::bigint,\n            COALESCE(p_label, ''),\n            p_properties || jsonb_build_object(\n                'correction_of', v_existing_id,\n                'corrected_at', now()\n            ),\n            p_organization_id\n        )\n        RETURNING id INTO v_new_id;\n\n        -- Link via derived_from edge (wasRevisionOf semantic)\n        INSERT INTO provenance_edges (edge_type, source_node_id, target_node_id, properties)\n        VALUES (\n            'derived_from',\n            v_new_id,\n            v_existing_id,\n            '{\\"relation\\": \\"wasRevisionOf\\"}'::jsonb\n        )\n        ON CONFLICT (edge_type, source_node_id, target_node_id) DO NOTHING;\n\n        RETURN v_new_id;\n    END IF;\nEND;\n$$","-- ############################################################################\n-- PART 4: integrity_status FUNCTION\n-- ############################################################################\n\n-- Computes the integrity status of a node at query time.\n-- Called by the provenance API route — not stored as a column to avoid\n-- the temptation to UPDATE it.\n--\n-- Values:\n--   'complete'         — has evidence AND has at least one edge\n--   'warning'          — has evidence but no edges (isolated node)\n--   'missing_evidence' — critical node type with no supporting evidence\n\nCREATE OR REPLACE FUNCTION provenance_node_integrity_status(\n    p_node_id   UUID,\n    p_node_type provenance_node_type\n) RETURNS TEXT\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_evidence_count INTEGER;\n    v_edge_count     INTEGER;\n    v_critical_types provenance_node_type[] := ARRAY[\n        'specimen'::provenance_node_type,\n        'aliquot'::provenance_node_type,\n        'consent'::provenance_node_type,\n        'shipment'::provenance_node_type\n    ];\nBEGIN\n    SELECT COUNT(*) INTO v_evidence_count\n    FROM provenance_evidence\n    WHERE node_id = p_node_id;\n\n    SELECT COUNT(*) INTO v_edge_count\n    FROM provenance_edges\n    WHERE source_node_id = p_node_id OR target_node_id = p_node_id;\n\n    IF v_evidence_count = 0 AND p_node_type = ANY(v_critical_types) THEN\n        RETURN 'missing_evidence';\n    END IF;\n\n    IF v_edge_count = 0 THEN\n        RETURN 'warning';\n    END IF;\n\n    RETURN 'complete';\nEND;\n$$","-- ############################################################################\n-- PART 5: BATCH integrity_status FOR API EFFICIENCY\n-- ############################################################################\n\n-- Called by GET /api/v1/operations/provenance to avoid N individual RPC calls.\n-- Returns one row per node id with its computed integrity_status.\n\nCREATE OR REPLACE FUNCTION provenance_node_integrity_status_batch(\n    p_node_ids UUID[]\n) RETURNS TABLE(node_id UUID, integrity_status TEXT)\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_critical_types provenance_node_type[] := ARRAY[\n        'specimen'::provenance_node_type,\n        'aliquot'::provenance_node_type,\n        'consent'::provenance_node_type,\n        'shipment'::provenance_node_type\n    ];\nBEGIN\n    RETURN QUERY\n    SELECT\n        n.id AS node_id,\n        CASE\n            WHEN COUNT(ev.id) = 0 AND n.node_type = ANY(v_critical_types) THEN 'missing_evidence'\n            WHEN COUNT(e.id) = 0                                           THEN 'warning'\n            ELSE                                                                'complete'\n        END AS integrity_status\n    FROM provenance_nodes n\n    LEFT JOIN provenance_evidence ev ON ev.node_id = n.id\n    LEFT JOIN provenance_edges    e  ON e.source_node_id = n.id OR e.target_node_id = n.id\n    WHERE n.id = ANY(p_node_ids)\n    GROUP BY n.id, n.node_type;\nEND;\n$$","-- ############################################################################\n-- PART 6: VERIFY — confirm triggers are in place\n-- ############################################################################\n\nDO $$\nDECLARE\n    v_trigger_count INTEGER;\nBEGIN\n    SELECT COUNT(*) INTO v_trigger_count\n    FROM information_schema.triggers\n    WHERE trigger_schema = 'public'\n    AND trigger_name LIKE '%provenance%'\n    AND event_manipulation IN ('UPDATE', 'DELETE');\n\n    IF v_trigger_count < 6 THEN\n        RAISE EXCEPTION 'Expected 6 provenance append-only triggers, found %', v_trigger_count;\n    END IF;\n\n    RAISE NOTICE 'Provenance append-only enforcement: % triggers confirmed', v_trigger_count;\nEND;\n$$"}	provenance_append_only
033	{"-- ============================================================================\n-- APF-02 — Sample Lifecycle Schema Fix\n-- ============================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n--\n-- Changes:\n--   1. Add DEFAULT gen_random_uuid() to collection_twins.id\n--      Without this, INSERT into collection_twins requires an explicit UUID,\n--      which breaks the API flow where the route creates collection_twins\n--      without providing an ID (expecting DB to generate one).\n--\n--   2. This is the only schema fix needed.\n--      processing_samples already has correct nullable parent_sample_id and\n--      TEXT sample_id (human-readable). No circular FK exists.\n-- ============================================================================\n\n-- ############################################################################\n-- PART 1: collection_twins — ADD DEFAULT gen_random_uuid()\n-- ############################################################################\n-- The current schema has `id UUID PRIMARY KEY` without a default.\n-- This means every INSERT must provide an explicit UUID, which is inconsistent\n-- with every other Kadarn table. This was discovered during ALPHA-PILOT-03.\n-- ============================================================================\n\nALTER TABLE IF EXISTS collection_twins\n    ALTER COLUMN id SET DEFAULT gen_random_uuid()","-- ############################################################################\n-- PART 2: VERIFY\n-- ############################################################################\n\nDO $$\nDECLARE\n    v_has_default BOOLEAN;\n    v_can_insert  UUID;\nBEGIN\n    -- Check that the default was set\n    SELECT pg_catalog.has_column_privilege(\n        'collection_twins'::regclass, 'id', 'INSERT'\n    ) INTO v_has_default;\n\n    -- Test that we can insert without providing an id\n    INSERT INTO collection_twins (organization_id, status)\n    VALUES ('a0000000-0000-0000-0000-000000000004', 'planned')\n    RETURNING id INTO v_can_insert;\n\n    RAISE NOTICE 'collection_twins auto-id: % (inserted id: %)',\n        CASE WHEN v_can_insert IS NOT NULL THEN 'OK' ELSE 'FAIL' END,\n        v_can_insert;\n\n    -- Clean up test row\n    DELETE FROM collection_twins WHERE id = v_can_insert;\n\n    RAISE NOTICE 'APF-02 migration applied successfully';\nEND;\n$$"}	sample_lifecycle_fix
034	{"-- ==========================================================================\n-- APF-03 — Twin UUID and Schema Hardening\n-- ==========================================================================\n-- Target: PostgreSQL 15+ (Supabase compatible)\n--\n-- Schema audit findings:\n--\n-- Tables with DEFAULT gen_random_uuid():        14/18 OK\n-- Tables WITHOUT DEFAULT gen_random_uuid():      4 (organization_twins,\n--                                                    shipment_twins,\n--                                                    specimen_twins,\n--                                                    transaction_twins)\n--\n-- These 4 twin tables share the same pattern and were likely created\n-- before the convention of adding DEFAULT gen_random_uuid() was established.\n-- Fix: add missing defaults to all 4.\n-- ==========================================================================\n\n-- ############################################################################\n-- PART 1: Add DEFAULT gen_random_uuid() to twin tables\n-- ############################################################################\n\nALTER TABLE IF EXISTS organization_twins\n    ALTER COLUMN id SET DEFAULT gen_random_uuid()","ALTER TABLE IF EXISTS shipment_twins\n    ALTER COLUMN id SET DEFAULT gen_random_uuid()","ALTER TABLE IF EXISTS specimen_twins\n    ALTER COLUMN id SET DEFAULT gen_random_uuid()","ALTER TABLE IF EXISTS transaction_twins\n    ALTER COLUMN id SET DEFAULT gen_random_uuid()","-- ############################################################################\n-- PART 2: VERIFY\n-- ############################################################################\n\nDO $$\nDECLARE\n    v_org_default TEXT;\n    v_shp_default TEXT;\n    v_spc_default TEXT;\n    v_trx_default TEXT;\nBEGIN\n    SELECT column_default INTO v_org_default FROM information_schema.columns\n        WHERE table_name = 'organization_twins' AND column_name = 'id';\n    SELECT column_default INTO v_shp_default FROM information_schema.columns\n        WHERE table_name = 'shipment_twins' AND column_name = 'id';\n    SELECT column_default INTO v_spc_default FROM information_schema.columns\n        WHERE table_name = 'specimen_twins' AND column_name = 'id';\n    SELECT column_default INTO v_trx_default FROM information_schema.columns\n        WHERE table_name = 'transaction_twins' AND column_name = 'id';\n\n    IF v_org_default IS NULL THEN RAISE EXCEPTION 'organization_twins.id still has no default'; END IF;\n    IF v_shp_default IS NULL THEN RAISE EXCEPTION 'shipment_twins.id still has no default'; END IF;\n    IF v_spc_default IS NULL THEN RAISE EXCEPTION 'specimen_twins.id still has no default'; END IF;\n    IF v_trx_default IS NULL THEN RAISE EXCEPTION 'transaction_twins.id still has no default'; END IF;\n\n    RAISE NOTICE 'APF-03: All twin tables have UUID defaults — OK';\n    RAISE NOTICE '  organization_twins: %', v_org_default;\n    RAISE NOTICE '  shipment_twins:     %', v_shp_default;\n    RAISE NOTICE '  specimen_twins:     %', v_spc_default;\n    RAISE NOTICE '  transaction_twins:  %', v_trx_default;\nEND;\n$$"}	twin_uuid_defaults
035	{"-- Staging helper — append-only trigger installer referenced by 041/042\r\nCREATE OR REPLACE FUNCTION public.apply_append_only_triggers(p_table regclass)\r\nRETURNS void\r\nLANGUAGE plpgsql\r\nAS $$\r\nBEGIN\r\n  NULL;\r\nEND;\r\n$$"}	append_only_helpers
036	{"-- ============================================================================\r\n-- KADARN PLATFORM — Extend visibility_scope for evidence-core\r\n-- ============================================================================\r\n-- Migration 008 creates visibility_scope with values:\r\n--   'organization', 'program', 'network', 'public'\r\n-- Evidence-core needs additional values: 'site', 'sponsor_authorized', 'system'.\r\n-- This file runs in its OWN transaction (separate migration file), so\r\n-- ALTER TYPE ... ADD VALUE works without triggering PostgreSQL error 55P04.\r\n-- Requires PostgreSQL 17+ for ADD VALUE IF NOT EXISTS.\r\n-- ============================================================================\r\n\r\nALTER TYPE visibility_scope ADD VALUE IF NOT EXISTS 'site'","ALTER TYPE visibility_scope ADD VALUE IF NOT EXISTS 'sponsor_authorized'","ALTER TYPE visibility_scope ADD VALUE IF NOT EXISTS 'system'"}	ext_visibility
041	{"-- ============================================================================\r\n-- KADARN PLATFORM — Sprint 4: Domain Events Runtime\r\n-- ============================================================================\r\n-- Event Store + Outbox Pattern + Idempotency + Replay\r\n-- Depends on: 010_audit_programs, 035_compliance_append_only\r\n-- ============================================================================\r\n\r\n-- ############################################################################\r\n-- PART 1: EVENT STORE (APPEND-ONLY)\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS public.domain_event_store (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    event_type          TEXT NOT NULL,\r\n    event_version       INTEGER NOT NULL DEFAULT 1,\r\n    occurred_at         TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    recorded_at         TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    actor_id            UUID NOT NULL,\r\n    organization_id     UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\r\n    program_id          UUID REFERENCES public.programs(id) ON DELETE SET NULL,\r\n    correlation_id      UUID,\r\n    causation_id        UUID,\r\n    idempotency_key     TEXT,\r\n    payload             JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n    metadata            JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n\r\n    CONSTRAINT domain_event_store_idempotency_unique\r\n        -- NOTE: NULLS NOT DISTINCT requires PostgreSQL 15+. On PG < 15, use a\r\n   -- unique index with COALESCE: CREATE UNIQUE INDEX ... ON domain_events (COALESCE(idempotency_key, ''))\r\n   UNIQUE NULLS NOT DISTINCT (idempotency_key)\r\n)","CREATE INDEX IF NOT EXISTS idx_domain_event_store_type_time\r\n    ON public.domain_event_store(event_type, occurred_at DESC)","CREATE INDEX IF NOT EXISTS idx_domain_event_store_correlation\r\n    ON public.domain_event_store(correlation_id, occurred_at DESC)\r\n    WHERE correlation_id IS NOT NULL","CREATE INDEX IF NOT EXISTS idx_domain_event_store_org\r\n    ON public.domain_event_store(organization_id, occurred_at DESC)\r\n    WHERE organization_id IS NOT NULL","COMMENT ON TABLE public.domain_event_store IS\r\n    'Append-only canonical domain event log. All cross-engine integration reads from here.'","-- ############################################################################\r\n-- PART 2: OUTBOX (TRANSACTIONAL PUBLISH)\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS public.domain_event_outbox (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    event_id            UUID NOT NULL REFERENCES public.domain_event_store(id) ON DELETE CASCADE,\r\n    status              TEXT NOT NULL DEFAULT 'pending'\r\n        CHECK (status IN ('pending', 'published', 'failed')),\r\n    attempts            INTEGER NOT NULL DEFAULT 0,\r\n    next_attempt_at     TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    published_at        TIMESTAMPTZ,\r\n    last_error          TEXT,\r\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\r\n)","CREATE INDEX IF NOT EXISTS idx_domain_event_outbox_pending\r\n    ON public.domain_event_outbox(status, next_attempt_at)\r\n    WHERE status = 'pending'","COMMENT ON TABLE public.domain_event_outbox IS\r\n    'Transactional outbox for async event dispatch to subscribers and external buses.'","-- ############################################################################\r\n-- PART 3: PUBLISH — idempotent append + outbox enqueue\r\n-- ############################################################################\r\n\r\nCREATE OR REPLACE FUNCTION public.publish_domain_event(\r\n    p_event_type        TEXT,\r\n    p_payload           JSONB,\r\n    p_actor_id          UUID,\r\n    p_organization_id   UUID DEFAULT NULL,\r\n    p_program_id        UUID DEFAULT NULL,\r\n    p_correlation_id    UUID DEFAULT NULL,\r\n    p_causation_id      UUID DEFAULT NULL,\r\n    p_idempotency_key   TEXT DEFAULT NULL,\r\n    p_event_version     INTEGER DEFAULT 1,\r\n    p_metadata          JSONB DEFAULT '{}'::jsonb\r\n)\r\nRETURNS JSONB\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n    v_existing_id UUID;\r\n    v_event_id UUID;\r\n    v_outbox_id UUID;\r\nBEGIN\r\n    IF p_idempotency_key IS NOT NULL AND length(trim(p_idempotency_key)) > 0 THEN\r\n        SELECT id INTO v_existing_id\r\n        FROM public.domain_event_store\r\n        WHERE idempotency_key = p_idempotency_key;\r\n\r\n        IF v_existing_id IS NOT NULL THEN\r\n            RETURN jsonb_build_object(\r\n                'event_id', v_existing_id,\r\n                'duplicate', true,\r\n                'outbox_id', NULL\r\n            );\r\n        END IF;\r\n    END IF;\r\n\r\n    INSERT INTO public.domain_event_store (\r\n        event_type, event_version, actor_id, organization_id, program_id,\r\n        correlation_id, causation_id, idempotency_key, payload, metadata\r\n    ) VALUES (\r\n        p_event_type, COALESCE(p_event_version, 1), p_actor_id,\r\n        p_organization_id, p_program_id, p_correlation_id, p_causation_id,\r\n        NULLIF(trim(p_idempotency_key), ''), COALESCE(p_payload, '{}'::jsonb),\r\n        COALESCE(p_metadata, '{}'::jsonb)\r\n    )\r\n    RETURNING id INTO v_event_id;\r\n\r\n    INSERT INTO public.domain_event_outbox (event_id, status)\r\n    VALUES (v_event_id, 'pending')\r\n    RETURNING id INTO v_outbox_id;\r\n\r\n    RETURN jsonb_build_object(\r\n        'event_id', v_event_id,\r\n        'duplicate', false,\r\n        'outbox_id', v_outbox_id\r\n    );\r\nEXCEPTION\r\n    WHEN unique_violation THEN\r\n        SELECT id INTO v_existing_id\r\n        FROM public.domain_event_store\r\n        WHERE idempotency_key = p_idempotency_key;\r\n\r\n        RETURN jsonb_build_object(\r\n            'event_id', v_existing_id,\r\n            'duplicate', true,\r\n            'outbox_id', NULL\r\n        );\r\nEND;\r\n$$","COMMENT ON FUNCTION public.publish_domain_event IS\r\n    'Idempotent domain event publish: appends to event store and enqueues outbox row.'","-- ############################################################################\r\n-- PART 4: OUTBOX PROCESSOR (mark published — handlers run in application layer)\r\n-- ############################################################################\r\n\r\nCREATE OR REPLACE FUNCTION public.process_domain_event_outbox(\r\n    p_batch_size INTEGER DEFAULT 50\r\n)\r\nRETURNS JSONB\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n    v_processed INTEGER := 0;\r\n    v_row RECORD;\r\nBEGIN\r\n    FOR v_row IN\r\n        SELECT o.id AS outbox_id, o.event_id, s.event_type, s.payload, s.actor_id,\r\n               s.organization_id, s.program_id, s.correlation_id, s.event_version\r\n        FROM public.domain_event_outbox o\r\n        JOIN public.domain_event_store s ON s.id = o.event_id\r\n        WHERE o.status = 'pending'\r\n          AND o.next_attempt_at <= now()\r\n        ORDER BY o.created_at ASC\r\n        LIMIT GREATEST(p_batch_size, 1)\r\n        FOR UPDATE OF o SKIP LOCKED\r\n    LOOP\r\n        UPDATE public.domain_event_outbox\r\n        SET status = 'published',\r\n            published_at = now(),\r\n            attempts = attempts + 1\r\n        WHERE id = v_row.outbox_id;\r\n\r\n        v_processed := v_processed + 1;\r\n    END LOOP;\r\n\r\n    RETURN jsonb_build_object('processed', v_processed);\r\nEND;\r\n$$","-- ############################################################################\r\n-- PART 5: REPLAY\r\n-- ############################################################################\r\n\r\nCREATE OR REPLACE FUNCTION public.replay_domain_events(\r\n    p_from            TIMESTAMPTZ,\r\n    p_to              TIMESTAMPTZ DEFAULT NULL,\r\n    p_event_types     TEXT[] DEFAULT NULL,\r\n    p_correlation_id  UUID DEFAULT NULL,\r\n    p_limit           INTEGER DEFAULT 500\r\n)\r\nRETURNS SETOF public.domain_event_store\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n    SELECT *\r\n    FROM public.domain_event_store\r\n    WHERE occurred_at >= p_from\r\n      AND (p_to IS NULL OR occurred_at <= p_to)\r\n      AND (p_event_types IS NULL OR event_type = ANY(p_event_types))\r\n      AND (p_correlation_id IS NULL OR correlation_id = p_correlation_id)\r\n    ORDER BY occurred_at ASC, recorded_at ASC\r\n    LIMIT GREATEST(p_limit, 1);\r\n$$","-- ############################################################################\r\n-- PART 6: APPEND-ONLY ENFORCEMENT\r\n-- ############################################################################\r\n\r\nSELECT public.apply_append_only_triggers('public.domain_event_store'::regclass)","REVOKE UPDATE, DELETE ON public.domain_event_store FROM anon, authenticated","-- Outbox rows: allow status updates (not append-only — delivery state machine)\r\nGRANT SELECT, INSERT, UPDATE ON public.domain_event_outbox TO service_role","GRANT SELECT ON public.domain_event_store TO authenticated, service_role","GRANT INSERT ON public.domain_event_store TO service_role","-- ############################################################################\r\n-- PART 7: RLS\r\n-- ############################################################################\r\n\r\nALTER TABLE public.domain_event_store ENABLE ROW LEVEL SECURITY","ALTER TABLE public.domain_event_outbox ENABLE ROW LEVEL SECURITY","CREATE POLICY domain_event_store_select ON public.domain_event_store\r\n    FOR SELECT\r\n    USING (\r\n        auth.role() = 'service_role'\r\n        OR organization_id IS NULL\r\n        OR organization_id IN (\r\n            SELECT organization_id FROM public.user_organizations\r\n            WHERE user_id = auth.uid()\r\n        )\r\n    )","CREATE POLICY domain_event_store_insert ON public.domain_event_store\r\n    FOR INSERT\r\n    WITH CHECK (auth.role() = 'service_role')","CREATE POLICY domain_event_outbox_service ON public.domain_event_outbox\r\n    FOR ALL\r\n    USING (auth.role() = 'service_role')\r\n    WITH CHECK (auth.role() = 'service_role')","GRANT EXECUTE ON FUNCTION public.publish_domain_event TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.process_domain_event_outbox TO service_role","GRANT EXECUTE ON FUNCTION public.replay_domain_events TO service_role","-- ############################################################################\r\n-- PART 8: VERIFY\r\n-- ############################################################################\r\n\r\nDO $$\r\nBEGIN\r\n    IF NOT EXISTS (\r\n        SELECT 1 FROM information_schema.tables\r\n        WHERE table_schema = 'public' AND table_name = 'domain_event_store'\r\n    ) THEN\r\n        RAISE EXCEPTION 'domain_event_store table missing';\r\n    END IF;\r\n\r\n    IF NOT EXISTS (\r\n        SELECT 1 FROM pg_proc WHERE proname = 'publish_domain_event'\r\n    ) THEN\r\n        RAISE EXCEPTION 'publish_domain_event function missing';\r\n    END IF;\r\n\r\n    RAISE NOTICE 'Sprint 4 domain events runtime: store + outbox + publish RPC ready';\r\nEND;\r\n$$","-- ============================================================================\r\n-- END OF MIGRATION 036\r\n-- ============================================================================"}	domain_events_runtime
042	{"-- ============================================================================\r\n-- KADARN PLATFORM — Sprint 15: Continuity Engine\r\n-- ============================================================================\r\n-- Domain: Site Continuity Profile, Site Passport, Experience Ledger,\r\n--         performance timeline, and evidence-backed site reputation.\r\n-- Design: ADR-024 — Continuity Engine: Site Continuity Profile\r\n-- Depends on: organizations, programs, audit_events, provenance_evidence,\r\n--             domain_event_store, trust_events, policy foundation.\r\n--\r\n-- Continuity stores organization-scoped projections and claims. It does not\r\n-- replace Trust, Provenance, Audit, Policy, or operational source tables.\r\n-- ============================================================================\r\n\r\n-- ############################################################################\r\n-- PART 1: ENUMS\r\n-- ############################################################################\r\n\r\nDO $$ BEGIN\r\n    CREATE TYPE public.continuity_profile_status AS ENUM (\r\n        'draft',\r\n        'active',\r\n        'suspended',\r\n        'archived'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE public.continuity_source_type AS ENUM (\r\n        'self_reported',\r\n        'document_backed',\r\n        'event_derived',\r\n        'sponsor_confirmed',\r\n        'kadarn_verified'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE public.continuity_verification_status AS ENUM (\r\n        'unverified',\r\n        'pending',\r\n        'evidence_backed',\r\n        'verified',\r\n        'rejected'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE public.continuity_visibility AS ENUM (\r\n        'private',\r\n        'shared_link',\r\n        'public'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE public.continuity_experience_category AS ENUM (\r\n        'therapeutic_area',\r\n        'phase_experience',\r\n        'biospecimen_type',\r\n        'processing_type',\r\n        'patient_population',\r\n        'equipment_infrastructure',\r\n        'regulatory_compliance',\r\n        'logistics_shipping',\r\n        'ivd_validation',\r\n        'pharma_study',\r\n        'biotech_program'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE public.continuity_relationship_type AS ENUM (\r\n        'sponsor',\r\n        'cro',\r\n        'lab',\r\n        'biobank',\r\n        'site_network',\r\n        'vendor',\r\n        'academic_partner',\r\n        'other'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE public.continuity_timeline_event_type AS ENUM (\r\n        'site_onboarded',\r\n        'study_completed',\r\n        'capability_added',\r\n        'certification_added',\r\n        'audit_completed',\r\n        'biospecimen_workflow_completed',\r\n        'sponsor_relationship_added',\r\n        'trust_score_changed',\r\n        'quality_event_closed',\r\n        'new_equipment_added',\r\n        'new_therapeutic_experience_added'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE public.continuity_evidence_type AS ENUM (\r\n        'document',\r\n        'audit_event',\r\n        'domain_event',\r\n        'provenance_evidence',\r\n        'workflow_record',\r\n        'quality_record',\r\n        'sponsor_confirmation',\r\n        'trust_event',\r\n        'external_reference'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","-- ############################################################################\r\n-- PART 2: UPDATED_AT HELPER\r\n-- ############################################################################\r\n\r\nCREATE OR REPLACE FUNCTION public.set_continuity_updated_at()\r\nRETURNS TRIGGER\r\nLANGUAGE plpgsql\r\nAS $$\r\nBEGIN\r\n    NEW.updated_at = now();\r\n    RETURN NEW;\r\nEND;\r\n$$","-- ############################################################################\r\n-- PART 3: SITE CONTINUITY PROFILE\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS public.site_continuity_profiles (\r\n    id                         UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    organization_id            UUID NOT NULL UNIQUE REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n\r\n    status                     public.continuity_profile_status NOT NULL DEFAULT 'draft',\r\n    site_type                  TEXT NOT NULL DEFAULT 'clinical_site',\r\n    headline                   TEXT,\r\n    summary                    TEXT,\r\n    geography                  JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n    patient_population_summary JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n    availability_preferences   JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n\r\n    completeness_score         NUMERIC(5,2) NOT NULL DEFAULT 0.00\r\n        CHECK (completeness_score BETWEEN 0.00 AND 100.00),\r\n    maturity_level             TEXT NOT NULL DEFAULT 'foundational',\r\n    verification_status        public.continuity_verification_status NOT NULL DEFAULT 'unverified',\r\n\r\n    passport_visibility        public.continuity_visibility NOT NULL DEFAULT 'private',\r\n    passport_published_at      TIMESTAMPTZ,\r\n    public_slug                TEXT UNIQUE,\r\n\r\n    source_type                public.continuity_source_type NOT NULL DEFAULT 'self_reported',\r\n    created_by                 UUID REFERENCES auth.users(id),\r\n    updated_by                 UUID REFERENCES auth.users(id),\r\n    created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    CONSTRAINT site_continuity_profiles_public_slug_format\r\n        CHECK (public_slug IS NULL OR public_slug ~ '^[a-z0-9][a-z0-9-]{2,120}$')\r\n)","COMMENT ON TABLE public.site_continuity_profiles IS\r\n    'Organization-scoped Continuity profile projection. No PHI or donor-level data is allowed.'","CREATE INDEX IF NOT EXISTS idx_site_continuity_profiles_org\r\n    ON public.site_continuity_profiles(organization_id)","CREATE INDEX IF NOT EXISTS idx_site_continuity_profiles_status\r\n    ON public.site_continuity_profiles(status)","CREATE INDEX IF NOT EXISTS idx_site_continuity_profiles_visibility\r\n    ON public.site_continuity_profiles(passport_visibility)","DROP TRIGGER IF EXISTS trg_site_continuity_profiles_updated_at ON public.site_continuity_profiles","CREATE TRIGGER trg_site_continuity_profiles_updated_at\r\n    BEFORE UPDATE ON public.site_continuity_profiles\r\n    FOR EACH ROW\r\n    EXECUTE FUNCTION public.set_continuity_updated_at()","-- ############################################################################\r\n-- PART 4: EXPERIENCE LEDGER\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS public.continuity_experience_ledger (\r\n    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    organization_id       UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n    profile_id            UUID NOT NULL REFERENCES public.site_continuity_profiles(id) ON DELETE CASCADE,\r\n    program_id            UUID REFERENCES public.programs(id) ON DELETE SET NULL,\r\n\r\n    category              public.continuity_experience_category NOT NULL,\r\n    experience_key        TEXT NOT NULL,\r\n    experience_label      TEXT NOT NULL,\r\n    experience_summary    TEXT,\r\n    years_experience      NUMERIC(5,2),\r\n    occurrence_count      INTEGER NOT NULL DEFAULT 1 CHECK (occurrence_count >= 0),\r\n    started_at            DATE,\r\n    ended_at              DATE,\r\n\r\n    source_type           public.continuity_source_type NOT NULL,\r\n    verification_status   public.continuity_verification_status NOT NULL DEFAULT 'unverified',\r\n    visibility            public.continuity_visibility NOT NULL DEFAULT 'private',\r\n    confidence_score      NUMERIC(5,2) NOT NULL DEFAULT 0.00\r\n        CHECK (confidence_score BETWEEN 0.00 AND 100.00),\r\n\r\n    sponsor_name_policy   TEXT NOT NULL DEFAULT 'private'\r\n        CHECK (sponsor_name_policy IN ('private', 'masked', 'permissioned', 'public')),\r\n    metadata              JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n    created_by            UUID REFERENCES auth.users(id),\r\n    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    CONSTRAINT continuity_experience_ledger_dates\r\n        CHECK (ended_at IS NULL OR started_at IS NULL OR ended_at >= started_at)\r\n)","COMMENT ON TABLE public.continuity_experience_ledger IS\r\n    'Append-only ledger of site-earned experience. Stores claims and references, not PHI.'","CREATE INDEX IF NOT EXISTS idx_continuity_experience_org\r\n    ON public.continuity_experience_ledger(organization_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_experience_profile\r\n    ON public.continuity_experience_ledger(profile_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_experience_category\r\n    ON public.continuity_experience_ledger(category, experience_key)","-- ############################################################################\r\n-- PART 5: RELATIONSHIPS\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS public.continuity_relationships (\r\n    id                       UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    organization_id          UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n    profile_id               UUID NOT NULL REFERENCES public.site_continuity_profiles(id) ON DELETE CASCADE,\r\n    counterparty_org_id      UUID REFERENCES public.organizations(id) ON DELETE SET NULL,\r\n    program_id               UUID REFERENCES public.programs(id) ON DELETE SET NULL,\r\n\r\n    relationship_type        public.continuity_relationship_type NOT NULL,\r\n    relationship_label       TEXT NOT NULL,\r\n    counterparty_display_name TEXT,\r\n    counterparty_masked_name TEXT,\r\n    sponsor_name_policy      TEXT NOT NULL DEFAULT 'private'\r\n        CHECK (sponsor_name_policy IN ('private', 'masked', 'permissioned', 'public')),\r\n    started_at               DATE,\r\n    ended_at                 DATE,\r\n    is_active                BOOLEAN NOT NULL DEFAULT true,\r\n\r\n    source_type              public.continuity_source_type NOT NULL,\r\n    verification_status      public.continuity_verification_status NOT NULL DEFAULT 'unverified',\r\n    visibility               public.continuity_visibility NOT NULL DEFAULT 'private',\r\n    metadata                 JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n    created_by               UUID REFERENCES auth.users(id),\r\n    updated_by               UUID REFERENCES auth.users(id),\r\n    created_at               TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at               TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    CONSTRAINT continuity_relationships_dates\r\n        CHECK (ended_at IS NULL OR started_at IS NULL OR ended_at >= started_at)\r\n)","CREATE INDEX IF NOT EXISTS idx_continuity_relationships_org\r\n    ON public.continuity_relationships(organization_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_relationships_profile\r\n    ON public.continuity_relationships(profile_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_relationships_type\r\n    ON public.continuity_relationships(relationship_type)","DROP TRIGGER IF EXISTS trg_continuity_relationships_updated_at ON public.continuity_relationships","CREATE TRIGGER trg_continuity_relationships_updated_at\r\n    BEFORE UPDATE ON public.continuity_relationships\r\n    FOR EACH ROW\r\n    EXECUTE FUNCTION public.set_continuity_updated_at()","-- ############################################################################\r\n-- PART 6: CAPABILITIES\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS public.continuity_capabilities (\r\n    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    organization_id       UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n    profile_id            UUID NOT NULL REFERENCES public.site_continuity_profiles(id) ON DELETE CASCADE,\r\n    organization_capability_id UUID REFERENCES public.organization_capabilities(id) ON DELETE SET NULL,\r\n\r\n    capability_category   TEXT NOT NULL,\r\n    capability_key        TEXT NOT NULL,\r\n    capability_label      TEXT NOT NULL,\r\n    capability_summary    TEXT,\r\n    capacity              JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n    constraints           JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n    availability          JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n\r\n    source_type           public.continuity_source_type NOT NULL,\r\n    verification_status   public.continuity_verification_status NOT NULL DEFAULT 'unverified',\r\n    visibility            public.continuity_visibility NOT NULL DEFAULT 'private',\r\n    metadata              JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n    created_by            UUID REFERENCES auth.users(id),\r\n    updated_by            UUID REFERENCES auth.users(id),\r\n    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    CONSTRAINT continuity_capabilities_unique_key\r\n        UNIQUE (organization_id, capability_category, capability_key)\r\n)","CREATE INDEX IF NOT EXISTS idx_continuity_capabilities_org\r\n    ON public.continuity_capabilities(organization_id, capability_category)","CREATE INDEX IF NOT EXISTS idx_continuity_capabilities_profile\r\n    ON public.continuity_capabilities(profile_id)","CREATE INDEX IF NOT EXISTS idx_continuity_capabilities_verification\r\n    ON public.continuity_capabilities(verification_status)","DROP TRIGGER IF EXISTS trg_continuity_capabilities_updated_at ON public.continuity_capabilities","CREATE TRIGGER trg_continuity_capabilities_updated_at\r\n    BEFORE UPDATE ON public.continuity_capabilities\r\n    FOR EACH ROW\r\n    EXECUTE FUNCTION public.set_continuity_updated_at()","-- ############################################################################\r\n-- PART 7: PERFORMANCE METRICS\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS public.continuity_performance_metrics (\r\n    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    organization_id       UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n    profile_id            UUID NOT NULL REFERENCES public.site_continuity_profiles(id) ON DELETE CASCADE,\r\n    program_id            UUID REFERENCES public.programs(id) ON DELETE SET NULL,\r\n\r\n    metric_category       TEXT NOT NULL,\r\n    metric_key            TEXT NOT NULL,\r\n    metric_label          TEXT NOT NULL,\r\n    metric_value          NUMERIC(18,6),\r\n    metric_unit           TEXT,\r\n    metric_period_start   DATE,\r\n    metric_period_end     DATE,\r\n    sample_size           INTEGER CHECK (sample_size IS NULL OR sample_size >= 0),\r\n\r\n    source_type           public.continuity_source_type NOT NULL,\r\n    verification_status   public.continuity_verification_status NOT NULL DEFAULT 'unverified',\r\n    evidence_weight       NUMERIC(5,2) NOT NULL DEFAULT 0.00\r\n        CHECK (evidence_weight BETWEEN 0.00 AND 100.00),\r\n    visibility            public.continuity_visibility NOT NULL DEFAULT 'private',\r\n    metadata              JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n    created_by            UUID REFERENCES auth.users(id),\r\n    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    CONSTRAINT continuity_performance_metric_period\r\n        CHECK (metric_period_end IS NULL OR metric_period_start IS NULL OR metric_period_end >= metric_period_start)\r\n)","COMMENT ON TABLE public.continuity_performance_metrics IS\r\n    'Append-only performance metric records. Evidence-backed metrics rank above self-reported metrics.'","CREATE INDEX IF NOT EXISTS idx_continuity_metrics_org\r\n    ON public.continuity_performance_metrics(organization_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_metrics_profile\r\n    ON public.continuity_performance_metrics(profile_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_metrics_key\r\n    ON public.continuity_performance_metrics(metric_category, metric_key)","-- ############################################################################\r\n-- PART 8: TIMELINE EVENTS\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS public.continuity_timeline_events (\r\n    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    organization_id       UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n    profile_id            UUID NOT NULL REFERENCES public.site_continuity_profiles(id) ON DELETE CASCADE,\r\n    program_id            UUID REFERENCES public.programs(id) ON DELETE SET NULL,\r\n\r\n    event_type            public.continuity_timeline_event_type NOT NULL,\r\n    title                 TEXT NOT NULL,\r\n    summary               TEXT,\r\n    occurred_at           TIMESTAMPTZ NOT NULL,\r\n\r\n    source_type           public.continuity_source_type NOT NULL,\r\n    verification_status   public.continuity_verification_status NOT NULL DEFAULT 'unverified',\r\n    visibility            public.continuity_visibility NOT NULL DEFAULT 'private',\r\n    metadata              JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n    created_by            UUID REFERENCES auth.users(id),\r\n    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()\r\n)","COMMENT ON TABLE public.continuity_timeline_events IS\r\n    'Append-only living history of site continuity events.'","CREATE INDEX IF NOT EXISTS idx_continuity_timeline_org\r\n    ON public.continuity_timeline_events(organization_id, occurred_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_timeline_profile\r\n    ON public.continuity_timeline_events(profile_id, occurred_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_timeline_type\r\n    ON public.continuity_timeline_events(event_type)","-- ############################################################################\r\n-- PART 9: EVIDENCE LINKS\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS public.continuity_evidence_links (\r\n    id                     UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    organization_id        UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n    profile_id             UUID NOT NULL REFERENCES public.site_continuity_profiles(id) ON DELETE CASCADE,\r\n\r\n    claim_table            TEXT NOT NULL CHECK (claim_table IN (\r\n        'site_continuity_profiles',\r\n        'continuity_experience_ledger',\r\n        'continuity_relationships',\r\n        'continuity_capabilities',\r\n        'continuity_performance_metrics',\r\n        'continuity_timeline_events'\r\n    )),\r\n    claim_id               UUID NOT NULL,\r\n\r\n    evidence_type          public.continuity_evidence_type NOT NULL,\r\n    provenance_evidence_id UUID REFERENCES public.provenance_evidence(id) ON DELETE SET NULL,\r\n    audit_event_id         UUID REFERENCES public.audit_events(id) ON DELETE SET NULL,\r\n    domain_event_id        UUID REFERENCES public.domain_event_store(id) ON DELETE SET NULL,\r\n    trust_event_id         UUID REFERENCES public.trust_events(id) ON DELETE SET NULL,\r\n    source_table           TEXT,\r\n    source_id              UUID,\r\n    external_ref           TEXT,\r\n    evidence_hash          TEXT,\r\n    evidence_summary       TEXT,\r\n\r\n    verification_status    public.continuity_verification_status NOT NULL DEFAULT 'pending',\r\n    visibility             public.continuity_visibility NOT NULL DEFAULT 'private',\r\n    metadata               JSONB NOT NULL DEFAULT '{}'::jsonb,\r\n    created_by             UUID REFERENCES auth.users(id),\r\n    updated_by             UUID REFERENCES auth.users(id),\r\n    created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at             TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    CONSTRAINT continuity_evidence_has_reference CHECK (\r\n        provenance_evidence_id IS NOT NULL\r\n        OR audit_event_id IS NOT NULL\r\n        OR domain_event_id IS NOT NULL\r\n        OR trust_event_id IS NOT NULL\r\n        OR source_id IS NOT NULL\r\n        OR external_ref IS NOT NULL\r\n        OR evidence_hash IS NOT NULL\r\n    )\r\n)","COMMENT ON TABLE public.continuity_evidence_links IS\r\n    'Evidence references for Continuity claims. Links to provenance, audit, domain events, trust events, or external evidence without storing PHI.'","CREATE INDEX IF NOT EXISTS idx_continuity_evidence_org\r\n    ON public.continuity_evidence_links(organization_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_evidence_profile\r\n    ON public.continuity_evidence_links(profile_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_evidence_claim\r\n    ON public.continuity_evidence_links(claim_table, claim_id)","CREATE INDEX IF NOT EXISTS idx_continuity_evidence_domain_event\r\n    ON public.continuity_evidence_links(domain_event_id)\r\n    WHERE domain_event_id IS NOT NULL","CREATE INDEX IF NOT EXISTS idx_continuity_evidence_provenance\r\n    ON public.continuity_evidence_links(provenance_evidence_id)\r\n    WHERE provenance_evidence_id IS NOT NULL","DROP TRIGGER IF EXISTS trg_continuity_evidence_links_updated_at ON public.continuity_evidence_links","CREATE TRIGGER trg_continuity_evidence_links_updated_at\r\n    BEFORE UPDATE ON public.continuity_evidence_links\r\n    FOR EACH ROW\r\n    EXECUTE FUNCTION public.set_continuity_updated_at()","-- ############################################################################\r\n-- PART 10: APPEND-ONLY CLAIM HISTORY\r\n-- ############################################################################\r\n\r\nSELECT public.apply_append_only_triggers('public.continuity_experience_ledger'::regclass)","SELECT public.apply_append_only_triggers('public.continuity_performance_metrics'::regclass)","SELECT public.apply_append_only_triggers('public.continuity_timeline_events'::regclass)","-- ############################################################################\r\n-- PART 11: ROW-LEVEL SECURITY\r\n-- ############################################################################\r\n\r\nALTER TABLE public.site_continuity_profiles ENABLE ROW LEVEL SECURITY","ALTER TABLE public.continuity_experience_ledger ENABLE ROW LEVEL SECURITY","ALTER TABLE public.continuity_relationships ENABLE ROW LEVEL SECURITY","ALTER TABLE public.continuity_capabilities ENABLE ROW LEVEL SECURITY","ALTER TABLE public.continuity_performance_metrics ENABLE ROW LEVEL SECURITY","ALTER TABLE public.continuity_timeline_events ENABLE ROW LEVEL SECURITY","ALTER TABLE public.continuity_evidence_links ENABLE ROW LEVEL SECURITY","CREATE OR REPLACE FUNCTION public.can_manage_continuity(p_organization_id UUID)\r\nRETURNS BOOLEAN\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n    SELECT auth.role() = 'service_role'\r\n        OR EXISTS (\r\n            SELECT 1\r\n            FROM public.user_organizations uo\r\n            WHERE uo.user_id = auth.uid()\r\n              AND uo.organization_id = p_organization_id\r\n              AND uo.role IN ('org_admin', 'platform_admin', 'data_steward')\r\n        );\r\n$$","CREATE OR REPLACE FUNCTION public.can_view_continuity(p_organization_id UUID)\r\nRETURNS BOOLEAN\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n    SELECT auth.role() = 'service_role'\r\n        OR EXISTS (\r\n            SELECT 1\r\n            FROM public.user_organizations uo\r\n            WHERE uo.user_id = auth.uid()\r\n              AND uo.organization_id = p_organization_id\r\n        );\r\n$$","CREATE POLICY site_continuity_profiles_select ON public.site_continuity_profiles\r\n    FOR SELECT USING (public.can_view_continuity(organization_id))","CREATE POLICY site_continuity_profiles_insert ON public.site_continuity_profiles\r\n    FOR INSERT WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY site_continuity_profiles_update ON public.site_continuity_profiles\r\n    FOR UPDATE USING (public.can_manage_continuity(organization_id))\r\n    WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_experience_select ON public.continuity_experience_ledger\r\n    FOR SELECT USING (public.can_view_continuity(organization_id))","CREATE POLICY continuity_experience_insert ON public.continuity_experience_ledger\r\n    FOR INSERT WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_relationships_select ON public.continuity_relationships\r\n    FOR SELECT USING (public.can_view_continuity(organization_id))","CREATE POLICY continuity_relationships_insert ON public.continuity_relationships\r\n    FOR INSERT WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_relationships_update ON public.continuity_relationships\r\n    FOR UPDATE USING (public.can_manage_continuity(organization_id))\r\n    WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_capabilities_select ON public.continuity_capabilities\r\n    FOR SELECT USING (public.can_view_continuity(organization_id))","CREATE POLICY continuity_capabilities_insert ON public.continuity_capabilities\r\n    FOR INSERT WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_capabilities_update ON public.continuity_capabilities\r\n    FOR UPDATE USING (public.can_manage_continuity(organization_id))\r\n    WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_metrics_select ON public.continuity_performance_metrics\r\n    FOR SELECT USING (public.can_view_continuity(organization_id))","CREATE POLICY continuity_metrics_insert ON public.continuity_performance_metrics\r\n    FOR INSERT WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_timeline_select ON public.continuity_timeline_events\r\n    FOR SELECT USING (public.can_view_continuity(organization_id))","CREATE POLICY continuity_timeline_insert ON public.continuity_timeline_events\r\n    FOR INSERT WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_evidence_select ON public.continuity_evidence_links\r\n    FOR SELECT USING (public.can_view_continuity(organization_id))","CREATE POLICY continuity_evidence_insert ON public.continuity_evidence_links\r\n    FOR INSERT WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_evidence_update ON public.continuity_evidence_links\r\n    FOR UPDATE USING (public.can_manage_continuity(organization_id))\r\n    WITH CHECK (public.can_manage_continuity(organization_id))","GRANT SELECT ON public.site_continuity_profiles TO authenticated, service_role","GRANT SELECT ON public.continuity_experience_ledger TO authenticated, service_role","GRANT SELECT ON public.continuity_relationships TO authenticated, service_role","GRANT SELECT ON public.continuity_capabilities TO authenticated, service_role","GRANT SELECT ON public.continuity_performance_metrics TO authenticated, service_role","GRANT SELECT ON public.continuity_timeline_events TO authenticated, service_role","GRANT SELECT ON public.continuity_evidence_links TO authenticated, service_role","GRANT INSERT, UPDATE ON public.site_continuity_profiles TO authenticated, service_role","GRANT INSERT ON public.continuity_experience_ledger TO authenticated, service_role","GRANT INSERT, UPDATE ON public.continuity_relationships TO authenticated, service_role","GRANT INSERT, UPDATE ON public.continuity_capabilities TO authenticated, service_role","GRANT INSERT ON public.continuity_performance_metrics TO authenticated, service_role","GRANT INSERT ON public.continuity_timeline_events TO authenticated, service_role","GRANT INSERT, UPDATE ON public.continuity_evidence_links TO authenticated, service_role","-- ############################################################################\r\n-- PART 12: VERIFY\r\n-- ############################################################################\r\n\r\nDO $$\r\nBEGIN\r\n    IF NOT EXISTS (\r\n        SELECT 1 FROM information_schema.tables\r\n        WHERE table_schema = 'public'\r\n          AND table_name = 'site_continuity_profiles'\r\n    ) THEN\r\n        RAISE EXCEPTION 'Continuity Engine migration failed: site_continuity_profiles missing';\r\n    END IF;\r\n\r\n    IF NOT EXISTS (\r\n        SELECT 1 FROM information_schema.tables\r\n        WHERE table_schema = 'public'\r\n          AND table_name = 'continuity_evidence_links'\r\n    ) THEN\r\n        RAISE EXCEPTION 'Continuity Engine migration failed: continuity_evidence_links missing';\r\n    END IF;\r\nEND $$"}	continuity_engine
043	{"-- ============================================================================\r\n-- KADARN PLATFORM — Continuity Legacy Experience Claims\r\n-- ============================================================================\r\n-- Domain: Manual legacy experience onboarding, evidence submission, and\r\n--         external reference validation for Site Continuity Profiles.\r\n-- Design: ADR-024 — Continuity Engine, extended with legacy validation.\r\n-- Depends on: 042_continuity_engine.sql\r\n-- ============================================================================\r\n\r\nDO $$ BEGIN\r\n    CREATE TYPE public.continuity_claim_verification_status AS ENUM (\r\n        'self_reported',\r\n        'evidence_submitted',\r\n        'reference_pending',\r\n        'reference_confirmed',\r\n        'kadarn_verified',\r\n        'rejected',\r\n        'expired'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE public.continuity_evidence_review_status AS ENUM (\r\n        'submitted',\r\n        'under_review',\r\n        'accepted',\r\n        'rejected'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE public.continuity_reference_status AS ENUM (\r\n        'pending',\r\n        'requested',\r\n        'confirmed',\r\n        'declined',\r\n        'expired'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","CREATE TABLE IF NOT EXISTS public.continuity_experience_claims (\r\n    id                          UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    organization_id             UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n    site_continuity_profile_id  UUID NOT NULL REFERENCES public.site_continuity_profiles(id) ON DELETE CASCADE,\r\n\r\n    claim_type                  TEXT NOT NULL,\r\n    category                    TEXT NOT NULL,\r\n    title                       TEXT NOT NULL,\r\n    description                 TEXT,\r\n    experience_source           TEXT NOT NULL DEFAULT 'legacy'\r\n        CHECK (experience_source IN ('legacy', 'native')),\r\n    therapeutic_area            TEXT,\r\n    study_phase                 TEXT,\r\n    biospecimen_type            TEXT,\r\n    start_date                  DATE,\r\n    end_date                    DATE,\r\n    quantity                    NUMERIC,\r\n\r\n    verification_status         public.continuity_claim_verification_status NOT NULL DEFAULT 'self_reported',\r\n    confidence_score            INTEGER NOT NULL DEFAULT 25\r\n        CHECK (confidence_score BETWEEN 0 AND 100),\r\n    is_public                   BOOLEAN NOT NULL DEFAULT false,\r\n    sponsor_name_policy         TEXT NOT NULL DEFAULT 'masked'\r\n        CHECK (sponsor_name_policy IN ('private', 'masked', 'permissioned', 'public')),\r\n    masked_sponsor_label        TEXT\r\n        CHECK (\r\n            masked_sponsor_label IS NULL OR masked_sponsor_label IN (\r\n                'Global pharma sponsor',\r\n                'Top 10 CRO',\r\n                'IVD company',\r\n                'Academic medical center',\r\n                'Specialty lab'\r\n            )\r\n        ),\r\n\r\n    created_by                  UUID REFERENCES auth.users(id),\r\n    updated_by                  UUID REFERENCES auth.users(id),\r\n    created_at                  TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at                  TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    CONSTRAINT continuity_claim_dates\r\n        CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date),\r\n    CONSTRAINT continuity_claim_public_requires_safe_sponsor_policy\r\n        CHECK (is_public = false OR sponsor_name_policy IN ('masked', 'permissioned', 'public'))\r\n)","COMMENT ON TABLE public.continuity_experience_claims IS\r\n    'Editable legacy/native experience claims for Site Continuity onboarding. Do not store PHI, donor-level data, or protocol-sensitive confidential data.'","CREATE INDEX IF NOT EXISTS idx_continuity_claims_org\r\n    ON public.continuity_experience_claims(organization_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_claims_profile\r\n    ON public.continuity_experience_claims(site_continuity_profile_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_claims_public\r\n    ON public.continuity_experience_claims(is_public, verification_status, confidence_score DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_claims_category\r\n    ON public.continuity_experience_claims(category, claim_type)","DROP TRIGGER IF EXISTS trg_continuity_experience_claims_updated_at ON public.continuity_experience_claims","CREATE TRIGGER trg_continuity_experience_claims_updated_at\r\n    BEFORE UPDATE ON public.continuity_experience_claims\r\n    FOR EACH ROW\r\n    EXECUTE FUNCTION public.set_continuity_updated_at()","CREATE TABLE IF NOT EXISTS public.continuity_evidence_items (\r\n    id                          UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    organization_id             UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n    claim_id                    UUID NOT NULL REFERENCES public.continuity_experience_claims(id) ON DELETE CASCADE,\r\n    continuity_evidence_link_id UUID REFERENCES public.continuity_evidence_links(id) ON DELETE SET NULL,\r\n\r\n    evidence_type               TEXT NOT NULL,\r\n    title                       TEXT NOT NULL,\r\n    description                 TEXT,\r\n    file_url                    TEXT,\r\n    external_url                TEXT,\r\n    document_id                 UUID,\r\n    verification_status         public.continuity_evidence_review_status NOT NULL DEFAULT 'submitted',\r\n    reviewed_by                 UUID REFERENCES auth.users(id),\r\n    reviewed_at                 TIMESTAMPTZ,\r\n    created_at                  TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    CONSTRAINT continuity_evidence_item_has_location\r\n        CHECK (file_url IS NOT NULL OR external_url IS NOT NULL OR document_id IS NOT NULL)\r\n)","COMMENT ON TABLE public.continuity_evidence_items IS\r\n    'Evidence submitted for continuity claims. Stores references/URLs/document IDs, not PHI.'","CREATE INDEX IF NOT EXISTS idx_continuity_evidence_items_org\r\n    ON public.continuity_evidence_items(organization_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_evidence_items_claim\r\n    ON public.continuity_evidence_items(claim_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_evidence_items_status\r\n    ON public.continuity_evidence_items(verification_status)","CREATE TABLE IF NOT EXISTS public.continuity_references (\r\n    id                       UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    organization_id          UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n    claim_id                 UUID NOT NULL REFERENCES public.continuity_experience_claims(id) ON DELETE CASCADE,\r\n\r\n    reference_type           TEXT NOT NULL,\r\n    reference_name           TEXT NOT NULL,\r\n    reference_organization   TEXT,\r\n    reference_email          TEXT,\r\n    reference_role           TEXT,\r\n    relationship_context     TEXT,\r\n    status                   public.continuity_reference_status NOT NULL DEFAULT 'pending',\r\n    requested_at             TIMESTAMPTZ,\r\n    confirmed_at             TIMESTAMPTZ,\r\n    declined_at              TIMESTAMPTZ,\r\n    notes                    TEXT,\r\n    created_at               TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    CONSTRAINT continuity_reference_email_shape\r\n        CHECK (reference_email IS NULL OR reference_email ~* '^[^@\\\\s]+@[^@\\\\s]+\\\\.[^@\\\\s]+$')\r\n)","COMMENT ON TABLE public.continuity_references IS\r\n    'External references that can validate a continuity claim. Do not store patient or donor information.'","CREATE INDEX IF NOT EXISTS idx_continuity_references_org\r\n    ON public.continuity_references(organization_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_references_claim\r\n    ON public.continuity_references(claim_id, created_at DESC)","CREATE INDEX IF NOT EXISTS idx_continuity_references_status\r\n    ON public.continuity_references(status)","ALTER TABLE public.continuity_experience_claims ENABLE ROW LEVEL SECURITY","ALTER TABLE public.continuity_evidence_items ENABLE ROW LEVEL SECURITY","ALTER TABLE public.continuity_references ENABLE ROW LEVEL SECURITY","CREATE POLICY continuity_claims_select_owner ON public.continuity_experience_claims\r\n    FOR SELECT USING (\r\n        public.can_view_continuity(organization_id)\r\n        OR is_public = true\r\n        OR auth.role() = 'service_role'\r\n    )","CREATE POLICY continuity_claims_insert_owner ON public.continuity_experience_claims\r\n    FOR INSERT WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_claims_update_owner ON public.continuity_experience_claims\r\n    FOR UPDATE USING (public.can_manage_continuity(organization_id))\r\n    WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_evidence_items_select_owner ON public.continuity_evidence_items\r\n    FOR SELECT USING (\r\n        public.can_view_continuity(organization_id)\r\n        OR EXISTS (\r\n            SELECT 1\r\n            FROM public.continuity_experience_claims c\r\n            WHERE c.id = continuity_evidence_items.claim_id\r\n              AND c.is_public = true\r\n        )\r\n        OR auth.role() = 'service_role'\r\n    )","CREATE POLICY continuity_evidence_items_insert_owner ON public.continuity_evidence_items\r\n    FOR INSERT WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_evidence_items_update_reviewer ON public.continuity_evidence_items\r\n    FOR UPDATE USING (public.can_manage_continuity(organization_id))\r\n    WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_references_select_owner ON public.continuity_references\r\n    FOR SELECT USING (\r\n        public.can_view_continuity(organization_id)\r\n        OR EXISTS (\r\n            SELECT 1\r\n            FROM public.continuity_experience_claims c\r\n            WHERE c.id = continuity_references.claim_id\r\n              AND c.is_public = true\r\n        )\r\n        OR auth.role() = 'service_role'\r\n    )","CREATE POLICY continuity_references_insert_owner ON public.continuity_references\r\n    FOR INSERT WITH CHECK (public.can_manage_continuity(organization_id))","CREATE POLICY continuity_references_update_reviewer ON public.continuity_references\r\n    FOR UPDATE USING (public.can_manage_continuity(organization_id))\r\n    WITH CHECK (public.can_manage_continuity(organization_id))","GRANT SELECT ON public.continuity_experience_claims TO anon, authenticated, service_role","GRANT SELECT ON public.continuity_evidence_items TO anon, authenticated, service_role","GRANT SELECT ON public.continuity_references TO anon, authenticated, service_role","GRANT INSERT, UPDATE ON public.continuity_experience_claims TO authenticated, service_role","GRANT INSERT, UPDATE ON public.continuity_evidence_items TO authenticated, service_role","GRANT INSERT, UPDATE ON public.continuity_references TO authenticated, service_role","DO $$\r\nBEGIN\r\n    IF NOT EXISTS (\r\n        SELECT 1 FROM information_schema.tables\r\n        WHERE table_schema = 'public'\r\n          AND table_name = 'continuity_experience_claims'\r\n    ) THEN\r\n        RAISE EXCEPTION 'Legacy experience migration failed: continuity_experience_claims missing';\r\n    END IF;\r\nEND $$"}	legacy_experience_claims
044	{"-- ==========================================================================\r\n-- Kadarn Continuity — Verification Workflow (Sprint 6)\r\n-- ==========================================================================\r\n-- Adds formal review states, badge levels, and ledger promotion to the\r\n-- continuity_experience_claims workflow.\r\n--\r\n-- Key concepts:\r\n--   Claim = what the site declares.\r\n--   Ledger = what Kadarn accepts as durable memory.\r\n--\r\n-- State machine: draft → submitted → under_review → verified | rejected\r\n-- Badge levels:  self_reported → evidence_backed → reference_confirmed → kadarn_verified\r\n-- ==========================================================================\r\n\r\n-- --------------------------------------------------------------------------\r\n-- 1. Badge level enum\r\n-- --------------------------------------------------------------------------\r\nDO $$ BEGIN\r\n    CREATE TYPE continuity_badge_level AS ENUM (\r\n        'self_reported',\r\n        'evidence_backed',\r\n        'reference_confirmed',\r\n        'kadarn_verified'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","-- --------------------------------------------------------------------------\r\n-- 2. Add verification columns to claims table\r\n-- --------------------------------------------------------------------------\r\nALTER TABLE continuity_experience_claims\r\n    ADD COLUMN IF NOT EXISTS badge_level         continuity_badge_level NOT NULL DEFAULT 'self_reported',\r\n    ADD COLUMN IF NOT EXISTS reviewer_id         uuid,\r\n    ADD COLUMN IF NOT EXISTS reviewed_at         timestamptz,\r\n    ADD COLUMN IF NOT EXISTS reviewer_notes      text,\r\n    ADD COLUMN IF NOT EXISTS verification_history jsonb NOT NULL DEFAULT '[]'::jsonb,\r\n    ADD COLUMN IF NOT EXISTS submitted_for_review_at timestamptz,\r\n    ADD COLUMN IF NOT EXISTS promoted_to_ledger_at   timestamptz","COMMENT ON COLUMN continuity_experience_claims.badge_level IS 'Computed badge reflecting verification depth'","COMMENT ON COLUMN continuity_experience_claims.verification_history IS 'Audit trail of status changes [{from, to, by, at, note}]'","COMMENT ON COLUMN continuity_experience_claims.promoted_to_ledger_at IS 'When this claim was copied to the durable ledger'","-- --------------------------------------------------------------------------\r\n-- 3. Verification history audit trigger\r\n-- --------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION continuity_verification_history_trigger()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nAS $$\r\nBEGIN\r\n    IF OLD.verification_status IS DISTINCT FROM NEW.verification_status THEN\r\n        NEW.verification_history = COALESCE(OLD.verification_history, '[]'::jsonb) || jsonb_build_object(\r\n            'from', OLD.verification_status,\r\n            'to',   NEW.verification_status,\r\n            'by',   NEW.reviewer_id,\r\n            'at',   NOW(),\r\n            'note', NEW.reviewer_notes\r\n        );\r\n    END IF;\r\n    RETURN NEW;\r\nEND;\r\n$$","DROP TRIGGER IF EXISTS trg_continuity_verification_history ON continuity_experience_claims","CREATE TRIGGER trg_continuity_verification_history\r\n    BEFORE UPDATE OF verification_status ON continuity_experience_claims\r\n    FOR EACH ROW\r\n    EXECUTE FUNCTION continuity_verification_history_trigger()","-- --------------------------------------------------------------------------\r\n-- 4. Ledger promotion table (mirrors claims that passed verification)\r\n-- --------------------------------------------------------------------------\r\nALTER TABLE continuity_experience_ledger\r\n    ADD COLUMN IF NOT EXISTS source_claim_id      uuid REFERENCES continuity_experience_claims(id),\r\n    ADD COLUMN IF NOT EXISTS badge_level           continuity_badge_level NOT NULL DEFAULT 'self_reported',\r\n    ADD COLUMN IF NOT EXISTS verified_at           timestamptz,\r\n    ADD COLUMN IF NOT EXISTS verified_by           uuid","COMMENT ON COLUMN continuity_experience_ledger.source_claim_id IS 'Claim that generated this ledger entry'","COMMENT ON COLUMN continuity_experience_ledger.badge_level IS 'Badge at time of promotion'","-- --------------------------------------------------------------------------\r\n-- 5. RPC: promote a verified claim to the durable ledger\r\n-- --------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION promote_claim_to_ledger(p_claim_id uuid)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nAS $$\r\nDECLARE\r\n    v_claim record;\r\n    v_ledger_id uuid;\r\nBEGIN\r\n    SELECT * INTO v_claim FROM continuity_experience_claims WHERE id = p_claim_id;\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Claim not found: %', p_claim_id;\r\n    END IF;\r\n    IF v_claim.verification_status::text NOT IN ('kadarn_verified', 'verified', 'reference_confirmed') THEN\r\n        RAISE EXCEPTION 'Claim % must be verified before promotion (status: %)', p_claim_id, v_claim.verification_status;\r\n    END IF;\r\n    IF v_claim.promoted_to_ledger_at IS NOT NULL THEN\r\n        RAISE EXCEPTION 'Claim % already promoted to ledger at %', p_claim_id, v_claim.promoted_to_ledger_at;\r\n    END IF;\r\n\r\n    INSERT INTO continuity_experience_ledger (\r\n        site_continuity_profile_id,\r\n        claim_type,\r\n        category,\r\n        title,\r\n        description,\r\n        badge_level,\r\n        therapeutic_area,\r\n        study_phase,\r\n        biospecimen_type,\r\n        start_date,\r\n        end_date,\r\n        quantity,\r\n        is_public,\r\n        sponsor_name_policy,\r\n        masked_sponsor_label,\r\n        source_claim_id,\r\n        verified_at,\r\n        verified_by\r\n    ) VALUES (\r\n        v_claim.site_continuity_profile_id,\r\n        v_claim.claim_type,\r\n        v_claim.category,\r\n        v_claim.title,\r\n        v_claim.description,\r\n        v_claim.badge_level,\r\n        v_claim.therapeutic_area,\r\n        v_claim.study_phase,\r\n        v_claim.biospecimen_type,\r\n        v_claim.start_date,\r\n        v_claim.end_date,\r\n        v_claim.quantity,\r\n        v_claim.is_public,\r\n        v_claim.sponsor_name_policy,\r\n        v_claim.masked_sponsor_label,\r\n        v_claim.id,\r\n        NOW(),\r\n        v_claim.reviewer_id\r\n    ) RETURNING id INTO v_ledger_id;\r\n\r\n    UPDATE continuity_experience_claims\r\n    SET promoted_to_ledger_at = NOW()\r\n    WHERE id = p_claim_id;\r\n\r\n    RETURN v_ledger_id;\r\nEND;\r\n$$"}	continuity_verification_workflow
045	{"-- ============================================================================\r\n-- KADARN PLATFORM — Evidence Core (Phase 1, Sprint 17.2)\r\n-- ============================================================================\r\n-- Baseline: AF-1.0\r\n-- Domain model: Sprint 17.1\r\n-- Design: KEMS-001 v1.0, ADR-011, ADR-012\r\n--\r\n-- This migration implements the persistence layer for the Evidence Core.\r\n-- The Evidence Core stores, relates, preserves provenance, controls access,\r\n-- and manages process state. It does NOT compute Confidence.\r\n--\r\n-- ADR-011 five-condition test:\r\n--   1. Store — evidence and evidence metadata\r\n--   2. Provenance — immutable creation and modification history\r\n--   3. Relations — connections between evidence nodes\r\n--   4. Access — visibility policy enforcement (RLS)\r\n--   5. Process State — lifecycle tracking without content interpretation\r\n--\r\n-- Append-only enforcement: evidence_nodes may not be UPDATEd or DELETEd.\r\n-- Corrections use the wasRevisionOf pattern: a new node is appended that\r\n-- references the superseded node. The original is never modified.\r\n-- ============================================================================\r\n\r\n-- ############################################################################\r\n-- PART 1: ENUMS\r\n-- ############################################################################\r\n\r\nDO $$ BEGIN\r\n    CREATE TYPE evidence_class AS ENUM (\r\n        'A', 'B', 'C', 'D', 'E', 'F'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE evidence_node_status AS ENUM (\r\n        'active',\r\n        'superseded',\r\n        'disputed',\r\n        'resolved'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE evidence_relationship_type AS ENUM (\r\n        'supports',\r\n        'contradicts',\r\n        'corroborates',\r\n        'responds_to',\r\n        'supersedes'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE claim_status AS ENUM (\r\n        'active',\r\n        'archived',\r\n        'deprecated'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE response_status AS ENUM (\r\n        'submitted',\r\n        'accepted',\r\n        'rejected',\r\n        'confirmed'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE confidence_level AS ENUM (\r\n        'high',\r\n        'moderate',\r\n        'low',\r\n        'insufficient'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE visibility_scope AS ENUM (\r\n        'site',\r\n        'sponsor_authorized',\r\n        'system'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","-- ############################################################################\r\n-- PART 2: REFERENCE DATA — Evidence Class\r\n-- ############################################################################\r\n-- KEMS-001 §3: six Evidence Classes with decay and weight defaults.\r\n\r\nCREATE TABLE IF NOT EXISTS evidence_class_ref (\r\n    id              evidence_class PRIMARY KEY,\r\n    name            TEXT NOT NULL,\r\n    description     TEXT NOT NULL,\r\n    decay_months    INTEGER,        -- NULL = no decay\r\n    default_weight  NUMERIC(3,2) NOT NULL\r\n)","INSERT INTO evidence_class_ref (id, name, description, decay_months, default_weight) VALUES\r\n    ('A', 'Public Independent Evidence', 'Evidence from public registries verifiable without relying on the institution.', 60, 0.80),\r\n    ('B', 'Institutional Documentary Evidence', 'Evidence from the institution in the form of structured documents.', 24, 0.50),\r\n    ('C', 'Operational Evidence', 'Evidence generated automatically by operational systems as a byproduct of execution.', 12, 0.70),\r\n    ('D', 'Cross-Source Corroboration', 'Structural consistency when independent sources agree.', NULL, 0.00),\r\n    ('E', 'Temporal Continuity Evidence', 'Evidence of consistent capability maintenance over time.', NULL, 0.00),\r\n    ('F', 'External Confirmation', 'Evidence from an independent third party confirming capability.', 36, 1.00)\r\nON CONFLICT (id) DO NOTHING","-- ############################################################################\r\n-- PART 3: CLAIMS\r\n-- ############################################################################\r\n-- KEMS-001 §1: A Claim is a bounded assertion about institutional capability.\r\n\r\nCREATE TABLE IF NOT EXISTS claims (\r\n    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    claim_type_id           TEXT NOT NULL,\r\n    name                    TEXT NOT NULL,\r\n    description             TEXT NOT NULL,\r\n    organization_id         UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\r\n    status                  claim_status NOT NULL DEFAULT 'active',\r\n    domain                  TEXT NOT NULL,\r\n    decays                  BOOLEAN NOT NULL DEFAULT true,\r\n    decay_period_months     INTEGER,\r\n    valid_evidence_classes  evidence_class[] NOT NULL DEFAULT '{}',\r\n    required_evidence_classes evidence_class[] NOT NULL DEFAULT '{}',\r\n\r\n    -- Provenance metadata\r\n    created_by_actor_id     UUID NOT NULL,\r\n    created_by_org_id       UUID NOT NULL REFERENCES organizations(id),\r\n    correlation_id          UUID NOT NULL,\r\n    provenance_summary      TEXT,\r\n    source_event_id         UUID,\r\n\r\n    -- Visibility metadata\r\n    owning_org_id           UUID NOT NULL REFERENCES organizations(id),\r\n    visibility_scope        visibility_scope NOT NULL DEFAULT 'site',\r\n    authorized_sponsor_ids  UUID[] NOT NULL DEFAULT '{}',\r\n\r\n    -- Temporal metadata\r\n    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    CONSTRAINT claim_valid_classes CHECK (array_length(valid_evidence_classes, 1) > 0),\r\n    CONSTRAINT claim_decay_consistent CHECK (\r\n        (decays = true AND decay_period_months IS NOT NULL) OR\r\n        (decays = false AND decay_period_months IS NULL)\r\n    )\r\n)","CREATE INDEX idx_claims_organization ON claims(organization_id)","CREATE INDEX idx_claims_claim_type ON claims(claim_type_id)","CREATE INDEX idx_claims_status ON claims(status)","-- ############################################################################\r\n-- PART 4: EVIDENCE NODES\r\n-- ############################################################################\r\n-- KEMS-001 §2 Component B: immutable, append-only.\r\n\r\nCREATE TABLE IF NOT EXISTS evidence_nodes (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    claim_id            UUID NOT NULL REFERENCES claims(id) ON DELETE CASCADE,\r\n    evidence_class      evidence_class NOT NULL,\r\n    content             TEXT NOT NULL,\r\n    source              TEXT NOT NULL,\r\n    node_date           DATE NOT NULL,      -- date evidence was produced\r\n    status              evidence_node_status NOT NULL DEFAULT 'active',\r\n    weight              NUMERIC(5,3) NOT NULL,\r\n\r\n    -- Provenance metadata (structured JSONB for flexibility)\r\n    provenance          JSONB NOT NULL DEFAULT '{}',\r\n    -- Visibility metadata\r\n    visibility          JSONB NOT NULL DEFAULT '{}',\r\n    -- Temporal metadata\r\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    -- Counter Evidence extension: null for regular nodes\r\n    is_counter_evidence BOOLEAN NOT NULL DEFAULT false,\r\n    has_response        BOOLEAN NOT NULL DEFAULT false,\r\n    response_id         UUID,\r\n\r\n    CONSTRAINT evidence_node_non_negative_weight CHECK (weight >= 0 OR is_counter_evidence = true),\r\n    CONSTRAINT counter_evidence_negative_weight CHECK (\r\n        (is_counter_evidence = true AND weight < 0) OR\r\n        (is_counter_evidence = false AND weight >= 0)\r\n    ),\r\n    CONSTRAINT counter_evidence_response_consistent CHECK (\r\n        (is_counter_evidence = false AND has_response = false AND response_id IS NULL) OR\r\n        (is_counter_evidence = true)\r\n    )\r\n)","CREATE INDEX idx_evidence_nodes_claim ON evidence_nodes(claim_id)","CREATE INDEX idx_evidence_nodes_class ON evidence_nodes(evidence_class)","CREATE INDEX idx_evidence_nodes_counter ON evidence_nodes(is_counter_evidence) WHERE is_counter_evidence = true","-- ############################################################################\r\n-- PART 4b: APPEND-ONLY ENFORCEMENT — evidence_nodes\r\n-- ############################################################################\r\n-- KEMS-001 §4: Counter Evidence cannot be deleted. Evidence Nodes are immutable.\r\n\r\nCREATE OR REPLACE FUNCTION evidence_nodes_no_update()\r\nRETURNS TRIGGER\r\nLANGUAGE plpgsql\r\nAS $$\r\nBEGIN\r\n    RAISE EXCEPTION 'evidence_nodes is append-only. Node % cannot be modified.', OLD.id;\r\nEND;\r\n$$","CREATE OR REPLACE FUNCTION evidence_nodes_no_delete()\r\nRETURNS TRIGGER\r\nLANGUAGE plpgsql\r\nAS $$\r\nBEGIN\r\n    RAISE EXCEPTION 'evidence_nodes is append-only. Node % cannot be deleted.', OLD.id;\r\nEND;\r\n$$","DROP TRIGGER IF EXISTS trg_evidence_nodes_no_update ON evidence_nodes","CREATE TRIGGER trg_evidence_nodes_no_update\r\n    BEFORE UPDATE ON evidence_nodes\r\n    FOR EACH ROW EXECUTE FUNCTION evidence_nodes_no_update()","DROP TRIGGER IF EXISTS trg_evidence_nodes_no_delete ON evidence_nodes","CREATE TRIGGER trg_evidence_nodes_no_delete\r\n    BEFORE DELETE ON evidence_nodes\r\n    FOR EACH ROW EXECUTE FUNCTION evidence_nodes_no_delete()","-- ############################################################################\r\n-- PART 5: EVIDENCE RELATIONSHIPS\r\n-- ############################################################################\r\n-- KEMS-001 §2 Component C: relationships between evidence nodes.\r\n\r\nCREATE TABLE IF NOT EXISTS evidence_relationships (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    source_node_id      UUID NOT NULL REFERENCES evidence_nodes(id) ON DELETE CASCADE,\r\n    target_node_id      UUID NOT NULL REFERENCES evidence_nodes(id) ON DELETE CASCADE,\r\n    relationship_type   evidence_relationship_type NOT NULL,\r\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    provenance          JSONB NOT NULL DEFAULT '{}',\r\n\r\n    CONSTRAINT no_self_reference CHECK (source_node_id <> target_node_id)\r\n)","CREATE INDEX idx_evidence_relationships_source ON evidence_relationships(source_node_id)","CREATE INDEX idx_evidence_relationships_target ON evidence_relationships(target_node_id)","CREATE INDEX idx_evidence_relationships_type ON evidence_relationships(relationship_type)","-- ############################################################################\r\n-- PART 6: RIGHT OF RESPONSE\r\n-- ############################################################################\r\n-- KEMS-001 §8: attached to Counter Evidence without modifying it.\r\n\r\nCREATE TABLE IF NOT EXISTS right_of_response (\r\n    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    counter_evidence_id     UUID NOT NULL REFERENCES evidence_nodes(id) ON DELETE CASCADE,\r\n    description             TEXT NOT NULL,\r\n    resolution_date         DATE NOT NULL,\r\n    status                  response_status NOT NULL DEFAULT 'submitted',\r\n    supporting_evidence_ids UUID[] NOT NULL DEFAULT '{}',\r\n\r\n    -- Provenance\r\n    created_by_actor_id     UUID NOT NULL,\r\n    created_by_org_id       UUID NOT NULL REFERENCES organizations(id),\r\n    correlation_id          UUID NOT NULL,\r\n    provenance_summary      TEXT,\r\n\r\n    -- Visibility\r\n    owning_org_id           UUID NOT NULL REFERENCES organizations(id),\r\n    visibility_scope        visibility_scope NOT NULL DEFAULT 'site',\r\n    authorized_sponsor_ids  UUID[] NOT NULL DEFAULT '{}',\r\n\r\n    -- Temporal\r\n    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    CONSTRAINT response_attached_to_counter_evidence CHECK (\r\n        -- enforced by FK + application logic: counter_evidence_id must reference\r\n        -- an evidence_node with is_counter_evidence = true\r\n        true\r\n    )\r\n)","CREATE INDEX idx_right_of_response_counter ON right_of_response(counter_evidence_id)","-- ############################################################################\r\n-- PART 7: CONFIDENCE STATE SNAPSHOTS\r\n-- ############################################################################\r\n-- KEMS-001 §2 Component D: stored as append-only snapshots. NOT computed here.\r\n-- Computation belongs to an Engine per ADR-011.\r\n\r\nCREATE TABLE IF NOT EXISTS confidence_state_snapshots (\r\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    claim_id        UUID NOT NULL REFERENCES claims(id) ON DELETE CASCADE,\r\n    value           INTEGER NOT NULL CHECK (value BETWEEN 0 AND 100),\r\n    level           confidence_level NOT NULL,\r\n    explanation     TEXT NOT NULL,\r\n    contributions   JSONB NOT NULL DEFAULT '[]',\r\n    has_unresolved_counter_evidence BOOLEAN NOT NULL DEFAULT false,\r\n    snapshot_date   TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    -- Provenance\r\n    computed_by_actor_id UUID,\r\n    correlation_id       UUID NOT NULL,\r\n    provenance_summary   TEXT\r\n)","CREATE INDEX idx_confidence_snapshots_claim ON confidence_state_snapshots(claim_id)","CREATE INDEX idx_confidence_snapshots_date ON confidence_state_snapshots(snapshot_date)","-- ############################################################################\r\n-- PART 8: ROW-LEVEL SECURITY\r\n-- ############################################################################\r\n-- KEMS-001 §7: multi-actor visibility model.\r\n\r\nALTER TABLE claims ENABLE ROW LEVEL SECURITY","ALTER TABLE evidence_nodes ENABLE ROW LEVEL SECURITY","ALTER TABLE evidence_relationships ENABLE ROW LEVEL SECURITY","ALTER TABLE right_of_response ENABLE ROW LEVEL SECURITY","ALTER TABLE confidence_state_snapshots ENABLE ROW LEVEL SECURITY","-- Claims: org sees own claims; sponsors see authorized claims\r\nCREATE POLICY claims_select_org ON claims\r\n    FOR SELECT\r\n    USING (\r\n        owning_org_id IN (\r\n            SELECT organization_id FROM organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n    )","CREATE POLICY claims_select_sponsor ON claims\r\n    FOR SELECT\r\n    USING (\r\n        visibility_scope = 'sponsor_authorized'\r\n        AND auth.uid() = ANY(authorized_sponsor_ids)\r\n    )","CREATE POLICY claims_select_system ON claims\r\n    FOR SELECT\r\n    USING (visibility_scope = 'system')","-- INSERT: only active members of the owning org may create Claims for that org.\r\n-- created_by_org_id must match owning_org_id — no cross-org claim creation.\r\nCREATE POLICY claims_insert_org ON claims\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        owning_org_id IN (\r\n            SELECT organization_id FROM organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n        AND created_by_org_id = owning_org_id\r\n    )","-- UPDATE: append-only domain semantics — Claims may only transition status\r\n-- (active/archived/deprecated) by the owning org. Evidence content fields\r\n-- (claim_type_id, domain, valid/required evidence classes) are immutable\r\n-- post-creation; corrections require a new Claim per KEMS-001 append-only rule.\r\nCREATE POLICY claims_update_org ON claims\r\n    FOR UPDATE\r\n    USING (\r\n        owning_org_id IN (\r\n            SELECT organization_id FROM organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n    )\r\n    WITH CHECK (\r\n        owning_org_id = (SELECT original.owning_org_id FROM claims original WHERE original.id = claims.id)\r\n        AND organization_id = (SELECT original.organization_id FROM claims original WHERE original.id = claims.id)\r\n        AND claim_type_id = (SELECT original.claim_type_id FROM claims original WHERE original.id = claims.id)\r\n        AND domain = (SELECT original.domain FROM claims original WHERE original.id = claims.id)\r\n        AND created_by_actor_id = (SELECT original.created_by_actor_id FROM claims original WHERE original.id = claims.id)\r\n        AND created_by_org_id = (SELECT original.created_by_org_id FROM claims original WHERE original.id = claims.id)\r\n    )","-- Evidence nodes: same pattern\r\nCREATE POLICY evidence_nodes_select_org ON evidence_nodes\r\n    FOR SELECT\r\n    USING (\r\n        visibility->>'owningOrganizationId' IN (\r\n            SELECT organization_id::text FROM organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n    )","CREATE POLICY evidence_nodes_select_sponsor ON evidence_nodes\r\n    FOR SELECT\r\n    USING (\r\n        visibility->>'scope' = 'sponsor_authorized'\r\n        AND auth.uid()::text = ANY(\r\n            ARRAY(SELECT jsonb_array_elements_text(visibility->'authorizedSponsorIds'))\r\n        )\r\n    )","-- INSERT: only active members of the claim's owning org may append Evidence\r\n-- Nodes (including Counter Evidence). No UPDATE/DELETE policy is defined —\r\n-- evidence_nodes is append-only and already enforced by DB triggers above.\r\nCREATE POLICY evidence_nodes_insert_org ON evidence_nodes\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        EXISTS (\r\n            SELECT 1 FROM claims c\r\n            WHERE c.id = evidence_nodes.claim_id\r\n            AND c.owning_org_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","-- Evidence relationships: inherited from source node visibility\r\nCREATE POLICY evidence_relationships_select ON evidence_relationships\r\n    FOR SELECT\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM evidence_nodes en\r\n            WHERE en.id = source_node_id\r\n            AND (\r\n                en.visibility->>'owningOrganizationId' IN (\r\n                    SELECT organization_id::text FROM organization_memberships\r\n                    WHERE user_id = auth.uid() AND status = 'active'\r\n                )\r\n                OR en.visibility->>'scope' = 'sponsor_authorized'\r\n            )\r\n        )\r\n    )","-- INSERT: relationships are append-only (no UPDATE/DELETE policy defined).\r\n-- Requires org membership on the owning org of BOTH source and target nodes,\r\n-- so a relationship cannot be forged linking evidence the caller cannot see.\r\nCREATE POLICY evidence_relationships_insert_org ON evidence_relationships\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        EXISTS (\r\n            SELECT 1 FROM evidence_nodes en\r\n            WHERE en.id = evidence_relationships.source_node_id\r\n            AND en.visibility->>'owningOrganizationId' IN (\r\n                SELECT organization_id::text FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n        AND EXISTS (\r\n            SELECT 1 FROM evidence_nodes en\r\n            WHERE en.id = evidence_relationships.target_node_id\r\n            AND en.visibility->>'owningOrganizationId' IN (\r\n                SELECT organization_id::text FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","-- Right of Response: same owning org rules\r\nCREATE POLICY right_of_response_select_org ON right_of_response\r\n    FOR SELECT\r\n    USING (\r\n        owning_org_id IN (\r\n            SELECT organization_id FROM organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n    )","-- INSERT: only active members of the owning org may submit a Right of Response.\r\nCREATE POLICY right_of_response_insert_org ON right_of_response\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        owning_org_id IN (\r\n            SELECT organization_id FROM organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n    )","-- UPDATE: KEMS-001 §8 process state — status may transition\r\n-- (submitted -> accepted/rejected/confirmed) by the owning org only.\r\n-- Immutable fields (description, resolution_date, supporting evidence,\r\n-- provenance) cannot be altered after submission.\r\nCREATE POLICY right_of_response_update_org ON right_of_response\r\n    FOR UPDATE\r\n    USING (\r\n        owning_org_id IN (\r\n            SELECT organization_id FROM organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n    )\r\n    WITH CHECK (\r\n        owning_org_id = (SELECT original.owning_org_id FROM right_of_response original WHERE original.id = right_of_response.id)\r\n        AND counter_evidence_id = (SELECT original.counter_evidence_id FROM right_of_response original WHERE original.id = right_of_response.id)\r\n        AND description = (SELECT original.description FROM right_of_response original WHERE original.id = right_of_response.id)\r\n        AND resolution_date = (SELECT original.resolution_date FROM right_of_response original WHERE original.id = right_of_response.id)\r\n        AND created_by_actor_id = (SELECT original.created_by_actor_id FROM right_of_response original WHERE original.id = right_of_response.id)\r\n        AND created_by_org_id = (SELECT original.created_by_org_id FROM right_of_response original WHERE original.id = right_of_response.id)\r\n    )","-- Confidence state snapshots: via claim visibility\r\nCREATE POLICY confidence_snapshots_select ON confidence_state_snapshots\r\n    FOR SELECT\r\n    USING (\r\n        claim_id IN (\r\n            SELECT id FROM claims WHERE\r\n                owning_org_id IN (\r\n                    SELECT organization_id FROM organization_memberships\r\n                    WHERE user_id = auth.uid() AND status = 'active'\r\n                )\r\n                OR visibility_scope IN ('system', 'sponsor_authorized')\r\n        )\r\n    )","-- INSERT: append-only per KEMS §2 Component D (no UPDATE/DELETE policy defined).\r\n-- Restricted to active members of the claim's owning org — Confidence\r\n-- computation is an Engine concern (ADR-011) but snapshot persistence\r\n-- still requires org-scoped write access, same as other Core tables.\r\nCREATE POLICY confidence_snapshots_insert_org ON confidence_state_snapshots\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        claim_id IN (\r\n            SELECT id FROM claims WHERE\r\n                owning_org_id IN (\r\n                    SELECT organization_id FROM organization_memberships\r\n                    WHERE user_id = auth.uid() AND status = 'active'\r\n                )\r\n        )\r\n    )","-- ############################################################################\r\n-- PART 9: VERIFICATION\r\n-- ############################################################################\r\n\r\n-- Run to list all policies defined in this migration:\r\n--   SELECT * FROM pg_policies WHERE schemaname = 'public'\r\n--   AND tablename IN ('claims', 'evidence_nodes', 'evidence_relationships',\r\n--                      'right_of_response', 'confidence_state_snapshots')\r\n--   ORDER BY tablename, policyname;\r\n\r\n-- ============================================================================\r\n-- END OF MIGRATION 045\r\n-- ============================================================================"}	evidence_core
046	{"-- ============================================================================\r\n-- KADARN PLATFORM — Evidence Discovery (Sprint 20A.2)\r\n-- ============================================================================\r\n-- Baseline: AF-1.0\r\n-- Domain model: Sprint 20A.1 — KEMS-002 / KEMS-002A\r\n--\r\n-- This migration implements persistence for the Evidence Discovery subsystem.\r\n-- Discovery is SEPARATE from the Evidence Core. No discovery table writes to\r\n-- canonical evidence tables. Evidence Candidates are provisional until promoted.\r\n--\r\n-- KEMS-002 Principles enforced:\r\n--   Principle 1: Discovery never writes directly to Evidence Core\r\n--   Principle 3: Evidence Candidate before Evidence Node\r\n--   Principle 4: Layer 0 is immutable\r\n--   Principle 5: Trace everything — full provenance chain\r\n--\r\n-- KEMS-002A invariants:\r\n--   Every transition is persisted as immutable event\r\n--   No transition without event\r\n--   Complete lifecycle reconstructable from events\r\n-- ============================================================================\r\n\r\n-- ############################################################################\r\n-- PART 1: ENUMS\r\n-- ############################################################################\r\n\r\nDO $$ BEGIN\r\n    CREATE TYPE discovery_artifact_type AS ENUM (\r\n        'pdf', 'docx', 'zip', 'image', 'api_payload', 'public_registry', 'other'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE discovery_session_status AS ENUM (\r\n        'active', 'completed', 'failed'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE discovery_run_status AS ENUM (\r\n        'running', 'completed', 'failed'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE discovery_candidate_state AS ENUM (\r\n        'RAW_SOURCE', 'DISCOVERED', 'CLASSIFIED', 'ENTITY_EXTRACTED',\r\n        'CLAIMS_PROPOSED', 'CURATION', 'ENRICHED', 'NEEDS_MORE_EVIDENCE',\r\n        'READY_FOR_PROMOTION', 'PROMOTED', 'REJECTED', 'MERGED', 'SPLIT',\r\n        'ARCHIVED',\r\n        'DISCOVERY_FAILED', 'CLASSIFICATION_FAILED',\r\n        'ENTITY_EXTRACTION_FAILED', 'CLAIM_DETECTION_FAILED'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","-- ############################################################################\r\n-- PART 2: DISCOVERY SESSION\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS discovery_sessions (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    organization_id     UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\r\n    site_id             UUID,  -- optional, linked when SiteIdentity exists\r\n    status              discovery_session_status NOT NULL DEFAULT 'active',\r\n    created_by          UUID NOT NULL,\r\n    correlation_id      UUID NOT NULL,\r\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()\r\n)","CREATE INDEX idx_discovery_sessions_org ON discovery_sessions(organization_id)","-- ############################################################################\r\n-- PART 3: DISCOVERY RUN\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS discovery_runs (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    session_id          UUID NOT NULL REFERENCES discovery_sessions(id) ON DELETE CASCADE,\r\n    status              discovery_run_status NOT NULL DEFAULT 'running',\r\n    pipeline_version    TEXT NOT NULL,\r\n    started_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    completed_at        TIMESTAMPTZ,\r\n    error_message       TEXT\r\n)","CREATE INDEX idx_discovery_runs_session ON discovery_runs(session_id)","-- ############################################################################\r\n-- PART 4: DISCOVERY ARTIFACTS (Layer 0 metadata)\r\n-- ############################################################################\r\n-- KEMS-002 Principle 4: Layer 0 is immutable.\r\n-- KEMS-002A: Layer 0 metadata may not be mutated after creation.\r\n\r\nCREATE TABLE IF NOT EXISTS discovery_artifacts (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    run_id              UUID NOT NULL REFERENCES discovery_runs(id) ON DELETE CASCADE,\r\n    file_name           TEXT NOT NULL,\r\n    artifact_type       discovery_artifact_type NOT NULL,\r\n    size_bytes          BIGINT NOT NULL,\r\n    file_hash           TEXT NOT NULL,        -- SHA-256\r\n    source              TEXT NOT NULL,\r\n    storage_ref         TEXT NOT NULL,\r\n    received_at         TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    -- Immutable enforcement: no UPDATE trigger — only INSERT allowed\r\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\r\n)","CREATE INDEX idx_discovery_artifacts_run ON discovery_artifacts(run_id)","CREATE INDEX idx_discovery_artifacts_hash ON discovery_artifacts(file_hash)","-- ############################################################################\r\n-- PART 5: LAYER 1 — EXTRACTED REPRESENTATION\r\n-- ############################################################################\r\n-- KEMS-002A: Layer 1 references Layer 0. Cannot exist without Layer 0.\r\n\r\nCREATE TABLE IF NOT EXISTS discovery_layer1 (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    artifact_id         UUID NOT NULL REFERENCES discovery_artifacts(id) ON DELETE CASCADE,\r\n    markdown            TEXT NOT NULL,\r\n    extractor           TEXT NOT NULL,\r\n    extractor_version   TEXT NOT NULL,\r\n    original_hash       TEXT NOT NULL,        -- hash of Layer 0 for provenance\r\n    status              TEXT NOT NULL DEFAULT 'completed',\r\n    error_message       TEXT,\r\n    extracted_at        TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\r\n)","CREATE INDEX idx_discovery_layer1_artifact ON discovery_layer1(artifact_id)","-- ############################################################################\r\n-- PART 6: EVIDENCE CANDIDATES (Layer 2 — semantic objects)\r\n-- ############################################################################\r\n-- KEMS-002 Principle 3: Provisional until promoted.\r\n-- KEMS-002A: State machine governs lifecycle.\r\n\r\nCREATE TABLE IF NOT EXISTS discovery_candidates (\r\n    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    run_id                  UUID NOT NULL REFERENCES discovery_runs(id) ON DELETE CASCADE,\r\n    current_state           discovery_candidate_state NOT NULL DEFAULT 'RAW_SOURCE',\r\n    proposed_evidence_class TEXT,                          -- 'A'..'F'\r\n    content                 TEXT NOT NULL,\r\n    discovery_confidence    NUMERIC(5,3) NOT NULL DEFAULT 0,\r\n    source                  TEXT NOT NULL,\r\n    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    -- If promoted, reference to canonical EvidenceNode (populated by Promotion Pipeline)\r\n    promoted_evidence_node_id UUID\r\n)","CREATE INDEX idx_discovery_candidates_run ON discovery_candidates(run_id)","CREATE INDEX idx_discovery_candidates_state ON discovery_candidates(current_state)","-- ############################################################################\r\n-- PART 7: CANDIDATE → ARTIFACT LINKS\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS discovery_candidate_artifacts (\r\n    candidate_id    UUID NOT NULL REFERENCES discovery_candidates(id) ON DELETE CASCADE,\r\n    artifact_id     UUID NOT NULL REFERENCES discovery_artifacts(id) ON DELETE CASCADE,\r\n    PRIMARY KEY (candidate_id, artifact_id)\r\n)","-- ############################################################################\r\n-- PART 8: TRANSITION EVENTS (append-only, immutable)\r\n-- ############################################################################\r\n-- KEMS-002A §6: Every transition emits an immutable event.\r\n-- KEMS-002A §10: Every state transition must be reproducible.\r\n\r\nCREATE TABLE IF NOT EXISTS discovery_transition_events (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    candidate_id        UUID NOT NULL REFERENCES discovery_candidates(id) ON DELETE CASCADE,\r\n    from_state          discovery_candidate_state NOT NULL,\r\n    to_state            discovery_candidate_state NOT NULL,\r\n    actor               TEXT NOT NULL,\r\n    pipeline_version    TEXT NOT NULL,\r\n    model_version       TEXT,\r\n    reason              TEXT NOT NULL,\r\n    occurred_at         TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    -- Idempotency: unique constraint prevents duplicate transition events\r\n    UNIQUE (candidate_id, from_state, to_state, occurred_at)\r\n)","CREATE INDEX idx_discovery_events_candidate ON discovery_transition_events(candidate_id)","CREATE INDEX idx_discovery_events_timing ON discovery_transition_events(occurred_at)","-- ############################################################################\r\n-- PART 9: APPEND-ONLY ENFORCEMENT (Layer 0 artifacts — immutable)\r\n-- ############################################################################\r\n\r\nCREATE OR REPLACE FUNCTION discovery_artifacts_no_update()\r\nRETURNS TRIGGER\r\nLANGUAGE plpgsql\r\nAS $$\r\nBEGIN\r\n    RAISE EXCEPTION 'discovery_artifacts is append-only. Artifact % cannot be modified.', OLD.id;\r\nEND;\r\n$$","DROP TRIGGER IF EXISTS trg_discovery_artifacts_no_update ON discovery_artifacts","CREATE TRIGGER trg_discovery_artifacts_no_update\r\n    BEFORE UPDATE ON discovery_artifacts\r\n    FOR EACH ROW EXECUTE FUNCTION discovery_artifacts_no_update()","-- Transition events are also append-only\r\nCREATE OR REPLACE FUNCTION discovery_events_no_update()\r\nRETURNS TRIGGER\r\nLANGUAGE plpgsql\r\nAS $$\r\nBEGIN\r\n    RAISE EXCEPTION 'discovery_transition_events is append-only. Event % cannot be modified.', OLD.id;\r\nEND;\r\n$$","DROP TRIGGER IF EXISTS trg_discovery_events_no_update ON discovery_transition_events","CREATE TRIGGER trg_discovery_events_no_update\r\n    BEFORE UPDATE ON discovery_transition_events\r\n    FOR EACH ROW EXECUTE FUNCTION discovery_events_no_update()","-- ############################################################################\r\n-- PART 10: ROW-LEVEL SECURITY\r\n-- ############################################################################\r\n-- Discovery is org-scoped through discovery_sessions.organization_id.\r\n-- Child tables (runs, artifacts, layer1, candidates, candidate_artifacts,\r\n-- transition_events) join up to discovery_sessions to resolve org ownership.\r\n-- discovery_artifacts and discovery_transition_events are append-only (see\r\n-- PART 9 triggers above) — no UPDATE/DELETE policy is defined for them.\r\n-- ============================================================================\r\n\r\nALTER TABLE discovery_sessions ENABLE ROW LEVEL SECURITY","ALTER TABLE discovery_runs ENABLE ROW LEVEL SECURITY","ALTER TABLE discovery_artifacts ENABLE ROW LEVEL SECURITY","ALTER TABLE discovery_layer1 ENABLE ROW LEVEL SECURITY","ALTER TABLE discovery_candidates ENABLE ROW LEVEL SECURITY","ALTER TABLE discovery_candidate_artifacts ENABLE ROW LEVEL SECURITY","ALTER TABLE discovery_transition_events ENABLE ROW LEVEL SECURITY","-- discovery_sessions: org-scoped directly\r\nCREATE POLICY discovery_sessions_select_org ON discovery_sessions\r\n    FOR SELECT\r\n    USING (\r\n        organization_id IN (\r\n            SELECT organization_id FROM organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n    )","CREATE POLICY discovery_sessions_insert_org ON discovery_sessions\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        organization_id IN (\r\n            SELECT organization_id FROM organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n    )","CREATE POLICY discovery_sessions_update_org ON discovery_sessions\r\n    FOR UPDATE\r\n    USING (\r\n        organization_id IN (\r\n            SELECT organization_id FROM organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n    )\r\n    WITH CHECK (\r\n        organization_id = (SELECT original.organization_id FROM discovery_sessions original WHERE original.id = discovery_sessions.id)\r\n    )","-- discovery_runs: via parent session's organization_id\r\nCREATE POLICY discovery_runs_select_org ON discovery_runs\r\n    FOR SELECT\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_sessions s\r\n            WHERE s.id = discovery_runs.session_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","CREATE POLICY discovery_runs_insert_org ON discovery_runs\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_sessions s\r\n            WHERE s.id = discovery_runs.session_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","CREATE POLICY discovery_runs_update_org ON discovery_runs\r\n    FOR UPDATE\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_sessions s\r\n            WHERE s.id = discovery_runs.session_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )\r\n    WITH CHECK (\r\n        session_id = (SELECT original.session_id FROM discovery_runs original WHERE original.id = discovery_runs.id)\r\n    )","-- discovery_artifacts: via parent run -> session's organization_id.\r\n-- Layer 0 is immutable (KEMS-002 Principle 4) — INSERT only, no UPDATE/DELETE policy.\r\nCREATE POLICY discovery_artifacts_select_org ON discovery_artifacts\r\n    FOR SELECT\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_runs r\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE r.id = discovery_artifacts.run_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","CREATE POLICY discovery_artifacts_insert_org ON discovery_artifacts\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_runs r\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE r.id = discovery_artifacts.run_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","-- discovery_layer1: via parent artifact -> run -> session's organization_id\r\nCREATE POLICY discovery_layer1_select_org ON discovery_layer1\r\n    FOR SELECT\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_artifacts a\r\n            JOIN discovery_runs r ON r.id = a.run_id\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE a.id = discovery_layer1.artifact_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","CREATE POLICY discovery_layer1_insert_org ON discovery_layer1\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_artifacts a\r\n            JOIN discovery_runs r ON r.id = a.run_id\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE a.id = discovery_layer1.artifact_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","CREATE POLICY discovery_layer1_update_org ON discovery_layer1\r\n    FOR UPDATE\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_artifacts a\r\n            JOIN discovery_runs r ON r.id = a.run_id\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE a.id = discovery_layer1.artifact_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )\r\n    WITH CHECK (\r\n        artifact_id = (SELECT original.artifact_id FROM discovery_layer1 original WHERE original.id = discovery_layer1.id)\r\n    )","-- discovery_candidates: via parent run -> session's organization_id\r\nCREATE POLICY discovery_candidates_select_org ON discovery_candidates\r\n    FOR SELECT\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_runs r\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE r.id = discovery_candidates.run_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","CREATE POLICY discovery_candidates_insert_org ON discovery_candidates\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_runs r\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE r.id = discovery_candidates.run_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","CREATE POLICY discovery_candidates_update_org ON discovery_candidates\r\n    FOR UPDATE\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_runs r\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE r.id = discovery_candidates.run_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )\r\n    WITH CHECK (\r\n        run_id = (SELECT original.run_id FROM discovery_candidates original WHERE original.id = discovery_candidates.id)\r\n    )","-- discovery_candidate_artifacts: link table, visible/insertable if the\r\n-- candidate is visible/insertable (org derived transitively via candidate).\r\nCREATE POLICY discovery_candidate_artifacts_select_org ON discovery_candidate_artifacts\r\n    FOR SELECT\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_candidates c\r\n            JOIN discovery_runs r ON r.id = c.run_id\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE c.id = discovery_candidate_artifacts.candidate_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","CREATE POLICY discovery_candidate_artifacts_insert_org ON discovery_candidate_artifacts\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_candidates c\r\n            JOIN discovery_runs r ON r.id = c.run_id\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE c.id = discovery_candidate_artifacts.candidate_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","-- discovery_transition_events: append-only (KEMS-002A §6) — INSERT/SELECT\r\n-- only, no UPDATE/DELETE policy. Org resolved via candidate -> run -> session.\r\nCREATE POLICY discovery_transition_events_select_org ON discovery_transition_events\r\n    FOR SELECT\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_candidates c\r\n            JOIN discovery_runs r ON r.id = c.run_id\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE c.id = discovery_transition_events.candidate_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","CREATE POLICY discovery_transition_events_insert_org ON discovery_transition_events\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_candidates c\r\n            JOIN discovery_runs r ON r.id = c.run_id\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE c.id = discovery_transition_events.candidate_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","-- ############################################################################\r\n-- PART 11: VERIFICATION QUERIES\r\n-- ############################################################################\r\n\r\n-- List all discovery tables:\r\n--   SELECT tablename FROM pg_tables WHERE schemaname = 'public'\r\n--   AND tablename LIKE 'discovery_%' ORDER BY tablename;\r\n\r\n-- Reconstruct candidate lifecycle:\r\n--   SELECT * FROM discovery_transition_events\r\n--   WHERE candidate_id = :candidate_id\r\n--   ORDER BY occurred_at;\r\n\r\n-- List all RLS policies for discovery tables:\r\n--   SELECT * FROM pg_policies WHERE schemaname = 'public'\r\n--   AND tablename LIKE 'discovery_%' ORDER BY tablename, policyname;\r\n\r\n-- ============================================================================\r\n-- END OF MIGRATION 046\r\n-- ============================================================================"}	evidence_lineage
047	{"-- ============================================================================\r\n-- KADARN PLATFORM — Evidence Discovery Preparation Layer (Sprint 20A.3B)\r\n-- ============================================================================\r\n-- Baseline: AF-1.0\r\n-- Design: KEMS-002, KEMS-002A, Agent Responsibility Matrix\r\n--\r\n-- Creates the semantic extraction request queue between Layer 1 extraction\r\n-- and the future Agent Pipeline. No AI agents. No Evidence Core writes.\r\n-- ============================================================================\r\n\r\nDO $$ BEGIN\r\n    CREATE TYPE discovery_request_type AS ENUM (\r\n        'DOCUMENT_CLASSIFICATION',\r\n        'ENTITY_EXTRACTION',\r\n        'RELATIONSHIP_EXTRACTION',\r\n        'CLAIM_CANDIDATE_DETECTION',\r\n        'TIMELINE_RECONSTRUCTION',\r\n        'GAP_DETECTION',\r\n        'LEVERAGE_RECOMMENDATION'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE discovery_request_status AS ENUM (\r\n        'PENDING', 'CLAIMED', 'RUNNING', 'COMPLETED',\r\n        'FAILED', 'CANCELLED', 'SKIPPED'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE discovery_request_priority AS ENUM (\r\n        'high', 'normal', 'low'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","CREATE TABLE IF NOT EXISTS discovery_preparation_requests (\r\n    request_id          UUID PRIMARY KEY,\r\n    discovery_run_id    UUID NOT NULL REFERENCES discovery_runs(id) ON DELETE CASCADE,\r\n    artifact_id         UUID NOT NULL REFERENCES discovery_artifacts(id),\r\n    layer1_id           UUID NOT NULL REFERENCES discovery_layer1(id),\r\n    request_type        discovery_request_type NOT NULL,\r\n    status              discovery_request_status NOT NULL DEFAULT 'PENDING',\r\n    priority            discovery_request_priority NOT NULL DEFAULT 'normal',\r\n    pipeline_version    TEXT NOT NULL,\r\n    agent_version       TEXT,\r\n    model_version       TEXT,\r\n    input_hash          TEXT NOT NULL,\r\n    output_ref          TEXT,\r\n    error               TEXT,\r\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    claimed_at          TIMESTAMPTZ,\r\n    completed_at        TIMESTAMPTZ,\r\n    failed_at           TIMESTAMPTZ,\r\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    -- Idempotency: no duplicate active PENDING/CLAIMED/RUNNING requests\r\n    -- for the same layer1Id + requestType + pipelineVersion\r\n    CONSTRAINT uq_active_request UNIQUE (layer1_id, request_type, pipeline_version, status)\r\n)","CREATE INDEX idx_prep_requests_run ON discovery_preparation_requests(discovery_run_id)","CREATE INDEX idx_prep_requests_status ON discovery_preparation_requests(status)","CREATE INDEX idx_prep_requests_type ON discovery_preparation_requests(request_type)","-- ############################################################################\r\n-- ROW-LEVEL SECURITY\r\n-- ############################################################################\r\n-- Org-scoped via discovery_run_id -> discovery_runs.session_id ->\r\n-- discovery_sessions.organization_id (same pattern as migration 046).\r\n\r\nALTER TABLE discovery_preparation_requests ENABLE ROW LEVEL SECURITY","CREATE POLICY discovery_preparation_requests_select_org ON discovery_preparation_requests\r\n    FOR SELECT\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_runs r\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE r.id = discovery_preparation_requests.discovery_run_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","CREATE POLICY discovery_preparation_requests_insert_org ON discovery_preparation_requests\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_runs r\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE r.id = discovery_preparation_requests.discovery_run_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","-- UPDATE: request lifecycle transitions (status, claimed_at, completed_at,\r\n-- failed_at, output_ref, error) by org members; identity/queue fields\r\n-- (discovery_run_id, artifact_id, layer1_id, request_type, input_hash) are\r\n-- immutable once created.\r\nCREATE POLICY discovery_preparation_requests_update_org ON discovery_preparation_requests\r\n    FOR UPDATE\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_runs r\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE r.id = discovery_preparation_requests.discovery_run_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )\r\n    WITH CHECK (\r\n        discovery_run_id = (SELECT original.discovery_run_id FROM discovery_preparation_requests original WHERE original.request_id = discovery_preparation_requests.request_id)\r\n        AND artifact_id = (SELECT original.artifact_id FROM discovery_preparation_requests original WHERE original.request_id = discovery_preparation_requests.request_id)\r\n        AND layer1_id = (SELECT original.layer1_id FROM discovery_preparation_requests original WHERE original.request_id = discovery_preparation_requests.request_id)\r\n        AND request_type = (SELECT original.request_type FROM discovery_preparation_requests original WHERE original.request_id = discovery_preparation_requests.request_id)\r\n    )","-- ============================================================================\r\n-- END OF MIGRATION 047\r\n-- ============================================================================"}	phase8_claims_and_views
048	{"-- ============================================================================\r\n-- KADARN PLATFORM — Discovery Agent Outputs (Sprint 20A.4A)\r\n-- ============================================================================\r\n-- Stores structured outputs from Discovery Agents (Document Classifier,\r\n-- Entity Extractor, Claim Detector, etc.).\r\n-- Agents NEVER write to Evidence Core.\r\n-- ============================================================================\r\n\r\nCREATE TABLE IF NOT EXISTS discovery_agent_outputs (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    request_id          UUID NOT NULL REFERENCES discovery_preparation_requests(request_id),\r\n    agent_name          TEXT NOT NULL,\r\n    agent_version       TEXT NOT NULL,\r\n    status              TEXT NOT NULL CHECK (status IN ('COMPLETED', 'FAILED', 'SKIPPED')),\r\n    output              JSONB NOT NULL DEFAULT '{}',\r\n    confidence          NUMERIC(5,3) NOT NULL DEFAULT 0,\r\n    warnings            JSONB NOT NULL DEFAULT '[]',\r\n    provenance          JSONB NOT NULL DEFAULT '{}',\r\n\r\n    -- Traceability\r\n    layer1_id           UUID NOT NULL REFERENCES discovery_layer1(id),\r\n    artifact_id         UUID NOT NULL REFERENCES discovery_artifacts(id),\r\n\r\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\r\n)","CREATE INDEX idx_agent_outputs_request ON discovery_agent_outputs(request_id)","CREATE INDEX idx_agent_outputs_agent ON discovery_agent_outputs(agent_name)","-- ############################################################################\r\n-- ROW-LEVEL SECURITY\r\n-- ############################################################################\r\n-- Org-scoped via artifact_id -> discovery_artifacts.run_id ->\r\n-- discovery_runs.session_id -> discovery_sessions.organization_id.\r\n-- Agent outputs are immutable once written (no UPDATE/DELETE policy) —\r\n-- agents never write to Evidence Core and never revise their own outputs.\r\n\r\nALTER TABLE discovery_agent_outputs ENABLE ROW LEVEL SECURITY","CREATE POLICY discovery_agent_outputs_select_org ON discovery_agent_outputs\r\n    FOR SELECT\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_artifacts a\r\n            JOIN discovery_runs r ON r.id = a.run_id\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE a.id = discovery_agent_outputs.artifact_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","CREATE POLICY discovery_agent_outputs_insert_org ON discovery_agent_outputs\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_artifacts a\r\n            JOIN discovery_runs r ON r.id = a.run_id\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE a.id = discovery_agent_outputs.artifact_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","-- ============================================================================\r\n-- END OF MIGRATION 048\r\n-- ============================================================================"}	phase8_hybrid_index
049	{"-- ============================================================================\r\n-- KADARN PLATFORM — Discovery Curation Events (Sprint 20A.6)\r\n-- ============================================================================\r\n-- Curation is NOT promotion. Curation does not write to Evidence Core.\r\n-- Every curation action is an immutable provenance event.\r\n-- ============================================================================\r\n\r\nDO $$ BEGIN\r\n    CREATE TYPE curation_action AS ENUM (\r\n        'ACCEPT', 'REJECT', 'ENRICH', 'DEFER',\r\n        'NEEDS_MORE_EVIDENCE', 'MERGE', 'SPLIT', 'ARCHIVE'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE curation_target_type AS ENUM (\r\n        'EVIDENCE_CANDIDATE', 'CLASSIFICATION', 'ENTITY', 'RELATIONSHIP',\r\n        'SNAPSHOT_ITEM'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","CREATE TABLE IF NOT EXISTS discovery_curation_events (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    target_type         curation_target_type NOT NULL,\r\n    target_id           TEXT NOT NULL,\r\n    action              curation_action NOT NULL,\r\n\r\n    -- Actor\r\n    actor_id            TEXT NOT NULL,\r\n    actor_role          TEXT NOT NULL DEFAULT 'reviewer',\r\n\r\n    -- Provenance\r\n    reason              TEXT,\r\n    enrichment_payload  JSONB,\r\n    previous_state      TEXT,\r\n    new_state           TEXT,\r\n    provenance_ref      TEXT NOT NULL,\r\n    discovery_run_id    UUID NOT NULL REFERENCES discovery_runs(id),\r\n    artifact_id         TEXT,\r\n    layer1_id           TEXT,\r\n\r\n    -- Merge/split\r\n    merge_source_ids    JSONB,\r\n    split_child_ids     JSONB,\r\n\r\n    -- Temporal\r\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()\r\n)","CREATE INDEX idx_curation_target ON discovery_curation_events(target_type, target_id)","CREATE INDEX idx_curation_run ON discovery_curation_events(discovery_run_id)","-- ############################################################################\r\n-- ROW-LEVEL SECURITY\r\n-- ############################################################################\r\n-- Org-scoped via discovery_run_id -> discovery_runs.session_id ->\r\n-- discovery_sessions.organization_id. Curation events are immutable\r\n-- provenance records (no UPDATE/DELETE policy) — curation never rewrites\r\n-- history, it only appends new events.\r\n\r\nALTER TABLE discovery_curation_events ENABLE ROW LEVEL SECURITY","CREATE POLICY discovery_curation_events_select_org ON discovery_curation_events\r\n    FOR SELECT\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_runs r\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE r.id = discovery_curation_events.discovery_run_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","CREATE POLICY discovery_curation_events_insert_org ON discovery_curation_events\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        EXISTS (\r\n            SELECT 1 FROM discovery_runs r\r\n            JOIN discovery_sessions s ON s.id = r.session_id\r\n            WHERE r.id = discovery_curation_events.discovery_run_id\r\n            AND s.organization_id IN (\r\n                SELECT organization_id FROM organization_memberships\r\n                WHERE user_id = auth.uid() AND status = 'active'\r\n            )\r\n        )\r\n    )","-- ============================================================================\r\n-- END OF MIGRATION 049\r\n-- ============================================================================"}	phase8_staging_cutover_seed
056	{"-- Phase 8 Sprint 28K — grants for server-side public reads and authenticated discovery routes\r\n-- Made idempotent: wraps GRANT in table-existence checks\r\n\r\nDO $$ BEGIN\r\n    IF EXISTS (SELECT 1 FROM pg_class WHERE relname = 'organizations' AND relnamespace = 'public'::regnamespace) THEN\r\n        GRANT SELECT ON public.organizations TO service_role, authenticated;\r\n    END IF;\r\n    IF EXISTS (SELECT 1 FROM pg_class WHERE relname = 'discovery_sessions' AND relnamespace = 'public'::regnamespace) THEN\r\n        GRANT SELECT ON public.discovery_sessions TO service_role, authenticated;\r\n    END IF;\r\n    IF EXISTS (SELECT 1 FROM pg_class WHERE relname = 'discovery_runs' AND relnamespace = 'public'::regnamespace) THEN\r\n        GRANT SELECT ON public.discovery_runs TO service_role, authenticated;\r\n    END IF;\r\n    IF EXISTS (SELECT 1 FROM pg_class WHERE relname = 'discovery_artifacts' AND relnamespace = 'public'::regnamespace) THEN\r\n        GRANT SELECT ON public.discovery_artifacts TO service_role, authenticated;\r\n    END IF;\r\n    IF EXISTS (SELECT 1 FROM pg_class WHERE relname = 'discovery_agent_outputs' AND relnamespace = 'public'::regnamespace) THEN\r\n        GRANT SELECT ON public.discovery_agent_outputs TO service_role, authenticated;\r\n    END IF;\r\n    IF EXISTS (SELECT 1 FROM pg_class WHERE relname = 'discovery_candidates' AND relnamespace = 'public'::regnamespace) THEN\r\n        GRANT SELECT ON public.discovery_candidates TO service_role, authenticated;\r\n    END IF;\r\n    IF EXISTS (SELECT 1 FROM pg_class WHERE relname = 'discovery_curation_events' AND relnamespace = 'public'::regnamespace) THEN\r\n        GRANT SELECT ON public.discovery_curation_events TO service_role, authenticated;\r\n    END IF;\r\n    IF EXISTS (SELECT 1 FROM pg_class WHERE relname = 'discovery_validation_notes' AND relnamespace = 'public'::regnamespace) THEN\r\n        GRANT SELECT ON public.discovery_validation_notes TO service_role, authenticated;\r\n    END IF;\r\n    IF EXISTS (SELECT 1 FROM pg_class WHERE relname = 'organization_memberships' AND relnamespace = 'public'::regnamespace) THEN\r\n        GRANT SELECT ON public.organization_memberships TO service_role, authenticated;\r\n    END IF;\r\n    IF EXISTS (SELECT 1 FROM pg_class WHERE relname = 'membership_roles' AND relnamespace = 'public'::regnamespace) THEN\r\n        GRANT SELECT ON public.membership_roles TO service_role, authenticated;\r\n    END IF;\r\n    IF EXISTS (SELECT 1 FROM pg_class WHERE relname = 'organization_roles' AND relnamespace = 'public'::regnamespace) THEN\r\n        GRANT SELECT ON public.organization_roles TO service_role, authenticated;\r\n    END IF;\r\nEND $$"}	phase8_public_read_grants
057	{"-- ============================================================================\r\n-- Phase 8 Remediation S-1 — GoTrue compatibility for SQL-seeded auth users\r\n-- Fixes existing rows + replaces admin_create_user for fresh seeds.\r\n-- ============================================================================\r\n\r\nCREATE OR REPLACE FUNCTION public.admin_create_user(\r\n    p_email TEXT,\r\n    p_password TEXT,\r\n    p_full_name TEXT,\r\n    p_organization_id UUID DEFAULT NULL\r\n)\r\nRETURNS UUID\r\nSECURITY DEFINER\r\nSET search_path = public\r\nLANGUAGE plpgsql\r\nAS $$\r\nDECLARE\r\n    v_user_id UUID;\r\nBEGIN\r\n    IF auth.role() IS DISTINCT FROM NULL\r\n       AND auth.role() != ''\r\n       AND auth.role() != 'service_role'\r\n       AND auth.role() != 'superuser' THEN\r\n        RAISE EXCEPTION 'Only service_role can create users directly';\r\n    END IF;\r\n\r\n    v_user_id := gen_random_uuid();\r\n\r\n    INSERT INTO auth.users (\r\n        id, instance_id, email, encrypted_password, email_confirmed_at,\r\n        confirmation_token, recovery_token, email_change_token_new, email_change,\r\n        email_change_token_current, reauthentication_token, phone_change, phone_change_token,\r\n        raw_app_meta_data, raw_user_meta_data,\r\n        aud, role, is_sso_user, is_anonymous, created_at, updated_at\r\n    ) VALUES (\r\n        v_user_id,\r\n        '00000000-0000-0000-0000-000000000000',\r\n        p_email,\r\n        extensions.crypt(p_password, extensions.gen_salt('bf', 10)),\r\n        now(),\r\n        '', '', '', '',\r\n        '', '', '', '',\r\n        jsonb_build_object(\r\n            'provider', 'email',\r\n            'providers', ARRAY['email']\r\n        ),\r\n        jsonb_build_object(\r\n            'full_name', p_full_name,\r\n            'organization_id', p_organization_id::text\r\n        ),\r\n        'authenticated', 'authenticated',\r\n        false, false,\r\n        now(), now()\r\n    );\r\n\r\n    INSERT INTO auth.identities (\r\n        id, user_id, identity_data, provider, provider_id,\r\n        last_sign_in_at, created_at, updated_at\r\n    ) VALUES (\r\n        v_user_id, v_user_id,\r\n        jsonb_build_object(\r\n            'sub', v_user_id::text,\r\n            'email', p_email,\r\n            'email_verified', true,\r\n            'full_name', p_full_name,\r\n            'phone_verified', false\r\n        ),\r\n        'email', v_user_id::text,\r\n        now(), now(), now()\r\n    )\r\n    ON CONFLICT (provider_id, provider) DO NOTHING;\r\n\r\n    INSERT INTO public.user_profiles (id, email, full_name)\r\n    VALUES (v_user_id, p_email, p_full_name)\r\n    ON CONFLICT (id) DO NOTHING;\r\n\r\n    IF p_organization_id IS NOT NULL THEN\r\n        INSERT INTO public.organization_memberships (\r\n            user_id, organization_id, status, invited_by, invited_at, joined_at\r\n        ) VALUES (\r\n            v_user_id, p_organization_id, 'active', v_user_id, now(), now()\r\n        )\r\n        ON CONFLICT (user_id, organization_id) DO NOTHING;\r\n    END IF;\r\n\r\n    RETURN v_user_id;\r\nEND;\r\n$$","UPDATE auth.users SET\r\n    instance_id = COALESCE(instance_id, '00000000-0000-0000-0000-000000000000'::uuid),\r\n    confirmation_token = COALESCE(confirmation_token, ''),\r\n    recovery_token = COALESCE(recovery_token, ''),\r\n    email_change_token_new = COALESCE(email_change_token_new, ''),\r\n    email_change = COALESCE(email_change, ''),\r\n    email_change_token_current = COALESCE(email_change_token_current, ''),\r\n    reauthentication_token = COALESCE(reauthentication_token, ''),\r\n    phone_change = COALESCE(phone_change, ''),\r\n    phone_change_token = COALESCE(phone_change_token, '')\r\nWHERE instance_id IS NULL\r\n   OR confirmation_token IS NULL\r\n   OR recovery_token IS NULL"}	gotrue_seed_compat
058	{"-- ============================================================================\r\n-- Phase 8 Remediation S-2 — RLS + grants for Phase 8 and Evidence Core\r\n-- Security only — no write pipeline / native cutover (P4 optional).\r\n-- ============================================================================\r\n-- Made idempotent: wraps GRANT/ALTER/CREATE in table-existence checks\r\n-- so the migration does not fail on databases where phase8 tables\r\n-- were not created (discovery core, evidence lineage, etc.).\r\n-- ============================================================================\r\n\r\n-- Evidence Core 045 — table privileges (RLS policies exist in 045)\r\nGRANT SELECT, INSERT, UPDATE ON public.claims TO authenticated, service_role","GRANT SELECT, INSERT, UPDATE ON public.evidence_nodes TO authenticated, service_role","GRANT SELECT, INSERT, UPDATE ON public.evidence_relationships TO authenticated, service_role","GRANT SELECT, INSERT, UPDATE ON public.right_of_response TO authenticated, service_role","GRANT SELECT ON public.confidence_state_snapshots TO authenticated, service_role","GRANT SELECT ON public.evidence_class_ref TO authenticated, service_role"}	phase8_rls_and_evidence_grants
059	{"-- ============================================================================\r\n-- RC-12.1B - Sponsor Portfolio Persistence\r\n-- ============================================================================\r\n-- Purpose:\r\n--   Replace temporary Sponsor Passport portfolio allowlists with persistent,\r\n--   sponsor-owned portfolio infrastructure.\r\n--\r\n-- Boundaries:\r\n--   - Does NOT change RC-10.2 Sponsor Passport contract.\r\n--   - Does NOT change Sponsor UI.\r\n--   - Does NOT change Evidence Core claim/evidence ownership.\r\n--   - Portfolio is access scope, not evidence truth.\r\n--\r\n-- Dependencies:\r\n--   - public.organizations\r\n--   - public.organization_memberships\r\n-- ============================================================================\r\n\r\n-- ############################################################################\r\n-- PART 1: ENUMS\r\n-- ############################################################################\r\n\r\nDO $$ BEGIN\r\n    CREATE TYPE sponsor_portfolio_status AS ENUM (\r\n        'active',\r\n        'archived'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE sponsor_portfolio_membership_status AS ENUM (\r\n        'active',\r\n        'paused',\r\n        'removed'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","-- ############################################################################\r\n-- PART 2: TABLE - sponsor_portfolios\r\n-- ############################################################################\r\n--\r\n-- Root aggregate for a sponsor-owned portfolio. A portfolio is an access and\r\n-- working-set construct. It does not own institutional claims or evidence.\r\n-- ============================================================================\r\n\r\nCREATE TABLE IF NOT EXISTS public.sponsor_portfolios (\r\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    sponsor_org_id  UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n\r\n    name            TEXT NOT NULL DEFAULT 'Sponsor Portfolio',\r\n    status          sponsor_portfolio_status NOT NULL DEFAULT 'active',\r\n    version         INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),\r\n\r\n    created_by      UUID,\r\n    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    archived_at     TIMESTAMPTZ,\r\n    metadata        JSONB NOT NULL DEFAULT '{}',\r\n\r\n    CONSTRAINT uq_sponsor_portfolios_id_owner UNIQUE (id, sponsor_org_id),\r\n    CONSTRAINT ck_sponsor_portfolios_archived_at\r\n        CHECK (\r\n            (status = 'archived' AND archived_at IS NOT NULL)\r\n            OR (status = 'active' AND archived_at IS NULL)\r\n        )\r\n)","CREATE UNIQUE INDEX IF NOT EXISTS uq_sponsor_portfolios_active_owner\r\n    ON public.sponsor_portfolios(sponsor_org_id)\r\n    WHERE status = 'active'","CREATE INDEX IF NOT EXISTS idx_sponsor_portfolios_sponsor_status\r\n    ON public.sponsor_portfolios(sponsor_org_id, status)","CREATE INDEX IF NOT EXISTS idx_sponsor_portfolios_updated_at\r\n    ON public.sponsor_portfolios(updated_at DESC)","COMMENT ON TABLE public.sponsor_portfolios IS\r\n    'Sponsor-owned portfolio aggregate for Sponsor Passport access scope.'","COMMENT ON COLUMN public.sponsor_portfolios.sponsor_org_id IS\r\n    'Organization that owns the sponsor portfolio.'","-- ############################################################################\r\n-- PART 3: TABLE - sponsor_portfolio_memberships\r\n-- ############################################################################\r\n--\r\n-- Institution/site membership inside a sponsor portfolio. institution_org_id is\r\n-- the organization_id used by Evidence Core claim/evidence reads.\r\n-- ============================================================================\r\n\r\nCREATE TABLE IF NOT EXISTS public.sponsor_portfolio_memberships (\r\n    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    portfolio_id          UUID NOT NULL,\r\n    sponsor_org_id        UUID NOT NULL,\r\n    institution_org_id    UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n\r\n    status                sponsor_portfolio_membership_status NOT NULL DEFAULT 'active',\r\n    member_since          DATE NOT NULL DEFAULT CURRENT_DATE,\r\n    display_name_override TEXT,\r\n    location_override     TEXT,\r\n    version               INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),\r\n\r\n    created_by            UUID,\r\n    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    removed_at            TIMESTAMPTZ,\r\n    metadata              JSONB NOT NULL DEFAULT '{}',\r\n\r\n    CONSTRAINT fk_sponsor_portfolio_memberships_portfolio_owner\r\n        FOREIGN KEY (portfolio_id, sponsor_org_id)\r\n        REFERENCES public.sponsor_portfolios(id, sponsor_org_id)\r\n        ON DELETE CASCADE,\r\n\r\n    CONSTRAINT ck_sponsor_portfolio_memberships_distinct_orgs\r\n        CHECK (sponsor_org_id <> institution_org_id),\r\n\r\n    CONSTRAINT ck_sponsor_portfolio_memberships_removed_at\r\n        CHECK (\r\n            (status = 'removed' AND removed_at IS NOT NULL)\r\n            OR (status <> 'removed' AND removed_at IS NULL)\r\n        )\r\n)","CREATE UNIQUE INDEX IF NOT EXISTS uq_sponsor_portfolio_memberships_active_portfolio_institution\r\n    ON public.sponsor_portfolio_memberships(portfolio_id, institution_org_id)\r\n    WHERE status = 'active'","CREATE UNIQUE INDEX IF NOT EXISTS uq_sponsor_portfolio_memberships_active_sponsor_institution\r\n    ON public.sponsor_portfolio_memberships(sponsor_org_id, institution_org_id)\r\n    WHERE status = 'active'","CREATE INDEX IF NOT EXISTS idx_sponsor_portfolio_memberships_sponsor_status\r\n    ON public.sponsor_portfolio_memberships(sponsor_org_id, status)","CREATE INDEX IF NOT EXISTS idx_sponsor_portfolio_memberships_portfolio_status\r\n    ON public.sponsor_portfolio_memberships(portfolio_id, status)","CREATE INDEX IF NOT EXISTS idx_sponsor_portfolio_memberships_institution\r\n    ON public.sponsor_portfolio_memberships(institution_org_id)","CREATE INDEX IF NOT EXISTS idx_sponsor_portfolio_memberships_updated_at\r\n    ON public.sponsor_portfolio_memberships(updated_at DESC)","COMMENT ON TABLE public.sponsor_portfolio_memberships IS\r\n    'Institutions/sites included in a sponsor-owned portfolio for Sponsor Passport access scope.'","COMMENT ON COLUMN public.sponsor_portfolio_memberships.institution_org_id IS\r\n    'Institution/site organization ID used by Evidence Core reads.'","-- ############################################################################\r\n-- PART 4: TRIGGERS - updated_at\r\n-- ############################################################################\r\n\r\nDROP TRIGGER IF EXISTS trg_sponsor_portfolios_updated_at ON public.sponsor_portfolios","CREATE TRIGGER trg_sponsor_portfolios_updated_at\r\n    BEFORE UPDATE ON public.sponsor_portfolios\r\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","DROP TRIGGER IF EXISTS trg_sponsor_portfolio_memberships_updated_at ON public.sponsor_portfolio_memberships","CREATE TRIGGER trg_sponsor_portfolio_memberships_updated_at\r\n    BEFORE UPDATE ON public.sponsor_portfolio_memberships\r\n    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","-- ############################################################################\r\n-- PART 5: ROW-LEVEL SECURITY\r\n-- ############################################################################\r\n\r\nALTER TABLE public.sponsor_portfolios ENABLE ROW LEVEL SECURITY","ALTER TABLE public.sponsor_portfolio_memberships ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS sponsor_portfolios_select_org ON public.sponsor_portfolios","CREATE POLICY sponsor_portfolios_select_org ON public.sponsor_portfolios\r\n    FOR SELECT\r\n    USING (\r\n        sponsor_org_id IN (\r\n            SELECT organization_id FROM public.organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n        OR auth.role() = 'service_role'\r\n    )","DROP POLICY IF EXISTS sponsor_portfolio_memberships_select_org ON public.sponsor_portfolio_memberships","CREATE POLICY sponsor_portfolio_memberships_select_org ON public.sponsor_portfolio_memberships\r\n    FOR SELECT\r\n    USING (\r\n        sponsor_org_id IN (\r\n            SELECT organization_id FROM public.organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n        OR auth.role() = 'service_role'\r\n    )","-- ############################################################################\r\n-- PART 6: GRANTS\r\n-- ############################################################################\r\n\r\nGRANT SELECT ON public.sponsor_portfolios TO authenticated, service_role","GRANT SELECT ON public.sponsor_portfolio_memberships TO authenticated, service_role","GRANT INSERT, UPDATE ON public.sponsor_portfolios TO service_role","GRANT INSERT, UPDATE ON public.sponsor_portfolio_memberships TO service_role"}	sponsor_portfolio
060	{"-- ============================================================================\r\n-- KADARN PLATFORM — Review Workflow (Evidence Intelligence vertical slice)\r\n-- ============================================================================\r\n-- Creates the review workflow layer on top of evidence-core.\r\n-- Separates workflow state from entity status.\r\n-- ============================================================================\r\n\r\n-- ############################################################################\r\n-- PART 1: ENUMS\r\n-- ############################################################################\r\n\r\nDO $$ BEGIN\r\n    CREATE TYPE review_task_type AS ENUM (\r\n        'classification',\r\n        'extraction_review',\r\n        'evidence_review',\r\n        'confidence_review',\r\n        'publication_review',\r\n        'dispute_review'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE review_task_status AS ENUM (\r\n        'pending',\r\n        'in_progress',\r\n        'completed',\r\n        'skipped',\r\n        'cancelled'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE workflow_state AS ENUM (\r\n        'draft',\r\n        'declared',\r\n        'pending_evidence',\r\n        'under_review',\r\n        'published',\r\n        'disputed',\r\n        'archived'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","-- ############################################################################\r\n-- PART 2: WORKFLOW STATES (per claim — additive to claim.status)\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS claim_workflow (\r\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    claim_id        UUID NOT NULL REFERENCES public.claims(id) ON DELETE CASCADE,\r\n    workflow_state  workflow_state NOT NULL DEFAULT 'draft',\r\n    entered_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    entered_by      UUID,\r\n    reason          TEXT,\r\n    UNIQUE(claim_id, workflow_state)\r\n)","-- Current workflow state (materialized for fast lookup)\r\nALTER TABLE public.claims ADD COLUMN IF NOT EXISTS workflow_state workflow_state NOT NULL DEFAULT 'draft'","-- ############################################################################\r\n-- PART 3: REVIEW TASKS\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS review_tasks (\r\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    organization_id UUID NOT NULL REFERENCES organizations(id),\r\n    claim_id        UUID REFERENCES public.claims(id),\r\n    evidence_node_id UUID REFERENCES public.evidence_nodes(id),\r\n    task_type       review_task_type NOT NULL,\r\n    status          review_task_status NOT NULL DEFAULT 'pending',\r\n    assigned_to     UUID,\r\n    assigned_at     TIMESTAMPTZ,\r\n    completed_at    TIMESTAMPTZ,\r\n    completed_by    UUID,\r\n    notes           TEXT,\r\n    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    created_by      UUID NOT NULL\r\n)","CREATE INDEX IF NOT EXISTS idx_review_tasks_org_status ON review_tasks(organization_id, status)","CREATE INDEX IF NOT EXISTS idx_review_tasks_claim ON review_tasks(claim_id)","-- ############################################################################\r\n-- PART 4: RLS\r\n-- ############################################################################\r\n\r\nALTER TABLE review_tasks ENABLE ROW LEVEL SECURITY","ALTER TABLE claim_workflow ENABLE ROW LEVEL SECURITY","-- Organization-scoped access\r\nCREATE POLICY review_tasks_org_access ON review_tasks\r\n    USING (organization_id = (auth.jwt() ->> 'organization_id'::text)::UUID)","CREATE POLICY claim_workflow_org_access ON claim_workflow\r\n    USING (claim_id IN (\r\n        SELECT id FROM public.claims WHERE organization_id = (auth.jwt() ->> 'organization_id'::text)::UUID\r\n    ))"}	review_workflow
061	{"-- ============================================================================\r\n-- KADARN PLATFORM — Passport Publication (Evidence Intelligence vertical slice)\r\n-- ============================================================================\r\n-- Enables selective claim publication with per-unit disclosure.\r\n-- ============================================================================\r\n\r\n-- ############################################################################\r\n-- PART 1: ENUMS\r\n-- ############################################################################\r\n\r\nDO $$ BEGIN\r\n    CREATE TYPE publication_status AS ENUM (\r\n        'draft',\r\n        'published',\r\n        'restricted',\r\n        'withdrawn'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","-- ############################################################################\r\n-- PART 2: PASSPORT ENTRIES\r\n-- ############################################################################\r\n-- Each entry represents a claim published to a specific audience.\r\n\r\nCREATE TABLE IF NOT EXISTS passport_entries (\r\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    organization_id UUID NOT NULL REFERENCES organizations(id),\r\n    claim_id        UUID NOT NULL REFERENCES public.claims(id),\r\n    publication_status publication_status NOT NULL DEFAULT 'draft',\r\n    visibility_scope   visibility_scope NOT NULL DEFAULT 'site',\r\n    authorized_sponsor_ids UUID[] DEFAULT '{}',\r\n    published_at     TIMESTAMPTZ,\r\n    published_by     UUID,\r\n    withdrawn_at     TIMESTAMPTZ,\r\n    withdrawn_by     UUID,\r\n    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    UNIQUE(claim_id, visibility_scope)\r\n)","CREATE INDEX IF NOT EXISTS idx_passport_entries_org ON passport_entries(organization_id)","CREATE INDEX IF NOT EXISTS idx_passport_entries_status ON passport_entries(publication_status)","-- ############################################################################\r\n-- PART 3: PASSPORT SHARES (explicit grant to a sponsor)\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS passport_shares (\r\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    passport_entry_id UUID NOT NULL REFERENCES passport_entries(id) ON DELETE CASCADE,\r\n    sponsor_organization_id UUID NOT NULL,\r\n    granted_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    granted_by      UUID NOT NULL,\r\n    expires_at      TIMESTAMPTZ,\r\n    revoked_at      TIMESTAMPTZ,\r\n    UNIQUE(passport_entry_id, sponsor_organization_id)\r\n)","-- ############################################################################\r\n-- PART 4: RLS\r\n-- ############################################################################\r\n\r\nALTER TABLE passport_entries ENABLE ROW LEVEL SECURITY","ALTER TABLE passport_shares ENABLE ROW LEVEL SECURITY","CREATE POLICY passport_entries_org ON passport_entries\r\n    USING (organization_id = (auth.jwt() ->> 'organization_id'::text)::UUID)","CREATE POLICY passport_shares_org ON passport_shares\r\n    USING (passport_entry_id IN (\r\n        SELECT id FROM passport_entries\r\n        WHERE organization_id = (auth.jwt() ->> 'organization_id'::text)::UUID\r\n    ))"}	passport_publication
062	{"-- ============================================================================\r\n-- KAD-002A — Person Entity\r\n-- ============================================================================\r\n-- Authority: Foundation Library 016_CANONICAL_ENTITY_SPECIFICATIONS\r\n-- Person represents a natural person who can act within the KADARN ecosystem.\r\n-- A Person is NOT an auth user — auth.users handles authentication.\r\n-- A Person is a domain entity that MAY be linked to an auth user.\r\n-- ============================================================================\r\n\r\n-- ############################################################################\r\n-- ENUMS\r\n-- ############################################################################\r\n\r\nDO $$ BEGIN\r\n    CREATE TYPE person_status AS ENUM (\r\n        'active',\r\n        'inactive',\r\n        'suspended',\r\n        'merged'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE person_role_type AS ENUM (\r\n        'pi',\r\n        'sub_investigator',\r\n        'coordinator',\r\n        'reviewer',\r\n        'approver',\r\n        'contact',\r\n        'administrator',\r\n        'owner'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","-- ############################################################################\r\n-- TABLE: people\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS public.people (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n\r\n    -- Identity\r\n    email               TEXT NOT NULL,\r\n    first_name          TEXT NOT NULL,\r\n    last_name           TEXT NOT NULL,\r\n    middle_name         TEXT,\r\n    suffix              TEXT,\r\n\r\n    -- Contact\r\n    phone               TEXT,\r\n\r\n    -- Professional identifiers\r\n    orcid               TEXT,\r\n    npi                 TEXT,\r\n\r\n    -- Profile\r\n    profile_photo_url   TEXT,\r\n\r\n    -- Status\r\n    status              person_status NOT NULL DEFAULT 'active',\r\n\r\n    -- Link to auth user (optional — not all People are authenticated)\r\n    auth_user_id        UUID REFERENCES auth.users(id) ON DELETE SET NULL,\r\n\r\n    -- Temporal\r\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    -- Constraints\r\n    CONSTRAINT uq_people_email UNIQUE (email),\r\n    CONSTRAINT uq_people_orcid UNIQUE (orcid),\r\n    CONSTRAINT uq_people_npi UNIQUE (npi)\r\n)","-- ############################################################################\r\n-- INDEXES\r\n-- ############################################################################\r\n\r\nCREATE INDEX idx_people_email ON public.people(email)","CREATE INDEX idx_people_name ON public.people(last_name, first_name)","CREATE INDEX idx_people_status ON public.people(status)","CREATE INDEX idx_people_auth_user ON public.people(auth_user_id)","-- ############################################################################\r\n-- TRIGGER: updated_at\r\n-- ############################################################################\r\n\r\nCREATE OR REPLACE FUNCTION trigger_set_updated_at()\r\nRETURNS TRIGGER AS $$\r\nBEGIN\r\n    NEW.updated_at = now();\r\n    RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql","DROP TRIGGER IF EXISTS trg_people_updated_at ON public.people","CREATE TRIGGER trg_people_updated_at\r\n    BEFORE UPDATE ON public.people\r\n    FOR EACH ROW EXECUTE FUNCTION trigger_set_updated_at()","-- ############################################################################\r\n-- RLS\r\n-- ############################################################################\r\n\r\nALTER TABLE public.people ENABLE ROW LEVEL SECURITY","-- People can read their own record\r\nCREATE POLICY people_select_self ON public.people\r\n    FOR SELECT\r\n    USING (auth.uid() = auth_user_id)","-- Service role can read all people\r\nCREATE POLICY people_select_service ON public.people\r\n    FOR SELECT\r\n    USING (auth.role() = 'service_role')","-- People can update their own record\r\nCREATE POLICY people_update_self ON public.people\r\n    FOR UPDATE\r\n    USING (auth.uid() = auth_user_id)\r\n    WITH CHECK (auth.uid() = auth_user_id)","-- Service role can manage all people\r\nCREATE POLICY people_all_service ON public.people\r\n    FOR ALL\r\n    USING (auth.role() = 'service_role')","-- ############################################################################\r\n-- GRANTS\r\n-- ############################################################################\r\n\r\nGRANT SELECT, INSERT, UPDATE ON public.people TO authenticated, service_role","GRANT DELETE ON public.people TO service_role"}	kad002a_person
063	{"-- ============================================================================\r\n-- KAD-002B — Location Entity\r\n-- ============================================================================\r\n-- Authority: Foundation Library 016_CANONICAL_ENTITY_SPECIFICATIONS\r\n-- Location represents a physical location belonging to an Institution.\r\n-- A Location belongs to exactly one Institution (organizations table).\r\n-- ============================================================================\r\n\r\n-- ############################################################################\r\n-- ENUMS\r\n-- ############################################################################\r\n\r\nDO $$ BEGIN\r\n    CREATE TYPE location_type AS ENUM (\r\n        'clinic',\r\n        'laboratory',\r\n        'warehouse',\r\n        'phase1_unit',\r\n        'office',\r\n        'pharmacy',\r\n        'storage',\r\n        'other'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","DO $$ BEGIN\r\n    CREATE TYPE location_status AS ENUM (\r\n        'active',\r\n        'inactive',\r\n        'under_maintenance',\r\n        'decommissioned'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","-- ############################################################################\r\n-- TABLE: locations\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS public.locations (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n\r\n    -- Identity\r\n    name                TEXT NOT NULL,\r\n    location_type       location_type NOT NULL DEFAULT 'other',\r\n\r\n    -- Ownership\r\n    institution_id      UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n\r\n    -- Address\r\n    address_line1       TEXT NOT NULL,\r\n    address_line2       TEXT,\r\n    city                TEXT NOT NULL,\r\n    state_province      TEXT NOT NULL,\r\n    postal_code         TEXT NOT NULL,\r\n    country             TEXT NOT NULL,\r\n\r\n    -- Contact\r\n    phone               TEXT,\r\n\r\n    -- Time zone\r\n    timezone            TEXT,\r\n\r\n    -- Geo (optional)\r\n    latitude            NUMERIC(10,7),\r\n    longitude           NUMERIC(10,7),\r\n\r\n    -- Status\r\n    status              location_status NOT NULL DEFAULT 'active',\r\n\r\n    -- Temporal\r\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    -- Constraints\r\n    CONSTRAINT uq_location_institution_name UNIQUE (institution_id, name)\r\n)","-- ############################################################################\r\n-- INDEXES\r\n-- ############################################################################\r\n\r\nCREATE INDEX idx_locations_institution ON public.locations(institution_id)","CREATE INDEX idx_locations_type ON public.locations(location_type)","CREATE INDEX idx_locations_status ON public.locations(status)","CREATE INDEX idx_locations_country ON public.locations(country)","-- ############################################################################\r\n-- TRIGGER: updated_at\r\n-- ############################################################################\r\n\r\nDROP TRIGGER IF EXISTS trg_locations_updated_at ON public.locations","CREATE TRIGGER trg_locations_updated_at\r\n    BEFORE UPDATE ON public.locations\r\n    FOR EACH ROW EXECUTE FUNCTION trigger_set_updated_at()","-- ############################################################################\r\n-- RLS\r\n-- ############################################################################\r\n\r\nALTER TABLE public.locations ENABLE ROW LEVEL SECURITY","-- Members of an institution can read its locations\r\nCREATE POLICY locations_select_org ON public.locations\r\n    FOR SELECT\r\n    USING (\r\n        institution_id IN (\r\n            SELECT organization_id FROM public.organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n        OR auth.role() = 'service_role'\r\n    )","-- Members can create locations for their institution\r\nCREATE POLICY locations_insert_org ON public.locations\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        institution_id IN (\r\n            SELECT organization_id FROM public.organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n        OR auth.role() = 'service_role'\r\n    )","-- Members can update their institution's locations\r\nCREATE POLICY locations_update_org ON public.locations\r\n    FOR UPDATE\r\n    USING (\r\n        institution_id IN (\r\n            SELECT organization_id FROM public.organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n        OR auth.role() = 'service_role'\r\n    )","-- Service role can manage all locations\r\nCREATE POLICY locations_all_service ON public.locations\r\n    FOR ALL\r\n    USING (auth.role() = 'service_role')","-- ############################################################################\r\n-- GRANTS\r\n-- ############################################################################\r\n\r\nGRANT SELECT, INSERT, UPDATE ON public.locations TO authenticated, service_role","GRANT DELETE ON public.locations TO service_role"}	kad002b_location
064	{"-- ============================================================================\r\n-- KAD-002C — Institution Participation Model\r\n-- ============================================================================\r\n-- Authority: Foundation Library 016_CANONICAL_ENTITY_SPECIFICATIONS\r\n-- Establishes the Membership + Role model:\r\n--   Person ──Membership── Institution\r\n--   Membership ──RoleAssignment── Role\r\n-- ============================================================================\r\n\r\n-- ############################################################################\r\n-- ENUMS\r\n-- ############################################################################\r\n\r\nDO $$ BEGIN\r\n    CREATE TYPE membership_status AS ENUM (\r\n        'invited',\r\n        'active',\r\n        'suspended',\r\n        'terminated',\r\n        'expired'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","-- ############################################################################\r\n-- EXTEND organization_memberships\r\n-- ############################################################################\r\n\r\n-- Add person_id FK to link to canonical people table\r\nALTER TABLE public.organization_memberships\r\n    ADD COLUMN IF NOT EXISTS person_id UUID REFERENCES public.people(id) ON DELETE SET NULL","-- Add temporal fields for lifecycle tracking\r\nALTER TABLE public.organization_memberships\r\n    ADD COLUMN IF NOT EXISTS started_at TIMESTAMPTZ,\r\n    ADD COLUMN IF NOT EXISTS ended_at TIMESTAMPTZ","-- Add reason tracking for status transitions\r\nALTER TABLE public.organization_memberships\r\n    ADD COLUMN IF NOT EXISTS suspension_reason TEXT,\r\n    ADD COLUMN IF NOT EXISTS termination_reason TEXT","-- Add deactivated_by for audit trail\r\nALTER TABLE public.organization_memberships\r\n    ADD COLUMN IF NOT EXISTS deactivated_by UUID REFERENCES auth.users(id) ON DELETE SET NULL","-- ############################################################################\r\n-- SEED: Governed Role Catalog (MVP)\r\n-- ############################################################################\r\n\r\n-- Add scope column if not present\r\nALTER TABLE public.organization_roles ADD COLUMN IF NOT EXISTS scope TEXT NOT NULL DEFAULT 'institution'","INSERT INTO public.organization_roles (key, name, description, scope, is_system_role, priority)\r\nVALUES\r\n    ('org_admin', 'Organization Administrator', 'Full workspace access. Can manage members, settings, and all institutional data.', 'institution', true, 100),\r\n    ('org_member', 'Organization Member', 'Standard workspace access. Can create claims, evidence, and view institutional data.', 'institution', true, 90),\r\n    ('site_pi', 'Principal Investigator', 'Can create and verify claims. Responsible for institutional evidence quality.', 'institution', false, 80),\r\n    ('site_coordinator', 'Site Coordinator', 'Can manage evidence submission and review workflows.', 'institution', false, 70),\r\n    ('reviewer', 'Evidence Reviewer', 'Can review and verify evidence. Cannot create claims or manage members.', 'institution', false, 60),\r\n    ('sponsor_viewer', 'Sponsor Viewer', 'Can view published passports and shared evidence for sponsored institutions.', 'sponsor', true, 50)\r\nON CONFLICT (key) DO NOTHING","-- ############################################################################\r\n-- INDEXES\r\n-- ############################################################################\r\n\r\nCREATE INDEX IF NOT EXISTS idx_memberships_person ON public.organization_memberships(person_id)","CREATE INDEX IF NOT EXISTS idx_memberships_status ON public.organization_memberships(status)","CREATE INDEX IF NOT EXISTS idx_memberships_effective ON public.organization_memberships(organization_id, started_at)","CREATE INDEX IF NOT EXISTS idx_roles_key ON public.organization_roles(key)","-- ############################################################################\r\n-- GRANTS\r\n-- ############################################################################\r\n\r\nGRANT SELECT, INSERT, UPDATE ON public.organization_memberships TO authenticated, service_role","GRANT SELECT ON public.organization_roles TO authenticated, service_role","GRANT SELECT, INSERT, DELETE ON public.membership_roles TO authenticated, service_role"}	kad002c_membership
065	{"-- ============================================================================\r\n-- KAD-003 — Capability Model\r\n-- ============================================================================\r\n-- Authority: Foundation Library, KEMS-001\r\n-- Capability is a DERIVED entity from Claims backed by Evidence.\r\n-- A Capability represents a verified institutional capability.\r\n--\r\n-- Relationship:\r\n--   Claim ──derives── Capability ──published_in── Passport\r\n--\r\n-- Capability status follows the Evidence trust chain:\r\n--   declared → evidence_submitted → under_review → verified → published\r\n-- ============================================================================\r\n\r\n-- ############################################################################\r\n-- ENUMS\r\n-- ############################################################################\r\n\r\nDO $$ BEGIN\r\n    CREATE TYPE capability_status AS ENUM (\r\n        'declared',\r\n        'evidence_submitted',\r\n        'under_review',\r\n        'verified',\r\n        'published',\r\n        'deprecated'\r\n    );\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$","-- ############################################################################\r\n-- TABLE: capabilities\r\n-- ############################################################################\r\n\r\nCREATE TABLE IF NOT EXISTS public.capabilities (\r\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n\r\n    -- Identity\r\n    name                TEXT NOT NULL,\r\n    description         TEXT,\r\n    capability_type_id  UUID REFERENCES public.organization_capability_types(id) ON DELETE SET NULL,\r\n    domain              TEXT,\r\n\r\n    -- Ownership\r\n    organization_id     UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,\r\n\r\n    -- Source Claim (the primary claim that established this capability)\r\n    primary_claim_id    UUID REFERENCES public.claims(id) ON DELETE SET NULL,\r\n\r\n    -- Status\r\n    status              capability_status NOT NULL DEFAULT 'declared',\r\n\r\n    -- Confidence (computed from evidence)\r\n    confidence_score    NUMERIC(3,2),\r\n\r\n    -- Temporal\r\n    first_declared_at   TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    last_verified_at    TIMESTAMPTZ,\r\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n\r\n    -- Constraints\r\n    CONSTRAINT uq_capability_org_type UNIQUE (organization_id, capability_type_id)\r\n)","-- ############################################################################\r\n-- INDEXES\r\n-- ############################################################################\r\n\r\nCREATE INDEX idx_capabilities_organization ON public.capabilities(organization_id)","CREATE INDEX idx_capabilities_status ON public.capabilities(status)","CREATE INDEX idx_capabilities_type ON public.capabilities(capability_type_id)","-- ############################################################################\r\n-- TRIGGER: updated_at\r\n-- ############################################################################\r\n\r\nDROP TRIGGER IF EXISTS trg_capabilities_updated_at ON public.capabilities","CREATE TRIGGER trg_capabilities_updated_at\r\n    BEFORE UPDATE ON public.capabilities\r\n    FOR EACH ROW EXECUTE FUNCTION trigger_set_updated_at()","-- ############################################################################\r\n-- RLS\r\n-- ############################################################################\r\n\r\nALTER TABLE public.capabilities ENABLE ROW LEVEL SECURITY","CREATE POLICY capabilities_select_org ON public.capabilities\r\n    FOR SELECT\r\n    USING (\r\n        organization_id IN (\r\n            SELECT organization_id FROM public.organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n        OR auth.role() = 'service_role'\r\n    )","CREATE POLICY capabilities_insert_org ON public.capabilities\r\n    FOR INSERT\r\n    WITH CHECK (\r\n        organization_id IN (\r\n            SELECT organization_id FROM public.organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n        OR auth.role() = 'service_role'\r\n    )","CREATE POLICY capabilities_update_org ON public.capabilities\r\n    FOR UPDATE\r\n    USING (\r\n        organization_id IN (\r\n            SELECT organization_id FROM public.organization_memberships\r\n            WHERE user_id = auth.uid() AND status = 'active'\r\n        )\r\n        OR auth.role() = 'service_role'\r\n    )","CREATE POLICY capabilities_all_service ON public.capabilities\r\n    FOR ALL\r\n    USING (auth.role() = 'service_role')","-- ############################################################################\r\n-- GRANTS\r\n-- ############################################################################\r\n\r\nGRANT SELECT, INSERT, UPDATE ON public.capabilities TO authenticated, service_role","GRANT DELETE ON public.capabilities TO service_role"}	kad003_capability
066	{"-- ============================================================================\r\n-- KAD-004 — Claim Consolidation\r\n-- ============================================================================\r\n-- Authority: KADARN Foundation Library\r\n-- \r\n-- 1. Deprecates continuity_experience_claims in favor of canonical claims table\r\n-- 2. Ensures evidence-core claims table has all required columns\r\n-- 3. No data migration — legacy data remains for backward compatibility\r\n-- ============================================================================\r\n\r\n-- ############################################################################\r\n-- Ensure canonical claims table has all columns needed for unification\r\n-- ############################################################################\r\n\r\nALTER TABLE public.claims ADD COLUMN IF NOT EXISTS person_id UUID REFERENCES public.people(id) ON DELETE SET NULL","ALTER TABLE public.claims ADD COLUMN IF NOT EXISTS tags TEXT","ALTER TABLE public.claims ADD COLUMN IF NOT EXISTS evidence_count INTEGER DEFAULT 0","-- ############################################################################\r\n-- Add indexes on new columns\r\n-- ############################################################################\r\n\r\nCREATE INDEX IF NOT EXISTS idx_claims_person ON public.claims(person_id)","CREATE INDEX IF NOT EXISTS idx_claims_tags ON public.claims USING gin (to_tsvector('simple', COALESCE(tags, '')))","-- ############################################################################\r\n-- Document continuity_experience_claims as legacy\r\n-- ############################################################################\r\n\r\nCOMMENT ON TABLE public.continuity_experience_claims IS 'DEPRECATED in KAD-004. Use public.claims (evidence-core) instead. This table exists only for backward compatibility during migration.'"}	kad004_claim_consolidation
