   FROM public.organization_memberships
  WHERE ((organization_memberships.user_id = auth.uid()) AND (organization_memberships.status = 'active'::public.membership_status)))) AND (created_by_org_id = owning_org_id)));


--
-- Name: claims claims_select_org; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY claims_select_org ON public.claims FOR SELECT USING ((owning_org_id IN ( SELECT organization_memberships.organization_id
   FROM public.organization_memberships
  WHERE ((organization_memberships.user_id = auth.uid()) AND (organization_memberships.status = 'active'::public.membership_status)))));


