--

CREATE POLICY claims_select_sponsor ON public.claims FOR SELECT USING (((visibility_scope = 'sponsor_authorized'::public.visibility_scope) AND (auth.uid() = ANY (authorized_sponsor_ids))));


--
-- Name: claims claims_select_system; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY claims_select_system ON public.claims FOR SELECT USING ((visibility_scope = 'system'::public.visibility_scope));


--
-- Name: claims claims_update_org; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY claims_update_org ON public.claims FOR UPDATE USING ((owning_org_id IN ( SELECT organization_memberships.organization_id
   FROM public.organization_memberships
  WHERE ((organization_memberships.user_id = auth.uid()) AND (organization_memberships.status = 'active'::public.membership_status))))) WITH CHECK (((owning_org_id = ( SELECT original.owning_org_id
   FROM public.claims original
  WHERE (original.id = claims.id))) AND (organization_id = ( SELECT original.organization_id
   FROM public.claims original
  WHERE (original.id = claims.id))) AND (claim_type_id = ( SELECT original.claim_type_id
   FROM public.claims original
  WHERE (original.id = claims.id))) AND (domain = ( SELECT original.domain
   FROM public.claims original
  WHERE (original.id = claims.id))) AND (created_by_actor_id = ( SELECT original.created_by_actor_id
   FROM public.claims original
  WHERE (original.id = claims.id))) AND (created_by_org_id = ( SELECT original.created_by_org_id
   FROM public.claims original
  WHERE (original.id = claims.id)))));


