--
-- Name: evidence_nodes evidence_nodes_insert_org; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY evidence_nodes_insert_org ON public.evidence_nodes FOR INSERT WITH CHECK ((EXISTS ( SELECT 1
   FROM public.claims c
  WHERE ((c.id = evidence_nodes.claim_id) AND (c.owning_org_id IN ( SELECT organization_memberships.organization_id
           FROM public.organization_memberships
          WHERE ((organization_memberships.user_id = auth.uid()) AND (organization_memberships.status = 'active'::public.membership_status))))))));


--
-- Name: evidence_nodes evidence_nodes_select_org; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY evidence_nodes_select_org ON public.evidence_nodes FOR SELECT USING (((visibility ->> 'owningOrganizationId'::text) IN ( SELECT (organization_memberships.organization_id)::text AS organization_id
   FROM public.organization_memberships
  WHERE ((organization_memberships.user_id = auth.uid()) AND (organization_memberships.status = 'active'::public.membership_status)))));


--
-- Name: evidence_nodes evidence_nodes_select_sponsor; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY evidence_nodes_select_sponsor ON public.evidence_nodes FOR SELECT USING ((((visibility ->> 'scope'::text) = 'sponsor_authorized'::text) AND ((auth.uid())::text = ANY (ARRAY( SELECT jsonb_array_elements_text((evidence_nodes.visibility -> 'authorizedSponsorIds'::text)) AS jsonb_array_elements_text)))));


