--
-- Name: evidence_relationships evidence_relationships_insert_org; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY evidence_relationships_insert_org ON public.evidence_relationships FOR INSERT WITH CHECK (((EXISTS ( SELECT 1
   FROM public.evidence_nodes en
  WHERE ((en.id = evidence_relationships.source_node_id) AND ((en.visibility ->> 'owningOrganizationId'::text) IN ( SELECT (organization_memberships.organization_id)::text AS organization_id
           FROM public.organization_memberships
          WHERE ((organization_memberships.user_id = auth.uid()) AND (organization_memberships.status = 'active'::public.membership_status))))))) AND (EXISTS ( SELECT 1
   FROM public.evidence_nodes en
  WHERE ((en.id = evidence_relationships.target_node_id) AND ((en.visibility ->> 'owningOrganizationId'::text) IN ( SELECT (organization_memberships.organization_id)::text AS organization_id
           FROM public.organization_memberships
          WHERE ((organization_memberships.user_id = auth.uid()) AND (organization_memberships.status = 'active'::public.membership_status)))))))));


--
-- Name: evidence_relationships evidence_relationships_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY evidence_relationships_select ON public.evidence_relationships FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.evidence_nodes en
  WHERE ((en.id = evidence_relationships.source_node_id) AND (((en.visibility ->> 'owningOrganizationId'::text) IN ( SELECT (organization_memberships.organization_id)::text AS organization_id
           FROM public.organization_memberships
          WHERE ((organization_memberships.user_id = auth.uid()) AND (organization_memberships.status = 'active'::public.membership_status)))) OR ((en.visibility ->> 'scope'::text) = 'sponsor_authorized'::text))))));


