--
-- Name: right_of_response right_of_response_insert_org; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY right_of_response_insert_org ON public.right_of_response FOR INSERT WITH CHECK ((owning_org_id IN ( SELECT organization_memberships.organization_id
   FROM public.organization_memberships
  WHERE ((organization_memberships.user_id = auth.uid()) AND (organization_memberships.status = 'active'::public.membership_status)))));


--
-- Name: right_of_response right_of_response_select_org; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY right_of_response_select_org ON public.right_of_response FOR SELECT USING ((owning_org_id IN ( SELECT organization_memberships.organization_id
   FROM public.organization_memberships
  WHERE ((organization_memberships.user_id = auth.uid()) AND (organization_memberships.status = 'active'::public.membership_status)))));


--
-- Name: right_of_response right_of_response_update_org; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY right_of_response_update_org ON public.right_of_response FOR UPDATE USING ((owning_org_id IN ( SELECT organization_memberships.organization_id
   FROM public.organization_memberships
  WHERE ((organization_memberships.user_id = auth.uid()) AND (organization_memberships.status = 'active'::public.membership_status))))) WITH CHECK (((owning_org_id = ( SELECT original.owning_org_id
   FROM public.right_of_response original
  WHERE (original.id = right_of_response.id))) AND (counter_evidence_id = ( SELECT original.counter_evidence_id
   FROM public.right_of_response original
  WHERE (original.id = right_of_response.id))) AND (description = ( SELECT original.description
   FROM public.right_of_response original
  WHERE (original.id = right_of_response.id))) AND (resolution_date = ( SELECT original.resolution_date
   FROM public.right_of_response original
  WHERE (original.id = right_of_response.id))) AND (created_by_actor_id = ( SELECT original.created_by_actor_id
   FROM public.right_of_response original
  WHERE (original.id = right_of_response.id))) AND (created_by_org_id = ( SELECT original.created_by_org_id
   FROM public.right_of_response original
  WHERE (original.id = right_of_response.id)))));


